  '\\u{1F4CA}\\uFE0F?',
  '\\u{1F49A}\\uFE0F?',
  '\\u{1F4D0}\\uFE0F?',
  '\\u{1F4CC}\\uFE0F?',
  '\\u{1F4E4}\\uFE0F?',
  '\\u{1F93A}\\uFE0F?',
  '\\u{1F9DB}\\uFE0F?\\u200D?\\u2642\\uFE0F?',
  '\\u{1F3BB}\\uFE0F?',
  '\\u{1F47B}\\uFE0F?',
  '\\u{1F47E}\\uFE0F?',
  '\\u{1F4A3}\\uFE0F?',
  '\\u{1F525}\\uFE0F?',
  '\\u2615\\uFE0F?',
  '\\u{1F5E1}\\uFE0F?',
  '\\u{1F50E}\\uFE0F?',
  '\\u{1F9F0}\\uFE0F?',
  '\\u{1F52D}\\uFE0F?',
  '\\u26D3\\uFE0F?',
