/* 精灵图挂载点。幂等：任意位置调都安全（代价是一次 getElementById）。
 * 插 body 末尾而不是头部：它就是一层 0x0 的定义库，位置不影响任何层叠。 */
function ensureIconSprite() {
  if (typeof document === 'undefined') return null;
  const exist = document.getElementById('arkIconSprite');
  if (exist) return exist;
  const host = document.body || document.documentElement;
  if (!host) return null;
  const box = document.createElement('div');
  box.id = 'arkIconSprite';
  box.setAttribute('aria-hidden', 'true');
  box.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden;pointer-events:none';
  box.innerHTML = ICON_SPRITE_HTML;
  host.appendChild(box);
  return box;
}

function escapeHtmlForIcon(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

/* 单个图标：默认输出内联 svg（class=vico，尺寸 1em，见 ICON_SVG 登记表）；
 * 没登记进 ICON_SVG 的才退回系统 emoji 字符（class=emo）。
 * data-ico 两个分支都带 —— 门禁与调试都靠它认图，别删。 */
function iconTag(slug, cls) {
  if (!slug) return '';
  if (ICON_SVG[slug]) {
    return '<svg class="' + (cls || 'vico') + '" data-ico="' + slug + '" aria-hidden="true" focusable="false">' +
           '<use href="#ico-' + slug + '"/></svg>';
  }
  const ch = ICON_CHAR[slug];
  if (!ch) return '';
  return '<span class="emo" data-ico="' + slug + '">' + ch + '</span>';
}

/* innerHTML 上下文用：字符串里的 emoji 全部换掉，已有的 HTML 标记不受影响。 */
function iconify(s) {
  if (s == null || s === '') return '';
  const str = String(s);
  EMOJI_ICON_RE.lastIndex = 0;
  if (!EMOJI_ICON_RE.test(str)) return str;     // 没有 emoji 是最常见的情况，早退
  EMOJI_ICON_RE.lastIndex = 0;
  ensureIconSprite();
  return str.replace(EMOJI_ICON_RE, function (m) {
    const slug = EMOJI_TO_ICON[m.split('\uFE0F').join('')];
    return slug ? iconTag(slug) : m;
  });
}

/* 纯文本上下文（战斗日志等）用：先转义再 iconify —— 顺序不能反，
 * 反了会把 svg 自己也转义掉，日志里出现一堆转义后的尖括号。 */
function iconifyText(s) {
  if (s == null || s === '') return '';
  return iconify(escapeHtmlForIcon(s));
}

/* ★ 静态 HTML 里的 emoji（例如模板里直接写死的 <button>👤</button>）不经过任何 JS 字符串，
 * iconify 够不到。这里用文本节点遍历补一刀 —— 只在启动时跑，不是每帧。
 * 每个命中的文本节点换成一个 display:contents 的 span，布局一像素都不会动。 */
function iconifyDom(root) {
  if (typeof document === 'undefined' || !document.createTreeWalker) return;
  const host = root || document.body;
  if (!host) return;
  ensureIconSprite();
  const walker = document.createTreeWalker(host, NodeFilter.SHOW_TEXT, null, false);
  const hits = [];
  while (walker.nextNode()) hits.push(walker.currentNode);
  for (let i = 0; i < hits.length; i++) {
    const node = hits[i];
    const v = node.nodeValue;
    if (!v) continue;
    /* 已经在 .emo 里的文本不要重复包 —— 二次调用 iconifyDom 时会套娃。 */
    if (node.parentNode && node.parentNode.classList && node.parentNode.classList.contains('emo')) continue;
    EMOJI_ICON_RE.lastIndex = 0;
    if (!EMOJI_ICON_RE.test(v)) continue;
    EMOJI_ICON_RE.lastIndex = 0;
    const box = document.createElement('span');
    box.style.display = 'contents';
    box.innerHTML = iconifyText(v);
    if (node.parentNode) node.parentNode.replaceChild(box, node);
  }
}

try { ensureIconSprite(); } catch (_) {}
/* 模块求值点时脚本已在 body 末尾，静态 DOM 全部就位，可以立刻扫一遍。 */
try { iconifyDom(document.body); } catch (_) {}

