/* 角色 id → 专属课 id（没有专属课的返回 null） */
function tutorialLessonForChar(charId) {
  const key = 'char-' + String(charId || '');
  return TUTORIAL_LESSONS[key] ? key : null;
}

/* ---- 运行时状态（模块级单例）---- */
const TUTORIAL_DONE_KEY = 'ark_tutorial_done';
let tutorialOn = false;
let tutorialStepIdx = 0;
let tutorialLessonId = 'action';
/* 计数器全部累积在本对象里，步骤判据比较绝对阈值（够用且不会错位） */
let tutorialFlags = null;
/* 地图字符 → 敌人性格，按「逐行扫描顺序」缓存。tutorialDecorateEnemies 依赖它对齐下标。 */
let tutorialKinds = [];
/* ★ ISSUE-110：cond.rounds 的基准（进课时记一次 battleRound）。
 * 用差值而不是自己维护计数器 —— battleRound 已经是「回合」的唯一真相，
 * 另存一份迟早和它漂移（重开 / 切课都要记得清零，漏一处就永远判不满）。 */
let tutorialRoundBase = 0;

function tutorialFlagReset() {
  tutorialFlags = { hits: 0, skill: 0, kills: 0, hurt: 0, counter: 0, blood: 0 };
}
tutorialFlagReset();

function tutorialLesson() { return tutorialLessonId; }
function tutorialIsOn() { return tutorialOn; }
function tutorialLessonDef() { return TUTORIAL_LESSONS[tutorialLessonId] || TUTORIAL_LESSONS.action; }
function tutorialLessonTitle() { return tutorialLessonDef().title; }
/* 教程内玩家血线夹在 1（src/rules/relics.js#damagePlayer 问这一句） */
function tutorialHpFloor() { return tutorialOn; }
/* 教程内是否允许放技能节点（通用课关掉，角色课打开） */
function tutorialSkillsBlocked() { return tutorialOn && !tutorialLessonDef().allowSkills; }
/* 教程内强制使用的角色（null = 沿用玩家已选） */
function tutorialForcedChar() { return tutorialOn ? (tutorialLessonDef().charId || null) : null; }

/* 教程是否已看过（存在标记就不再强制播）
 * ★ 测试 / 调试逃生口：`window.__ARK_TUTORIAL_OFF = true` 一处关掉整条教程链
 *   （总标记 + 每角色标记一起失效）。
 *   为什么必须有：教程会把地图换成手写关、把敌人数改成手写数、给木桩挂 cannotDie ——
 *   于是「摆 3 个敌人测连环攻击」这类**场景可编程**的门禁一旦跑在教程里，
 *   敌人 id 对不上、靶子打不死，报错信息还指向被测逻辑本身，排查成本极高。
 *   与 `window.__ARK_REC_DISABLE` / `window.__ARK_DEBUG__` 是同一类开关，不给玩家暴露。 */
function tutorialOffBySwitch() {
  try { return !!(window && window.__ARK_TUTORIAL_OFF); } catch (_) { return false; }
}
function tutorialDoneFlag() {
  if (tutorialOffBySwitch()) return true;
  try { return !!(window.localStorage && window.localStorage.getItem(TUTORIAL_DONE_KEY) === '1'); }
  catch (_) { return false; }
}
function tutorialMarkDone() {
  try { if (window.localStorage) window.localStorage.setItem(TUTORIAL_DONE_KEY, '1'); } catch (_) {}
}
/* 角色专属课的「上过没有」标记（每个角色一个键）。
 * 为什么要单独记：通用课只看一次，但角色课是「换一个角色就该再上一次」——
 * 用同一个键的话，玩家第二次选别的角色就再也看不到那节课了（E5-1 推荐值的另一半）。 */
const TUT_CHAR_KEY_PREFIX = 'ark_tut_char_';
function tutorialCharDoneFlag(charId) {
  if (tutorialOffBySwitch()) return true;
  if (!charId) return true;
  try { return !!(window.localStorage && window.localStorage.getItem(TUT_CHAR_KEY_PREFIX + charId) === '1'); }
  catch (_) { return false; }
}
function tutorialMarkCharDone(charId) {
  if (!charId) return;
  try { if (window.localStorage) window.localStorage.setItem(TUT_CHAR_KEY_PREFIX + charId, '1'); } catch (_) {}
}
/* 设置面板「重看教程」用：清掉标记后重新播 */
function tutorialResetDoneFlag() {
  try {
    if (!window.localStorage) return;
    window.localStorage.removeItem(TUTORIAL_DONE_KEY);
    for (const id of Object.keys(CHARACTERS)) window.localStorage.removeItem(TUT_CHAR_KEY_PREFIX + id);
  } catch (_) {}
}

/* ★ ISSUE-20261031-94：这个角色「现在还有没有没上完的课」—— 大厅正式入口 🚪 的显隐只认这一个出口。
 *
 * 返回 null      = 上完了（放行正式入口）
 * 返回 lessonId  = 还没上完，该去上这一课
 *
 * ⚠️ 为什么必须抽成一个函数，而不是在渲染 / 点击 / 走位三处各写一遍判定：
 *    三处各写一遍，改了一处忘另两处，就会出现「看得见点不到」或「走过去照样开局」——
 *    这是本号最容易漏、也最难查的地方（显示与行为用了两套真相）。
 *    现在三处消费同一份返回值，只要这个函数对，三处必然一致。
 *
 * 口径（人类 2026-10-31 12:5x 拍板 Q2① / Q3①；★ 16:06 追加「角色课不加入链条」）：
 *   · 「完成所有教程」= **入门三关走完**（action → battle → mutual），不看角色；
 *   · 角色专属课**不在这条链上**，也不再有「没上过就自动拽进去」的自动入口 ——
 *     它只是设置面板「重看教程」里的**可选**内容（chrome.js 的列表）；
 *   · 三关没走完时，任何角色点 🚪 都会从第一关开始（规则无例外，玩家才可预期）。
 *
 * @param {string|null} charId 当前选中的角色；未选角色时传 null
 *   ⚠️ 参数保留只为调用处签名兼容。★ 角色课移出链条后，本函数**不再因 charId 返回角色课**
 *      （原来「该角色专属课没上过 → 去那一课」那条自动分支已删，见 ISSUE-110 / 人类 16:06）。
 */
function tutorialPendingLesson(charId) {
  if (tutorialOffBySwitch()) return null;                 // 测试逃生口：整条教程链关掉
  /* 入门三关没走完 → 从第一关开始（与「选了哪个角色」无关，Q3①） */
  if (!tutorialDoneFlag()) return TUTORIAL_INTRO_CHAIN[0];
  /* 三关走完了 —— 没有待上的课。角色课要玩家自己去设置面板点，不再自动弹。 */
  return null;
}

/* 切到指定课（不清「已看过」标记 —— 标记只在整条教程走完时写） */
function tutorialStartById(lessonId) {
  if (!TUTORIAL_LESSONS[lessonId]) return false;
  tutorialOn = true;
  tutorialLessonId = lessonId;
  tutorialStepIdx = 0;
  tutorialFlagReset();
  /* ★ ISSUE-110：回合基准随课重置（cond.rounds 用的是差值） */
  try { tutorialRoundBase = (typeof battleRound === 'number') ? battleRound : 0; } catch (_) { tutorialRoundBase = 0; }
  return true;
}
/* 首次进游戏：从第一关「行动」开始（char-select 调） */
function tutorialStart() { return tutorialStartById(TUTORIAL_INTRO_CHAIN[0]); }

function tutorialEnd() {
  /* 收尾时把「这一课」记下来：角色课单独记（换角色还能再上一次），通用课记总标记 */
  const def = tutorialLessonDef();
  if (def.charId) tutorialMarkCharDone(def.charId);
  else tutorialMarkDone();
  tutorialOn = false;
}

/* ★ 中止 ≠ 完成：重开 / 回选角厅时只把教程态卸掉，**不写任何「已看过」标记**。
 * 为什么不能图省事复用 tutorialEnd()：它会调 tutorialMarkDone / tutorialMarkCharDone，
 * 于是「教程看了一半就点重开」会被记成「学过了」——玩家其实一步都没操作过，
 * 下次进来却再也不会触发教程，等于永久失去这段引导。
 * 两者的区别只有「写不写标记」，但写错方向的代价不可逆，所以单独立一个函数。 */
function tutorialAbort() {
  tutorialOn = false;
  tutorialStepIdx = 0;
  tutorialFlagReset();
}

/* 这一课走完之后接哪一节。
 * ★ ISSUE-110：入门三关是一条链，必须**一关接一关**自动往下走 —— action → battle → mutual。
 * ★ 人类 2026-10-31 16:06 拍板「角色课不加入链条」：mutual 走完**链条就结束**，直接回大厅，
 *   不再自动接该角色的专属课。角色课只能在设置面板「重看教程」里手动进入。
 *   （这里返回 null 会让 tutorialAdvance 走 tutorialEnd() → 写总标记 → 'done' → 回大厅。） */
function tutorialNextLesson() {
  const i = TUTORIAL_INTRO_CHAIN.indexOf(tutorialLessonId);
  if (i >= 0 && i + 1 < TUTORIAL_INTRO_CHAIN.length) return TUTORIAL_INTRO_CHAIN[i + 1];
  return null;
}

/* 当前步（越界返回 null） */
function tutorialCurrentStep() {
  if (!tutorialOn) return null;
  return tutorialLessonDef().steps[tutorialStepIdx] || null;
}

/* ---- 技力查询（提示条占位符 + 步骤判据共用）----
 * 全部返回**真实值**（不是预览值）：判据比较的是「玩家真的攒到了没有」。
 * 唯一例外是风笛的预览值 —— 她的技力来自「本回合要走的那条路径」，
 * 规划阶段就该看到它涨（否则玩家永远看不到「攒满」提示）。 */
function tutorialSpNow() {
  const ch = (typeof selectedChar !== 'undefined') ? selectedChar : null;
  switch (ch) {
    case 'wheelchair':
      return (typeof wheelchairPreviewSp === 'function') ? wheelchairPreviewSp()
        : (typeof wheelchairSp === 'number' ? wheelchairSp : 0);
    case 'vampire': return (typeof vampireSp === 'number') ? vampireSp : 0;
    case 'fencer': return (typeof fencerSp === 'number') ? fencerSp : 0;
    case 'amiya': return (typeof amiyaBonusTargets === 'number') ? amiyaBonusTargets : 0;
    case 'rookie': return (typeof rookieSp === 'number') ? rookieSp : 0;
    default: return 0;
  }
}
function tutorialSpMax() {
  const ch = (typeof selectedChar !== 'undefined') ? selectedChar : null;
  switch (ch) {
    case 'wheelchair': return (typeof WHEELCHAIR_SP_MAX === 'number') ? WHEELCHAIR_SP_MAX : 5;
    case 'vampire': return (typeof VAMPIRE_SP_MAX === 'number') ? VAMPIRE_SP_MAX : 5;
    case 'fencer': return (typeof FENCER_SP_MAX === 'number') ? FENCER_SP_MAX : 5;
    case 'amiya': return (typeof amiyaSpMax === 'function') ? amiyaSpMax() : 10;
    case 'rookie': return (typeof ROOKIE_SP_MAX === 'number') ? ROOKIE_SP_MAX : 5;
    default: return 0;
  }
}

/* 提示条文案：{sp}/{spMax} 占位符换成真实数值（别在文案里硬编码 5 / 10） */
function tutorialTipText() {
  const s = tutorialCurrentStep();
  if (!s) return '';
  /* ★ ISSUE-110：课程可以挂一个 tip(step, lessonId) 覆盖函数 —— battle 那一课的
   *   最后一步要按「近战 / 远程」说两套不同的弱点说明，又不想把同一段文字写两遍。 */
  let txt = s.tip;
  try {
    const def = tutorialLessonDef();
    if (def && typeof def.tip === 'function') {
      const override = def.tip(s, tutorialLessonId);
      if (override) txt = override;
    }
  } catch (_) {}
  try {
    txt = String(txt).replace(/\{sp\}/g, String(tutorialSpNow()))
             .replace(/\{spMax\}/g, String(tutorialSpMax()));
  } catch (_) {}
  return txt;
}
function tutorialProgress() {
  const total = tutorialLessonDef().steps.length;
  return { step: Math.min(tutorialStepIdx + 1, total), total: total };
}

/* ---- 锁骰钩子（src/rules/dnd.js 调用）----
 * 返回 1~20 = 本次强制用这个点数；返回 null = 正常随机。 */
function tutorialForceD20() {
  const s = tutorialCurrentStep();
  if (!s || !s.d20) return null;
  return s.d20;
}

/* ---- ISSUE-20261030-91：地图内 4×9 文字区 ----
 * 人类 2026-10-30 23:4x：「教程关默认角色在地图中心 (5,5) 的位置，下面 4×9 的区域用来进行教程关的说明」。
 * 11×11 棋盘：第 0 / 10 行列是墙，内部 9×9 = x 1..9 · y 1..9；
 * 中心行 y=5 之下恰好剩 y=6..9 **4 行** × x=1..9 **9 列** —— 就是这块。
 *
 * ★ 坐标只在这里定义一次。渲染层（game.html#renderTutorialBar）拿它去算像素，
 *   门禁（net/tutorial_test.mjs）拿它断言「没有任何要素被摆进文字区」。
 *   两处各写一份数字 = 早晚漂移。 */
const TUTORIAL_TEXT_ZONE = { x0: 1, y0: 6, x1: 9, y1: 9 };
function tutorialTextZone() { return TUTORIAL_TEXT_ZONE; }

/* 本步该指哪一格（光标指引的落点）。规则从 cond 推，不在步骤里手写第二份坐标：
 *   cond.pos   → 就指那一格（「走到这里」）
 *   cond.blood → 指最近的一处血迹（她要去"踩"它，指敌人就指错了）
 *   cond.skill → 指路径末端（技能节点是右键路径格设的）
 *   其余（打敌人 / cond.hurt / cond.counter）→ 指最近的活敌人；一个都不剩就指玩家自己。
 *     · hurt / counter 走这条不是偷懒：「让人来打你」这一步，玩家该盯的正是
 *       **那个会打你的敌人**，指它比指自己更能说明「你不用动，等它过来」。
 *     · ⚠️ 曾经给这两步写过 cursor: '.start-btn'（指向「开始行动」按钮），
 *       但本函数只返回 {x, y} 地图坐标，渲染层 #tutCursor 也只吃地图格 ——
 *       选择器根本传不出去，是死数据。要指按钮得改渲染层，另立 issue，别塞这里。
 * 返回 null = 本步不需要指引（例如收尾的 cont 步）。 */
function tutorialGuideTarget() {
  const s = tutorialCurrentStep();
  if (!s || !s.cond) return null;
  /* ★ ISSUE-110：本步的动作是「按开始行动」→ 光标改去高亮那个按钮（渲染层认 button:'start'） */
  if (s.pointStart) return { button: 'start' };
  if (s.cond.cont) return null;
  const px = (typeof player !== 'undefined' && player) ? player.x : 0;
  const py = (typeof player !== 'undefined' && player) ? player.y : 0;
  /* 路径末端（playerPath 最后一项）—— 「走到这里」类的步骤都指它 */
  const pathEnd = () => {
    try {
      if (typeof playerPath !== 'undefined' && playerPath && playerPath.length) {
        const e = playerPath[playerPath.length - 1];
        if (e) return { x: e.x, y: e.y };
      }
    } catch (_) {}
    return null;
  };
  /* 路径第 n 步所在的格子（节点类步骤：攻击/技能都设在路径某一步上） */
  const pathAt = (n) => {
    try {
      if (typeof playerPath !== 'undefined' && playerPath && n >= 0 && n < playerPath.length) {
        const e = playerPath[n];
        if (e) return { x: e.x, y: e.y };
      }
    } catch (_) {}
    return null;
  };
  if (s.cond.pos) return { x: s.cond.pos[0], y: s.cond.pos[1] };
  /* ★ 入门三关的指引：全部从 cond 推，绝不手写第二份坐标 */
  if (s.cond.pathEnd) return { x: s.cond.pathEnd[0], y: s.cond.pathEnd[1] };
  if (typeof s.cond.attackIdx === 'number') return pathAt(s.cond.attackIdx) || pathEnd();
  if (typeof s.cond.skillIdx === 'number') return pathAt(s.cond.skillIdx) || pathEnd();
  if (typeof s.cond.waits === 'number') return pathEnd();
  if (s.cond.multiAt) return { x: s.cond.multiAt[0], y: s.cond.multiAt[1] };
  if (s.cond.allDead) return null;
  const nearestOf = (list) => {
    let best = null, bd = 1e9;
    for (const it of list) {
      if (!it) continue;
      const d = Math.abs(it.x - px) + Math.abs(it.y - py);
      if (d < bd) { bd = d; best = it; }
    }
    return best;
  };
  try {
    if (typeof s.cond.blood === 'number' && typeof bloodDrops !== 'undefined' && bloodDrops && bloodDrops.length) {
      const b = nearestOf(bloodDrops);
      if (b) return { x: b.x, y: b.y };
    }
  } catch (_) {}
  try {
    if (typeof s.cond.skill === 'number' && typeof playerPath !== 'undefined' && playerPath && playerPath.length > 1) {
      const end = playerPath[playerPath.length - 1];
      if (end) return { x: end.x, y: end.y };
    }
  } catch (_) {}
  try {
    if (typeof enemies !== 'undefined' && enemies && enemies.length) {
      const e = nearestOf(enemies.filter(x => x && x.alive));
      if (e) return { x: e.x, y: e.y };
    }
  } catch (_) {}
  if (typeof player !== 'undefined' && player) return { x: px, y: py };
  return null;
}

/* ---- 地图钩子（templates/game.html#initLevel 调用）----
 * 返回 null 表示「不在教程里」；否则给 initLevel 一份等价于 generateMap() 的结果。 */
function tutorialMapOverride() {
  if (!tutorialOn) return null;
  /* ★ ISSUE-110：rows 可以是函数（battle 课按近战 / 远程换一张图），
   *   所以这里必须每次求值、不能缓存 —— 缓存了会在「换角色重看教程」时用上一张图。 */
  const def = tutorialLessonDef();
  const rows = (typeof def.rows === 'function') ? def.rows() : def.rows;
  const R = rows.length;
  const C = rows[0].length;
  /* ★ 尺寸自适应：initLevel 里 `ROWS = BOARD_ROWS` 是常量赋值，地图尺寸不匹配会在
   *   render / updateStats 里抛「undefined 读 [0]」→ 一进关就白屏，而且报错位置离原因很远。
   *   这里直接对齐到 BOARD_ROWS × BOARD_COLS（多出来的行/列补墙、少的裁掉），
   *   让「谁把地图写成 9×9」变成一个可见的画面（多一圈墙），而不是一场白屏。 */
  const TR = (typeof BOARD_ROWS === 'number') ? BOARD_ROWS : R;
  const TC = (typeof BOARD_COLS === 'number') ? BOARD_COLS : C;
  const map = [];
  let playerStart = null;
  const enemyStarts = [];
  const blood = [];
  tutorialKinds = [];
  for (let y = 0; y < TR; y++) {
    const line = rows[y] || '';
    const row = [];
    for (let x = 0; x < TC; x++) {
      const ch = line[x] || TUTORIAL_WALL;
      row.push(ch === TUTORIAL_WALL ? 1 : 0);
      if (ch === 'P') playerStart = { x: x, y: y };
      else if (ch === 'T') { enemyStarts.push({ x: x, y: y, kind: 'dummy' }); tutorialKinds.push('dummy'); }
      else if (ch === 'M') { enemyStarts.push({ x: x, y: y, kind: 'patrol' }); tutorialKinds.push('patrol'); }
      else if (ch === 'C') { enemyStarts.push({ x: x, y: y, kind: 'chaser' }); tutorialKinds.push('chaser'); }
      else if (ch === 'W') { enemyStarts.push({ x: x, y: y, kind: 'walker' }); tutorialKinds.push('walker'); }
      else if (ch === 'E') { enemyStarts.push({ x: x, y: y, kind: 'hostile' }); tutorialKinds.push('hostile'); }
      else if (ch === 'K') { enemyStarts.push({ x: x, y: y, kind: 'mob' }); tutorialKinds.push('mob'); }
      else if (ch === 'X') { enemyStarts.push({ x: x, y: y, kind: 'tank' }); tutorialKinds.push('tank'); }
      else if (ch === 'B') blood.push({ x: x, y: y });
    }
    map.push(row);
  }
  return {
    map: map,
    rewards: [],
    playerStart: playerStart || { x: 4, y: 4 },
    enemyStarts: enemyStarts,
    tutorialBlood: blood,
  };
}

/* ---- 敌人参数钩子（initLevel 造完敌人后调用）----
 * 地图字符 → 敌人性格。顺序由地图逐行扫描决定，这里按下标一一对应。 */
function tutorialDecorateEnemies(list) {
  if (!tutorialOn || !list || !list.length) return;
  for (let i = 0; i < list.length; i++) {
    const e = list[i];
    if (!e) continue;
    const kind = tutorialKinds[i] || 'dummy';
    /* ★ 把性格写在敌人身上。原先 tutorialEnterStep 靠 `enemies[1]` 找巡逻敌，
     *   等于把「地图扫描顺序」这个实现细节当成了契约 —— 91 号重排地图后
     *   巡逻敌从下标 1 变成了下标 0，那种写法会静默失效（巡逻敌永不解除静止，
     *   玩家等不到它的意图箭头，s5 就白讲了）。 */
    e.tutorialKind = kind;
    /* 词缀 / 精英一律清掉：教程关的敌人性格是**手写**的，随机词缀（护盾、荆棘、分裂）
     * 会让「这一下为什么没掉血」变成一个新的教学负担。level 在教程里恒为 1，
     * 本来也抽不到这些，但手写关不该依赖那个巧合。 */
    e.isElite = false;
    e.affixes = [];
    e.shieldLeft = 0;
    switch (kind) {
      case 'dummy':
        /* 木桩：不动、打不死、没有意图箭头（不动的敌人本来就没箭头） */
        e.dormant = true;
        e.cannotDie = true;
        e.hp = Math.max(e.hp || 0, 40);
        e.maxHp = e.hp;
        e.name = '训练木桩';
        break;
      case 'patrol':
        /* 巡逻敌（老通用课留下的类型，入门三关已不使用，角色课若用到仍生效）：
         * 前 4 步不动，之后才行动 —— 前四步不会被它打断。 */
        e.dormant = tutorialStepIdx < 4;
        e.hp = Math.max(e.hp || 0, 40);
        e.maxHp = e.hp;
        e.name = '巡逻敌人';
        break;
      case 'chaser':
        /* ★ ISSUE-110 第一关的「陪跑」：正常寻路追玩家，但玩家一路往左上跑，
         *   它永远差着几格 —— 追不上才是设计目的（只用来让玩家看见回合在推进）。
         *   HP 拉高：去程的攻击节点可能顺手打到它，别让它死，死了就没人演示回合了。 */
        e.hp = Math.max(e.hp || 0, 30);
        e.maxHp = e.hp;
        e.name = '追击敌人';
        break;
      case 'walker':
        /* ★ ISSUE-110 第三关的相杀演示对象：血量要够挨一次**双倍**近战伤害还活着，
         *   否则「相杀」会在它死亡动画里被忽略掉。 */
        e.hp = Math.max(e.hp || 0, 14);
        e.maxHp = e.hp;
        e.name = '逼近的敌人';
        break;
      case 'hostile':
        /* 泥岩课的陪练：正常敌对，负责打她（她的技力来源） */
        e.hp = Math.max(e.hp || 0, 10);
        e.maxHp = e.hp;
        e.name = '陪练敌人';
        break;
      case 'mob':
        /* 阿米娅课的燃料：1 HP，一击就死 */
        e.hp = 1;
        e.maxHp = 1;
        e.name = '脆皮小怪';
        break;
      case 'tank':
        /* 华法琳课的高 AC 靶子：AC 拉高，普通射击大概率 MISS */
        e.ac = 20;
        e.hp = Math.max(e.hp || 0, 14);
        e.maxHp = e.hp;
        e.name = '重甲靶子';
        break;
      default: break;
    }
  }
}

/* ---- 进关补丁（initLevel 造完玩家、造敌人之前调用）----
 * 预置技力 / 预置血迹都只能在「地图已换成教程图、玩家已建好」之后落地。 */
function tutorialAfterInit(gen) {
  if (!tutorialOn) return;
  const def = tutorialLessonDef();
  /* 预置血迹（华法琳课）。bloodDrops 是 src/rules/state.js 的全局数组，
   * 这里**改内容不改引用**（别的模块持有它）。 */
  try {
    if (typeof bloodDrops !== 'undefined' && bloodDrops) {
      bloodDrops.length = 0;
      const preset = (gen && gen.tutorialBlood) || def.blood || [];
      for (const b of preset) bloodDrops.push({ x: b.x, y: b.y });
    }
  } catch (_) {}
  /* 预置技力 */
  const sp = def.startSP || 0;
  if (sp > 0) {
    try {
      if (def.charId === 'vampire' && typeof vampireSp === 'number') vampireSp = Math.min(VAMPIRE_SP_MAX, sp);
      if (def.charId === 'fencer' && typeof fencerSp === 'number') fencerSp = Math.min(FENCER_SP_MAX, sp);
      if (def.charId === 'amiya' && typeof amiyaBonusTargets === 'number') amiyaBonusTargets = Math.min(amiyaSpMax(), sp);
      if (def.charId === 'wheelchair' && typeof wheelchairSp === 'number') wheelchairSp = Math.min(WHEELCHAIR_SP_MAX, sp);
      if (def.charId === 'rookie' && typeof rookieSp === 'number') rookieSp = Math.min(ROOKIE_SP_MAX, sp);
    } catch (_) {}
  }
  /* ★ ISSUE-110：入门三关的走位要**够得着**。
   * 第一关要求「走到正上方第 4 格」，而移动力 = floor(dex/2) + 藏品加成（src/rules/dnd.js:158），
   * 敏捷低的角色可能只有 3 —— 那样这一步永远做不完，教程会当场卡死。
   * 这里给一个下限（只抬不削），让「第 4 格」在任何角色身上都成立。
   * 为什么敢改移动力：教程关不结算经验、不上榜、不进正式局，改的是教学场地不是平衡。 */
  try {
    if (def.intro && typeof player !== 'undefined' && player) {
      const floor = (typeof TUTORIAL_MOVE_FLOOR === 'number') ? TUTORIAL_MOVE_FLOOR : 4;
      if (typeof player.move === 'number' && player.move < floor) {
        log(`📖 教程里先把移动力抬到 ${floor} 步（你的角色原本是 ${player.move} 步），这样才走得到「上方第 4 格」。`);
        player.move = floor;
      }
    }
  } catch (_) {}
}

/* ---- 计数器钩子（全部挂在唯一收口处，见文件头设计原则 2）---- */
function tutorialOnEnemyDamaged(target) {          /* 任何单位被玩家打中 */
  if (!tutorialOn) return;
  tutorialFlags.hits += 1;
}
function tutorialOnKill() {                        /* game.html#killEnemy */
  if (!tutorialOn) return;
  tutorialFlags.kills += 1;
}
function tutorialOnPlayerHurt() {                   /* src/rules/relics.js#damagePlayer */
  if (!tutorialOn) return;
  tutorialFlags.hurt += 1;
}
function tutorialOnSkillCast(charId) {              /* game.html 技能节点统一扣动作处 */
  if (!tutorialOn) return;
  tutorialFlags.skill += 1;
}
function tutorialOnCounter() {                      /* game.html#triggerFencerCounter */
  if (!tutorialOn) return;
  tutorialFlags.counter += 1;
}
function tutorialOnBloodPicked() {                  /* game.html#tryPickup 血迹分支 */
  if (!tutorialOn) return;
  tutorialFlags.blood += 1;
}

/* 判据：cond 里每个键都要同时满足（AND）
 *
 * ★ ISSUE-110 新增「规划态」键（在玩家还没点开始行动时就成立，见 tutorialTick）：
 *   pathEnd [x,y]  路径末端正好落在这一格（「点那一格铺路径」）
 *   attackIdx n    路径第 n 步挂着攻击节点
 *   skillIdx  n    路径第 n 步挂着技能节点
 *   waits     n    路径里有 n 个等待步（第一个等待 = 闪避动作）
 *   multiAt [x,y]  该格同时有「等待步（闪避）」和「攻击节点」= 同格叠动作
 * 以及「回合态」键：
 *   rounds    n    已经结束过 n 个回合（读 battleRound 差值，不另存计数器）
 *   allDead        场上没有存活敌人（第二关清场）
 *
 * ⚠️ 为什么判据读 playerPath / attackIndices 而不是读事件：
 *   文件头设计原则 2 —— 教程只认状态。读事件意味着要在 toggleAttack / 长按 / 拖拽
 *   三个入口各插一次桩，改一处忘两处就是「教程卡住」。
 */
function tutorialCondMet(cond) {
  if (!cond) return false;
  if (cond.pos) {
    const p = (typeof player !== 'undefined') ? player : null;
    if (!p || p.x !== cond.pos[0] || p.y !== cond.pos[1]) return false;
  }
  if (typeof cond.hits === 'number' && tutorialFlags.hits < cond.hits) return false;
  if (typeof cond.kills === 'number' && tutorialFlags.kills < cond.kills) return false;
  if (typeof cond.hurt === 'number' && tutorialFlags.hurt < cond.hurt) return false;
  if (typeof cond.counter === 'number' && tutorialFlags.counter < cond.counter) return false;
  if (typeof cond.skill === 'number' && tutorialFlags.skill < cond.skill) return false;
  if (typeof cond.blood === 'number' && tutorialFlags.blood < cond.blood) return false;
  if (typeof cond.sp === 'number' && tutorialSpNow() < cond.sp) return false;
  if (cond.pathEnd) {
    let end = null;
    try { if (typeof playerPath !== 'undefined' && playerPath && playerPath.length) end = playerPath[playerPath.length - 1]; } catch (_) {}
    if (!end || end.x !== cond.pathEnd[0] || end.y !== cond.pathEnd[1]) return false;
  }
  if (typeof cond.attackIdx === 'number') {
    let ok = false;
    try { ok = (typeof attackIndices !== 'undefined') && Array.isArray(attackIndices) && attackIndices.indexOf(cond.attackIdx) >= 0; } catch (_) {}
    if (!ok) return false;
  }
  if (typeof cond.skillIdx === 'number') {
    let ok = false;
    try { ok = (typeof skillIndices !== 'undefined') && Array.isArray(skillIndices) && skillIndices.indexOf(cond.skillIdx) >= 0; } catch (_) {}
    if (!ok) return false;
  }
  if (typeof cond.waits === 'number') {
    let n = 0;
    try { n = (typeof countWaitSteps === 'function') ? countWaitSteps(playerPath) : 0; } catch (_) {}
    if (n < cond.waits) return false;
  }
  if (cond.multiAt) {
    const mx = cond.multiAt[0], my = cond.multiAt[1];
    let idxs = [];
    try {
      idxs = playerPath.map((p, i) => (p && p.x === mx && p.y === my) ? i : -1).filter(i => i >= 0);
    } catch (_) {}
    /* 同格出现 ≥2 次（其中一次是等待步）+ 其中至少一步挂着攻击节点 */
    const hasAtk = idxs.some(i => { try { return attackIndices.indexOf(i) >= 0; } catch (_) { return false; } });
    if (!(idxs.length >= 2 && hasAtk)) return false;
  }
  if (typeof cond.rounds === 'number') {
    let done = 0;
    try { done = (typeof battleRound === 'number' ? battleRound : 0) - (tutorialRoundBase || 0); } catch (_) {}
    if (done < cond.rounds) return false;
  }
  if (cond.allDead) {
    let any = false;
    try { any = (typeof enemies !== 'undefined' && enemies) ? enemies.some(e => e && e.alive) : false; } catch (_) {}
    if (any) return false;
  }
  if (cond.cont) return true;      /* 「继续」由按钮直接调 tutorialContinue() */
  return !!(cond.pos || typeof cond.hits === 'number' || typeof cond.kills === 'number'
    || typeof cond.hurt === 'number' || typeof cond.counter === 'number'
    || typeof cond.skill === 'number' || typeof cond.blood === 'number'
    || typeof cond.sp === 'number' || cond.pathEnd || typeof cond.attackIdx === 'number'
    || typeof cond.skillIdx === 'number' || typeof cond.waits === 'number'
    || cond.multiAt || typeof cond.rounds === 'number' || cond.allDead);
}

/* 进入某一步时的副作用。
 * ★ ISSUE-110：老通用课的「按步号解除巡逻敌静止」已随那套课一起删除 ——
 *   入门三关的敌人从一开始就是正常行动的（追击敌 / 逼近敌必须会动）。
 *   函数保留成空壳，是因为 game.html 与门禁都还在调用它，删掉会多出两处改动。 */
function tutorialEnterStep(idx) {
  /* 记录「本课的回合基准」：cond.rounds 用的是 battleRound 的差值，
   * 这样切课 / 重开后不用手工清零任何计数器。 */
  if (idx === 0) {
    try { tutorialRoundBase = (typeof battleRound === 'number') ? battleRound : 0; } catch (_) { tutorialRoundBase = 0; }
  }
}

/* 往前走一步；返回 'next' | 'lesson' | 'done' | false */
function tutorialAdvance(force) {
  const s = tutorialCurrentStep();
  if (!s) return false;
  if (!force && !tutorialCondMet(s.cond)) return false;
  tutorialStepIdx += 1;
  const total = tutorialLessonDef().steps.length;
  if (tutorialStepIdx >= total) {
    /* 这一课跑完 → 接下一课。
     * ★ ISSUE-110：入门三关是**一条链**（action → battle → mutual），
     *   中途切课时**不能**写「入门课已看过」的总标记 —— 否则玩家只看了第一关，
     *   下次进来就直接跳过第二、三关。
     * ★ 16:06 人类「角色课不加入链条」后，mutual 的教程走完 tutorialNextLesson() 返回 null，
     *   于是这里直接落进 tutorialEnd()（def.charId 为 null → 写总标记）→ 'done' → 回大厅。
     *   原来那行 `if (tutorialLessonId === TUTORIAL_INTRO_LAST) tutorialMarkDone()` 是给
     *   「mutual 交棒给角色课」准备的，链尾不再有下一课，它已成死代码，随本次改动删除。 */
    const next = tutorialNextLesson();
    if (next) {
      tutorialStartById(next);
      return 'lesson';
    }
    tutorialEnd();
    return 'done';
  }
  tutorialEnterStep(tutorialStepIdx);
  return 'next';
}

/* 每回合结束调用一次：条件满足就推进（不满足什么都不做，玩家可以随便走）
 * 一回合最多推进 3 步 —— 多个条件在同一个回合内被同时满足时（比如风笛一回合走满 5 格，
 * 「攒到 1 点」和「攒满 5 点」同时成立），不让玩家卡在已经做完的步骤上。
 * 上限 3 而不是无限：避免一步跳过整节课，玩家连提示条都没看清。 */
function tutorialAfterTurn() {
  if (!tutorialOn) return false;
  let result = false;
  for (let i = 0; i < 3; i++) {
    const s = tutorialCurrentStep();
    if (!s || s.cond.cont) break;      /* cont 步只能由按钮推进 */
    const r = tutorialAdvance(false);
    if (!r) break;
    result = r;
    if (r === 'lesson' || r === 'done') return r;
  }
  return result;
}

/* 提示条按钮「继续」：只对 cont 步有效 */
function tutorialContinue() {
  const s = tutorialCurrentStep();
  if (!s) return false;
  if (!s.cond.cont) return false;
  return tutorialAdvance(true);
}

/* ★ ISSUE-110：入门三关的「只许点光标格」白名单。
 * 人类原话：「注意教程要禁止玩家点其他地方，只能点光标指引的位置」。
 *
 * 放行两类格：
 *   ① 本步光标指的那一格（tutorialGuideTarget 的 x/y）—— 「该点的」；
 *   ② 路径上已有的格（**不含起点**）—— 允许改主意 / 取消节点。不放行的话点错一次
 *      就得重开，比不给点更挫败。
 * 起点（玩家脚下）刻意**不放行**：它是「原地攻击」入口，三关里没有一步需要它。
 *
 * ⚠️ 只对入门三关生效（def.intro）。角色课的判据绑在技力上、文案也没教「跟着光标点」，
 *   硬拦会让那 5 节课走不下去。
 * 返回 false = 拦下（调用方写一句提示）。 */
function tutorialClickAllowed(x, y) {
  if (!tutorialOn) return true;
  const def = tutorialLessonDef();
  if (!def || !def.intro) return true;
  const t = tutorialGuideTarget();
  if (t && typeof t.x === 'number' && t.x === x && t.y === y) return true;
  try {
    if (typeof playerPath !== 'undefined' && playerPath) {
      for (let i = 1; i < playerPath.length; i++) {
        const p = playerPath[i];
        if (p && p.x === x && p.y === y) return true;
      }
    }
  } catch (_) {}
  return false;
}

/* ★ ISSUE-110：规划态推进。
 * 入门三关的步骤全部发生在**规划阶段**（铺路径 / 设节点 / 长按等待），
 * 玩家不点开始行动就已经满足了下一步的条件。而 tutorialAfterTurn 只在回合结束时跑 ——
 * 只靠它，第一关会永远停在 a1（`pathEnd` 早就成立了，却没人来检查）。
 * 所以「路径或节点一变」就调一次本函数（game.html#pointerup / 长按回调 / 节点切换处）。
 * 返回值与 tutorialAfterTurn 一致，调用方按同样方式处理 'lesson' / 'done'。 */
function tutorialTick() {
  if (!tutorialOn) return false;
  let result = false;
  for (let i = 0; i < 4; i++) {
    const s = tutorialCurrentStep();
    if (!s || s.cond.cont) break;        /* 「继续」步只能由按钮推 */
    const r = tutorialAdvance(false);
    if (!r) break;
    result = r;
    if (r === 'lesson' || r === 'done') return r;
  }
  return result;
}

/* ★ ISSUE-教程导航：上一步按钮。只能退、不能越界。
 * 回退是「复习」——计数器只增不减，所以退回的那一步条件依然满足，
 * 下一步按钮随时能把你带回当前进度，绝不会「回看一眼就丢进度」。
 * 不写任何「已看过」标记（那是 tutorialAbort / tutorialEnd 的职责）。 */
function tutorialBack() {
  if (!tutorialOn) return false;
  if (tutorialStepIdx <= 0) return false;
  tutorialStepIdx -= 1;
  tutorialEnterStep(tutorialStepIdx);
  return true;
}

/* src: src/ui/radar.js */
/* P0.1-4 拆分 · 20261028b 基线 1185-1350 行 · 六维雷达图 drawRadar */
/* =========================================================
 * 六维雷达图
 * ========================================================= */
let charRadarLabelHits = [];   // drawRadar 写入：角色面板六维图 6 个属性文字的命中框（ISSUE-20261029-37）
function drawRadar(forceCanvas, forceAbilities) {
  const canvas = forceCanvas || radarCanvas;
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  /* ★ 角色面板六维图（#charRadarCanvas）也要记录命中区，让点击顶点文字直接加点（ISSUE-20261029-37） */
  const isChar = (canvas && canvas.id === 'charRadarCanvas');
  const recordHits = (canvas === radarCanvas) || isChar;
  if (recordHits) { if (isChar) charRadarLabelHits = []; else radarLabelHits = []; }
  const dpr = window.devicePixelRatio || 1;
  const cssW = canvas.clientWidth || 120;
  const cssH = canvas.clientHeight || 120;
  if (canvas.width !== Math.round(cssW * dpr) || canvas.height !== Math.round(cssH * dpr)) {
    canvas.width = Math.round(cssW * dpr);
    canvas.height = Math.round(cssH * dpr);
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, cssW, cssH);

  const cx = cssW / 2, cy = cssH / 2;
  const n = ABILITY_ORDER.length;
  const max = ABILITY_CAP;
  // 轴上是 2 字全称，±30° 那两根轴最容易被裁 → 按横向余量反推半径
  const labelFont = Math.max(8, Math.round(Math.min(cssW, cssH) / 13));
  const pad = 3;
  const R = Math.min(
    Math.min(cssW, cssH) / 2 - labelFont * 0.95 - pad,
    (Math.min(cssW, cssH) / 2 - labelFont * 2.45) / 0.87 - pad
  );

  let abilities = forceAbilities || null;
  if (!abilities) {
    if (phase === PHASE.CHAR_SELECT) {
      /* ISSUE-20261028-19：动态角色读候选副本（加点后立刻反映），静态角色仍读常量 */
      if (selectedCandidate) abilities = candidateAbilitiesOf(selectedCandidate.id);
    } else if (player) {
      abilities = player.abilities;
    } else if (playerStats && playerStats.abilities) {
      abilities = playerStats.abilities;
    }
  }

  ctx.strokeStyle = 'rgba(255,255,255,0.10)';
  ctx.lineWidth = 1;
  for (let ring = 1; ring <= 3; ring++) {
    const r = R * ring / 3;
    ctx.beginPath();
    for (let i = 0; i < n; i++) {
      const a = -Math.PI / 2 + (Math.PI * 2 * i) / n;
      const x = cx + Math.cos(a) * r;
      const y = cy + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.stroke();
  }
  for (let i = 0; i < n; i++) {
    const a = -Math.PI / 2 + (Math.PI * 2 * i) / n;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(a) * R, cy + Math.sin(a) * R);
    ctx.stroke();
  }

  if (abilities) {
    ctx.beginPath();
    for (let i = 0; i < n; i++) {
      const k = ABILITY_ORDER[i];
      const v = Math.max(0, Math.min(max, abilities[k] || 0));
      const r = R * v / max;
      const a = -Math.PI / 2 + (Math.PI * 2 * i) / n;
      const x = cx + Math.cos(a) * r;
      const y = cy + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fillStyle = 'rgba(78, 205, 196, 0.30)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(78, 205, 196, 0.95)';
    ctx.lineWidth = 1.8;
    ctx.stroke();

    // 最高属性（并列时都算）：数值用与「熟练项」相同的绿色，其余与属性名同色
    const LABEL_NORMAL = '#9aa';
    const LABEL_PROF = '#8fe28a';
    let topV = -1;
    for (let i = 0; i < n; i++) {
      const v = Math.max(0, Math.min(max, abilities[ABILITY_ORDER[i]] || 0));
      if (v > topV) topV = v;
    }

    // 顶点：小圆点 + 该属性的数值（沿轴外推，空间不足时往内收）
    const vFont = Math.max(8, Math.round(labelFont * 1.05));
    ctx.font = `bold ${vFont}px system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (let i = 0; i < n; i++) {
      const k = ABILITY_ORDER[i];
      const v = Math.max(0, Math.min(max, abilities[k] || 0));
      const r = R * v / max;
      const a = -Math.PI / 2 + (Math.PI * 2 * i) / n;
      const ca = Math.cos(a), sa = Math.sin(a);
      const px = cx + ca * r, py = cy + sa * r;
      ctx.beginPath();
      ctx.arc(px, py, 2.4, 0, Math.PI * 2);
      ctx.fillStyle = '#4ecdc4';
      ctx.fill();
      const outward = r + vFont * 1.25 < R;
      const off = outward ? vFont * 0.72 : -vFont * 1.0;
      const tx = px + ca * off, ty = py + sa * off;
      ctx.lineWidth = 3;
      ctx.strokeStyle = 'rgba(10,10,18,0.92)';
      ctx.strokeText(String(v), tx, ty);
      ctx.fillStyle = (v === topV) ? LABEL_PROF : LABEL_NORMAL;
      ctx.fillText(String(v), tx, ty);
    }
  }

  // 轴名：2 字全称，按左右方向对齐向外排版（避免被画布裁切）
  ctx.font = `bold ${labelFont}px system-ui, sans-serif`;
  ctx.textBaseline = 'middle';
  /* ISSUE-20261028-19：选角阶段的可加点提示要跟随候选副本（预备干员有 5 点，前四人没有）。
   * 这里不用 canAllocateNow() 是为了不让 radar.js 依赖 panels.js 的加载顺序 —— 语义完全一致。 */
  const canAlloc = !forceAbilities && ((phase === PHASE.CHAR_SELECT)
    ? (candidatePointsLeft() > 0)
    : !!(playerStats && playerStats.abilityPoints > 0 && (phase === PHASE.PLANNING || phase === PHASE.LEVELCLEAR)));
  for (let i = 0; i < n; i++) {
    const k = ABILITY_ORDER[i];
    const ang = -Math.PI / 2 + (Math.PI * 2 * i) / n;
    const ca = Math.cos(ang), sa = Math.sin(ang);
    const dist = R + pad + labelFont * 0.2;
    const lx = cx + ca * dist, ly = cy + sa * dist;
    ctx.textAlign = ca > 0.2 ? 'left' : (ca < -0.2 ? 'right' : 'center');
    const inSelect = phase === PHASE.CHAR_SELECT;
    /* 熟练项：选角时动态角色按副本现算（int > str → 远程），静态角色照旧读常量 */
    const selRanged = inSelect
      ? (selectedCandidate ? isRangedCharOf(selectedCandidate.id, abilities) : false)
      : false;
    const profMelee = inSelect ? !selRanged : !!(playerStats && playerStats.profMelee);
    const profRanged = inSelect ? selRanged : !!(playerStats && playerStats.profRanged);
    const profMark = abilities && ((k === 'str' && profMelee) || (k === 'int' && profRanged));
    let col = profMark ? '#8fe28a' : '#9aa';
    if (canAlloc) col = '#cfe6ff';           // 可加点时整体提亮，提示可点击
    ctx.fillStyle = col;
    ctx.fillText(ABILITY_FULL[k], lx, ly);
    if (recordHits) { (isChar ? charRadarLabelHits : radarLabelHits).push({ k, x: lx, y: ly, r: labelFont }); }
    /* ISSUE-20261030-74 ③：属性名外框两种状态 ——
       ① 角色面板里正在看该属性说明 → 绿色渐变描边 + 淡绿底；
       ② 可加点且未达上限 → 金色描边（原行为）。
       几何只算一次，避免两份重复代码漂移。 */
    const viewingInfo = isChar && (typeof charAbilityInfoKey !== 'undefined') && charAbilityInfoKey === k;
    if (viewingInfo || (canAlloc && abilities && abilities[k] < ABILITY_CAP)) {
      const tw = ctx.measureText(ABILITY_FULL[k]).width;
      const padX = Math.max(3, labelFont * 0.34);
      const padY = Math.max(2, labelFont * 0.22);
      const bw = tw + padX * 2;
      const bh = labelFont + padY * 2;
      let bx = (ca > 0.2) ? (lx - padX)
             : (ca < -0.2) ? (lx - tw - padX)
             : (lx - tw / 2 - padX);
      bx = Math.max(1, Math.min(cssW - 1 - bw, bx));      // 贴边时收进画布，避免被裁
      let by = ly - bh / 2;
      by = Math.max(1, Math.min(cssH - 1 - bh, by));
      const rr = Math.min(4, bh / 2);
      function roundRectPath(rx, ry, rw, rh, rrad) {
        ctx.beginPath();
        ctx.moveTo(rx + rrad, ry);
        ctx.lineTo(rx + rw - rrad, ry);
        ctx.quadraticCurveTo(rx + rw, ry, rx + rw, ry + rrad);
        ctx.lineTo(rx + rw, ry + rh - rrad);
        ctx.quadraticCurveTo(rx + rw, ry + rh, rx + rw - rrad, ry + rh);
        ctx.lineTo(rx + rrad, ry + rh);
        ctx.quadraticCurveTo(rx, ry + rh, rx, ry + rh - rrad);
        ctx.lineTo(rx, ry + rrad);
        ctx.quadraticCurveTo(rx, ry, rx + rrad, ry);
      }
      if (viewingInfo) {
        const grad = ctx.createLinearGradient(bx, by, bx + bw, by + bh);
        grad.addColorStop(0, 'rgba(120, 230, 140, 0.95)');
        grad.addColorStop(1, 'rgba(40, 180, 100, 0.95)');
        ctx.strokeStyle = grad;
        ctx.lineWidth = 2.2;
        roundRectPath(bx, by, bw, bh, rr);
        ctx.stroke();
        ctx.fillStyle = 'rgba(80, 220, 120, 0.14)';
        roundRectPath(bx, by, bw, bh, rr);
        ctx.fill();
      } else {
        ctx.strokeStyle = '#ffd700';
        ctx.lineWidth = 1.4;
        roundRectPath(bx, by, bw, bh, rr);
        ctx.stroke();
      }
    }
  }

  // 等级已移到角色卡「名字右侧」显示（金色 Lv.N），六维图中心不再绘制，保持留白。
}

/* src: src/rules/path.js */
/* P0.1-4 拆分 · 20261028b 基线 1352-1564 行 · 路径判定 / 冲锋计算 / 步数统计 */
/* =========================================================
 * 基础工具
 * ========================================================= */
function isWalkable(x, y) {
  if (phase === PHASE.CHAR_SELECT) return inBounds(x, y) && selMap[y][x] === 0;
  return inBounds(x, y) && map[y][x] === 0;
}
function faceToward(from, to) {
  const dx = to.x - from.x, dy = to.y - from.y;
  if (dx === 0 && dy === 0) return { dx: 1, dy: 0 };
  if (Math.abs(dx) >= Math.abs(dy)) return { dx: Math.sign(dx), dy: 0 };
  return { dx: 0, dy: Math.sign(dy) };
}
function isFacingTarget(unit, target) {
  if (!unit || !unit.facing) return false;
  const dx = Math.sign(target.x - unit.x);
  const dy = Math.sign(target.y - unit.y);
  if (dx === 0 && dy === 0) return false;
  return dx === unit.facing.dx && dy === unit.facing.dy;
}
function isInFacingCone(unit, target) {
  if (!unit || !unit.facing) return false;
  const dx = Math.sign(target.x - unit.x);
  const dy = Math.sign(target.y - unit.y);
  if (dx === 0 && dy === 0) return false;
  if (unit.facing.dx !== 0) {
    return dx === unit.facing.dx && Math.abs(dy) <= 1;
  } else {
    return dy === unit.facing.dy && Math.abs(dx) <= 1;
  }
}
/* ISSUE-20261030-?（远程「弱点攻击」改十字）：与 isFacingTarget（单方向）并列，
 * 远程角色用的「弱点攻击」判定 = 十字（四个直线方向，无限格）。
 *   · 目标与 unit 同行或同列（正交十字，斜向不算）；
 *   · 中间无墙遮挡（需视线，墙/障碍挡断）；
 *   · 不读 unit.facing（十字四向都算，朝向不再区分前后）。
 * 仅用于远程（阿米娅 +5 技力 / 远程弱点暴击 / 排序优先）；
 * 近战「弱点必中」仍走 isFacingTarget（单方向），此处不动。 */
function isFacingCross(unit, target) {
  if (!unit || !target) return false;
  const dx = target.x - unit.x, dy = target.y - unit.y;
  if (dx === 0 && dy === 0) return false;       // 同一格，不算
  if (dx !== 0 && dy !== 0) return false;        // 只认正交十字，斜向不算
  const stepX = Math.sign(dx), stepY = Math.sign(dy);
  let cx = unit.x + stepX, cy = unit.y + stepY;
  while (cx !== target.x || cy !== target.y) {    // 逐格检查中间是否挡墙（需视线）
    if (!inBounds(cx, cy) || map[cy][cx] !== 0) return false;
    cx += stepX; cy += stepY;
  }
  return true;
}
/* =========================================================================
 * ISSUE-20261029-41 · 朝向 = 「下一步要去的方向」（人类 2026-10-29 16:18「3 是」）
 *
 * 旧语义是「来向」：落地时写 sign(目标格 - 起点格)，即**进入**方向。
 * 于是「朝上站着 → 原地攻击 → 下一步往左走」这一拳仍按朝上判，左边的敌人吃不到弱点必中。
 *
 * facingAt(path, i) = 从路径第 i 格出发、走向下一个**移动步**的方向：
 *   · path[i+1] 与 path[i] 同格（等待步）→ 继续往后找，即「等待步不转身」；
 *   · 没有下一步移动（终点 / 整条路径都在等）→ 用「进入该格」的方向兜底
 *     （起点格没有来向，才用调用方传进来的 fallback）。
 *
 * ★ 纯函数，不读全局、不碰 DOM：结算（移动落地 / 原地攻击）与渲染（previewFacing /
 *   路径格箭头）必须用同一个它，否则「屏幕上朝哪」和「按哪判」又会分成两套。
 * ========================================================================= */
function facingAt(path, i, fallback) {
  const fb = fallback || { dx: 0, dy: 0 };
  if (!path || !path.length) return fb;
  const start = Math.max(0, Math.min(i | 0, path.length - 1));
  for (let j = start; j < path.length - 1; j++) {
    const dx = Math.sign(path[j + 1].x - path[j].x);
    const dy = Math.sign(path[j + 1].y - path[j].y);
    if (dx !== 0 || dy !== 0) return { dx, dy };
  }
  if (start > 0) {
    const dx = Math.sign(path[start].x - path[start - 1].x);
    const dy = Math.sign(path[start].y - path[start - 1].y);
    if (dx !== 0 || dy !== 0) return { dx, dy };
  }
  return fb;
}
/* 规划期的渲染朝向 = facingAt(0)，即**第一个移动步**的方向。
 * 旧实现返回「整条路径最后一步」的方向（路径尽头），与结算用的 player.facing 不是同一套；
 * 改完「屏幕上朝哪就按哪判」（ISSUE-20261029-33 的口径）。
 * startX/startY 只为兼容旧调用签名保留：path[0] 与玩家位置不一致（异常态）时，
 * 用它补一个「玩家 → path[0]」的方向。 */
function previewFacing(path, startX, startY) {
  if (!path || !path.length) return null;
  const f = facingAt(path, 0, null);
  if (f && (f.dx || f.dy)) return f;
  const dx = Math.sign(path[0].x - startX);
  const dy = Math.sign(path[0].y - startY);
  if (dx !== 0 || dy !== 0) return { dx, dy };
  return null;
}
function calcPathSignature() {
  if (!player || !enemies) return '';
  // 修复：签名必须包含玩家正在规划的路径。
  // 原来只放玩家坐标，玩家画/撤回路径时坐标没变 → 签名不变 → 敌人意图永远不重算，
  // 于是「预判玩家路径」这套逻辑完全没有触发机会。
  const pathSig = playerPath.map(p => p.x + ',' + p.y).join('>');
  /* ISSUE-20261029-28：小队成员的位置也要进签名 —— 它们是敌人的移动占位，
   * 漏了这条会让「成员走开 / 召唤出新成员」不触发敌人意图重算，箭头指向过期格子。 */
  const squadSig = (typeof squadUnits !== 'undefined' ? squadUnits : [])
    .map(s => s.x + ',' + s.y).join(';');
  /* ★ ISSUE-20261031-128：合作队友的位置同理 —— 队友走过去也是敌人要重算路径的事件，
   * 漏了这条，队友挪开后敌人箭头还指着旧格子。 */
  const coopSig = (typeof coopAllies !== 'undefined' ? coopAllies : [])
    .filter(u => u && u.alive).map(u => u.x + ',' + u.y).join(';');
  return player.x + ',' + player.y + '|' + pathSig + '|' + squadSig + '|' + coopSig + '|' +
    enemies.map(e => e.alive ? key(e.x, e.y) : 'x').join(';');
}

/* 风笛技力：路径里每段「同方向连续 ≥2 步」贡献该段长度（1 步不算直线，得 0）。
 * 等待（同格重复）和转向都会断开一段。
 *   wdds → w(1=0) + d(2=2) + s(1=0) = 2 点
 *   wwwd → w(3=3) + d(1=0)        = 3 点
 */
function pathSpGain(path) {
  if (!path || path.length < 3) return 0;
  let gain = 0, runDx = 0, runDy = 0, runLen = 0;
  const flush = () => { if (runLen >= 2) gain += runLen; runLen = 0; };
  for (let i = 1; i < path.length; i++) {
    const dx = Math.sign(path[i].x - path[i - 1].x);
    const dy = Math.sign(path[i].y - path[i - 1].y);
    if (dx === 0 && dy === 0) { flush(); runDx = 0; runDy = 0; continue; }  // 等待：断开
    if (runLen > 0 && dx === runDx && dy === runDy) { runLen++; }
    else { flush(); runDx = dx; runDy = dy; runLen = 1; }
  }
  flush();
  return gain;
}
/* 规划时预览用的技力（真实值 + 当前路径将获得的量，封顶 5） */
function wheelchairPreviewSp() {
  if (selectedChar !== 'wheelchair') return wheelchairSp;
  return Math.min(WHEELCHAIR_SP_MAX, wheelchairSp + pathSpGain(playerPath));
}
/* 冲锋模式：技力满 5 时，路径里第一个「移动步上的技能节点」就是冲锋触发点，返回其路径下标。
 * sp 省略时用「预览技力」（真实值 + 当前路径将获得的量）；结算阶段传真实值，避免重复计入增量。 */
function findChargeSkillIndex(path, sp) {
  const spNow = (sp === undefined) ? wheelchairPreviewSp() : sp;
  if (!path || spNow < WHEELCHAIR_SP_MAX) return null;
  const idxs = [...skillIndices]
    .filter(i => i > 0 && i < path.length)
    .filter(i => !(path[i].x === path[i - 1].x && path[i].y === path[i - 1].y))
    .sort((a, b) => a - b);
  return idxs.length ? idxs[0] : null;
}
function pathHasCharge(path, sp) { return findChargeSkillIndex(path, sp) !== null; }
/* 规划期预览：若在当前路径上发动冲锋，额度（= 剩余移动步数）是多少（ISSUE-20261028-01）。
 * 返回 null 表示当前不满足发动条件；返回 0 表示额度不够、发不动。 */
function previewChargeBudget(path) {
  const p = path || playerPath;
  if (!p || !player) return null;
  const idx = findChargeSkillIndex(p, wheelchairPreviewSp());
  if (idx === null) return null;
  const usedMove = countMoveSteps(p.slice(0, idx + 1));
  return Math.max(0, (player.move || 1) - usedMove);
}
/* 生成冲锋段。maxSteps = 本回合剩余移动步数（ISSUE-20261028-01）：
 * 冲锋距离不再「一路到墙」，而是最多推进 maxSteps 格——剩几步就冲几格、打几次。
 * 撞墙/出界提前结束返回 'wall'；走满额度仍未撞墙返回 'budget'（日志要区分这两种）。
 * maxSteps 省略时退回旧行为（到墙为止），仅供调试/兼容调用。 */
function computeStraightChargePath(path, trigger, maxSteps) {
  const startPos = path[trigger.endIdx];
  const dir = trigger.dir;
  const result = [];
  const limit = (maxSteps === undefined || maxSteps === null) ? Infinity : Math.max(0, maxSteps | 0);
  let cx = startPos.x, cy = startPos.y;
  let safety = 0;
  const maxSafety = COLS + ROWS + 4;
  while (safety < maxSafety) {
    if (result.length >= limit) return { chargePath: result, stopReason: 'budget' };
    safety++;
    const nx = cx + dir.dx, ny = cy + dir.dy;
    if (!inBounds(nx, ny) || map[ny][nx] === 1) {
      return { chargePath: result, stopReason: 'wall' };
    }
    result.push({ x: nx, y: ny });
    cx = nx; cy = ny;
  }
  return { chargePath: result, stopReason: 'maxSafety' };
}

/* 冲锋停下后，找出「朝向前方 maxDist 格」内的存活敌人（由近到远，遇墙截断视线）。
 * 只认朝向直线上的格子，侧后方一律不吃冲锋伤害。 */
function findFacingEnemiesWithin(origin, dir, maxDist) {
  const out = [];
  if (!origin || !dir || (!dir.dx && !dir.dy)) return out;
  for (let k = 1; k <= maxDist; k++) {
    const x = origin.x + dir.dx * k, y = origin.y + dir.dy * k;
    if (!inBounds(x, y) || map[y][x] === 1) break;      // 墙挡视线
    for (const e of enemies) {
      if (!e.alive || e.hp <= 0) continue;
      if (e.x === x && e.y === y) out.push(e);
    }
  }
  return out;
}

/* 结算冲锋「剩余额度」（ISSUE-20261028-01）：
 * 撞到没秒掉的敌人会立即停下，但剩余攻击次数不作废 —— 继续按朝向逐次输出，
 * 直到额度用完或前方 3 格内再无可命中的敌人。每次伤害与冲锋撞击一致：近战伤害骰（2d4+修正）× 2。 */
function resolveChargeRemainingHits() {
  if (!playerChargingThisTurn || !player || !player.alive || playerChargeBudget <= 0) return;
  const origin = { x: player.x, y: player.y };
  let guard = 0;
  while (playerChargeBudget > 0 && guard++ < 60) {
    const list = findFacingEnemiesWithin(origin, playerChargeDir, CHARGE_FINISH_RANGE);
    if (list.length === 0) break;
    const target = list[0];                 // 优先最近的
    const dmg = rollPlayerMeleeDamage() * 2;
    target.hp -= dmg;
    playerChargeCausedDamage = true;
    playerChargeBudget -= 1;
    playerChargeHits += 1;
    slashFx(target.x, target.y, '#ffd700');
    ringFx(target.x, target.y, '#ff4500');
    hitFlashCell(target.x, target.y);
    floatText(target.x, target.y, `冲锋追击 -${dmg}`, '#ffd700', true);
    log(`冲锋追击敌人${target.id + 1}，造成${dmg}点伤害！（剩余 ${playerChargeBudget} 次）`);
    if (target.hp <= 0) killEnemy(target, { logText: `敌人${target.id + 1}被冲锋追击击倒` });
  }
  if (playerChargeBudget > 0 && playerChargeHits > 0) {
    log(`冲锋结束：朝向前方 ${CHARGE_FINISH_RANGE} 格内已无可命中目标，剩余 ${playerChargeBudget} 次攻击作废。`);
  }
}

/* ===== 技能节点 =====
 * 技能节点由玩家「右键路径节点」设置，到达该步时发动各角色技能（见 resolveStep 的 triggerSkillNode）。
 * 是否可发动只取决于角色自己的技力/状态，因此这里集中给出「当前是否就绪」的预览信息。 */
function skillReadyInfo(path, usePreview = true) {
  switch (selectedChar) {
    case 'wheelchair': {
      const sp = usePreview ? wheelchairPreviewSp() : wheelchairSp;
      return { ready: sp >= WHEELCHAIR_SP_MAX, name: '高效冲击', spNow: sp, spMax: WHEELCHAIR_SP_MAX };
    }
    case 'vampire':
      return { ready: !vampireSkillActive && vampireSp >= VAMPIRE_SP_MAX, name: '不稳定血浆', spNow: vampireSp, spMax: VAMPIRE_SP_MAX };
    case 'fencer':
      return { ready: !fencerCounterActive && fencerSp >= FENCER_SP_MAX, name: '岩崩锤', spNow: fencerSp, spMax: FENCER_SP_MAX };
    case 'amiya':
      return { ready: amiyaBonusTargets > 0, name: '精神爆发', spNow: amiyaBonusTargets, spMax: amiyaSpMax() };
    case 'rookie':
      /* ISSUE-20261029-28：技力满 5 才能召唤，没有「部分发动」这回事 */
      return { ready: rookieSp >= ROOKIE_SP_MAX, name: '增援召唤', spNow: rookieSp, spMax: ROOKIE_SP_MAX };
    default:
      return { ready: false, name: '技能', spNow: 0, spMax: 0 };
  }
}
/* 路径上有效的技能节点下标（升序、去重；下标 0 = 起点不算） */
function skillNodesOnPath(path) {
  const p = path || playerPath;
  return [...new Set(skillIndices.filter(i => i > 0 && i < p.length))].sort((a, b) => a - b);
}
/* 攻击范围高亮用的路径下标（第一个攻击/技能节点）；没有节点则以角色当前位置为圆心 */
function rangeDisplayOrigin() {
  if (!player) return null;
  const idxs = [...attackIndices, ...skillIndices].filter(i => i < playerPath.length).sort((a, b) => a - b);
  if (idxs.length) return playerPath[idxs[0]];
  return { x: player.x, y: player.y };
}

function countMoveSteps(path) {
  let n = 0;
  for (let i = 1; i < path.length; i++) {
    if (path[i].x !== path[i-1].x || path[i].y !== path[i-1].y) n++;
  }
  return n;
}
function countWaitSteps(path) {
  let n = 0;
  for (let i = 1; i < path.length; i++) {
    if (path[i].x === path[i-1].x && path[i].y === path[i-1].y) n++;
  }
  return n;
}

/* src: src/rules/actions.js */
/* P0.1-4 拆分 · 20261028b 基线 1566-1621 行 · 动作机制与有效 AC 计算 */
/* =========================================================
 * ★ 动作机制（技能触发系统重做后）
 *
 * 主动行动只有三种，共用同一份动作预算：
 *   - 攻击：单击路径节点设攻击节点，到达该步时攻击。
 *     正对目标近战时触发「弱点必中」（dnd.js#applyFacingGuaranteedHit），伤害与暴击判定照旧。
 *   - 技能：右键路径节点设技能节点，到达该步时发动角色技能。
 *   - 闪避：路径里第一个「等待」自动成为闪避节点，AC +⌊敏捷 / 2⌋（ISSUE-20261030-60）。
 *
 * 【2026-10-29 删机制】旧的「自动补刀」被动已彻底移除 —— 本 tick 只要有动作，就对**所有**相邻
 * 敌人各补一刀，不占动作、无上限，实际占了玩家总输出的一大半；功能上和攻击节点重复。
 * 现在攻击只有一条路：设攻击节点（含弱点必中）。没有自动补刀、没有白嫖出手，不要加回来。
 *
 * 默认每回合 1 次动作（scout 的 extraAttacks 可 +1）。按路径先后先到先得，
 * 超出预算的动作在结算时报失败并写日志。
 * 技能节点占住第一个等待步且技能就绪时，技能优先，该步不结算闪避。
 * ========================================================= */
/* ISSUE-20261030-60（人类 2026-10-30 02:5x 拍板）：闪避的 AC 加成不再是固定 +3，
 * 而是 **⌊敏捷属性值 / 2⌋** —— 与「移动力 = ⌊敏捷 / 2⌋」同一套口径。
 *   dex 8 → +4 · dex 10 → +5 · dex 14 → +7
 * 人类当时否掉了另外两种候选口径：敏捷调整值再折半（dex 10 只给 +0，等于废掉闪避）
 * 与敏捷调整值本身；最终选的就是这句原话「AC + 敏捷/2」的字面算法。
 * 「危险直觉」收藏品仍按**加算 +3** 叠在这上面（relicDodgeAcBonus），与旧版 3+3=6 语义连续。
 * 取数优先级：局内 playerStats → player → 0（选角相位没建号时不该走到这里）。 */
function dodgeAcBonusBase() {
  const ab = (playerStats && playerStats.abilities) || (player && player.abilities) || {};
  return Math.floor((ab.dex || 0) / 2);
}

// 路径里第一个「等待」步的下标；没有则 -1
function firstWaitIndex(path) {
  const p = path || playerPath;
  for (let i = 1; i < p.length; i++) {
    if (p[i].x === p[i-1].x && p[i].y === p[i-1].y) return i;
  }
  return -1;
}

/* 本回合规划出来的「动作」占用情况：{ dodge, dodgeIndex, actions, skillIdxs, attackCount, skillCount, order } */
function plannedActionInfo(path, atkIdxs, skillIdxs) {
  const p = path || playerPath;
  const atk = atkIdxs || attackIndices;
  const sk = skillIdxs || skillIndices;
  const wIdx = firstWaitIndex(p);
  /* ★ ISSUE-20261029-34：技能节点的过滤口径必须与攻击节点一致（都含起点 idx 0）。
   * 旧版写 `i > 0`，于是「在原地点技能」既不占动作预算、也永远不会被结算到
   * （resolveStep 只在 pathIdx >= 1 的移动步上检查技能节点）。现在统一成 `i >= 0`：
   * 起点技能 = 本回合第一个 tick 原地发动（见 templates/game.html#resolveStep）。 */
  const skOnPath = [...new Set(sk.filter(i => i >= 0 && i < p.length))].sort((a, b) => a - b);
  const skSet = new Set(skOnPath);
  /* 技能节点占了第一个等待步：技能就绪时技能优先（这一步不闪避）；技能没就绪时仍可闪避 */
  const dodge = wIdx >= 0 && !(skSet.has(wIdx) && skillReadyInfo(p).ready);
  /* ★ 起点格（idx 0）的攻击节点也要算一个动作 —— 它是「原地攻击」，
   * 结算时走 pendingAttack 分支、同样消耗 playerActionsUsed。
   * 旧版用 `i > 0` 把它漏掉，导致「起点攻击 + 另一个攻击节点」规划期不报超限、
   * 结算时才莫名其妙打空（ISSUE-20261028-17 / BUG-STARTCELL-ATTACK）。 */
  const atkOnPath = [...new Set(atk.filter(i => i >= 0 && i < p.length))];
  const actions = (dodge ? 1 : 0) + atkOnPath.length + skOnPath.length;

  /* ★ ISSUE-20261029-34：动作显示顺序 = 实际结算顺序。
   * 旧版 UI 固定按「闪避 → 攻击 → 技能」拼类型序，与真实结算（按路径步序）相反 ——
   * 于是「原地先点攻击再点等待（闪避）」在界面上显示成「闪避+攻击」。
   * 真实顺序：
   *   ① 起点格（idx 0）的攻击 / 技能最先结算（不移动，先出手 / 先施法）；
   *   ② 其余按路径下标升序，同一下标上先闪避（步首判定）再攻击（步末出手）；
   *      攻击 / 技能可落在同一格（各算 1 件动作，受 maxActionsThisTurn 预算限制），结算按路径步序并列。
   * order 里按 kind 分组计数（组序 = 首次出现顺序），UI 直接照着渲染。 */
  const seq = [];
  if (atkOnPath.includes(0)) seq.push({ kind: 'attack', idx: 0 });
  if (skOnPath.includes(0)) seq.push({ kind: 'skill', idx: 0 });
  const stepIdxs = [...new Set([
    ...atkOnPath.filter(i => i > 0),
    ...skOnPath.filter(i => i > 0),
    ...(dodge ? [wIdx] : []),
  ])].sort((a, b) => a - b);
  for (const i of stepIdxs) {
    if (dodge && i === wIdx) seq.push({ kind: 'dodge', idx: i });
    if (skOnPath.includes(i)) seq.push({ kind: 'skill', idx: i });
    if (atkOnPath.includes(i)) seq.push({ kind: 'attack', idx: i });
  }
  const order = [];
  for (const s of seq) {
    const g = order.find(o => o.kind === s.kind);
    if (g) g.count += 1;
    else order.push({ kind: s.kind, count: 1, firstIdx: s.idx });
  }

  return {
    dodge,
    dodgeIndex: (dodge ? wIdx : -1),
    skillIdxs: skOnPath,
    attackCount: atkOnPath.length,
    skillCount: skOnPath.length,
    actions,
    order,
  };
}

// 再加一个节点会不会超出预算（用于设置节点时的提示）：
// ① 动作数 ≤ maxActionsThisTurn()（ISSUE-20261029-25 起为 2）② 攻击节点数 ≤ maxAttacksThisTurn()（仍为 1）
function nodeFitsBudget(path, atkIdxs, skillIdxs) {
  const info = plannedActionInfo(path, atkIdxs, skillIdxs);
  return info.actions <= maxActionsThisTurn() && info.attackCount <= maxAttacksThisTurn();
}
// 被拒时说清是哪条线撞的（ISSUE-20261029-25 起「动作数」与「攻击次数」是两个不同的上限，
// 一句「动作上限 2」会把玩家带偏 —— 明明只放了一个攻击节点也会被拒）
function budgetRejectReason(path, atkIdxs, skillIdxs) {
  const info = plannedActionInfo(path, atkIdxs, skillIdxs);
  if (info.attackCount > maxAttacksThisTurn()) {
    return `攻击次数上限 ${maxAttacksThisTurn()}：本回合只能出手 ${maxAttacksThisTurn()} 次（动作预算 ${maxActionsThisTurn()} 件里最多 1 件是攻击，其余留给技能/闪避）。`;
  }
  return `动作上限 ${maxActionsThisTurn()}：攻击节点 + 技能节点 + 闪避合计不能超过 ${maxActionsThisTurn()} 件。`;
}

/* ★ ISSUE-20261029-34：追加一个「等待」步（= 闪避动作）前先查预算。
 * 等待步本身不消耗移动力以外的东西，但**第一个**等待步会自动变成闪避动作（占 1 件）。
 * 旧版三处入口（等待按钮 / Q 键 / 长按 400ms）都只看「等待次数 < 移动力」，
 * 完全不查动作预算 —— 于是「攻击 + 技能 + 闪避」三件能被规划出来（预算只有 2），
 * 界面上出现红色的「3/2」，这就是「连续点会出现 3 个行动」的根因。
 * 注意：第二个及以后的等待步不会新增闪避动作，所以永远不会超预算。 */
function canAddWaitStep(path, atkIdxs, skillIdxs) {
  const p = path || playerPath;
  const last = p.length ? p[p.length - 1] : (player ? { x: player.x, y: player.y } : { x: 0, y: 0 });
  const next = [...p, { x: last.x, y: last.y }];
  if (!nodeFitsBudget(next, atkIdxs, skillIdxs)) {
    return { ok: false, reason: budgetRejectReason(next, atkIdxs, skillIdxs) };
  }
  return { ok: true, path: next };
}

/* 玩家当前有效 AC：闪避状态下额外 +N（闪避持续到本回合结束） */
function playerEffectiveAC() {
  let ac = player ? player.ac : 10;
  if (playerDodging) ac += playerDodgeACBonus;
  return ac;
}

/* src: src/ui/units.js */
/* P0.1-4 拆分 · 20261028b 基线 1623-1768 行 · 动作预算与单位渲染 */
/* ★ 动作预算（ISSUE-20261029-25 起）：一回合可以做 BASE_ACTIONS_PER_TURN = 2 件事。
 * 攻击 / 技能 / 闪避各算 1 件 —— 不再是「互斥二选一」，可以「打一拳 + 闪一次」。
 * ★ 但「攻击次数」仍由 maxAttacks（templates 里 1 + extraAttacks）单独限制，动作预算放宽不等于攻击翻倍。
 * scout（探测先锋）的 +1 加在动作预算上，所以拿到它就是 3 件事。
 * playerActionsUsed = 本回合已消耗的动作数（闪避占 1，攻击每执行一次占 1）。 */
function maxActionsThisTurn() {
  return BASE_ACTIONS_PER_TURN + (player ? player.extraAttacks : 0);
}
/* ★ 攻击次数上限（与动作预算分开）：每回合 1 次 + 探测先锋。
 * ISSUE-20261029-25 把动作预算放宽到 2 之后，这两个数不再相等 ——
 * 「2 件事」里最多只有 1 件是攻击。所有「攻击还能不能打」的判定都该用这个函数。 */
function maxAttacksThisTurn() {
  return 1 + (player ? player.extraAttacks : 0);
}
function canPerformAttackAction() {
  return playerActionsUsed < maxActionsThisTurn();
}
function clearUnitLayer() {
  unitEls.forEach(rec => rec.el.remove());
  unitEls.clear();
  /* ISSUE-20261030-90：DOM 清空了，动画层也要一起停，否则会留在棋盘上飘着 */
  if (typeof spineLayerClear === 'function') {
    try { spineLayerClear(); } catch (e) { /* 静默 */ }
  }
}
function getUnitIcon() {
  const c = CHARACTERS[selectedChar];
  return c ? c.icon : '🧝';
}
function getPlayerRenderFacing() {
  if (!player) return null;
  if (phase === PHASE.PLANNING) {
    return previewFacing(playerPath, player.x, player.y) || player.facing;
  }
  return player.facing;
}
/* ★ ISSUE-20261029-33：远程「弱点攻击」判定用的朝向。
 *   原则上用**渲染朝向**（屏幕上朝哪就按哪判定），但 previewFacing 假定
 *   playerPath[0] 就是玩家当前格 —— 万一两者不同步（异常态 / 脚本改过坐标），
 *   它会拿「路径末格 vs 玩家位置」算出一个无意义的斜向 → 判定看起来随机。
 *   所以这里加一道保险：路径起点与玩家位置不一致时，一律回退到实际朝向 player.facing。 */
function playerFacingForRanged() {
  if (!player) return null;
  const pf = player.facing;
  if (typeof getPlayerRenderFacing !== 'function') return pf;
  const p0 = playerPath && playerPath[0];
  if (!p0 || p0.x !== player.x || p0.y !== player.y) return pf;
  return getPlayerRenderFacing() || pf;
}
function isPlayerPreviewCharging() {
  if (phase !== PHASE.PLANNING) return playerChargingThisTurn || fencerCounterActive;
  return skillReadyInfo(playerPath).ready || vampireSkillActive;
}

/* =========================================================================
 * ★ ISSUE-20261030-56：同格多单位「斜向分格」
 *
 * 成因：54 号把召唤落点改成预备干员本格之后，同一格叠 2~5 个单位成了常态，
 * 而 renderUnits() 原来把 player / enemies / squadUnits / peer 一起塞进 toRender
 * 后逐个按「格子矩形 + translate」绝对定位 —— 不做任何按坐标分组 → 同格必然像素级重合；
 * 又因 squadUnits 在 player **之后** push，成员直接把玩家盖住。
 *
 * 方案：一格沿 45°（带方向左下→右上）切成 N 条斜带，第 i 个单位只显示第 i 条
 * （clip-path，样式在 templates/game.html 里按 N=2..5 穷举），内容整体平移到带中心、
 * 并按 N 缩小（图标 = --cell × 0.55 × --stk-f）。
 * N 硬上限 5（1 干员 + 4 成员，issue §6-3），所以不需要「+N 角标」之类的退化方案。
 *
 * ★ 槽位表必须是**状态的纯函数**（stackUnitsAt），不能是 renderUnits 的副产物：
 *   buildBoardHtml 画动作标记、board-fx 算浮字 / 子弹落点都要读同一张表。
 *   若读的是「上一次 renderUnits 的残留」，两处排序会不一致 → 标记跑到别人的带上。
 * ========================================================================= */
const STACK_MAX_N = 5;
/* 缩放系数表（下标 = N；N=0/1 都是 1）。图标实际像素 = --cell × 0.55 × f，
 * 桌面 --cell=74 时 N=5 约 19px，竖屏小格只够辨轮廓 —— issue §4.2 明确接受。 */
const STACK_SCALE = [1, 1, 0.72, 0.58, 0.5, 0.46];

/* 某一格上的可见单位，顺序即槽位顺序：玩家永远第 0 位（最显眼的左上斜带）。
 * ⚠️ 顺序必须与 renderUnits 里 push 的语义一致，改动要同步两边。 */
function stackUnitsAt(x, y) {
  const arr = [];
  if (player && player.alive && player.x === x && player.y === y) arr.push({ key: 'player', isPlayer: true });
  for (const e of enemies) if (e.alive && e.x === x && e.y === y) arr.push({ key: 'enemy-' + e.id, isPlayer: false });
  for (const s of (typeof squadUnits !== 'undefined' ? squadUnits : [])) {
    if (s.alive && s.x === x && s.y === y) arr.push({ key: 'squad-' + s.uid, isPlayer: false });
  }
  /* ★ ISSUE-20261031-128：合作队友。顺序排在成员之后、对手之前 —— 单人局这里是空循环，
   * 槽位表与改动前逐项一致（这是「单人零影响」的底线）。 */
  for (const a of (typeof coopAllies !== 'undefined' ? coopAllies : [])) {
    if (a && a.alive && a.x === x && a.y === y) arr.push({ key: 'coop-' + a.slot, isPlayer: false });
  }
  if (mode === 'pvp' && peer && peer.alive && peer.x === x && peer.y === y) arr.push({ key: 'peer', isPlayer: false });
  return arr;
}

/* 某个单位在这一格的槽位 { i, n }。n = 1 表示独占（不做任何斜分，与改动前完全一致）。
 * N 超过 STACK_MAX_N 时只切 5 条，多出来的压到最后一条（理论上不会发生）。 */
function unitStackSlot(key, x, y) {
  const arr = stackUnitsAt(x, y);
  const n = Math.min(arr.length, STACK_MAX_N);
  if (n <= 1) return { i: 0, n: 1 };
  let i = 0;
  for (let k = 0; k < arr.length; k++) if (arr[k].key === key) { i = k; break; }
  if (i >= n) i = n - 1;
  return { i, n };
}

/* 斜带几何：第 i 条（共 n 条）的内容偏移。
 * 带方向沿 (1,-1)（左下→右上），带内「x+y」恒定；第 i 条的中心线 x+y = (2i+1)/n，
 * 而这条线段在方格内的中点恒为 (c/2, c/2)（c = (2i+1)/n）→ **x 与 y 的偏移分量相等**。
 * 于是 N=2 时两条带就是「左上 / 右下」，玩家（i=0）永远在左上。 */
function stackSlotOffset(i, n, cellSize) {
  const k = (i + 0.5) / n - 0.5;
  return { dx: k * cellSize, dy: k * cellSize, f: STACK_SCALE[n] || 1 };
}

/* 取某单位的斜带偏移；独占一格（n=1）时返回 null —— 调用方据此「什么都不做」，
 * 保证单格单单位时与改动前逐字节一致（56 号 §7-8 的回归底线）。 */
function stackOffsetFor(key, x, y) {
  const slot = unitStackSlot(key, x, y);
  if (slot.n <= 1) return null;
  return stackSlotOffset(slot.i, slot.n, cellSizePx());
}

/* 给 buildBoardHtml 用：直接产出可拼进 innerHTML 的行内样式（含 data-stk 那套变量）。 */
function stackSlotStyleAttr(key, x, y) {
  const off = stackOffsetFor(key, x, y);
  if (!off) return '';
  const slot = unitStackSlot(key, x, y);
  return ` data-stk="${slot.n}" data-stk-i="${slot.i}" style="--stk-n:${slot.n};--stk-i:${slot.i};`
    + `--stk-f:${off.f};--stk-dx:${off.dx.toFixed(2)}px;--stk-dy:${off.dy.toFixed(2)}px"`;
}

/* ISSUE-20261030-90：让动画层能把某个单位的 emoji 隐藏/还原。
 * 为什么不是只在 renderUnits 里判断一次：runtime 和资源是异步到位的，
 * 到位那一刻没有人会再跑一遍 renderUnits，所以那个「一次判断」永远等不到。 */
function spineMarkIcon(key, hidden) {
  const rec = unitEls.get(key);
  if (rec && rec.icon) rec.icon.classList.toggle('spine-hidden', !!hidden);
}

function renderUnits() {
  /* ★ ISSUE-20261031-126：事件关里玩家由**自由移动层**（unitLayer 里的 .cand-unit）绘制，
   * 格子层保持空 —— 与选角大厅同一套处理（两者都是「非战斗相位」，都不该有战斗单位渲染）。
   * ⚠️ 这一支必须在大厅那句 `freeMoveClearEls()` **之前** return：那句话会把事件关的角色
   *   一起清掉，而事件关的 render() 是会被反复调用的（resize / 抽屉 / 进关），
   *   清完不重建就是「角色凭空消失」。重建由 render() 末尾的 freeMoveRefreshEls() 负责。 */
  if (phase === PHASE.CHAR_SELECT || phase === PHASE.EVENT || !player) { clearUnitLayer(); return; }
  /* 离开非战斗相位后，选角大厅的绝对定位角色层必须清掉（ISSUE-20261028-12），
   * 否则会留在战斗棋盘上飘着 */
  if (typeof freeMoveClearEls === 'function') freeMoveClearEls();
  const lr = unitLayer.getBoundingClientRect();
  const toRender = [];
  if (player.alive) {
    toRender.push({
      key: 'player', x: player.x, y: player.y,
      icon: getUnitIcon(), hp: player.hp, maxHp: player.maxHp,
      isPlayer: true, isGhost: false, facing: getPlayerRenderFacing(),
      /* ISSUE-20261030-90：code 只用来查「有没有对应的 Spine 资源」，查不到就继续用 emoji */
      code: selectedChar,
      /* ISSUE-20261028-10-B：被 Boss 推动后要看得见「晕」，否则玩家只会觉得「点了没反应」 */
      stunTurns: player.stunTurns || 0,
    });
  }
  for (const e of enemies) {
    if (!e.alive) continue;
    /* 图标统一由数据层提供（ISSUE-20261028-04 新增盾卫/自爆虫）
     * ★ ISSUE-20261031-132：`iconOverride` 已**退役** —— 旧 #118 用它把「被弱点打废的骷髅」
     *   画成 💀；新机制里 💀 是一个**独立类型**（`skeleton_corpse`），图标直接来自 ENEMY_STATS，
     *   不再需要单位级覆盖（留着只会让人以为骷髅还会「退化」）。
     * ★ ISSUE-20261031-120：改走 `enemyIconOf(e)` —— 猴王的 🙊/🙉/🙈 形态要按单位换脸。
     *   **仍然不写 `iconOverride` 字段**（门禁断言它不存在），形态图标是「读时计算」的。 */
    const icon = (typeof enemyIconOf === 'function') ? enemyIconOf(e) : ((ENEMY_STATS[e.type] || {}).icon || '💀');
    const isGhost = e.type === 'ghost';
    toRender.push({
      key: 'enemy-' + e.id, x: e.x, y: e.y,
      icon, hp: e.hp, maxHp: e.maxHp,
      isPlayer: false, isGhost, facing: e.facing,
      code: e.type,
      stunTurns: e.stunTurns || 0,
      /* 词缀 / 精英（ISSUE-20261028-05）：标签文字由数据层拼，渲染层只负责显示 */
      isElite: !!e.isElite,
      affixTag: enemyAffixLabel(e),
    });
  }
  /* ISSUE-20261029-28：小队成员单独一层。它们不是敌人（不入 enemies），
   * 也不吃敌人 AI，所以必须在这里单独渲染，否则召唤出来在棋盘上看不见。 */
  for (const s of (typeof squadUnits !== 'undefined' ? squadUnits : [])) {
    if (!s.alive) continue;
    toRender.push({
      key: 'squad-' + s.uid, x: s.x, y: s.y,
      icon: s.icon, hp: s.hp, maxHp: s.maxHp,
      isPlayer: false, isSquad: true, isGhost: false,
      facing: s.facing, stunTurns: 0,
    });
  }
  /* ★ ISSUE-20261031-128：合作队友单独一层（与小队成员同理 —— 它们不在 enemies 里）。 */
  for (const a of (typeof coopAllies !== 'undefined' ? coopAllies : [])) {
    if (!a || !a.alive) continue;
    toRender.push({
      key: 'coop-' + a.slot, x: a.x, y: a.y,
      icon: a.icon, hp: a.hp, maxHp: a.maxHp,
      isPlayer: false, isAlly: true, isGhost: false,
      facing: a.facing, code: a.charId, stunTurns: 0,
    });
  }
  /* 联机对战：对手是玩家控制的单位，不是敌人，单独一个渲染条目 */
  if (mode === 'pvp' && peer && peer.alive) {
    toRender.push({
      key: 'peer', x: peer.x, y: peer.y,
      icon: (CHARACTERS[peer.charId] && CHARACTERS[peer.charId].icon) || '❓',
      hp: peer.hp, maxHp: peer.maxHp,
      isPlayer: false, isPeer: true, isGhost: false,
      facing: peer.facing, code: peer.charId, stunTurns: 0,
    });
  }
  for (const u of toRender) {
    if (unitEls.has(u.key)) continue;
    const el = document.createElement('div');
    el.className = 'unit-abs';
    el.style.transition = 'none';
    el.innerHTML = `
      <div class="facing-ind" style="display:none"></div>
      <div class="icon"></div>
      <div class="hp-bar"><div class="hp-fill"></div></div>
      <div class="affix-tag" style="display:none"></div>
    `;
    unitLayer.appendChild(el);
    unitEls.set(u.key, {
      el,
      icon: el.querySelector('.icon'),
      hpFill: el.querySelector('.hp-fill'),
      facingEl: el.querySelector('.facing-ind'),
      affixEl: el.querySelector('.affix-tag'),
      lastPos: null,
    });
  }
  const positions = new Map();
  for (const u of toRender) {
    const cell = getCellEl(u.x, u.y);
    if (cell) {
      const r = cell.getBoundingClientRect();
      positions.set(u.key, {
        left: r.left - lr.left, top: r.top - lr.top,
        w: r.width, h: r.height, feet: null,
      });
    }
  }
  /* ★ ISSUE-20261030-56：按坐标分组 → 斜带槽位。
   * 排序直接由 stackUnitsAt 给出（玩家永远第 0 位），这里只读不算，
   * 保证 buildBoardHtml 的动作标记与 board-fx 的浮字拿到的是同一套槽位。 */
  for (const u of toRender) {
    const slot = unitStackSlot(u.key, u.x, u.y);
    u.stackIndex = slot.i;
    u.stackCount = slot.n;
  }
  const maxAtk = 1 + player.extraAttacks;
  const playerCharging = isPlayerPreviewCharging();
  const playerAttacked = playerAttacksDone >= maxAtk;
  for (const u of toRender) {
    const rec = unitEls.get(u.key);
    const pos = positions.get(u.key);
    if (!rec || !pos) continue;
    rec.el.style.width = pos.w + 'px';
    rec.el.style.height = pos.h + 'px';
    if (rec.lastPos === null) {
      rec.el.style.transform = `translate(${pos.left}px, ${pos.top}px)`;
      void rec.el.offsetWidth;
      rec.el.style.transition = '';
    } else if (rec.lastPos.left !== pos.left || rec.lastPos.top !== pos.top) {
      rec.el.style.transform = `translate(${pos.left}px, ${pos.top}px)`;
    }
    rec.lastPos = { left: pos.left, top: pos.top };
    /* ★ ISSUE-20261030-56：把斜带参数挂到 .unit-abs 上（clip-path 由 CSS 按 data-stk 穷举）。
     * N=1 时一个属性都不挂 —— 单格单单位的 DOM 与改动前完全一致，不能残留 clip-path。 */
    if (u.stackCount > 1) {
      const off = stackSlotOffset(u.stackIndex, u.stackCount, pos.w);
      rec.el.dataset.stk = String(u.stackCount);
      rec.el.dataset.stkI = String(u.stackIndex);
      rec.el.style.setProperty('--stk-n', String(u.stackCount));
      rec.el.style.setProperty('--stk-i', String(u.stackIndex));
      rec.el.style.setProperty('--stk-f', String(off.f));
      rec.el.style.setProperty('--stk-dx', off.dx.toFixed(2) + 'px');
      rec.el.style.setProperty('--stk-dy', off.dy.toFixed(2) + 'px');
    } else if (rec.el.dataset.stk) {
      delete rec.el.dataset.stk;
      delete rec.el.dataset.stkI;
      rec.el.style.removeProperty('--stk-n');
      rec.el.style.removeProperty('--stk-i');
      rec.el.style.removeProperty('--stk-f');
      rec.el.style.removeProperty('--stk-dx');
      rec.el.style.removeProperty('--stk-dy');
    }
    /* ★ ISSUE-20261030-64：棋盘单位图标换矢量。
     * 原来是拿 textContent 做脏判断，换成 <svg> 后 textContent 恒为空 → 改用 dataset 记上一次的值。 */
    if (rec.icon.dataset.ico !== u.icon) { rec.icon.innerHTML = iconify(u.icon); rec.icon.dataset.ico = u.icon; }
    rec.icon.classList.toggle('ghost-icon', !!u.isGhost);
    /* ISSUE-20261030-90：这个单位已经被 Spine 画布接管 → 只把 emoji 变透明，节点/布局/命中全不动 */
    if (typeof spineLayerShows === 'function') {
      rec.icon.classList.toggle('spine-hidden', !!spineLayerShows(u.code));
    }
    /* 词缀标签：无词缀时藏起来，避免空格子挂一个空胶囊 */
    if (rec.affixEl) {
      const tagText = u.affixTag || '';
      if (rec.affixEl.textContent !== tagText) rec.affixEl.textContent = tagText;
      rec.affixEl.style.display = tagText ? 'flex' : 'none';
    }
    const pct = u.maxHp > 0 ? Math.max(0, Math.min(100, (u.hp / u.maxHp) * 100)) : 0;
    rec.hpFill.style.width = pct + '%';
    rec.hpFill.style.background = u.isPlayer ? '#3b9eff'
      : (u.isAlly ? '#2ee6c8' : (u.isPeer ? '#e8a33d' : (u.isSquad ? '#4ade80' : '#e74c3c')));
    if (u.facing) {
      const v = FACING_GLYPH[u.facing.dx + ',' + u.facing.dy];
      if (v) {
        rec.facingEl.style.display = 'flex';
        rec.facingEl.textContent = v[0];
        rec.facingEl.className = 'facing-ind ' + v[1];
      } else rec.facingEl.style.display = 'none';
    } else {
      rec.facingEl.style.display = 'none';
    }
    if (u.isPlayer) {
      rec.el.classList.add('ua-player');
      rec.el.classList.remove('ua-enemy', 'ua-stunned');
      rec.el.classList.toggle('ua-charging', playerCharging);
      rec.el.classList.toggle('ua-attacked', playerAttacked && !playerCharging);
    } else if (u.isPeer) {
      rec.el.classList.add('ua-peer');
      rec.el.classList.remove('ua-player', 'ua-enemy', 'ua-charging', 'ua-attacked', 'ua-stunned');
    } else if (u.isSquad) {
      /* 友军绿框：与玩家的青框、敌人的红框区分开，避免被误认成敌人 */
      rec.el.classList.add('ua-squad');
      rec.el.classList.remove('ua-player', 'ua-enemy', 'ua-peer', 'ua-charging', 'ua-attacked', 'ua-stunned', 'ua-elite');
    } else {
      rec.el.classList.add('ua-enemy');
      rec.el.classList.remove('ua-player', 'ua-charging', 'ua-attacked');
      rec.el.classList.toggle('ua-stunned', u.stunTurns > 0);
      rec.el.classList.toggle('ua-elite', !!u.isElite);
    }
  }
  const seen = new Set(toRender.map(u => u.key));
  for (const [k, rec] of unitEls) {
    if (!seen.has(k)) { rec.el.remove(); unitEls.delete(k); }
  }
  /* ★ ISSUE-20261030-90：同步 Spine 动画层。
   * 放在最后一步、且外面裹 try —— 任何异常都只能让动画层自己死掉，
   * 不允许它把 renderUnits 的 DOM 结果带崩（玩法不变是硬要求）。
   * 这里的 positions 已经是「单位层坐标」，动画层直接复用，**不再多读一次 rect**。 */
  if (typeof spineLayerSync === 'function') {
    try {
      /* 脚底 = 血条上沿。必须等上面那个循环把宽高/transform 都写完了才读得准，
       * 否则读到的是还没布局的空盒子（血条高度 0）。 */
      for (const u of toRender) {
        const pos = positions.get(u.key);
        const rec = unitEls.get(u.key);
        if (!pos || !rec) continue;
        const bar = rec.el.querySelector('.hp-bar');
        if (bar) {
          const br = bar.getBoundingClientRect();
          if (br.height > 0) pos.feet = br.top - lr.top - 1;
        }
      }
      spineLayerSync(toRender.map(u => ({
        key: u.key,
        code: u.code,
        dir: u.facing ? Math.sign(u.facing.dx || 0) : 0,
      })), positions);
    } catch (e) { /* 静默：动画层自己的事 */ }
  }
}

/* src: src/ui/action-pips.js */
/* ISSUE-20261030-77 · 动作 UI = 一排「棋盘格大小」的小方块（人类 2026-10-30 17:20）
 *
 * 方块边长走 CSS 变量 --apip，**恒等于棋盘格 --cell**（ISSUE-20261101-137 起取消桌面封顶：
 * UI 改成 11×11 大格栅后，方块与棋盘格同边长才是「嵌在格子里」的本义）。
 * 计算在 templates/game.html#updateCellSize。
 *
 * 原来的文本（`攻击×1+技能×1 2/2`）全部删除，改由方块的数量与颜色表达：
 *   · 方块总数 = 移动力 + 动作预算   （泥岩 dex8 → 4 移动 + 2 动作 = 6 格）
 *   · 每消耗一件动作点亮一格，按**真实消耗顺序**从左往右
 *   · 额外行动（extraAttacks）会把动作预算 +1，方块自动多一格
 *   · 攻击格在结算完伤害后，格子中心显示这次攻击的**总伤害**
 *
 * 两个显示态：
 *   规划态（PLANNING）  空心描边 —— 「我已经排了这么多」，还没花出去
 *   执行态（RESOLVING） 实心     —— 「这一格已经花掉了」
 *
 * ★ 颜色必须与棋盘同格动作标记（ISSUE-20261030-74 的同心方框）一致，不许另立一套。
 *   唯一例外是「移动」——74 号没有移动概念，人类本次指定移动 = 蓝。
 */

const ACTION_PIP_COLOR = {
  move:   '#3aa0ff',   // 蓝（人类 17:20 指定「移动 → 第一个格子变蓝」）
  attack: '#ff5a5a',   // 红（沿用 ISSUE-20261030-74）
  skill:  '#b06bff',   // 紫（沿用 ISSUE-20261030-74）
  dodge:  '#22d3ee',   // 青（本条推定：不能再用蓝，会和移动撞色）
};
const ACTION_PIP_IDLE = '#3a3a4e';   // 未使用的格子（人类原话「6 个灰色格子」）

/* 本回合最多能亮几个格子。
 * `player.move` 是本回合移动力（src/rules/dnd.js:142 = ⌊dex/2⌋ + 收藏品加成），
 * `maxActionsThisTurn()` 是攻击/技能/闪避共用的动作预算（src/ui/units.js:7）。
 * 取 max(1) 兜底：选角相位 / 异常态下不该出现 0 格容器。 */
function actionPipTotal() {
  const mv = (player && player.move) ? player.move : 0;
  return Math.max(1, mv + maxActionsThisTurn());
}

/* 规划态的格子序列（尚未花出去的那一份），顺序 = 真实结算顺序。
 *
 * 与 plannedActionInfo 的 order 不同：order 只给「按类型分组的计数」，这里要的是
 * 「第 N 格是什么颜色」这种逐格序列，所以自己按路径走一遍：
 *   ① 起点格（idx 0）的攻击 / 技能最先结算（不移动，先出手）；
 *   ② 之后每一格：能移动就先移动（移动 = 花一格），再判闪避（第一个等待步），再技能，再攻击。
 * 同一格上「移动 + 动作」是两件事，各自一格 —— 与结算时先走位再出手的顺序一致。 */
function actionPipPlan() {
  const p = playerPath || [];
  const seq = [];
  if (!p.length) return seq;
  const atkSet = new Set(attackIndices.filter(i => i >= 0 && i < p.length));
  const skSet = new Set(skillIndices.filter(i => i >= 0 && i < p.length));
  const plan = plannedActionInfo(p, attackIndices, skillIndices);

  if (atkSet.has(0)) seq.push('attack');
  if (skSet.has(0)) seq.push('skill');
  for (let i = 1; i < p.length; i++) {
    if (p[i].x !== p[i - 1].x || p[i].y !== p[i - 1].y) seq.push('move');
    if (plan.dodge && plan.dodgeIndex === i) seq.push('dodge');
    if (skSet.has(i)) seq.push('skill');
    if (atkSet.has(i)) seq.push('attack');
  }
  return seq;
}

/* 记一件「已消耗」的动作。返回记账对象本身，攻击结算完拿它回写伤害。
 * 只改数据 + 局部重绘，不重建按钮（重建会丢 hover / 焦点，也会让动画闪烁）。 */
function noteActionPip(kind) {
  const rec = { kind: kind, dmg: null };
  actionPipLog.push(rec);
  renderActionPips();
  return rec;
}

/* 攻击打完把本次总伤害写到格子中心。dmg<=0 不写（挥空 / 被护盾吃光）。 */
function finishActionPip(pip, dmg) {
  if (!pip) return;
  pip.dmg = (typeof dmg === 'number' && dmg > 0) ? Math.round(dmg) : null;
  renderActionPips();
}

/* 动作被退回时撤销刚点亮的那一格。
 * 目前唯一用法：预备干员「增援召唤」满编失败 → playerActionsUsed -= 1 同时把格子退掉
 * （见 templates/game.html#triggerSkillNode）。不退的话 UI 会显示已经花掉、实际没花。 */
function revokeActionPip(pip) {
  const i = actionPipLog.indexOf(pip);
  if (i < 0) return;
  actionPipLog.splice(i, 1);
  renderActionPips();
}

function actionPipsHtml() {
  const total = actionPipTotal();
  const resolving = (phase === PHASE.RESOLVING);
  const plan = resolving ? null : actionPipPlan();
  const out = [];
  for (let i = 0; i < total; i++) {
    let kind = null, dmg = null, cls = '';
    if (resolving) {
      const rec = actionPipLog[i];
      if (rec) { kind = rec.kind; dmg = rec.dmg; cls = 'on'; }
    } else if (plan && i < plan.length) {
      kind = plan[i];
      cls = 'plan';
    }
    const color = kind ? ACTION_PIP_COLOR[kind] : ACTION_PIP_IDLE;
    const txt = (dmg != null) ? String(dmg) : '';
    /* 格子边长走 --apip（桌面封顶 22px），字号必须按它算而不是 --cell，
       否则桌面端 50px 的字号塞进 22px 的格子会顶破。1 位 .62 / 2 位 .52 / 3 位 .40 */
    const fs = txt.length >= 3 ? '.40' : (txt.length === 2 ? '.52' : '.62');
    const style = '--pc:' + color + (txt ? ';font-size:calc(var(--apip, var(--cell)) * ' + fs + ')' : '');
    out.push('<span class="apip' + (cls ? ' ' + cls : '') + '" style="' + style + '">' + txt + '</span>');
  }
  return out.join('');
}

/* 只刷内容，不碰宿主元素 —— PLANNING 的按钮与 RESOLVING 的占位框共用同一个 id。 */
function renderActionPips() {
  const host = document.getElementById('actionPips');
  if (!host) return;
  const html = actionPipsHtml();
  if (host.innerHTML !== html) host.innerHTML = html;
}

/* src: src/rules/reset.js */
/* P0.1-4 拆分 · 20261028c 基线 1908-2003 行 · 状态重置（整局 / 整轮两级收敛）：freshRelics / clearLevelUpOverlay / resetSkillState / resetRunProgress / resetTurnState / createPlayerStats / createPlayerUnit / syncPlayerFromStats */
/* =========================================================
 * ★ 状态重置：开局 / 换角色 / 通关 / 回合切换
 * 原来同一个变量表在 initCharSelect、selectCharacter、initLevel、
 * confirmAction、endRound 里各抄了一份，新增状态时极容易漏清。
 * 这里按「整局 / 整轮」两级收敛。
 * ========================================================= */
/* ★ ISSUE-20261028-06：独立 relics 层已删除，整局重置改用统一收藏品字典。
 * freshRelics() 定义在 src/rules/relics.js（收藏品层），这里只调用 —— 不要在这里再抄一份，
 * key 由 RELIC_POOL 生成，往池子里加收藏品时不需要回来补。 */
function clearLevelUpOverlay() {
  document.querySelectorAll('.lv-mask').forEach(m => m.remove());
}
/* 技力与角色专属技能状态（换角色 / 重开时清零） */
function resetSkillState() {
  fencerSp = 0;
  wheelchairSp = 0;
  vampireSp = 0;
  vampireSkillActive = false;
  amiyaBonusTargets = 0;
  /* ISSUE-20261029-28：预备干员技力 + 小队成员一起清。
   * ⚠️ 这里只能在「换角色 / 重开」清 —— 跨关（initLevel）要保留技力，别挪过去。 */
  rookieSp = 0;
  squadUnits = [];
  lastSquadType = null;
}
/* 整局成长：等级 / 经验 / buff / 护盾 / 升级弹窗 */
function resetRunProgress() {
  /* ISSUE-20261030-52：整局击杀累计，新的一局从 0 开始（不在 initLevel 归零，
     那里每关都跑一次）。 */
  runKills = 0;
  /* 同上：告诉外壳「新的一局开始了」→ 解除成绩上报的「同局只报一次」标记。
     派发失败不能影响开局，所以包 try/catch。 */
  try { window.dispatchEvent(new CustomEvent('ark:runstart')); } catch (e) {}
  levelHpBonus = 0;
  heroLevel = 1;
  xp = 0;                       // 漏重置 → 二周目带经验开局
  pendingLevelUps = 0;
  levelStartHp = 0;
  levelActions = 0;
  relics = freshRelics();
  playerShield = 0;
  levelUpOpen = false;
  lastLevelUpConMod = 0;
  /* ISSUE-20261028-06：收藏品相关的一次性 / 跨关状态 —— 全部是本局级，换局必须清。
   * 注意 nextLevelEnemyDelta（事件给的下一关敌人数修正）也在这里归零：
   * 它在 initLevel 里是「用完才清」，重开时补清一次，避免上局残留影响新局第 1 关。 */
  relicShieldUsedThisLevel = false;
  relicEchoArmed = false;
  relicMaxHpPenalty = 0;
  nextLevelEnemyDelta = 0;
  relicLevelsCleared = 0;
  relicOfferPendingCount = 0;
  relicOfferOpen = false;
  relicOfferChoices = [];
  levelEventDue = false;
  levelEventOpen = false;
  levelEventData = null;
  /* ★ ISSUE-20261031-126：双关卡计数器 + 事件关状态，全部是本局级 → 换局必须归零。
   * ⚠️ `level` 的归零在 selectCharacter() 里（`level = 1`），不在这里 —— 本函数也可能被
   *    「同一局内重来」复用，动 level 会打乱外部刚设好的值。battleLevel 相反必须归 0：
   *   initLevel() 开头会 `battleLevel += 1`，不归零就会从上一局的数字接着涨。 */
  battleLevel = 0;
  battleLevelsCleared = 0;
  eventLevelData = null;
  eventExit = { x: 5, y: 0 };
  eventExitOpen = false;
  eventObjects = [];
  eventActor = null;
  eventPendingObject = null;
  /* ISSUE-20261030-80：金币是整局级资源，换局 / 换角色必须归零。
   * 声明在 src/rules/currency.js，**不要挪到 initLevel** —— 那里每关都跑，会把攒的钱冲掉。 */
  currency = 0;
  clearLevelUpOverlay();
  resetSkillState();
}
/* 一回合内的临时状态（每回合开始 / 结束时都清）。
 * clearCounter=true 时连反击状态一起清（回合结束时需要）。 */
function resetTurnState({ clearCounter = false } = {}) {
  playerChargingThisTurn = false;
  playerAttacksDone = 0;
  playerActionsUsed = 0;
  actionPipLog = [];   // ISSUE-20261030-77：动作 UI 小方块每回合从全灰重来
  playerDodging = false;
  playerDodgeACBonus = 0;
  dodgeTriggerIndex = -1;
  dodgeResolved = false;   // ISSUE-20261029-40：闪避已结算标记，每回合重来
  pendingAttack = false;
  pendingStartSkill = false;
  pendingChargeInfo = null;
  playerChargeStopReason = null;
  playerChargeCausedDamage = false;
  playerChargeBudget = 0;
  playerChargeHits = 0;
  if (clearCounter) fencerCounterActive = false;
}

function createPlayerStats(charId) {
  const char = CHARACTERS[charId];
  return {
    charId: charId,                 /* ISSUE-19：动态熟练要靠它认人，别去读全局 selectedChar */
    abilities: { ...char.abilities },
    profMelee: char.profMelee,
    profRanged: char.profRanged,
    /* ISSUE-20261028-19：数据驱动 —— 只有声明了 startAbilityPoints 的角色开局带点（预备干员 5），
     * 其余四人缺省 0。不要在这个共用入口里写 if (charId === 'rookie')。 */
    abilityPoints: char.startAbilityPoints || 0,
    currentHp: 0,
    extraTargets: 0,
    extraAttacks: 0,
    critChance: BASE_CRIT_CHANCE,   // ISSUE-20261028-06：磨刀石在此之上叠加（常量在 src/rules/relics.js）
  };
}
function createPlayerUnit(start) {
  return {
    x: start.x, y: start.y,
    hp: playerStats.currentHp, maxHp: playerStats.maxHp,
    move: playerStats.move, range: PLAYER_RANGE,
    rangedDmg: playerStats.rangedDmg,
    meleeDmg: playerStats.meleeDmg,
    critChance: playerStats.critChance,
    extraTargets: playerStats.extraTargets,
    extraAttacks: playerStats.extraAttacks,
    visibleSteps: playerStats.visibleSteps,
    abilities: playerStats.abilities,
    ac: playerStats.ac,
    prof: playerStats.prof,
    meleeProf: playerStats.meleeProf,
    rangedProf: playerStats.rangedProf,
    alive: true, facing: { dx: 1, dy: 0 },
    /* ISSUE-20261028-10-B：被圆岩巨像推动后的眩晕计数。
     * 每关重建玩家单位 → 跨关不会残留眩晕（进新关永远是清醒的）。 */
    stunTurns: 0,
  };
}
/* 加点 / 升级后把派生面板同步到战斗单位（唯一入口，避免两边字段漂移） */
function syncPlayerFromStats() {
  if (!player) return;
  player.maxHp = playerStats.maxHp;
  player.move = playerStats.move;
  player.meleeDmg = playerStats.meleeDmg;
  player.rangedDmg = playerStats.rangedDmg;
  player.visibleSteps = playerStats.visibleSteps;
  player.abilities = playerStats.abilities;
  player.ac = playerStats.ac;
  player.prof = playerStats.prof;
  player.meleeProf = playerStats.meleeProf;
  player.rangedProf = playerStats.rangedProf;
}

/* src: src/ui/char-select.js */
/* P0.1-4 拆分 · 20261028c 基线 2005-2050 行 · 角色选择流程：initCharSelect / selectCharacter
 * 2026-10-28 追加「非战斗相位平滑自由移动」（ISSUE-20261028-12）与「大厅无障碍」（ISSUE-20261028-13）。
 * 2026-10-29 追加「联机 UI 独立成地图入口」（ISSUE-20261029-46）。 */

/* =========================================================================
 * ★ ISSUE-20261029-46：选角厅的两个「入口实体」
 *   selExit        🚪 开始游戏 —— 人类坐标 (5,10) → **代码 (5,0)**（见 initCharSelect）
 *   selOnlineExit  🌐 联机大厅入口 —— 人类坐标 (10,5) → **代码 (10,5)**（ISSUE-20261030-63 右移一格）
 * ⚠️ 坐标换算（本 issue 最容易搞反的地方）：人类描述 y 从**下往上**，代码 y 从上往下，
 *    棋盘 11×11 → **代码 y = 10 − 人类 y**。所以人类 y=10（最上一行）→ 代码 y=0；
 *    人类 y=0（最底一行）→ 代码 y=10；人类 y=5 换算后仍是 5。
 * x=9 是可走的：选角厅只有左右两列（x=0 / x=10）是墙。
 * ========================================================================= */
let selOnlineExit = { x: 10, y: 5 };
/* ★ ISSUE-20261031-94（v2）：教程入口 🎓 由「单格 (6,0)」改成一个 **3×3 区域**，
 *   区域里只显示**一个大图标**（人类 2026-10-31 原话：「教程入口放在 (4,7) 到 (6,9)，
 *   用 3*3 的格子显示这个大图标」）。
 *
 * ⚠️ 坐标换算再强调一次（本 issue 最常搞反的地方）：人类 y 从**下往上**数，
 *    代码 y 从上往下 → **代码 y = 10 − 人类 y**。所以
 *      人类 (4,7) → 代码 (4,3)      人类 (6,9) → 代码 (6,1)
 *    区域在代码里是 **x ∈ [4,6]，y ∈ [1,3]**，中心格 = **(5,2)**。
 *    顺手核对：🚪 在代码 (5,0)、5 个角色在代码 y=10，三者互不重叠。
 *
 * ⚠️ 9 格必须全部显式挖开（`selMap[y][x] = 0`），否则渲染分支 `m[y][x] === 1` 先命中，
 *    玩家看到的是一块普通石头 —— 与 🚪/🌐 同一个坑。
 *
 * ★ 为什么渲染只画**中心格**：9 个格子各画一个 🎓 出来就是「九宫格贴纸」，不是大图标。
 *   中心格用 overflow:visible + 绝对定位覆盖层才画得出一块连续的 3×3 面板（见 game.html 的
 *   `.cell.tut-core`）。剩下 8 格保持普通地面，被覆盖层盖住，玩家看到的是一个整体。 */
const SEL_TUT_ZONE = { x0: 4, y0: 1, x1: 6, y1: 3 };
/* 中心格（走位判定 / 渲染落点 / 兼容旧的单点写法都读它） */
let selTutExit = { x: 5, y: 2 };
/* 坐标是否落在 3×3 教程区里 */
function selTutInZone(x, y) {
  return x >= SEL_TUT_ZONE.x0 && x <= SEL_TUT_ZONE.x1
      && y >= SEL_TUT_ZONE.y0 && y <= SEL_TUT_ZONE.y1;
}

/* 联机地图阶段：'' = 不在联机地图（普通选角厅）／'lobby' = 联机大厅／'room' = 联机房间（显示房间码）。
 * ★ 必须声明在这里（而不是联机面板那一块）：freeMove* 一族要读它来判
 *   「联机地图里的 🚪 是返回而不是开始游戏」，而它们整个都在脚本最前的 default 槽里定义，
 *   声明晚了在旧浏览器/裁剪版上可能踩 TDZ。 */
let onlineStage = '';
/* 建房后那张房间地图上要显示的**五位**房间码（'' = 不显示）。
 * 渲染位置：代码底行 y = ROWS-1 = 10，x 从 3 到 7（人类「最底下一行 (0,3)~(0,7)」）。 */
let onlineRoomCode = '';

function initCharSelect() {
  phase = PHASE.CHAR_SELECT;
  /* ★ ISSUE-2026-10-31：教程进行中点「⟲ 重开」，说明区与光标指引没有消失。
   * 根因：之前全线没有任何一处在这条路上关教程 —— chrome.js 的 logResetBtn 直接
   * 调 initCharSelect()，tutorialOn 仍为 true，而教书 UI 只在 renderTutorialBar() 里
   * 收（它会在 !tutorialOn 时摘掉 #tutText/#tutCursor 的 .on class），没人调它就没人收。
   * 更隐蔽的一半：tutorialMapOverride / tutorialDecorateEnemies 这些钩子还全部生效，
   * 玩家在选角厅选角色进去，会继续被当成教程（地图被换成手写关）。
   * 这里用 tutorialAbort()（不写「已看过」标记）——半途退出不算学过，下次还得重看。
   * 顺序上必须在这里：本函数是「回到选角大厅」的唯一出口，改一处顶改所有入口。 */
  if (typeof tutorialAbort === 'function') tutorialAbort();
  if (typeof renderTutorialBar === 'function') renderTutorialBar();
  setDebugMode(false);
  lastPathSignature = '';
  /* 新的一局 = 新的种子（ISSUE-20261028-03）：敌人成长按 RUN_SEED 推演，
   * 不重掷的话「重开」会得到和上一局完全相同的敌人面板序列。联机进入房间后由服务器再覆盖。 */
  seedRng(Date.now());
  resetTurnState({ clearCounter: true });
  resetRunProgress();
  isMoving = false;
  dragging = false;
  dragDownCell = null;
  hasDragged = false;
  clearTimeout(pressTimer);
  clearUnitLayer();
  ROWS = BOARD_ROWS; COLS = BOARD_COLS;
  /* ★ ISSUE-20261029-29：选角厅改版（人类 04:42）
   *   「选角界面改成角色在最后一行并列，第一行中间的位置放开始游戏的出口」。
   * 旧布局：外圈四周全是墙，5 个角色散在左上区域，出口在右侧中间 (7,4)。
   * 新布局：
   *   - 左右两列仍是墙（保留「厅堂有边界」的框感，也避免角色走出画面）；
   *   - 第 0 行整行可走 → 中间那格放出口 🚪；
   *   - 最后一行（ROWS-1）整行可走 → 5 个角色在这一行居中并列（x = 2..6）。
   * ★ ISSUE-20261029-46：出口由 (4,0) 挪到 **(5,0)**（人类「开始游戏的门 → (5,10)」，
   *   人类 y=10 是最上一行 → 代码 y = 10 − 10 = 0，x 不变）；
   *   并在 (10,5) 新增联机入口 🌐（人类 (10,5) → 代码 (10,5)，ISSUE-20261030-63 由 (9,5) 右移）。
   * ★ 上下两行必须显式开成可走：freeMove 的夹取范围与「墙」判定都读 selMap，
   *   若留着旧的外圈墙，角色会卡在 y=1..7，永远够不到第 0 行的出口。 */
  selMap = Array.from({ length: ROWS }, () => Array(COLS).fill(0));
  for (let i = 0; i < ROWS; i++) { selMap[i][0] = 1; selMap[i][COLS - 1] = 1; }
  /* 内部不再摆任何阻挡物（ISSUE-20261028-13 方案 A）：大厅是选角厅，不是战场。
   * 联机 9×9 竞技场不再复用这张图，改用 buildPvpArena() 的独立快照，联机地形一格不变。 */
  selExit = { x: 5, y: 0 };
  selMap[selExit.y][selExit.x] = 0;
  /* ★ ISSUE-20261031-94（v2）：3×3 教程区 9 格全部挖开（见声明处注释）。 */
  for (let y = SEL_TUT_ZONE.y0; y <= SEL_TUT_ZONE.y1; y++) {
    for (let x = SEL_TUT_ZONE.x0; x <= SEL_TUT_ZONE.x1; x++) selMap[y][x] = 0;
  }
  /* ★ ISSUE-20261030-63：联机入口由 (9,5) 右移到 (10,5)。
   * ⚠️ 地图只有 11 列，第 0 列与第 COLS-1 列（x=10）整列是墙 —— 不把它挖开，
   *    入口会落在墙里：渲染分支里 `m[y][x] === 1` 先命中，content 会被判成岩石/干脆不画，
   *    玩家看到的就是「右墙中间一块普普通通的石头」。挖开之后它更像一扇开在墙上的传送门。 */
  selMap[selOnlineExit.y][selOnlineExit.x] = 0;
  /* 回到选角厅 = 离开联机地图（房间码 / 大厅阶段一并清）。
   * ⚠️ 这里只清**地图标记**，不断连：断连要发 /api/quit，那是 chrome.js 的 onlineQuit()，
   *    它先断连再调本函数。反过来本函数也被「重开」复用，不能顺手把联机掐了。 */
  onlineStage = '';
  onlineRoomCode = '';
  /* 5 个角色在最后一行并列：9 列去掉两侧墙剩 7 格，取中间 5 格（x = 2..6）居中。
   * 顺序沿用原顺序（风笛 / 华法琳 / 泥岩 / 阿米娅 / 预备干员），索引变了不影响任何逻辑。 */
  charCandidates = ['wheelchair', 'vampire', 'fencer', 'amiya', 'rookie'].map((id, i) => {
    const x = 2 + i, y = ROWS - 1;
    return { id, x, y, fx: x, fy: y, alive: true };
  });
  selectedCandidate = null;
  /* 回大厅 = 说明层必须收起（charSheetOpen 是下面声明的 let，本函数在运行时才被调用，无 TDZ 风险） */
  charSheetOpen = false;
  /* ISSUE-20261028-19：新的一局 → 清空候选属性副本与剩余点数。
   * 只在 initCharSelect 清（B4）：切到别的角色再切回来，已分配的点必须还在。 */
  candidateAbilities = null;
  candidatePoints = 0;
  clearLog();
  /* ISSUE-20261029-46：两个入口都支持「点一下直接进入」和「走过去进入」，提示一并更新 */
  /* ★ ISSUE-20261031-94（v2）：🚪 **不再**被教程锁住（人类原话：「没有进教程也可以直接点 🚪 开始游戏」）。
   * 教程变成可选入口：想上就点中间那个 3×3 的大 🎓，不想上直接点 🚪/走过去开局。
   * 提示文案只在「还有课没上完」时补一句软引导，不再宣称 🚪 不存在（那是旧版的强制策略，已废）。 */
  {
    const pend = lobbyPendLesson();
    const base = '请点击选择一个角色，然后点 🚪（或走过去）开始游戏，点 🎓 大图标（3×3）进入教程，点 🌐（或走过去）进入联机大厅。';
    /* ★ 人类 2026-10-31 16:06「角色课不加入链条」后，lobbyPendLesson() 只会返回入门三关的一节或 null，
     *   原来「这个角色还有一节专属教程没上」那条 else 分支已成死代码，随本次改动删除。
     *   角色课现在只在设置面板「重看教程」里手动进入，大厅不再提示。 */
    if (!pend) {
      log(base);
    } else {
      log(base + '（提示：入门三关还没上完，点 🎓 可以接着学。）');
    }
  }
  setTimeout(() => {
    updateCellSize();
    render();
    /* 自由移动层要等格子布局稳定后才能量出格子间距，所以跟着这次重绘一起初始化 */
    initFreeMoveLobby();
  }, 50);
}

function selectCharacter(charId) {
  stopFreeMove();          /* 进关前务必停掉 rAF，否则战斗里还在写大厅元素的 transform */
  freeMoveClearEls();      /* 大厅角色层是独立的绝对定位节点，进关前必须清干净 */
  selectedChar = charId;
  /* ★ ISSUE-20261028-14：教程课的进入判定。两条来源，优先级从高到低：
   *   ① 设置面板「重看教程」点了某一节（window.__ARK_TUT_REPLAY，一次性，**角色课只能走这条**）
   *   ② 入门三关没走完 → 从第一关「行动」开始（ISSUE-110 取代了老的通用课）
   * ★ 人类 2026-10-31 16:06「角色课不加入链条」：原来的来源 ③「入门三关走完、但这个角色
   *   还没上过课 → 自动播该角色那节」已删除。三关走完 = 教程结束，直接开局，不再被拽进角色课。
   * ⚠️ 必须在 createPlayerStats() 之前定下 selectedChar：
   *   角色课强制使用它自己的角色（E4 验收「进关后 selectedChar 与 charId 一致」），
   *   晚于造面板再换，会出现「面板是 A、地图里的技力是 B」的错配。 */
  let tutLessonId = null;
  try {
    if (window.__ARK_TUT_REPLAY) { tutLessonId = window.__ARK_TUT_REPLAY; window.__ARK_TUT_REPLAY = null; }
  } catch (_) {}
  /* ★ ISSUE-20261031-115（人类：教程只走 🎓 与设置「课程」两条显式入口）：
   * 这里原本还有一条**兜底自动进教程**：
   *     if (!tutLessonId && typeof tutorialPendingLesson === 'function') tutLessonId = tutorialPendingLesson(selectedChar);
   * 后果是「新玩家点 🚪 开始游戏」与「脚本/autotest 直接调 selectCharacter」都会被被动送进教程，
   * 与 templates/game.html 里「🚪 永远可见 → 点它直接开局」的注释直接矛盾
   * （ISSUE-94 v2 改渲染与提示文案时，漏改了这里 —— 见 ISSUE-111 的 40HP 木桩 / 1 血怪根因）。
   * 现已删除：教程**只**由两条显式路径进入 —— 选角厅 🎓（startTutorialFromLobby）与
   * 设置面板「课程」（bindTutorialReplay），两者都先置 window.__ARK_TUT_REPLAY，由上面那行消费。
   * ⚠️ tutorialPendingLesson() 本身**保留**：🎓 的「该上哪一节」仍靠它挑课，它只是选课器，不是入口。 */
  if (tutLessonId && typeof tutorialStartById === 'function' && tutorialStartById(tutLessonId)) {
    const forced = (typeof tutorialForcedChar === 'function') ? tutorialForcedChar() : null;
    if (forced && CHARACTERS[forced] && forced !== selectedChar) {
      selectedChar = forced;
      log(`📖「${tutorialLessonTitle()}」这一课固定使用${CHARACTERS[forced].name}，先跟着走一遍。`);
    }
  }
  setDebugMode(false);
  playerStats = createPlayerStats(selectedChar);
  /* ISSUE-20261028-19：把选角时加的 5 点交给正式面板，剩余点数一并带进第 1 关（B5）。
   * 只有动态角色才可能有副本；没加完的点不清零 —— 大厅出口判定已经够敏感，再拦「必须先加完」会卡人。
   * ★ 加了 `selectedChar === charId` 这个前置：上面可能把角色换成了课指定的那个，
   *   这时候选副本属于另一个角色，套上去就是错配。 */
  if (candidateAbilities && charIsDynamic(charId) && selectedChar === charId) {
    playerStats.abilities = { ...candidateAbilities };
    playerStats.abilityPoints = candidatePoints;
  }
  level = 1;
  resetRunProgress();
  recomputePlayerDerivedStats();
  playerStats.currentHp = playerStats.maxHp;
  initLevel();
}

/* =========================================================
 * 选角阶段的「候选属性副本」（ISSUE-20261028-19）
 *
 * ★ 绝对不许直接往 CHARACTERS.rookie.abilities 里写加点：那是模块级常量对象，
 *   雷达图、面板、联机快照都直接读它 → 一写就是全局污染（重开一局、甚至下一局选别人都会带着）。
 *   所以选中动态角色时建一份副本，加点只改副本；selectCharacter() 确认时才写进 playerStats。
 * ========================================================= */
let candidateAbilities = null;   /* 动态角色在选角阶段的六维副本 */
let candidatePoints = 0;         /* 选角阶段剩余可分配点数 */

/* 当前候选人的六维：动态角色读副本，静态角色读常量（后者永远不该被写） */
function candidateAbilitiesOf(id) {
  if (charIsDynamic(id) && candidateAbilities) return candidateAbilities;
  return CHARACTERS[id] ? CHARACTERS[id].abilities : null;
}
/* 切到某个候选人（点角色时调用）：动态角色首次选中时建副本并发放点数 */
function candidateSelect(id) {
  if (!charIsDynamic(id)) return;
  if (!candidateAbilities) {
    candidateAbilities = { ...CHARACTERS[id].abilities };
    candidatePoints = CHARACTERS[id].startAbilityPoints || 0;
  }
}
function candidateIsDynamic() {
  return !!(selectedCandidate && charIsDynamic(selectedCandidate.id));
}
function candidatePointsLeft() {
  return candidateIsDynamic() ? candidatePoints : 0;
}
/* 选角阶段加点：只动副本，不碰 playerStats（那时它还不该存在） */
function allocateCandidatePoint(k) {
  if (!candidateIsDynamic()) return false;
  if (candidatePoints <= 0) return false;
  if (!candidateAbilities || !(k in candidateAbilities)) return false;
  if (candidateAbilities[k] >= ABILITY_CAP) return false;
  candidateAbilities[k] += 1;
  candidatePoints -= 1;
  return true;
}

/* =========================================================
 * 非战斗相位的「平滑自由移动」（ISSUE-20261028-12）
 *
 * 位置模型：charCandidates[n].fx / fy = 连续坐标，单位是「格」，
 *           整数即该格中心（fx=2 就是 selMap[·][2] 的正中间）。
 *           整数 x / y 仍然同步维护（取整），供旧逻辑/测试读取。
 * 渲染：每帧只写「当前角色」那一个元素的 transform，绝不整盘重绘
 *       （paintBoard() 会 innerHTML 重建 81 格，60fps 调它必卡）。
 * 输入：点击（设目标点，可随时改向）与 WASD（按住连续走），
 *       两者共用同一套向量/位移代码；虚拟摇杆本轮不做（见 issue §待确认 1）。
 * ========================================================= */
const FREE_MOVE_SPEED = 4.5;    /* 格/秒，与 ISSUE-12 §待确认 2 的建议值一致 */
const FREE_MOVE_ARRIVE = 0.05;  /* 点击到位的到达判定：距目标 < 0.05 格即停，避免抖动 */
const FREE_MOVE_EXIT_EPS = 0.5; /* 与出口格矩形相交（中心距 <= 0.5 格）即算踩到 */
const FREE_MOVE_KEYS = ['w', 'a', 's', 'd'];
/* ISSUE-20261028-18 跟随指针 */
const FREE_MOVE_FOLLOW_DEADZONE = 0.18;  /* 跟随模式的到达半径：指针永远在微动，0.05 会每帧抖 */
const FREE_MOVE_EXIT_DWELL = 0.15;       /* 在出口格连续停留这么久才进关（人类 23:42 拍板 B 方案） */
const FREE_MOVE_DRAG_THRESHOLD = 8;      /* 触屏位移超过 8px 才算「拖动跟随」，否则仍算点击（B4） */
const FREE_MOVE_TOUCH_LIFT = 1.2;        /* 触屏拖动时目标点上移 1.2 格，别让手指盖住角色（§待确认 2 推荐 B） */

let freeMoveActive = false;     /* 大厅里是否启用自由移动 */
let freeMoveRaf = 0;
let freeMoveLast = 0;           /* 上一帧时间戳，dt 用它算（不能按固定步长） */
let freeMoveTarget = null;      /* 移动目标 {fx, fy, follow}；follow=true 表示由指针跟随写入 */
let freeMoveExitDwell = 0;      /* 在出口格内已连续停留的秒数（ISSUE-18 D1） */
let freeMoveExiting = false;    /* 已触发进关，防重复 */
let freeMoveGeom = null;        /* { ox, oy, sx, sy, cw, ch } 像素几何 */
/* ★ ISSUE-20261031-126：事件关「门锁着」的提示只报一次 ——
 * 玩家站在门前不动时 tick 每帧都在跑，不记标记会一秒刷 60 条日志。走开一格以上复位。 */
let eventLockHintShown = false;
const freeMoveKeys = { w: false, a: false, s: false, d: false };
/* ★ 相反方向「后按优先」（ISSUE-20261031-125；人类 2026-10-31 21:0x 报：自由移动按下 A 后立刻按 D，角色要停顿一下才往右）。
 * 旧实现每帧直接相减 `(d?1:0)-(a?1:0)`：A 还没松开时按下 D，两根轴抵消成 0 → 角色原地卡住，
 * 直到玩家松手才动，视觉上就是「顿一下」。
 * 这里给每根轴记一个「最后被按下的方向键」：两键同按时用后按的那个，松开后自动回落到仍按着的那个。
 * 只在「松开 → 按下」这一刻记（见 freeMoveKeyDown），系统重复 keydown 不覆盖 ——
 * 否则按住 A 时 A 的自动重复会不断把轴抢回去，角色会左右抖。 */
const freeMoveKeyLast = { x: '', y: '' };
const candEls = new Map();      /* 角色 id → 绝对定位元素 */

/* 非战斗相位（可自由移动）：选角大厅 + 事件关卡。
 * ★ ISSUE-20261031-126：原作者在这里留过一行「将来 ISSUE-06 的关卡间事件也是非战斗相位，
 *   一并放进这里即可」—— 本 issue 就是来兑现它的，事件关正是第二种非战斗相位。 */
function isFreeMovePhase() {
  return phase === PHASE.CHAR_SELECT || phase === PHASE.EVENT;
}
/* 事件关是不是「当前处于非战斗房间」——几乎每个自由移动函数都要分叉，
 * 单独包一层纯粹是为了让调用点的意图一眼可读（`isEventRoom()` 比 `phase === PHASE.EVENT` 短且明确）。 */
function isEventRoom() {
  return phase === PHASE.EVENT;
}

/* =========================================================================
 * ★ ISSUE-20261031-126：把「自由移动」从「大厅专有」解耦成「非战斗相位通用」
 *
 * 大厅与事件关的差别只有三样，全部收在下面四个小函数里：
 *   ① 角色源   大厅 = 5 个候选角色（charCandidates）；事件关 = 单个 eventActor
 *   ② 地图     大厅 = selMap；事件关 = 全局 map（房间地图）
 *   ③ 墙       大厅只夹边界（不判墙，会穿墙）；事件关要真墙体碰撞
 * 除了这三样，位移 / 输入 / 指针跟随 / 虚拟摇杆 / 每帧摆放全部**共用同一套代码** ——
 * 这就是本 issue 最大的省力点：事件关的手感天然和选角厅一致，不用另写一套移动系统。
 *
 * ⚠️ 为什么事件关用 `eventActor` 而不是直接操作 `player`：
 *   `player` 是**战斗单位**（hp / alive / facing / 技能都在它身上），每关由 createPlayerUnit 重建；
 *   而自由移动需要一份「连续坐标 { fx, fy }」。把 fx/fy 硬塞进 player 会让
 *   renderUnits / 战斗结算 / 联机快照都多两个外来字段，很难保证没人误用。
 *   所以单独一个 eventActor 只承载坐标，`freeMoveTick` 收尾时把整数坐标写回 player.x/y，
 *   让所有读 `player.x` 的既有代码（渲染 / 特效 / 落点）继续有效。
 * ========================================================================= */
function freeMoveActors() {
  if (isEventRoom()) return eventActor ? [eventActor] : [];
  return charCandidates;
}
function freeMoveActor() {
  return isEventRoom() ? eventActor : selectedCandidate;
}
function freeMoveMap() {
  return isEventRoom() ? map : selMap;
}
/* 角色「身体」的半宽（格）。略小于 0.5 是刻意的：
 *   · 中心正好在一格正中间（fx = 整数）时，fx±0.499 会四舍五入到**同一格** → 只判那一格；
 *   · 用 0.5 的话整数中心会落到两格边界上（Math.round(0.5)=1、Math.round(1.5)=2），
 *     判定凭空多出一格，走廊窄一格就走不过去；
 *   · 出生点在最后一行的**格中心**（y=10，地图 0..10），用 0.5 会算出 y+0.5=10.5→11 越界 → 
 *     一进房间就被判「站在墙里」，人完全动不了。 */
const FREE_MOVE_BODY = 0.499;

/* 这个位置能不能站：读地图真墙。
 * ⚠️ 只有事件关用它（大厅沿用原来的「夹边界」口径，人类对大厅手感已经验收过，不要顺带改掉）。
 *
 * ★ 为什么判**四个角**而不是「中心所在的一格」：
 *   只判中心那一格时，`Math.round(0.7) === 1`，角色能一路推到中心 0.5 ——
 *   视觉上半个身子已经插进墙里了（实测就是「撞墙停不下来、人嵌进墙」）。
 *   判角 = 判「角色这一整块砖压到了哪些格」，压到墙就拦，这才是贴墙滑行该有的边界。
 * 每帧步长最大 4.5×0.05 ≈ 0.22 格，远小于 1 格，不会「一帧跳过整面墙」。 */
function freeMoveBlockedAt(fx, fy) {
  const m = freeMoveMap();
  if (!m || !m.length) return true;
  for (const yy of [fy - FREE_MOVE_BODY, fy + FREE_MOVE_BODY]) {
    const gy = Math.round(yy);
    if (gy < 0 || gy >= m.length) return true;
    const row = m[gy];
    if (!row) return true;
    for (const xx of [fx - FREE_MOVE_BODY, fx + FREE_MOVE_BODY]) {
      const gx = Math.round(xx);
      if (gx < 0 || gx >= row.length) return true;
      if (row[gx] === 1) return true;
    }
  }
  return false;
}
/* 分轴推进：贴墙滑行的实现本体。
 * 两根轴**独立判定** —— x 被挡时 y 仍然走，于是「斜着撞墙」会顺着墙滑过去而不是原地卡死。
 * 这正是人类拍板 2 要的手感。返回 { moved, blockedBoth } 供调用方决定要不要清目标点。 */
function freeMoveAdvance(c, ddx, ddy) {
  const x0 = c.fx, y0 = c.fy;
  if (ddx) {
    const nx = c.fx + ddx;
    if (!freeMoveBlockedAt(nx, c.fy)) c.fx = nx;
  }
  if (ddy) {
    const ny = c.fy + ddy;
    if (!freeMoveBlockedAt(c.fx, ny)) c.fy = ny;
  }
  const moved = (c.fx !== x0 || c.fy !== y0);
  /* ★ `blockedBoth` =「**有推进意图**但一步都没挪」。
   *   `intended` 这一半不能省：rAF 的第一帧 dt 一定是 0（freeMoveKick 把 freeMoveLast 置 0），
   *   于是 stepX/stepY 都是 0。若此时仍判 blockedBoth，调用方会把 freeMoveTarget 清掉 ——
   *   玩家点了一下地图，角色**原地不动**、目标点还已经没了，表现就是「点了没反应」。
   *   （实测复现：setTarget 后一帧内 tgt 变 null、actor.fy 一动不动。） */
  const intended = ddx !== 0 || ddy !== 0;
  return { moved, blockedBoth: intended && !moved };
}

function freeMoveClearKeys() {
  for (const k of FREE_MOVE_KEYS) freeMoveKeys[k] = false;
  freeMoveKeyLast.x = '';
  freeMoveKeyLast.y = '';
  /* ★ ISSUE-20261031-130：逐格模式的方向队列必须跟着清 —— 否则切窗口 / 失焦回来，
   * 队列里残留的那个方向会让角色自己一直走（与 C3「键表不清会一直跑」同一个坑）。 */
  if (typeof stepMoveReset === 'function') stepMoveReset();
}

/* 单根轴的当前方向：-1 / 0 / 1。
 * 两个相反键同按时返回「后按的那个」，而不是相减抵消（见 freeMoveKeyLast 的注释）。 */
function freeMoveAxis(axis) {
  const pos = axis === 'x' ? 'd' : 's';
  const neg = axis === 'x' ? 'a' : 'w';
  const p = freeMoveKeys[pos];
  const n = freeMoveKeys[neg];
  if (p && n) return freeMoveKeyLast[axis] === neg ? -1 : 1;
  if (p) return 1;
  if (n) return -1;
  return 0;
}

/* =========================================================================
 * ★ ISSUE-20261031-130 · 逐格即时移动（游戏里的**第三种**移动方式）
 *
 * 人类原话（2026-10-31 22:51）：
 *   「加入一种新的移动方式，逐格即时移动，按方向键直接移动，但还是在格子里，
 *     按一次方向键走一格，每次移动结束都是在格子里，表现上和规划模式开始行动的时候一样」
 *
 * 三套移动的分工（**这一节只加第三种，一个字节都不动前两种**）：
 *   ① 战斗关规划   `stepPathByDir`   按方向键只往 playerPath 追加节点，人不动
 *   ② 事件关/大厅（平滑）`freeMoveTick` 的 dt 位移分支：连续坐标、能斜走、能贴墙滑行
 *   ③ 本节（逐格）  同一个 rAF 循环，只把「按 dt 位移」换成「按 120ms 节拍走整格」
 *
 * 生效范围（拍板 1 / 4）：
 *   选角厅（含联机大厅）→ 默认逐格，设置面板可切回平滑
 *   事件关            → **强制逐格**，不读设置（R6：避免开关被做成全局变量后事件关也读到）
 *   战斗关            → 不经过这里
 *
 * ⚠️ 落点恒在格心是本 issue 的根本约束：位置永远是整数 fx/fy。
 *   撞墙时**一个字节都不改**（只播视觉顿碰），所以不存在「卡在半格」。
 * ========================================================================= */
const STEP_MOVE_MS = UNIT_MOVE_MS;   /* 拍板 5：完全照结算的 120ms 硬切，不另立常量 */
const STEP_SAME_FRAME_MS = 16;       /* 拍板 6「真的同时按」的判定窗 = 一帧 */
const STEP_MOVE_KEY = 'ark_step_move';   /* '1' = 逐格（默认）· '0' = 平滑 */
const STEP_MOVE_SMOOTH_CLASS = 'smooth-free-move';   /* 挂在 <html> 上：有它 = 平滑 */
const STEP_BUMP_PX = 6;              /* 顿碰位移（纯视觉，不进坐标） */

let stepMoveQueue = [];        /* 按下顺序队列：队首 = 当前生效方向 */
let stepMoveDidStep = false;   /* 本次按键序列里「是否真的走过一格」→ 决定新按键 push 还是 unshift */
let stepMovePressAt = 0;       /* 上一次「新按下」的时间戳，用于同帧判定 */
let stepMovePressKey = '';
let stepNextAt = 0;            /* 下一次允许走格的 rAF 时间戳；0 = 下一帧就走 */
let stepMovePath = null;       /* 点地图自动走：待消费的格队列 [{x,y}, …] */
let stepMovePathTo = null;     /* 上面那条路径的目标格（判断要不要重算） */
let stepMoveBumpShown = false; /* 撞墙顿碰只播一次，按住不放不重复抽搐 */

/* 逐格模式此刻是否生效。事件关**硬编码为 true 且不看设置**（R6）。 */
function stepMoveMode() {
  if (isEventRoom()) return true;
  return !document.documentElement.classList.contains(STEP_MOVE_SMOOTH_CLASS);
}

/* ---- 纯函数区（不读 DOM、不读时间 → jsdom 可直接断言，见 issue R3） ---- */

/* 队列首位的方向。没有按键 → null（返回 null = 「没人要我走」）。 */
function stepMoveDirOf(queue) {
  const k = Array.isArray(queue) ? queue[0] : null;
  if (k === 'w') return { dx: 0, dy: -1 };
  if (k === 's') return { dx: 0, dy: 1 };
  if (k === 'a') return { dx: -1, dy: 0 };
  if (k === 'd') return { dx: 1, dy: 0 };
  return null;
}

/* 按下 k 之后的队列。priority：
 *   'first'    → 排到队尾（静止时「先按优先」，拍板 6）
 *   'takeover' → 插到队首（移动中「新键立即接管」，拍板 7；同轴相反键也走这条）
 * 先 filter 掉同名键：系统重复 keydown 已在调用处过滤，这里防的是「松手事件丢了」的脏数据。 */
function stepMoveQueuePress(queue, k, priority) {
  const q = (Array.isArray(queue) ? queue : []).filter((x) => x !== k);
  if (priority === 'first') q.push(k); else q.unshift(k);
  return q;
}

/* 按下时该用哪种优先级。判定顺序就是拍板的优先级顺序：
 *   ① 同帧且跨轴 → 上下优先（纵向 unshift，横向 push 让纵向继续留在队首）
 *   ①′ 同帧且同轴（W 与 S / A 与 D，一帧内两根相反键）→ 取后按的那个。
 *      同轴没有「上下优先」可依，issue §5.1 标的是「假设」：unshift 顺序决定队首，
 *      也就是谁后按谁生效。不做这条会退化成「先按优先」，按住 W 立刻按 S 会继续往上走 ——
 *      人类明确要的是「想停就往反方向按一下」，先按优先在这里是反直觉的。
 *   ② 已经在走了 → 立即接管
 *   ③ 还没走过一格 → 先按优先 */
function stepMovePressPriority(queue, k, prevKey, sameFrame) {
  const kVert = (k === 'w' || k === 's');
  const prevVert = (prevKey === 'w' || prevKey === 's');
  if (sameFrame && prevKey && k !== prevKey) {
    if (kVert === prevVert) return 'takeover';   /* 同轴相反键：后按接管 */
    return kVert ? 'takeover' : 'first';         /* 跨轴：上下优先 */
  }
  if (stepMoveDidStep) return 'takeover';
  return 'first';
}

/* 这一格能不能站。事件关读真墙；大厅沿用平滑模式那套「只夹边界」口径
 * （左右两列是墙、上下两行可走 —— 出口行与角色行）。 */
function stepMoveWalkable(x, y) {
  const m = freeMoveMap();
  if (!m || !m.length || !m[0]) return false;
  if (y < 0 || y >= m.length || x < 0 || x >= m[0].length) return false;
  if (isEventRoom()) return m[y][x] !== 1;
  return x >= 1 && x <= COLS - 2 && y >= 0 && y <= ROWS - 1;
}

/* 四向 BFS：起点 → 终点，返回**不含起点**的格序列；不可达返回 null。
 * 为什么不复用 templates 里的 bfsPathTo：那个带 tick 占位 / ghost / 占位函数一整套战斗语义，
 * 拿来走大厅只会多出两处口径不一致的地方；这里只有 100 来格，20 行足够。 */
function stepMovePathFind(sx, sy, tx, ty) {
  sx = Math.round(sx); sy = Math.round(sy);
  tx = Math.round(tx); ty = Math.round(ty);
  if (sx === tx && sy === ty) return [];
  if (!stepMoveWalkable(tx, ty)) return null;
  const DIRS = [[0, -1], [0, 1], [-1, 0], [1, 0]];
  const prev = new Map();
  const startKey = sx + ',' + sy;
  prev.set(startKey, null);
  const q = [{ x: sx, y: sy }];
  let guard = 0;
  while (q.length && guard++ < 4000) {
    const cur = q.shift();
    if (cur.x === tx && cur.y === ty) {
      /* 回溯：从终点一路取前驱，直到回到起点。结果**不含起点**，末位是终点。 */
      const out = [];
      let node = { x: cur.x, y: cur.y };
      let hop = 0;
      while (!(node.x === sx && node.y === sy) && hop++ < 4000) {
        out.push({ x: node.x, y: node.y });
        const p = prev.get(node.x + ',' + node.y);
        if (!p) return null;
        node = p;
      }
      out.reverse();
      return out;
    }
    for (const [dx, dy] of DIRS) {
      const nx = cur.x + dx, ny = cur.y + dy;
      const nk = nx + ',' + ny;
      if (prev.has(nk)) continue;
      if (!stepMoveWalkable(nx, ny)) continue;
      prev.set(nk, { x: cur.x, y: cur.y });
      q.push({ x: nx, y: ny });
    }
  }
  return null;
}

/* ---- 有副作用的执行层 ---- */

/* 顿碰（拍板 10）：只改视觉，不改坐标。按住不放顶在墙上只播一次。 */
function stepMoveBump(c, dx, dy) {
  if (stepMoveBumpShown) return;
  stepMoveBumpShown = true;
  const host = candEls.get(c.id);
  const icon = host && host.querySelector ? host.querySelector('.cand-icon') : null;
  if (!icon || !icon.style || !icon.classList) return;
  icon.style.setProperty('--bx', ((dx > 0 ? 1 : dx < 0 ? -1 : 0) * STEP_BUMP_PX) + 'px');
  icon.style.setProperty('--by', ((dy > 0 ? 1 : dy < 0 ? -1 : 0) * STEP_BUMP_PX) + 'px');
  icon.classList.remove('bump');
  /* 强制重排再挂 class：同名动画不重排的话第二次撞墙不会重播 */
  try { void icon.offsetWidth; } catch (_) {}
  icon.classList.add('bump');
}

function stepMoveClearBump(c) {
  if (!c) return;
  const host = candEls.get(c.id);
  const icon = host && host.querySelector ? host.querySelector('.cand-icon') : null;
  if (icon && icon.classList) icon.classList.remove('bump');
}

/* 走一格。返回 true = 真的走了；false = 撞墙（坐标不动）。 */
function stepMoveTry(c, dx, dy) {
  if (!c) return false;
  if (!dx && !dy) return true;
  const cx = Math.round(c.fx), cy = Math.round(c.fy);
  const nx = cx + dx, ny = cy + dy;
  if (!stepMoveWalkable(nx, ny)) { stepMoveBump(c, dx, dy); return false; }
  /* ★ 顺带把「从平滑切过来时残留的小数坐标」对齐到格心 —— 这正是「落点恒在格心」。 */
  c.fx = nx; c.fy = ny; c.x = nx; c.y = ny;
  stepMoveBumpShown = false;
  stepMoveClearBump(c);
  return true;
}

/* 清空队列 / 路径 / 节拍。模式切换、停表、失焦都走它。 */
function stepMoveReset() {
  stepMoveQueue = [];
  stepMoveDidStep = false;
  stepMovePressAt = 0;
  stepMovePressKey = '';
  stepNextAt = 0;
  stepMovePath = null;
  stepMovePathTo = null;
  stepMoveBumpShown = false;
}

/* 按下一个方向键（**只在「新按下」时调用**，系统重复 keydown 由调用处过滤）。
 * 方向真的变了 → stepNextAt 归零，下一个 rAF 立刻走（拍板 7「≤ 一帧」）；
 * 同方向按住不唤醒，否则按住不放会越走越快。 */
function stepMoveOnPress(k) {
  const now = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
  const sameFrame = !!stepMovePressKey && (now - stepMovePressAt) < STEP_SAME_FRAME_MS;
  const before = stepMoveDirOf(stepMoveQueue);
  const prio = stepMovePressPriority(stepMoveQueue, k, stepMovePressKey, sameFrame);
  stepMoveQueue = stepMoveQueuePress(stepMoveQueue, k, prio);
  stepMovePressAt = now;
  stepMovePressKey = k;
  const after = stepMoveDirOf(stepMoveQueue);
  if (!before || !after || before.dx !== after.dx || before.dy !== after.dy) stepNextAt = 0;
}

/* 松开一个方向键：移出队列，剩谁走谁。队列空了才算「这一段按键结束」。 */
function stepMoveOnRelease(k) {
  stepMoveQueue = (stepMoveQueue || []).filter((x) => x !== k);
  if (!stepMoveQueue.length) {
    stepMoveDidStep = false;
    stepNextAt = 0;
  }
}

/* 逐格模式下的一帧。返回 true = 还在动（rAF 要继续）。
 * 与平滑分支共用同一个 rAF 循环 / 同一套 kick-stop / 同一套元素管理，只有「位置怎么算」不同。 */
function stepMoveTick(c, ts) {
  const dir = stepMoveDirOf(stepMoveQueue);
  if (dir) {
    /* C4 口径不变：键盘优先，按下即取消点击目标；并打断自动寻路（拍板 8） */
    freeMoveTarget = null;
    stepMovePath = null;
    stepMovePathTo = null;
    if (ts >= stepNextAt) {
      stepMoveTry(c, dir.dx, dir.dy);
      /* ★ 以「现在」为新基准，不是 += 120 累加：累加会在掉帧后攒出「一帧走两格」的跳格 */
      stepNextAt = ts + STEP_MOVE_MS;
      stepMoveDidStep = true;
      return true;
    }
    return true;   /* 还在按键、只是这一拍还没到 → rAF 必须续上 */
  }
  if (!freeMoveTarget) return false;

  const tx = Math.round(freeMoveTarget.fx), ty = Math.round(freeMoveTarget.fy);
  if (Math.round(c.fx) === tx && Math.round(c.fy) === ty) {
    stepMovePath = null; stepMovePathTo = null;
    /* 跟随模式（手指还按着）保留目标，等指针继续移动；点击模式到点即停 */
    if (!freeMoveTarget.follow) freeMoveTarget = null;
    return !!freeMoveTarget;
  }
  /* 目标变了 / 没路径 → 重算一次 BFS。箭头键按下走不到这里（上面已 return）。 */
  if (!stepMovePath || !stepMovePath.length || !stepMovePathTo ||
      stepMovePathTo.x !== tx || stepMovePathTo.y !== ty) {
    stepMovePath = stepMovePathFind(c.fx, c.fy, tx, ty);
    stepMovePathTo = { x: tx, y: ty };
    if (!stepMovePath || !stepMovePath.length) {
      freeMoveTarget = null; stepMovePath = null; stepMovePathTo = null;
      return false;
    }
  }
  if (ts >= stepNextAt) {
    const cell = stepMovePath[0];
    const dx = Math.sign(cell.x - Math.round(c.fx));
    const dy = Math.sign(cell.y - Math.round(c.fy));
    if (stepMoveTry(c, dx, dy)) {
      stepMovePath.shift();
      stepNextAt = ts + STEP_MOVE_MS;
    } else {
      /* 走不过去（地图被改 / 目标在墙里）→ 停，不要每拍都撞 */
      freeMoveTarget = null; stepMovePath = null; stepMovePathTo = null;
    }
  }
  return true;
}


/* 量一次格子几何：用两个对角格子的中心点反推「格间距」，
 * 比 rect.width/COLS 精确（后者会把 grid gap 摊进格宽，右端误差最大可到十几像素）。 */
function freeMoveMeasure() {
  if (!(COLS >= 4 && ROWS >= 4)) return false;
  const a = getCellEl(1, 1);
  const b = getCellEl(COLS - 2, ROWS - 2);
  if (!a || !b) return false;
  const lr = unitLayer.getBoundingClientRect();
  const ar = a.getBoundingClientRect();
  const br = b.getBoundingClientRect();
  if (!(ar.width > 0) || !(br.width > 0)) return false;
  const ax = ar.left - lr.left + ar.width / 2;
  const ay = ar.top - lr.top + ar.height / 2;
  const bx = br.left - lr.left + br.width / 2;
  const by = br.top - lr.top + br.height / 2;
  freeMoveGeom = {
    ox: ax, oy: ay,
    sx: (bx - ax) / (COLS - 3),
    sy: (by - ay) / (ROWS - 3),
    cw: ar.width, ch: ar.height,
    /* 把 unitLayer 的视口偏移也缓存下来：pointermove 里要按每秒 500+ 次换算坐标，
       每次都 getBoundingClientRect() 会强制重排（ISSUE-18 约束 1）。
       页面滚动 / 尺寸变化时统一重测（见文件末尾的 scroll / resize 监听）。 */
    lx: lr.left, ly: lr.top,
  };
  return Math.abs(freeMoveGeom.sx) > 0.5 && Math.abs(freeMoveGeom.sy) > 0.5;
}

function freeMoveToPixels(fx, fy) {
  const g = freeMoveGeom;
  return { x: g.ox + (fx - 1) * g.sx - g.cw / 2, y: g.oy + (fy - 1) * g.sy - g.ch / 2 };
}

/* 视口坐标 → 连续格坐标。只用缓存的几何，不读布局（约束 1：pointermove 高频调用） */
function freeMoveClientToCell(clientX, clientY) {
  const g = freeMoveGeom;
  if (!g) return { fx: 1, fy: 1 };
  return {
    fx: 1 + (clientX - g.lx - g.ox) / g.sx,
    fy: 1 + (clientY - g.ly - g.oy) / g.sy,
  };
}

function freeMoveEnsureEls() {
  /* ★ ISSUE-20261031-126：先清掉「不属于当前相位」的残留元素。
   * 典型场景：事件关里点 ⟲ 重开 → 回大厅。若不清理，事件关那个 `__event_player`
   * 的绝对定位节点会一直留在 unitLayer 里飘在大厅上（它不在 charCandidates 里，
   * 下面那个 for 永远不会碰到它）。反过来「大厅 → 事件关」同理。 */
  const want = new Set(freeMoveActors().map(c => c.id));
  for (const [id, el] of candEls) {
    if (!want.has(id)) { el.remove(); candEls.delete(id); }
  }
  for (const c of freeMoveActors()) {
    const old = candEls.get(c.id);
    if (old && old.isConnected) continue;
    if (old) old.remove();
    const el = document.createElement('div');
    el.className = 'cand-unit';
    const iconEl = document.createElement('div');
    iconEl.className = 'cand-icon';
    /* ★ ISSUE-20261030-64：候选角色的图标同样是 innerHTML 写入。
     * ★ ISSUE-20261031-126：事件关的角色对象（eventActor）不是角色 id，自己带 `icon` 字段，
     *   所以这里先读 `c.icon`，读不到才回落到 CHARACTERS 表（大厅的候选角色没有 icon 字段）。 */
    const iconChar = c.icon || (CHARACTERS[c.id] && CHARACTERS[c.id].icon) || '❓';
    iconEl.innerHTML = iconify(iconChar);
    el.appendChild(iconEl);
    unitLayer.appendChild(el);
    candEls.set(c.id, el);
  }
}

function freeMoveClearEls() {
  for (const [, el] of candEls) el.remove();
  candEls.clear();
}

function freeMovePlace(c) {
  const el = candEls.get(c.id);
  if (!el || !freeMoveGeom) return;
  const w = freeMoveGeom.cw + 'px';
  const h = freeMoveGeom.ch + 'px';
  if (el.style.width !== w) el.style.width = w;
  if (el.style.height !== h) el.style.height = h;
  const p = freeMoveToPixels(c.fx, c.fy);
  el.style.transform = `translate(${p.x}px, ${p.y}px)`;
}

/* 选中态 / 初始摆位：只在「选择变化、初始化、尺寸变化」时调，不进每帧循环 */
function freeMoveRenderAll() {
  const ev = isEventRoom();
  for (const c of freeMoveActors()) {
    const el = candEls.get(c.id);
    if (!el) continue;
    /* 事件关没有「候选角色」这回事，永远不画选中框 */
    el.classList.toggle('sel', ev ? false : selectedCandidate === c);
    freeMovePlace(c);
  }
}

/* ★ ISSUE-20261031-126：render() 之后重建事件关的角色层。
 *
 * 为什么需要它：事件关的 `render()` 会走 renderUnits() → `clearUnitLayer()`，
 * 把 unitLayer 的 innerHTML 整个清掉 —— 连自由移动层 append 进去的 `.cand-unit` 一起清。
 * 大厅靠「initFreeMoveLobby 在 render 之后调一次」躲过这一劫，但事件关的 render
 * 会在 resize / 切抽屉 / 关卡初始化等多处被调用，指望没人漏调是不现实的。
 * 所以在 render() 末尾统一挂钩：只要是事件相位就重建元素 + 重新摆位。
 * （candEls 里存的是已被清掉的旧节点，freeMoveEnsureEls 的 isConnected 检查会重建它们。） */
function freeMoveRefreshEls() {
  if (!isEventRoom() || !freeMoveActive) return;
  if (!freeMoveGeom && !freeMoveMeasure()) return;
  freeMoveEnsureEls();
  freeMoveRenderAll();
}

/* 事件关的初始化入口：对应大厅的 initFreeMoveLobby()。
 * 区别只有一处 —— 角色层只有一个元素，且必须先有 eventActor（initEventLevel 负责建）。 */
function initFreeMoveEvent() {
  stopFreeMove();
  freeMoveExiting = false;
  freeMoveExitDwell = 0;
  freeMoveEnsureEls();
  if (!freeMoveMeasure()) {
    requestAnimationFrame(() => {
      if (!isFreeMovePhase() || !freeMoveMeasure()) return;
      freeMoveRenderAll();
    });
  }
  freeMoveActive = true;
  freeMoveRenderAll();
}

function initFreeMoveLobby() {
  stopFreeMove();
  freeMoveExiting = false;
  freeMoveExitDwell = 0;   /* ISSUE-18：进出关都要清停留计时 */
  freeMoveEnsureEls();
  if (!freeMoveMeasure()) {
    /* 布局还没稳定（例如刚切横竖屏）：下一帧再试一次，量不到就保持静止 */
    requestAnimationFrame(() => {
      if (!isFreeMovePhase() || !freeMoveMeasure()) return;
      freeMoveRenderAll();
    });
  }
  freeMoveActive = true;
  freeMoveRenderAll();
}

function freeMoveKick() {
  if (!freeMoveActive || freeMoveRaf) return;
  freeMoveLast = 0;
  freeMoveRaf = requestAnimationFrame(freeMoveTick);
}

function stopFreeMove() {
  freeMoveActive = false;
  if (freeMoveRaf) cancelAnimationFrame(freeMoveRaf);
  freeMoveRaf = 0;
  freeMoveLast = 0;
  freeMoveTarget = null;
  freeMoveExitDwell = 0;
  eventLockHintShown = false;   /* 停表 = 一次移动结算结束，下次重新提示 */
  freeMoveClearKeys();
}

/* 单一入口：点击补位（follow=false）与指针跟随（follow=true）都走这里。
 * ★ 只写目标点，绝不直接写 c.fx / c.fy —— 位移永远由 freeMoveTick 用
 *   Math.min(d, FREE_MOVE_SPEED * dt) 封顶（ISSUE-18 约束 6 / A0）。 */
function freeMoveSetTarget(fx, fy, follow) {
  if (!freeMoveActive) return;
  if (!freeMoveGeom && !freeMoveMeasure()) return;
  if (isEventRoom()) {
    /* 事件关：只夹到地图范围内即可，**具体能否站**由 freeMoveTick 的分轴墙体判定处理。
     * 不能在这里做墙判定 —— 点击点可能在墙的另一侧，玩家期望的是「走到墙边停下」，
     * 而不是「点了墙就完全不动」。目标点交给 tick 去逼近，撞墙自然停在墙前。 */
    freeMoveTarget = {
      fx: Math.max(0, Math.min(COLS - 1, fx)),
      fy: Math.max(0, Math.min(ROWS - 1, fy)),
      follow: !!follow,
    };
  } else {
    /* 选角厅上下两行现在是可走的（出口在第 0 行、角色站在最后一行），
     * y 的夹取范围必须跟着放开（ISSUE-20261029-29）—— 留着旧的 1..ROWS-2 就永远走不到出口。 */
    freeMoveTarget = {
      fx: Math.max(1, Math.min(COLS - 2, fx)),
      fy: Math.max(0, Math.min(ROWS - 1, fy)),
      follow: !!follow,
    };
  }
  /* 开始走动了就把技能说明收起来：它还盖在棋盘中部，挡着看走路 */
  closeCharInfoSheet();
  freeMoveKick();
}

/* 清掉目标点（指针离开棋盘 / 中断 / 松手）：只清目标，不停表 ——
   停表交给 freeMoveTick 的自然静止分支，避免这里和 tick 抢 rAF 句柄。 */
function freeMoveClearTarget() {
  freeMoveTarget = null;
}

/* ISSUE-20261029-44 第2项：当前是否处于「跟随指针」的移动（拖动中）。
 * 松开鼠标/手指时用它判断要不要立即停 —— 纯点击（follow=false）不算，保留点击补位。 */
function freeMoveIsFollowing() {
  return !!(freeMoveTarget && freeMoveTarget.follow);
}

/* =========================================================================
 * ★ ISSUE-20261029-47：指针是不是压在「操作 UI」上
 *
 * 期望：在棋盘内按住后，**只要没压到操作 UI 就一直跟随**（移出棋盘照跟，
 *   角色被 freeMoveSetTarget 夹在可走区里，表现为贴着边界继续跟）；
 *   只有移到右侧栏 / 三个角标 / 已打开的抽屉 · 遮罩 · 技能说明层才停。
 *
 * 为什么用 elementFromPoint 而不是「指针坐标是否落在棋盘 rect 外」：
 *   抽屉是 <body> 直属、盖在棋盘上的，坐标落在棋盘矩形内照样可能是 UI；
 *   反过来棋盘外的页面空白处却要继续跟随。命中测试是唯一判得准的办法。
 * ⚠️ 判定不能在 pointerleave 里做（那是本 issue 的根因②）：设了 pointer capture
 *   之后拖动中途根本不会再发 pointerleave，它只在 capture 释放时补发一次。
 * ========================================================================= */
const FREE_MOVE_UI_SEL =
  '#sidebar, #setOpenBtn, #lobbyOpenBtn, #charOpenBtn, #rewardOpenBtn,' +
  ' .drawer.on, #drawerMask, #charInfoSheet';

function freeMoveOverUi(clientX, clientY) {
  /* 抽屉（设置 / 升级 / 角色 / 联机）或遮罩一开就整块盖住棋盘 → 一律算 UI，
   * 顺带省掉一次 elementFromPoint。drawerCurrent 由 src/ui/drawer.js 维护。 */
  if (typeof drawerCurrent !== 'undefined' && drawerCurrent) return true;
  let el = null;
  try { el = document.elementFromPoint(clientX, clientY); } catch (_) { return false; }
  if (!el || !el.closest) return false;   /* 指针跑到窗口外：算「非 UI」，继续跟随（会贴边界） */
  return !!el.closest(FREE_MOVE_UI_SEL);
}

function freeMoveKeyDown(k) {
  /* ★ ISSUE-20261031-126：早退条件从「没选候选角色」改成「当前相位没有可移动的角色」——
   *   事件关没有 selectedCandidate（那是大厅概念），只有 eventActor。
   *   沿用旧判据的后果是「事件关里 WASD 完全没反应」，而摇杆那个方向键又是走同一入口的。 */
  if (!freeMoveActive || !freeMoveActor()) return false;
  if (!FREE_MOVE_KEYS.includes(k)) return false;
  /* ★ 只有「这一下是新按下」才记轴（见 freeMoveKeyLast）：
   *   ① 忽略系统重复 keydown，否则按住 A 时按 D 会立刻被 A 的重复事件抢回去；
   *   ② 后按的那个方向生效 —— 这样 A→D 是「立刻右转」，而不是两键抵消卡住。 */
  if (!freeMoveKeys[k]) {
    if (k === 'a' || k === 'd') freeMoveKeyLast.x = k;
    else freeMoveKeyLast.y = k;
    /* ★ ISSUE-20261031-130：逐格模式的方向队列（先按优先 / 新键接管 / 同帧上下优先）。
     * 只在「新按下」这一刻记 —— 与上面的 freeMoveKeyLast 同一个理由：系统重复 keydown
     * 会把队列不断重排，按住不放就变成抽搐。平滑模式不看这个队列，记了也无副作用。 */
    if (typeof stepMoveOnPress === 'function') stepMoveOnPress(k);
  }
  freeMoveKeys[k] = true;
  closeCharInfoSheet();      /* 键盘移动同样要收起说明，理由同 freeMoveSetTarget */
  freeMoveKick();
  return true;
}

function freeMoveKeyUp(k) {
  if (FREE_MOVE_KEYS.includes(k)) freeMoveKeys[k] = false;
  /* ★ ISSUE-20261031-130：逐格队列同步移出（剩谁走谁）；队列空了才算这段按键结束。 */
  if (typeof stepMoveOnRelease === 'function') stepMoveOnRelease(k);
}

/* 点击命中角色：按「中心距 <= 0.75 格」判定，角色不在格中心也能点中 */
/* =========================================================================
 * ★ 选角厅「技能说明展开层」（ISSUE-20261029-29，人类 04:42）
 *   「点击角色之后，角色这一行以上的部分展开角色技能说明文字，可以滚轮滑动查看，
 *     删掉之前的技能说明面板」。
 *
 * 形态：一块盖在棋盘「第 1 行 ~ 倒数第 2 行」上的半透明卡片（出口所在的第一行不遮，
 *   否则玩家看不见、也走不到出口），内容 = 角色简介 + tips，超出高度可滚轮 / 触摸滑动。
 * 为什么做成棋盘上的覆盖层而不是侧栏卡片：需求就写在棋盘上；且手机端侧栏在下方，
 *   说明放那儿要低头找，放棋盘中部是拇指区。
 * 收起时机（四条）：
 *   ① 点面板空白处（位移 ≤8px 且 ≤700ms 才算「点」，滚动手指不会误触）
 *   ② 点地图设目标（freeMoveSetTarget）
 *   ③ 按 WASD（freeMoveKeyDown）
 *   ④ ★ ISSUE-20261031-116：点**面板以外**的任何位置（侧栏 / 角标 / 工具条 / 棋盘外空白）——
 *      document 级 pointerdown（捕获阶段）统一收口；棋盘本身例外，交给 ② 处理（见 bindCharInfoSheet 的注释）
 * 位置靠量单元格 (1,1) 与 (COLS-2, ROWS-2) 的矩形算，不用 --cell 反推公式
 *   —— 后者要在 CSS 里复述一遍 gap 与居中偏移，两处一旦不同步就会错位半格。
 * ========================================================================= */
let charSheetOpen = false;

function openCharInfoSheet() {
  charSheetOpen = true;
  renderCharInfoSheet();
}

function closeCharInfoSheet() {
  if (!charSheetOpen) return;
  charSheetOpen = false;
  renderCharInfoSheet();
}

function layoutCharInfoSheet() {
  const el = document.getElementById('charInfoSheet');
  if (!el || el.hidden) return;
  const a = getCellEl(1, 1);
  const b = getCellEl(COLS - 2, ROWS - 2);
  if (!a || !b) return;
  const lr = boardWrap.getBoundingClientRect();
  const ar = a.getBoundingClientRect();
  const br = b.getBoundingClientRect();
  if (!(ar.width > 0) || !(br.width > 0)) return;
  el.style.left = (ar.left - lr.left) + 'px';
  el.style.top = (ar.top - lr.top) + 'px';
  el.style.width = (br.left + br.width - ar.left) + 'px';
  el.style.height = (br.top + br.height - ar.top) + 'px';
}

function renderCharInfoSheet() {
  const el = document.getElementById('charInfoSheet');
  if (!el) return;
  if (phase !== PHASE.CHAR_SELECT || !selectedCandidate || !charSheetOpen) {
    el.hidden = true;
    return;
  }
  const char = CHARACTERS[selectedCandidate.id];
  if (!char) { el.hidden = true; return; }
  el.hidden = false;
  el.innerHTML =
    '<div class="cis-head">' +
      /* ★ ISSUE-20261030-75：角色头像必须走 iconify 补 VS16 + .emo 字体栈，否则 Win10 上按黑白文本字形画。
       * 同文件 line 245 候选列表已改，此处信息卡头像被 64 号改动漏掉。 */
      '<span class="cis-ico">' + iconify(char.icon) + '</span>' +
      '<span class="cis-name">' + char.name + '</span>' +
      /* ISSUE-20261031-116：改「点空白处」为「点任意处」—— 改完点面板外也真的会关了 */
      '<span class="cis-hint">滚轮 / 上下滑动查看 · 点任意处收起</span>' +
    '</div>' +
    '<div class="cis-desc">' + char.desc + '</div>' +
    '<ul class="tips cis-tips">' + renderTips(char.tips) + '</ul>';
  layoutCharInfoSheet();
}

(function bindCharInfoSheet() {
  const el = document.getElementById('charInfoSheet');
  if (!el) return;
  let down = null;
  el.addEventListener('pointerdown', function (e) {
    down = { x: e.clientX, y: e.clientY, t: Date.now() };
  });
  el.addEventListener('pointerup', function (e) {
    if (!down) return;
    const moved = Math.hypot(e.clientX - down.x, e.clientY - down.y);
    const dt = Date.now() - down.t;
    down = null;
    if (moved <= 8 && dt <= 700) closeCharInfoSheet();
  });
  el.addEventListener('pointercancel', function () { down = null; });
  /* 滚轮只在本层滚，别把页面带着一起滚（body 是 overflow:hidden，这里只是保险） */
  el.addEventListener('wheel', function (e) { e.stopPropagation(); }, { passive: true });

  /* ★ ISSUE-20261031-116（人类 16:18「角色技能说明面板点击其他位置可以直接关闭」）：
   * 上面只绑了**面板自己**的 pointerup，所以点侧栏 / 角标 / 工具条 / 棋盘外空白都纹丝不动，
   * 而面板提示写着「点空白处收起」—— 行为与文案不符，这本身就是 bug。
   * 这里补一个 document 级的「点外部关闭」。
   *
   * 三条排除，每条都不能省：
   *   ① `!charSheetOpen` 直接返回 —— 全局监听必须严格「面板开着才生效」，
   *      否则会在战斗 / 抽屉里制造来历不明的关闭。
   *   ② 点在面板内 → 交回它自己的 pointerup 判定（要区分「点」与「滚」，位移 >8px 不算点）。
   *   ③ 点在 `#board` 上 → 由 `freeMoveSetTarget()` 统一收口，不在这里抢。
   *      棋盘判「点了哪个角色」用的是**几何判定**（`freeMoveCandidateAt`，中心距 ≤0.75 格），
   *      不是 DOM 事件委托；这里抢先关闭会让「点角色 → 关 → 再开」翻两次，
   *      点**另一个**角色时还可能变成「只关不开」。
   *      ⚠️ 排除的是 `#board` 而不是 `#boardWrap`：角标 ⚙ / 👤 / ♟️ / 📟 在 boardWrap 内、
   *      board 外 → 点它们**应该**收起说明层（那层正压在棋盘中部挡着），这是本 issue 的期望行为。
   *
   * 捕获阶段（第三参数 `true`）：面板自己也监听 pointerdown 记录按下坐标，
   * 先跑才能保证不被任何下层 handler 的 stopPropagation 吃掉。 */
  document.addEventListener('pointerdown', function (e) {
    if (!charSheetOpen) return;
    const sheet = document.getElementById('charInfoSheet');
    if (sheet && sheet.contains(e.target)) return;
    if (e.target && e.target.closest && e.target.closest('#board')) return;
    closeCharInfoSheet();
  }, true);
})();

function freeMoveCandidateAt(x, y, radius) {
  let best = null;
  let bestD = radius || 0.75;
  for (const c of charCandidates) {
    const d = Math.hypot(c.fx - x, c.fy - y);
    if (d <= bestD) { bestD = d; best = c; }
  }
  return best;
}

/* ★ ISSUE-20261031-94：大厅正式入口 🚪 的教程判据。
 * 判定本体在 src/rules/tutorial.js#tutorialPendingLesson()，这里只负责「大厅语境下传谁进去」。
 * ⚠️ v2 起这个函数**只用于提示文案与 🎓 的选课**，不再锁 🚪 ——
 *    人类 2026-10-31 明确要求「没有进教程也可以直接点 🚪 开始游戏」，
 *    上一版那套「没上完课就整格不渲染」的强制策略（lobbyExitLocked）已整体拆除。 */
function lobbyPendLesson() {
  if (typeof tutorialPendingLesson !== 'function') return null;
  return tutorialPendingLesson(selectedCandidate ? selectedCandidate.id : null);
}

/* 纯检测：角色中心是否落在出口格判定区内（不再直接触发，ISSUE-18 D1 要累计停留） */
function freeMoveInExitZone(c) {
  if (!c) return false;
  if (Math.abs(c.fx - selExit.x) > FREE_MOVE_EXIT_EPS) return false;
  if (Math.abs(c.fy - selExit.y) > FREE_MOVE_EXIT_EPS) return false;
  return true;
}

/* ★ ISSUE-20261031-94（v2）：🎓 只保留「点击进入」，**走位触发已整体移除**。
 * 原因很实在：这个 3×3 区正好压在「角色行(y=10) → 🚪(5,0)」的必经路上，
 * 走过去就自动进教程，等于把「想直接开局」的人反复劫持进教学关 —— 人类明确要的是
 * 「没有进教程也可以直接点 🚪 开始游戏」，所以走位这条路必须让开。
 * 踩踏判定的口径本身（0.5 格相交）仍由 selTutInZone() 承载，点击分支直接用它。 */

/* ★ ISSUE-20261029-46：联机入口（🌐）的踩踏判定，与门同一套 0.5 格相交口径。
 * ⚠️ 只在**普通选角厅**里生效：进了联机大厅 / 房间地图之后不能再触发，
 *    否则角色路过 (9,5) 会把自己再送进一次联机大厅（面板反复弹）。 */
function freeMoveInOnlineZone(c) {
  if (!c || onlineStage) return false;
  if (Math.abs(c.fx - selOnlineExit.x) > FREE_MOVE_EXIT_EPS) return false;
  if (Math.abs(c.fy - selOnlineExit.y) > FREE_MOVE_EXIT_EPS) return false;
  return true;
}

/* 当前踩在哪个入口上：'' / 'exit' / 'online'。两个走位入口互不重叠，谁先命中算谁。
 * ⚠️ 没有 'tutorial'：教程入口只能点，不能走进去（原因见上面那段注释）。
 * ⚠️ 事件关**不走这里** —— 它的 ❓ 是无停留立即触发、出口是有停留的，两套语义不同，
 *    混进同一个 dwell 计时会让「走过 ❓ 顺手把出口也点开」。判定见下面 event* 三个函数。 */
function freeMoveZoneOf(c) {
  if (freeMoveInOnlineZone(c)) return 'online';
  if (freeMoveInExitZone(c)) return 'exit';
  return '';
}

/* =========================================================================
 * ★ ISSUE-20261031-126：事件关的两个触碰判定
 *
 * 口径差异（人类拍板 10 / 12）：
 *   ❓ 事件点 → **靠近 0.5 格立即触发**，没有停留要求。理由：它是个「看见就想点」的东西，
 *              加停留只会让人以为没反应；而且触发后它自己变淡消失，不存在反复误触。
 *   出口     → 0.5 格相交 **+ 停留 0.15 秒**（与选角厅同一套），防「路过门就被送走」。
 * ========================================================================= */
function eventObjectTouched(c) {
  if (!c) return null;
  for (const o of eventObjects) {
    if (o.used) continue;
    if (Math.abs(c.fx - o.x) > FREE_MOVE_EXIT_EPS) continue;
    if (Math.abs(c.fy - o.y) > FREE_MOVE_EXIT_EPS) continue;
    return o;
  }
  return null;
}
function eventExitTouched(c) {
  if (!c) return false;
  if (Math.abs(c.fx - eventExit.x) > FREE_MOVE_EXIT_EPS) return false;
  if (Math.abs(c.fy - eventExit.y) > FREE_MOVE_EXIT_EPS) return false;
  return true;
}

function freeMoveTouchesExit(c) {
  if (freeMoveExiting || !c) return false;
  if (!freeMoveInExitZone(c)) return false;
  freeMoveExiting = true;
  const id = c.id;
  stopFreeMove();          /* E2：先停表，否则进关后 rAF 还在跑 */
  /* ★ ISSUE-20261029-46：联机大厅 / 房间地图里的 🚪 是「返回选角厅」，不是开始游戏 ——
   * 否则玩家想退出联机却误开了一局单人。走 onlineQuit()：还占着房间就顺带 /api/quit，
   * 免得留下「房间挂着人、玩家却看不到房间号」、对手一直空等的状态。 */
  if (onlineStage) {
    log('离开联机大厅，返回角色选择。');
    setTimeout(() => { if (typeof onlineQuit === 'function') onlineQuit(); }, 400);
    return true;
  }
  log(`你选择了 ${CHARACTERS[id].name}！进入关卡。`);
  /* ★ ISSUE-20261030-62：开局前把还开着的面板收干净。
   * 最显眼的是角色说明面板（#charInfoSheet，点角色弹出来的）—— 它挂在 body 直属、
   * 绝对定位，不清的话会跟着切到战斗棋盘上浮着。
   * drawerClose() 是抽屉的统一出口，里面已经拦住「升级奖励没选完不许关」。 */
  try { if (typeof closeCharInfoSheet === 'function') closeCharInfoSheet(); } catch (_) {}
  try { if (typeof drawerClose === 'function') drawerClose(); } catch (_) {}
  /* 保留原有 400ms 过渡延迟（与旧的逐格动画收尾一致） */
  setTimeout(() => {
    if (isFreeMovePhase()) selectCharacter(id);
  }, 400);
  return true;
}

/* ★ ISSUE-20261029-46：走进联机入口 → 进联机大厅并展开联机面板。
 * 与门同一套 400ms 过渡；真正的进入动作在 chrome.js 的 enterOnlineLobby()。 */
function freeMoveTouchesOnline(c) {
  if (freeMoveExiting || !c) return false;
  if (!freeMoveInOnlineZone(c)) return false;
  freeMoveExiting = true;
  stopFreeMove();
  log('🌐 进入联机大厅…');
  setTimeout(() => {
    if (typeof enterOnlineLobby === 'function') enterOnlineLobby();
  }, 400);
  return true;
}

/* ★ ISSUE-20261031-94：从大厅触发教程（🎓 点击 / 走去都走这一条）。
 * 复用的是既有「设置面板重看教程」那条最稳的链路：置 window.__ARK_TUT_REPLAY 一次，
 * 再走 selectCharacter() —— 它会优先消费这个标记，顺带处理「这一课固定用哪个角色」
 * 与「回合内技能/技力重置」等一整套前置，不需要在这里重写一遍。
 * 返回 false = 还没选角色，进不去（调用方负责提示）。 */
function startTutorialFromLobby() {
  const cand = selectedCandidate;
  if (!cand) { log('请先点一个角色，再点 🎓 进教程。'); return false; }
  const pend = lobbyPendLesson();
  /* 还有没上完的课 → 上那一课；全上完了 → 🎓 变成「重看教程」，从第一关重播。 */
  const lessonId = pend || ((typeof TUTORIAL_INTRO_CHAIN !== 'undefined') ? TUTORIAL_INTRO_CHAIN[0] : 'action');
  try { window.__ARK_TUT_REPLAY = lessonId; } catch (_) {}
  try { if (typeof closeCharInfoSheet === 'function') closeCharInfoSheet(); } catch (_) {}
  try { if (typeof drawerClose === 'function') drawerClose(); } catch (_) {}
  log(`🎓 进入教程「${(typeof tutorialLessonTitle === 'function') ? tutorialLessonTitle() : lessonId}」…`);
  return true;
}

/* ★ 已删除（ISSUE-20261031-94 v2）：freeMoveTouchesTutorial()。
 * 教程入口改成 3×3 大图标后位置正压在通往 🚪 的必经路上，走位触发会把玩家
 * 反复劫持进教学关 —— 人类要的是「不教程也能直接开局」，所以只保留点击入口。 */

function freeMoveTick(ts) {
  freeMoveRaf = 0;
  if (!freeMoveActive || !isFreeMovePhase()) return;
  /* ★ ISSUE-20261031-126：角色源按相位分派 —— 大厅 = 选中的候选角色，事件关 = eventActor。
   * 旧代码写死 `selectedCandidate`，事件关里它恒为 null（那是大厅概念）→ 整个人不动。 */
  const c = freeMoveActor();
  const inRoom = isEventRoom();
  /* dt 必须用 rAF 时间戳：120Hz 屏按固定步长会让速度翻倍 */
  const dt = freeMoveLast ? Math.min(0.05, Math.max(0, (ts - freeMoveLast) / 1000)) : 0;
  freeMoveLast = ts;
  let moving = false;

  if (c) {
    /* ★ ISSUE-20261031-130：逐格模式 = **新增分支**，不是替换实现。
     *   两模式共用这个 rAF 循环、同一套 kick/stop、同一套元素管理，只有「这一帧位置怎么算」不同；
     *   平滑那一段（含贴墙滑行的分轴推进）一个字节都没动（§5.7 / 九「不删平滑移动代码」）。 */
    if (stepMoveMode()) {
      moving = stepMoveTick(c, ts);
    } else {
    /* ★ ISSUE-20261031-125：同轴两键同按走「后按优先」（freeMoveAxis），
     *   不能像旧代码那样相减 —— 那样按住 A 再按 D 会得到 0，角色顿一下才转向。 */
    const dx = freeMoveAxis('x');
    const dy = freeMoveAxis('y');
    if (dx || dy) {
      freeMoveTarget = null;                        /* C4：键盘优先，按下即取消点击目标 */
      const len = Math.hypot(dx, dy);               /* C2：斜向归一化，速度与直向相同 */
      const stepX = (dx / len) * FREE_MOVE_SPEED * dt;
      const stepY = (dy / len) * FREE_MOVE_SPEED * dt;
      /* ★ 事件关走分轴推进（贴墙滑行）；大厅保持「直接累加 + 事后夹边界」的原逻辑不动
       *   —— 大厅的手感人类已经验收过，不要顺手一起改。 */
      if (inRoom) freeMoveAdvance(c, stepX, stepY);
      else { c.fx += stepX; c.fy += stepY; }
      moving = true;
    } else if (freeMoveTarget) {
      const tx = freeMoveTarget.fx - c.fx;
      const ty = freeMoveTarget.fy - c.fy;
      const d = Math.hypot(tx, ty);
      /* 跟随模式用更大的死区：指针永远在微动，0.05 会让角色在指针附近每帧微抖（ISSUE-18 约束 2） */
      const arrive = freeMoveTarget.follow ? FREE_MOVE_FOLLOW_DEADZONE : FREE_MOVE_ARRIVE;
      if (d <= arrive) {
        freeMoveTarget = null;                      /* B3：到点就停，不抖 */
      } else {
        const step = Math.min(d, FREE_MOVE_SPEED * dt);
        const stepX = (tx / d) * step;
        const stepY = (ty / d) * step;
        if (inRoom) {
          /* 两轴都被挡 = 真的推不动（正对着一面墙）→ 清掉目标点。
           * 不清的话每帧都会朝同一面墙推进，rAF 永不停：（玩家看到的是「角色站在墙边"用力"，但没反应」）。
           * 只有一轴被挡时不清理 —— 那正是「贴墙滑行」要的效果。 */
          const r = freeMoveAdvance(c, stepX, stepY);
          if (r.blockedBoth) freeMoveTarget = null;
          else moving = r.moved;
        } else {
          c.fx += stepX;
          c.fy += stepY;
          moving = true;
        }
      }
    }
    }   /* ← 结束 ISSUE-20261031-130 的「非逐格」分支 */
    if (!inRoom) {
      /* F1：中心点夹在可行走区域内 —— 左右两列仍是墙，上下两行可走（出口行 / 角色行） */
      const minX = 1, maxX = COLS - 2, minY = 0, maxY = ROWS - 1;
      if (c.fx < minX) { c.fx = minX; freeMoveTarget = null; }
      if (c.fx > maxX) { c.fx = maxX; freeMoveTarget = null; }
      if (c.fy < minY) { c.fy = minY; freeMoveTarget = null; }
      if (c.fy > maxY) { c.fy = maxY; freeMoveTarget = null; }
    } else {
      /* 事件关的兜底夹取：墙体碰撞已经拦住了正常路径，这里只防「房间尺寸被改小 /
       * 格子几何量出错」这类数值飘出去的情况 —— 飘出去会让 freeMovePlace
       * 把角色画到棋盘外面，看起来像「角色消失了」。 */
      if (c.fx < 0) { c.fx = 0; freeMoveTarget = null; }
      if (c.fx > COLS - 1) { c.fx = COLS - 1; freeMoveTarget = null; }
      if (c.fy < 0) { c.fy = 0; freeMoveTarget = null; }
      if (c.fy > ROWS - 1) { c.fy = ROWS - 1; freeMoveTarget = null; }
    }
    /* 兼容：整数格坐标跟着小数坐标走（其他逻辑/测试仍读 x / y） */
    c.x = Math.round(c.fx);
    c.y = Math.round(c.fy);
    /* ★ 事件关：把整数坐标写回 player —— 渲染 / 特效 / 落点判定读的都是 player.x/y。
     * 不写回的话，棋盘格里的「你在这里」标记会一直留在出生点。 */
    if (inRoom && player) { player.x = c.x; player.y = c.y; }
    freeMovePlace(c);

    if (inRoom) {
      /* ---------------- 事件关：❓ 立即触发 / 出口停留 0.15s ---------------- */
      const obj = eventObjectTouched(c);
      if (obj) {
        /* ★ 吸附到 ❓ 的格心再停表。触发半径是 0.5 格，停表那一帧角色正好停在**两格交界**上
         *   （实测 fy=5.5），抽屉关掉之后看着像「站在格子缝里」；更麻烦的是
         *   `Math.round(5.5) === 6`，写回 player.y 会比 ❓ 实际所在格**偏一格**。
         *   ❓ 一定生成在可走格上，所以这次吸附不会把人塞进墙里。 */
        c.fx = obj.x; c.fy = obj.y; c.x = obj.x; c.y = obj.y;
        if (player) { player.x = obj.x; player.y = obj.y; }
        freeMovePlace(c);
        /* 先停表再弹抽屉：抽屉盖住棋盘，指针事件到不了 board，
         * 但键盘 WASD 没有遮罩 —— 不停表的话玩家能一边看抽屉一边把角色走开。 */
        stopFreeMove();
        if (typeof eventObjectTouch === 'function') { eventObjectTouch(obj); return; }
      }
      if (eventExitTouched(c)) {
        freeMoveExitDwell += dt;
        if (freeMoveExitDwell >= FREE_MOVE_EXIT_DWELL) {
          stopFreeMove();
          if (typeof exitEventLevel === 'function') { exitEventLevel(); return; }
        }
      } else {
        freeMoveExitDwell = 0;
      }
      /* 续帧条件要带上「站在出口格里」：否则站定在门上时 rAF 会停，
       * dwell 永远累不到 0.15s —— 和大厅 ISUUE-18 D1 同一个坑。 */
      if (moving || freeMoveTarget || eventExitTouched(c)) {
        freeMoveRaf = requestAnimationFrame(freeMoveTick);
      } else {
        freeMoveLast = 0;
      }
      return;
    }

    /* ---------------- 大厅：出口 / 联机入口判定（原逻辑一字未改） ---------------- */
    const zone = freeMoveZoneOf(c);
    if (zone) {
      freeMoveExitDwell += dt;
      if (freeMoveExitDwell >= FREE_MOVE_EXIT_DWELL) {
        const hit = zone === 'online' ? freeMoveTouchesOnline(c) : freeMoveTouchesExit(c);
        if (hit) return;
      }
    } else {
      freeMoveExitDwell = 0;
    }
    if (moving || freeMoveTarget || zone) {
      freeMoveRaf = requestAnimationFrame(freeMoveTick);
    } else {
      freeMoveLast = 0;   /* 静止且不在出口区：停表，等下一次输入再 kick，不空转烧 CPU */
    }
    return;
  }
  freeMoveLast = 0;
}

/* 按键松开 / 失焦都要清空按键表，否则切窗口回来角色会一直朝一个方向跑（C3） */
document.addEventListener('keyup', (e) => {
  if (!isFreeMovePhase()) return;
  freeMoveKeyUp(String(e.key || '').toLowerCase());
});
window.addEventListener('blur', () => { if (isFreeMovePhase()) freeMoveClearKeys(); });
document.addEventListener('visibilitychange', () => {
  if (document.hidden && isFreeMovePhase()) freeMoveClearKeys();
});

/* 尺寸变化（含横竖屏切换）后格间距会变，重量一次几何再整体摆位 */
window.addEventListener('resize', () => {
  if (!isFreeMovePhase()) return;
  setTimeout(() => {
    if (!isFreeMovePhase()) return;
    if (!freeMoveMeasure()) return;
    freeMoveRenderAll();
  }, 140);
});

/* ISSUE-18：pointermove 用缓存的视口偏移换算坐标，页面一滚缓存就偏了 → 滚动时重测。
 * passive + 只在自由移动相位里干活，不阻塞滚动。 */
window.addEventListener('scroll', () => {
  if (!isFreeMovePhase()) return;
  freeMoveMeasure();
}, { passive: true });

/* =========================================================================
 * ★ ISSUE-20261031-130 · 设置面板「移动·逐格 / 移动·平滑」开关
 *
 * 写法照抄 ISSUE-98 的光标开关（`<html>` 挂 class + localStorage，不新造机制）：
 *   · 没有 `smooth-free-move` class  = 逐格（**默认**，人类拍板 9）
 *   · 有   `smooth-free-move` class  = 平滑（老的连续坐标手感）
 * ★ 作用域只有选角厅：事件关在 `stepMoveMode()` 里硬编码为逐格，**根本不读这个 class**
 *   （拍板 4「在大厅可以用设置切换，其他地方不行」+ R6）。
 * ★ 文案写「逐格 / 平滑」而不是「新 / 旧」：半年后没人知道哪个是新的。
 * 整段包 IIFE：产物是单脚本共享作用域，避免新顶层标识符撞名（verify 有「无重复定义」检查）。
 * ========================================================================= */
(function initStepMoveToggle() {
  const btn = document.getElementById('stepToggleBtn');
  function isStep() {
    return !document.documentElement.classList.contains(STEP_MOVE_SMOOTH_CLASS);
  }
  function apply(step, save) {
    document.documentElement.classList.toggle(STEP_MOVE_SMOOTH_CLASS, !step);
    if (btn) {
      btn.textContent = step ? '移动·逐格' : '移动·平滑';
      btn.title = step
        ? '当前：逐格（按一下走一格，落点恒在格心）· 点击切回平滑'
        : '当前：平滑（按住连续走，可斜走 / 贴墙滑行）· 点击切回逐格';
      btn.setAttribute('aria-pressed', step ? 'true' : 'false');
    }
    /* 切换时把残留的队列 / 路径 / 点击目标清干净：
     * 「平滑走到半格 → 切逐格」如果留着一个旧目标点，下一步会先被自动寻路接走，
     * 玩家会看到角色自己又走了一步。坐标本身不动（第一步会自然对齐到格心）。 */
    stepMoveReset();
    freeMoveTarget = null;
    if (save) { try { localStorage.setItem(STEP_MOVE_KEY, step ? '1' : '0'); } catch (_) {} }
  }
  let saved = null;
  try { saved = localStorage.getItem(STEP_MOVE_KEY); } catch (_) {}
  apply(saved !== '0', false);   /* 无记忆 / 读不到 → 默认逐格 */
  if (btn) {
    btn.addEventListener('click', function (e) {
      e.stopPropagation();
      apply(!isStep(), true);
    });
  }
})();

/* src: src/ui/board-fx.js */
/* P0.1-4 拆分 · 20261028c 基线 2052-2340 行 · 棋盘几何与特效：findPath / getBoundingBox / getCellEl / cellCenter / unitCenter / facingIndicatorHtml / unitHtml / hasLineOfSight / canRangedAttack / playerAttackRangeCells / 敌人首步箭头 / floatText / ringFx / slashFx / animateBullet / hitFx / missFx / refreshUnits */
function findPath(startX, startY, targetX, targetY, maxSteps = 99) {
  if (startX === targetX && startY === targetY) return [];
  const queue = [{ x: startX, y: startY, path: [] }];
  const visited = new Set();
  visited.add(key(startX, startY));
  const dirs = DIR4_BFS;
  while (queue.length > 0) {
    const curr = queue.shift();
    if (curr.path.length >= maxSteps) continue;
    for (const [dx, dy] of dirs) {
      const nx = curr.x + dx, ny = curr.y + dy;
      if (!isWalkable(nx, ny)) continue;
      if (visited.has(key(nx, ny))) continue;
      if (phase === PHASE.CHAR_SELECT) {
        if (charCandidates.some(c => c !== selectedCandidate && c.x === nx && c.y === ny && (nx !== targetX || ny !== targetY))) continue;
      } else if (phase === PHASE.PLANNING) {
        if (nx === player.x && ny === player.y) continue;
      }
      visited.add(key(nx, ny));
      const newPath = [...curr.path, { x: nx, y: ny }];
      if (nx === targetX && ny === targetY) return newPath;
      queue.push({ x: nx, y: ny, path: newPath });
    }
  }
  return null;
}

/* =========================================================================
 * ISSUE-20261029-43 · 棋盘必须是正方形（人类 2026-10-29 16:2x）
 *
 * 「包围盒」是渲染真源：render() 用它写 gridTemplateColumns/Rows，
 * buildBoardHtml() 只遍历这个范围 —— 所以包围盒不方，棋盘就不方，
 * 覆盖棋盘的弹窗（设置 / 角色）也跟着变成竖条。
 *
 * 实测：地图本体 11×11，但包围盒被裁成 10 列 × 11 行 → 棋盘 794×874。
 * 这里把它补成 side×side 的正方形窗口：
 *   1. side = max(列数, 行数)；
 *   2. **优先向右下扩展**（左上角不动 —— 玩家相对位置不跳），
 *      扩展格落在原有墙区，所以只是「多露出一圈石头」，不会凭空造出可走格；
 *   3. 右侧/下方越界 → 整体左移/上移这个窗口，仍保持正方形；
 *   4. 只有「地图本身 ROWS≠COLS 且 side 放不下」这一种情况才会退回非正方形
 *      （当前所有关卡与联机竞技场都是方图，走不到这里）。
 *
 * ★ 改这个函数等于改所有渲染路径：不要在这里读 DOM / 量尺寸（每帧多次调用）。
 * ★ 里面是纯计算，扩展出来的坐标一定在 0..ROWS-1 / 0..COLS-1 内，
 *   所以 buildBoardHtml 照常读 m[y][x] 即可，不需要额外判空。
 * ========================================================================= */
function getBoundingBox() {
  let minX = COLS, maxX = -1, minY = ROWS, maxY = -1;
  const m = phase === PHASE.CHAR_SELECT ? selMap : map;
  for (let y = 0; y < ROWS; y++) for (let x = 0; x < COLS; x++) {
    let v = false;
    if (m[y][x] === 0) v = true;
    else if (m[y][x] === 1) {
      for (const [dx, dy] of DIR4) {
        const nx = x + dx, ny = y + dy;
        if (nx >= 0 && nx < COLS && ny >= 0 && ny < ROWS && m[ny][nx] === 0) { v = true; break; }
      }
    }
    if (v) { minX = Math.min(minX, x); maxX = Math.max(maxX, x); minY = Math.min(minY, y); maxY = Math.max(maxY, y); }
  }
  if (minX === COLS) return { minX: 0, maxX: COLS - 1, minY: 0, maxY: ROWS - 1 };
  return squareifyBox(minX, maxX, minY, maxY);
}

/** 把紧包围盒撑成正方形（见上方长注释）。纯函数，不碰 DOM。 */
function squareifyBox(minX, maxX, minY, maxY) {
  const bc = maxX - minX + 1, br = maxY - minY + 1;
  if (bc === br) return { minX, maxX, minY, maxY };   // 已经是正方形，一行都不改
  const side = Math.max(bc, br);
  const sx = Math.min(side, COLS), sy = Math.min(side, ROWS);
  let x0 = Math.min(minX, COLS - sx);
  let y0 = Math.min(minY, ROWS - sy);
  x0 = Math.max(0, x0);
  y0 = Math.max(0, y0);
  return { minX: x0, maxX: x0 + sx - 1, minY: y0, maxY: y0 + sy - 1 };
}

function getCellEl(x, y) { return boardEl.querySelector(`.cell[data-x="${x}"][data-y="${y}"]`); }
function cellCenter(x, y) {
  const cell = getCellEl(x, y);
  if (cell) {
    const r = cell.getBoundingClientRect();
    const lr = fxLayer.getBoundingClientRect();
    return { x: r.left - lr.left + r.width / 2, y: r.top - lr.top + r.height / 2 };
  }
  return { x: 0, y: 0 };
}
/* ISSUE-20261030-56：当前格边长（px）。--cell 由 updateCellSize() 写在 :root 上，
 * 斜带偏移要用它换算；读一次就够，别在每个格子里重复 getComputedStyle。 */
function cellSizePx() {
  const v = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--cell'));
  return (!v || !isFinite(v)) ? 0 : v;
}
function unitCenter(x, y, unitKey) {
  /* ★ ISSUE-20261030-56：第三参 unitKey 可选，不传 = 与改动前完全一致（向后兼容）。
   * 传了就把中心挪到该单位自己那条斜带 —— 否则同格两个单位同时掉血时，
   * 「护盾抵消」和「-3」会精确叠在一起，看成一个。 */
  const off = unitKey ? stackOffsetFor(unitKey, x, y) : null;
  const cell = getCellEl(x, y);
  if (cell) {
    const icon = cell.querySelector('.icon');
    if (icon) {
      const r = icon.getBoundingClientRect();
      const lr = fxLayer.getBoundingClientRect();
      return {
        x: r.left - lr.left + r.width / 2 + (off ? off.dx : 0),
        y: r.top - lr.top + r.height / 2 + (off ? off.dy : 0),
      };
    }
  }
  const c = cellCenter(x, y);
  if (off) { c.x += off.dx; c.y += off.dy; }
  return c;
}
function facingIndicatorHtml(facing) {
  if (!facing) return '';
  const v = FACING_GLYPH[facing.dx + ',' + facing.dy];
  if (!v) return '';
  return `<div class="facing-ind ${v[1]}">${v[0]}</div>`;
}
function unitHtml(icon, hp, opts = {}) {
  const { isGhost = false, maxHp = 1, isPlayer = false, facing = null } = opts;
  const pct = maxHp > 0 ? Math.max(0, Math.min(100, (hp / maxHp) * 100)) : 0;
  const color = isPlayer ? '#3b9eff' : '#e74c3c';
  const iconClass = isGhost ? 'icon ghost-icon' : 'icon';
  return `<div class="unit">${facingIndicatorHtml(facing)}<div class="${iconClass}">${icon}</div><div class="hp-bar"><div class="hp-fill" style="width:${pct}%;background:${color};"></div></div></div>`;
}
function hasLineOfSight(from, to) {
  const distCheb = Math.max(Math.abs(to.x - from.x), Math.abs(to.y - from.y));
  if (distCheb === 0) return true;
  if (distCheb === 1) return true;
  let x0 = from.x, y0 = from.y;
  const x1 = to.x, y1 = to.y;
  const dx = Math.abs(x1 - x0);
  const dy = -Math.abs(y1 - y0);
  const sx = x0 < x1 ? 1 : -1;
  const sy = y0 < y1 ? 1 : -1;
  let err = dx + dy;
  while (true) {
    if (!(x0 === from.x && y0 === from.y) && !(x0 === x1 && y0 === y1)) {
      if (!inBounds(x0, y0)) return false;
      if (map[y0][x0] === 1) return false;
    }
    if (x0 === x1 && y0 === y1) break;
    const e2 = 2 * err;
    const moveX = e2 >= dy;
    const moveY = e2 <= dx;
    if (moveX) { err += dy; x0 += sx; }
    if (moveY) { err += dx; y0 += sy; }
    // ★ 斜向拐角穿透检测：同时跨 X、Y（对角线步）时，不能从两个相邻墙的夹角里钻过去。
    // 若「横向相邻格」与「纵向相邻格」都是墙，则这条对角连线被堵死。
    if (moveX && moveY) {
      const cornerX = x0 - sx; // 横向侧格（本步起点的那一列）
      const cornerY = y0 - sy; // 纵向侧格（本步起点的那一行）
      const blockedA = inBounds(cornerX, y0) ? (map[y0][cornerX] === 1) : true;
      const blockedB = inBounds(x0, cornerY) ? (map[cornerY][x0] === 1) : true;
      if (blockedA && blockedB) return false;
    }
  }
  return true;
}
/* 远程攻击可达性判定。range 省略时取 player.range。
 * 幽灵：停在墙格内时无敌（无法被命中）；站在墙外可走格时仍需视线，
 * 不可隔墙命中（即「墙后幽灵」必须没被墙挡住视线才能打）。 */
function canRangedAttack(from, target, range) {
  const r = (range === undefined) ? player.range : range;
  if (cheb(from, target) > r) return false;
  if (target.type === 'ghost') {
    if (map[target.y][target.x] === 1) return false;  // 墙里的幽灵无敌（保留设计意图）
    // 墙外幽灵：继续走下面的视线判定，避免隔墙命中
  }
  return hasLineOfSight(from, target);
}
/* 「攻击范围」高亮：以第一个攻击节点（没有则当前位置）为圆心，
 * 远程角色取 player.range，近战角色取相邻 1 格；视线被墙挡掉的格子不算。 */
function playerAttackRangeCells() {
  const set = new Set();
  if (phase !== PHASE.PLANNING || !player) return set;
  /* ISSUE-20261028-19：攻击类型按当前六维现算（预备干员可翻转），不要再读静态角色表 */
  const range = playerIsRanged() ? (player.range || PLAYER_RANGE) : 1;
  const origin = rangeDisplayOrigin();
  if (!origin) return set;
  for (let y = origin.y - range; y <= origin.y + range; y++) {
    for (let x = origin.x - range; x <= origin.x + range; x++) {
      if (!inBounds(x, y)) continue;
      if (map[y][x] === 1) continue;
      const d = Math.max(Math.abs(x - origin.x), Math.abs(y - origin.y));
      if (d > range) continue;
      if (d > 0 && !hasLineOfSight(origin, { x, y })) continue;
      set.add(key(x, y));
    }
  }
  return set;
}

function showEnemyFirstStepArrows() {
  clearEnemyArrows();
  if (phase !== PHASE.PLANNING) return;
  /* ★ ISSUE-20261031-120（人类拍板 Q4 + 2.4）：**恢复意图显示**。
   *   这里原来是 `ISSUE-20261031-100-③` 的全局 `return`（意图全部不显示），
   *   下面那一整段画箭头的代码全是死代码。现在按人类口径恢复：
   *   「看不到意图」本来就该是**猴王 🙈 形态**的效果，而不是全局关死。
   * ⚠️ 与 templates/game.html#logEnemyMainDirections 必须成对 —— 只藏箭头不藏日志，
   *    等于把藏起来的信息用文字又说了一遍。 */
  const intentHidden = (typeof kingHidesIntent === 'function') && kingHidesIntent();
  if (intentHidden) return;
  const cellSize = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--cell')) || 50;
  const offset = cellSize * 0.35;
  enemies.forEach((e, i) => {
    if (!e.alive) return;
    if (e.stunTurns > 0) return;
    const path = enemyPaths[i];
    if (!path || path.length < 2) return;
    /* ★ 括号别漏：三元表达式的 else 分支会把后面的 + 吞进去（`x ? a : 0 + b` 是 `x ? a : (0+b)`） */
    const extra = ((selectedChar === 'amiya' && e.amiyaRevealActive) ? e.amiyaRevealActive : 0)
      + (e.type === BOSS_TYPE ? BOSS_INTENT_EXTRA_STEPS : 0);
    const stepsToShow = (player ? player.visibleSteps : 1) + extra;
    for (let s = 1; s <= stepsToShow && s < path.length; s++) {
      const prev = path[s-1], curr = path[s];
      const dx = Math.sign(curr.x - prev.x), dy = Math.sign(curr.y - prev.y);
      const ch = ARROW_CHARS[`${dx},${dy}`];
      if (!ch) continue;
      let ox = 0, oy = 0;
      if (dx === -1) ox = offset; if (dx === 1) ox = -offset;
      if (dy === -1) oy = offset; if (dy === 1) oy = -offset;
      const c = cellCenter(curr.x, curr.y);
      const el = document.createElement('div');
      el.className = 'enemy-arrow';
      el.textContent = ch;
      el.style.left = (c.x + ox) + 'px';
      el.style.top = (c.y + oy) + 'px';
      fxLayer.appendChild(el);
      enemyArrows.push(el);
    }
  });
}
function clearEnemyArrows() { enemyArrows.forEach(el => el.remove()); enemyArrows = []; }

/* unitKey（ISSUE-20261030-56，可选）：浮字落进该单位那条斜带，不传则落在格心（照旧）。 */
function floatText(x, y, text, color, isCrit, offsetY = 0, unitKey) {
  const c = unitKey ? unitCenter(x, y, unitKey) : cellCenter(x, y);
  floatTextAt(c.x, c.y, text, color, isCrit, offsetY);
}
function floatTextAt(px, py, text, color, isCrit, offsetY = 0, extraClass = '') {
  const el = document.createElement('div');
  el.className = 'float-text' + (isCrit ? ' crit' : '') + (extraClass ? ' ' + extraClass : '');
  el.textContent = text;
  if (!isCrit) el.style.color = color;
  el.style.left = px + 'px';
  el.style.top = (py + offsetY) + 'px';
  fxLayer.appendChild(el);
  const endScale = isCrit ? 1.7 : 1.35, startScale = isCrit ? 0.9 : 0.7;
  el.animate([
    { transform: `translate(-50%,-50%) scale(${startScale})`, opacity: 0.2, offset: 0 },
    { transform: `translate(-50%,-130%) scale(${endScale})`, opacity: 1, offset: 0.35 },
    { transform: `translate(-50%,-200%) scale(${endScale * 0.9})`, opacity: 0, offset: 1 }
  ], { duration: isCrit ? 1000 : 800, easing: 'ease-out' }).finished
    .then(() => el.remove())
    .catch(() => el.remove());
}
/* unitKey（ISSUE-20261030-56，可选）：特效落在该单位那条斜带的中心，不传则落在格心（照旧）。 */
function ringFx(x, y, color, unitKey) {
  const c = unitKey ? unitCenter(x, y, unitKey) : cellCenter(x, y);
  const el = document.createElement('div');
  el.className = 'ring-fx';
  el.style.left = c.x + 'px';
  el.style.top = c.y + 'px';
  el.style.borderColor = color;
  el.style.boxShadow = `0 0 14px ${color}`;
  fxLayer.appendChild(el);
  el.animate([{ transform: 'translate(-50%,-50%) scale(0.2)', opacity: 1 }, { transform: 'translate(-50%,-50%) scale(1.9)', opacity: 0 }], { duration: 420, easing: 'ease-out' }).finished
    .then(() => el.remove())
    .catch(() => el.remove());
}
function slashFx(x, y, color, unitKey) {
  const c = unitKey ? unitCenter(x, y, unitKey) : cellCenter(x, y);
  const el = document.createElement('div');
  el.className = 'slash-fx';
  el.style.left = c.x + 'px';
  el.style.top = c.y + 'px';
  el.style.filter = `drop-shadow(0 0 6px ${color})`;
  fxLayer.appendChild(el);
  el.animate([{ transform: 'translate(-50%,-50%) scale(0.4) rotate(0deg)', opacity: 1 }, { transform: 'translate(-50%,-50%) scale(1.2) rotate(25deg)', opacity: 0 }], { duration: 360, easing: 'ease-out' }).finished
    .then(() => el.remove())
    .catch(() => el.remove());
}
function getLiveCenter(unitKey, layerRect) {
  const rec = unitEls.get(unitKey);
  if (!rec) return null;
  const r = rec.el.getBoundingClientRect();
  /* ISSUE-20261030-56：同格多单位时 .unit-abs 的盒子仍是整格，
   * 所以这里要再按斜带偏移一次，子弹才会落到目标自己那条带上。
   * 偏移量直接读 renderUnits 写在行内的 --stk-dx/--stk-dy（N=1 时没有，退回 0）。 */
  const dx = parseFloat(rec.el.style.getPropertyValue('--stk-dx')) || 0;
  const dy = parseFloat(rec.el.style.getPropertyValue('--stk-dy')) || 0;
  return {
    x: r.left - layerRect.left + r.width / 2 + dx,
    y: r.top - layerRect.top + r.height / 2 + dy,
  };
}
/* noteSlug：ISSUE-20261031-114 —— 阿米娅音符弹道（musical_note 普通 / musical_notes 爆发）。
 * 为什么用参数传、不在函数内读 selectedChar：普通远程与精神爆发走**两个不同调用点**，
 * 读全局根本区分不了「这一次是普通还是爆发」，两者会变成同一个音符。 */
async function animateBullet(fromPos, targetKey, fallback, isCrit, isAlien, fromKey, noteSlug) {
  const layerRect = fxLayer.getBoundingClientRect();
  const start = (fromKey && getLiveCenter(fromKey, layerRect)) || unitCenter(fromPos.x, fromPos.y);
  const bullet = document.createElement('div');
  bullet.className = 'bullet' + (isCrit ? ' crit' : '') + (isAlien ? ' alien' : '')
                   + (noteSlug ? ' note' : '');
  bullet.style.left = '0px';
  bullet.style.top = '0px';
  bullet.style.transform = `translate(${start.x}px, ${start.y}px) translate(-50%,-50%)`;
  /* 音符走 SVG 图标（与全项目图标同一套 fluent_flat），没有 slug 就还是原来的圆点 */
  if (noteSlug) bullet.innerHTML = iconTag(noteSlug, 'vico bullet-ico');
  fxLayer.appendChild(bullet);
  let bx = start.x, by = start.y;
  const startTime = performance.now();
  const SPEED_PX_PER_MS = 0.85;
  const HARD_TIMEOUT = 900;
  await new Promise(resolve => {
    function tick(now) {
      const live = getLiveCenter(targetKey, layerRect)
                || (fallback ? unitCenter(fallback.x, fallback.y) : null);
      if (!live) { resolve(); return; }
      const dx = live.x - bx, dy = live.y - by;
      const d = Math.hypot(dx, dy);
      if (d < 6 || now - startTime > HARD_TIMEOUT) { resolve(); return; }
      const frameTravel = Math.min(d, SPEED_PX_PER_MS * 16.67);
      bx += dx / d * frameTravel;
      by += dy / d * frameTravel;
      bullet.style.transform = `translate(${bx}px, ${by}px) translate(-50%,-50%)`;
      requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  });
  bullet.remove();
}
function hitFlashCell(x, y) {
  const cell = getCellEl(x, y);
  if (!cell) return;
  cell.classList.remove('hitflash');
  void cell.offsetWidth;
  cell.classList.add('hitflash');
}

/* 战斗结算后同步单位层与数值面板（原为成对的 renderUnits(); updateStats();） */
function refreshUnits() { renderUnits(); updateStats(); }

/* 统一命中/暴击特效：暴击走橙环 + 金字，普通命中走黄环 + 淡黄字。
 * label 为暴击前缀文案（如「暴击」「爆发暴击」），仅暴击时拼接。 */
function hitFx(x, y, dmg, isCrit, label) {
  ringFx(x, y, isCrit ? '#ff4500' : '#ffe66d');
  hitFlashCell(x, y);
  floatText(x, y, (isCrit ? label + ' -' : '-') + dmg, isCrit ? '#ffd700' : '#ffe66d', isCrit);
}

/* 统一未命中特效 */
function missFx(x, y) {
  floatText(x, y, 'MISS', '#bbb');
}

/* src: src/rules/event-levels.js */
/* ISSUE-20261031-126 · 事件关卡注册表
 *
 * 事件关 = 非战斗、角色自由走动的房间。每通过 EVENT_LEVEL_EVERY_N_BATTLES 个战斗关进一次。
 * 现在的玩法是「走进去 → 踩到 ❓ 弹出事件抽屉 → 选完 → 出口解锁 → 走到出口离开」。
 *
 * ★ 为什么做成**注册表**而不是写死一张图（人类 21:4x 拍板 13「暂时 1 个，以后会增加」）：
 *   以后加房间 = 往 `EVENT_LEVELS` 里 push 一条，`initEventLevel()` / 渲染 / 测试一行都不用改。
 *   写死一张图的话，加第二个房间要动主流程（相位切换、出口判定、渲染分支全都要带上房间概念）。
 *
 * 一条定义的字段（全部必需，缺一个就到不了出口）：
 *   id       唯一标识（日志 / 测试用）
 *   name     房间名（进关日志与 HUD 用）
 *   rows/cols 尺寸，默认与战斗关一致（11×11）。**改动必须同步 BOARD_ROWS/COLS 的假设**
 *            （格栅 CSS 是 --cell 驱动的正方形格，行列不等会被拉伸）
 *   spawn    玩家出生格 {x,y}，必须是地板
 *   exit     出口格 {x,y}。允许落在墙上 —— buildEventRoomMap 会**显式挖开**它，
 *            否则「一扇开在墙里的门」会变成「一堵看起来像门的墙」，玩家走不进去
 *   objects  可交互物模板 [{ x, y, kind }]，kind 现在只有 'event'（= ❓ 事件点）。
 *            以后要加宝箱/商人/休息点，就在这里扩 kind，并在 game.html 的
 *            `eventObjectHtml()`（渲染）与 `eventObjectTouch()`（触发）两处各加一个分支。
 *
 * ⚠️ 坐标口径（本文件最容易搞反的地方，与选角厅一致）：
 *   人类描述 y 从**下往上**，代码 y 从上往下 → **代码 y = rows − 1 − 人类 y**。
 *   所以「底部出生」在代码里是 y = rows−1 = 10，「顶部出口」是 y = 0。
 */

const EVENT_LEVELS = [
  {
    id: 'empty_room',
    name: '空房间',
    rows: BOARD_ROWS,
    cols: BOARD_COLS,
    /* 人类 21:5x 拍板 9「11×11 纯空大地，只有外墙」+ 默认值「出生底中 (5,10) / 出口顶中 (5,0) / ❓ 中央 (5,5)」 */
    spawn: { x: 5, y: 10 },
    exit:  { x: 5, y: 0 },
    objects: [
      { x: 5, y: 5, kind: 'event' },
    ],
  },
];

/* 从注册表里随机抽一张房间。
 * ★ 走 `randInt`（= rng 派生）而不是 Math.random：门禁硬断言「全库禁止 Math.random」，
 *   且同 RUN_SEED 下重开必须得到同一张图（目前只有 1 张，等价于固定；以后多张才看得出差别）。
 * 注册表为空时返回 null —— 调用方 `initEventLevel()` 会退回「直接进下一战斗关」，
 *   不能让一次误删数据把整局卡死在事件相位里。 */
function pickEventLevel() {
  if (!EVENT_LEVELS.length) return null;
  return EVENT_LEVELS[randInt(EVENT_LEVELS.length)];
}

/* 按定义生成房间地图：四周一圈墙 + 内部空 + 显式挖开出口与所有交互物格。
 *
 * ★ 出口/交互物必须显式置 0（不能只依赖「定义里没写墙」）：
 *   出口按设计就开在**顶行的墙上**，那格本来就是 1；不挖开就是「门在墙里走不进去」。
 *   交互物同理 —— 以后如果有人把 ❓ 摆在角落，也应该是地板。
 * ★ 内部**不摆任何障碍**（人类拍板 9「纯空大地」）：一眼能看穿到对面出口，不会迷路。 */
function buildEventRoomMap(def) {
  const rows = def.rows || BOARD_ROWS;
  const cols = def.cols || BOARD_COLS;
  const m = Array.from({ length: rows }, () => Array(cols).fill(0));
  for (let y = 0; y < rows; y++) { m[y][0] = 1; m[y][cols - 1] = 1; }
  for (let x = 0; x < cols; x++) { m[0][x] = 1; m[rows - 1][x] = 1; }
  const dig = (p) => {
    if (!p) return;
    if (p.y < 0 || p.y >= rows || p.x < 0 || p.x >= cols) return;
    m[p.y][p.x] = 0;
  };
  dig(def.spawn);
  dig(def.exit);
  for (const o of (def.objects || [])) dig(o);
  return m;
}

/* 房间里的交互物实例化：把模板拷成带 `used` 标记的运行时对象。
 * ★ 必须深拷（不能直接用模板对象）：template 是模块级常量，写一次 `used = true`
 *   会永久污染注册表 —— 这一局用完之后，下一局同一张房间里的 ❓ 一进去就是「已用过」。 */
function instantiateEventObjects(def) {
  return (def.objects || []).map((o, i) => ({
    id: i,
    x: o.x, y: o.y,
    kind: o.kind || 'event',
    used: false,
  }));
}

/* 出口是否该解锁：所有交互物都 used 过。
 * 现在只有 1 个 ❓；写成「全部」而不是「第 0 个」是为了以后加多个事件点时天然正确
 * （人类拍板 10 的口径就是「弹完事件才开启」，多事件点自然演变成「都看完才开」）。 */
function eventAllObjectsUsed() {
  if (!eventObjects.length) return true;
  return eventObjects.every(o => o.used);
}

/* src: src/ui/debug_names.js */
/* =========================================================================
 * ISSUE-20261030-86 · 调试标注层：按住 Shift 把光标移到元件上，浮出「中文名 + 选择器」
 * ----------------------------------------------------------------------------
 * 人类原话（泽雨 2026-10-30 21:5x）：
 *   「给每个面板都加一个名称，在调试模式按下 Shift、光标对准就显示，
 *     这样我以后给出建议也能更加精准。」
 *
 * 目标不是「好玩」，是让反馈能精确点名：「把 📟 奖励角标往左挪 2px」
 * 而不是「那个按钮」。所以 tooltip 里必须同时给**中文名**和**可复制的选择器**。
 *
 * 设计底线（改之前先读）：
 *  1. **正式构建零开销**：只有 URL 带 `?debug=1`（或 `window.__ARK_DEBUG_NAMES`）才挂监听、
 *     才建 tooltip 节点。没开时这个文件跑完就 return，一个 listener 都不留。
 *  2. **绝不干扰游戏**：监听全部 passive，绝不 preventDefault / stopPropagation ——
 *     Shift 在本游戏里不是快捷键，但仍不许拦截，免得将来加了快捷键就打架。
 *  3. **只读**：不写任何游戏状态、不碰 canvas、不触发重排以外的副作用。
 *  4. 命中测试用 `elementFromPoint`（取最顶层元素）再向上 `closest` 回溯，
 *     不自己算 z-index / 坐标 —— 布局由 CSS 决定，重算必错。
 * ========================================================================= */

const DEBUG_NAMES_ENABLED = (function () {
  try {
    if (window.__ARK_DEBUG_NAMES) return true;
    const q = new URLSearchParams(window.location.search || '');
    return q.get('debug') === '1';
  } catch (_) { return false; }
})();

let debugNamesShift = false;
let debugNamesRaf = 0;
let debugNamesTip = null;
let debugNamesLast = null;      /* 上次光标位置，rAF 里取用 */

/* 选择器：优先带 id / data-drawer 的精确写法，退到 tag.class，最后只剩 tag */
function debugNameSelector(el) {
  if (!el) return '?';
  if (el.id) return '#' + el.id;
  const dw = el.getAttribute && el.getAttribute('data-drawer');
  if (dw) return '[data-drawer="' + dw + '"]';
  const tag = (el.tagName || 'div').toLowerCase();
  const cls = (el.className && typeof el.className === 'string')
    ? el.className.trim().split(/\s+/).filter(Boolean).slice(0, 2).join('.')
    : '';
  return cls ? tag + '.' + cls : tag;
}

/* 从光标下的元素往上找「最近一个说得清自己是谁的」：
 *   抽屉遮罩(优先报当前抽屉) → data-debug-name → data-drawer(取 drawer-title) → id → tagName
 * ★ 遮罩为什么排在最前：遮罩本身也标了 data-debug-name="抽屉遮罩"，但那个名字没用 ——
 *   玩家真正想知道的是「现在开着哪个抽屉」。收起态抽屉是 visibility:hidden，
 *   elementFromPoint 取不到，只能靠 drawerCurrent 兜底。 */
function debugNameResolve(el) {
  if (!el || typeof el.closest !== 'function') return null;
  const mask = el.closest('#drawerMask');
  if (mask) {
    const cur = (typeof drawerCurrent !== 'undefined') ? drawerCurrent : null;
    if (cur) {
      const d = document.querySelector('[data-drawer="' + cur + '"]');
      const t = d && d.querySelector('.drawer-title');
      return {
        name: (t && t.textContent ? t.textContent.trim() : cur) + ' · 遮罩（当前抽屉）',
        sel: '[data-drawer="' + cur + '"]',
      };
    }
    return { name: '抽屉遮罩', sel: '#drawerMask' };
  }
  let hit = el.closest('[data-debug-name]');
  if (hit) {
    return { name: hit.getAttribute('data-debug-name'), sel: debugNameSelector(hit) };
  }
  hit = el.closest('[data-drawer]');
  if (hit) {
    const t = hit.querySelector('.drawer-title');
    const title = t && t.textContent ? t.textContent.trim() : hit.getAttribute('data-drawer');
    return { name: title || '抽屉', sel: '[data-drawer="' + hit.getAttribute('data-drawer') + '"]' };
  }
  hit = el.closest('[id]');
  if (hit) return { name: '（未命名）' + (hit.tagName || ''), sel: '#' + hit.id };
  return { name: '（未命名）' + ((el.tagName || '').toLowerCase()), sel: (el.tagName || '').toLowerCase() };
}

function debugNameShow(x, y) {
  if (!debugNamesTip) return;
  const el = document.elementFromPoint(x, y);
  const info = debugNameResolve(el);
  if (!info) { debugNamesTip.style.display = 'none'; return; }
  debugNamesTip.innerHTML = '<div class="dn-name"></div><div class="dn-sel"></div>';
  debugNamesTip.firstChild.textContent = info.name;
  debugNamesTip.lastChild.textContent = info.sel;
  debugNamesTip.style.display = 'block';
  /* 偏移 14px 避开被测元件本身；贴右/下边时翻到另一侧，永不跑出视口 */
  const vw = window.innerWidth || 1024, vh = window.innerHeight || 768;
  const r = debugNamesTip.getBoundingClientRect();
  let left = x + 14, top = y + 14;
  if (left + r.width > vw - 4) left = Math.max(4, x - r.width - 14);
  if (top + r.height > vh - 4) top = Math.max(4, y - r.height - 14);
  debugNamesTip.style.left = left + 'px';
  debugNamesTip.style.top = top + 'px';
}

function debugNameHide() {
  if (debugNamesTip) debugNamesTip.style.display = 'none';
}

function debugNamesInit() {
  if (!DEBUG_NAMES_ENABLED) return false;
  if (debugNamesTip) return true;
  debugNamesTip = document.createElement('div');
  debugNamesTip.id = 'debugNameTip';
  debugNamesTip.style.display = 'none';
  document.body.appendChild(debugNamesTip);

  /* 只挂一次：Shift 按下才进入「标注模式」 */
  window.addEventListener('keydown', function (e) {
    if (e.key === 'Shift') { debugNamesShift = true; }
  }, { passive: true });
  window.addEventListener('keyup', function (e) {
    if (e.key === 'Shift') { debugNamesShift = false; debugNameHide(); }
  }, { passive: true });
  /* 切到别的窗口回来时可能漏掉 keyup，统一在这里收一次 */
  window.addEventListener('blur', function () { debugNamesShift = false; debugNameHide(); }, { passive: true });

  /* mousemove 用 rAF 节流：elementFromPoint 会强制布局，逐事件调用在手机上会掉帧 */
  window.addEventListener('mousemove', function (e) {
    if (!debugNamesShift) return;
    debugNamesLast = { x: e.clientX, y: e.clientY };
    if (debugNamesRaf) return;
    debugNamesRaf = requestAnimationFrame(function () {
      debugNamesRaf = 0;
      if (!debugNamesShift || !debugNamesLast) return;
      debugNameShow(debugNamesLast.x, debugNamesLast.y);
    });
  }, { passive: true });

  /* 调试台提示：让知道这个功能的人一眼看到怎么用 */
  try { console.log('[debug] 按住 Shift 把光标移到元件上，可看到名称与选择器。'); } catch (_) {}
  return true;
}

debugNamesInit();

/* src: src/ui/text_edit.js */
/* =========================================================================
 * ISSUE-20261031-95 · 调试模式下「Alt + 就地编辑静态文案」
 *
 * 人类原话（2026-10-31 00:5x）：
 *   「调试模式下所有文本按住 alt 可以进行修改，修改之后会同步到服务器，
 *     这样以后我就可以自由的直接修改文本表现了」
 *
 * ★ 服务端形态已由人类 2026-10-31 12:5x 拍板走 **C 案：不落服务端**。
 *   即：本模块**不发任何网络请求**、不改 `房间服务/room-server.py`、不新增 `/api/texts`。
 *   改动只做三件事 —— 浏览器内即时生效 → 落 `localStorage` → 一键导出 `text-overrides.json`，
 *   由人/AI 拿这份 JSON 回写 `唯一正源/src/**`，再走正常发版闸门。
 *
 *   为什么只有 C 对（详见 issue §四）：
 *   产物 `game.html` 是 NB-04 单文件，文案最终必须以**字符串常量**内联进去 ——
 *   服务端 override 在最终产物里根本无处安放；硬做只会出现「源码 / 服务端」两个文案正源，
 *   这正是 89 号（部署链静默空转）踩过的同一类坑。
 *
 * ★ 判据用 `debugMode`（连点版本号 5 次 + 管理员门槛，state.js:51-79），
 *   **不用** `?debug=1`（那是 debug_names.js 的无鉴权开关）。理由：这是「能改文案」的写权限，
 *   必须跟「点敌人秒杀」同一套门槛。
 *
 * ★ 非侵入底线（对齐 86 号）：
 *   · debugMode 关闭时**一个监听器都不挂**（本文件在模块加载时只做一次 localStorage 预读）；
 *   · 全部监听 passive / 捕获阶段早退；
 *   · 正式玩家路径零新增 DOM、零 rAF、零定时器。
 * ========================================================================= */
(function () {
  'use strict';

  const LS_KEY = 'arkTextOverrides';

  /* 动态数值 / 流式追加 / 输入控件：这些改了也会被下一次渲染冲掉，
   * 编辑它们只会产生无效 overrides 项（issue §5.3 明确要求排除）。 */
  const EXCLUDE_SEL = [
    '.coin-num', '.hp-num', '.sp-num', '.turn-num',
    '#logLines', '.log-line', '.log', '.float-text', '.ring-fx', '.enemy-arrow',
    '#unitLayer', '#fxLayer', 'canvas', 'input', 'textarea', 'select',
    '[contenteditable]', '.dslider', '.tut-chip',
  ].join(',');

  let installed = false;    // 监听器是否已挂（debugMode 首次打开时挂一次，之后不再重复）
  let altDown = false;      // 是否按住 Alt（编辑态的开关）
  let editing = null;       // { el, key, from, html } 当前正在编辑的节点
  let overrides = {};       // { key: { from, to } } 内存副本，与 localStorage 双向同步

  /* ---------------- 持久化 ---------------- */

  function load() {
    try {
      const raw = window.localStorage && window.localStorage.getItem(LS_KEY);
      const o = raw ? JSON.parse(raw) : null;
      overrides = (o && typeof o === 'object') ? o : {};
    } catch (_) { overrides = {}; }
  }
  function save() {
    try { if (window.localStorage) window.localStorage.setItem(LS_KEY, JSON.stringify(overrides)); }
    catch (_) { /* 隐私模式 / 配额满：内存里仍然生效，只是不持久 —— 不弹窗、不打断 */ }
  }

  /* ---------------- 稳定 key ----------------
   * 优先 data-tid（将来铺量后最稳），否则用「标签 + :nth-of-type 链」生成路径选择器。
   * ⚠️ 路径选择器在面板重排后会漂 —— 所以每条 override 都带 `from`（原文）做二次校验：
   *    命中节点当下文本 !== from 就**跳过**，宁可失效也不乱改（issue §三 方案 B）。 */

  function cssPath(el) {
    const parts = [];
    let node = el;
    let depth = 0;
    while (node && node.nodeType === 1 && depth < 8) {
      if (node.id) { parts.unshift('#' + node.id); break; }
      const tid = node.getAttribute && node.getAttribute('data-tid');
      if (tid) { parts.unshift('[data-tid="' + tid + '"]'); break; }
      let seg = node.tagName.toLowerCase();
      const p = node.parentElement;
      if (p) {
        let n = 1;
        for (const sib of p.children) {
          if (sib === node) break;
          if (sib.tagName === node.tagName) n += 1;
        }
        seg += ':nth-of-type(' + n + ')';
      }
      parts.unshift(seg);
      node = p;
      depth += 1;
    }
    return parts.join(' > ');
  }

  function keyOf(el) {
    const tid = el.getAttribute && el.getAttribute('data-tid');
    return tid ? ('tid:' + tid) : ('sel:' + cssPath(el));
  }

  /* ---------------- 命中测试 ---------------- */

  /* 从点击点往上找「叶子文本宿主」：没有子元素、且自身有非空白文本。
   * 不取容器，否则点标题会选中整个面板并把它的 DOM 结构改坏。 */
  function leafTextHost(el) {
    let node = el;
    let guard = 0;
    while (node && node.nodeType === 1 && guard < 12) {
      if (node.matches && node.matches(EXCLUDE_SEL)) return null;
      const hasChildEl = node.children && node.children.length > 0;
      const text = (node.textContent || '').trim();
      if (!hasChildEl && text) return node;
      node = node.parentElement;
      guard += 1;
    }
    return null;
  }

  /* ---------------- 应用 overrides ---------------- */

  function applyAll() {
    const keys = Object.keys(overrides);
    if (!keys.length) return 0;
    let n = 0;
    for (const k of keys) {
      const rec = overrides[k];
      if (!rec || typeof rec.to !== 'string') continue;
      const sel = k.indexOf('tid:') === 0
        ? '[data-tid="' + k.slice(4) + '"]'
        : k.slice(4);
      let el = null;
      try { el = document.querySelector(sel); } catch (_) { continue; }
      if (!el) continue;
      /* from 校验：文本已经变了 → 说明这条 override 对应的原文不在了，跳过不改。 */
      if ((el.textContent || '').trim() !== rec.from) continue;
      el.textContent = rec.to;
      n += 1;
    }
    return n;
  }

  /* ---------------- 编辑态 ---------------- */

  function beginEdit(el) {
    const key = keyOf(el);
    const from = (el.textContent || '').trim();
    if (!from) return;
    editing = { el, key, from };
    el.setAttribute('contenteditable', 'plaintext-only');
    /* 老浏览器不认 plaintext-only → 退回 true（仍会被下面的 Enter 拦成单行） */
    if (el.getAttribute('contenteditable') !== 'plaintext-only') el.setAttribute('contenteditable', 'true');
    el.classList.add('ark-txt-editing');
    try { el.focus({ preventScroll: true }); } catch (_) { el.focus(); }
    try {
      const r = document.createRange();
      r.selectNodeContents(el);
      const s = window.getSelection();
      s.removeAllRanges();
      s.addRange(r);
    } catch (_) {}
  }

  function endEdit(commit) {
    if (!editing) return;
    const { el, key, from } = editing;
    editing = null;
    el.removeAttribute('contenteditable');
    el.classList.remove('ark-txt-editing');
    const now = (el.textContent || '').trim();
    if (!commit) { el.textContent = from; return; }
    /* 动态节点自检（issue §5.3 推荐做法，比硬编码黑名单可靠）：
     * 提交瞬间再读一次 —— 若这一格已经被别的渲染逻辑重写过，就判为动态数值，拒绝入库。 */
    if (now === from) return;                       // 没改
    if (el.matches(EXCLUDE_SEL)) { el.textContent = from; return; }
    overrides[key] = { from, to: now };
    save();
    el.textContent = now;
    try { if (typeof log === 'function') log(`文案已改（${Object.keys(overrides).length} 条待导出）`); } catch (_) {}
  }

  /* ---------------- 导出 ---------------- */

  function exportJson() {
    const out = {};
    for (const k of Object.keys(overrides)) {
      const r = overrides[k];
      if (r && typeof r.to === 'string') out[k] = r.to;
    }
    const text = JSON.stringify(out, null, 2);
    /* a[download] + Blob：离线产物里也能用，不发任何网络请求（C 案的硬要求）。 */
    try {
      const blob = new Blob([text], { type: 'application/json;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'text-overrides.json';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 4000);
    } catch (_) {}
    try { if (navigator.clipboard) navigator.clipboard.writeText(text); } catch (_) {}
    try { if (typeof log === 'function') log(`📤 已导出 text-overrides.json（${Object.keys(out).length} 条），同时已复制到剪贴板。`); } catch (_) {}
    return text;
  }

  /* ---------------- 监听器 ---------------- */

  function onKeyDown(e) {
    if (e.key === 'Alt') {
      altDown = true;
      document.documentElement.classList.add('ark-alt-edit');
      return;
    }
    if (!editing) return;
    if (e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); endEdit(true); return; }
    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); endEdit(false); return; }
  }
  function onKeyUp(e) {
    if (e.key !== 'Alt') return;
    altDown = false;
    document.documentElement.classList.remove('ark-alt-edit');
    /* 松手时若还在编辑：提交（人类预期「按住 Alt 改完松开 = 生效」） */
    if (editing) endEdit(true);
  }
  function onBlurWindow() {
    altDown = false;
    document.documentElement.classList.remove('ark-alt-edit');
    if (editing) endEdit(true);
  }
  function onClickCapture(e) {
    if (!editing) {
      if (!altDown) return;
      if (typeof debugMode === 'undefined' || !debugMode) return;
      const host = leafTextHost(e.target);
      if (!host) return;
      e.preventDefault();
      e.stopPropagation();
      beginEdit(host);
      return;
    }
    /* 编辑中点到别处 → 先提交（与 blur 提交同口径），再放行这次点击 */
    if (editing.el && editing.el.contains(e.target)) return;
    endEdit(true);
  }

  function install() {
    if (installed) return;
    installed = true;
    document.addEventListener('keydown', onKeyDown, true);
    document.addEventListener('keyup', onKeyUp, true);
    document.addEventListener('click', onClickCapture, true);
    window.addEventListener('blur', onBlurWindow);
  }

  /* 设置抽屉里的「导出文案」按钮：默认 hidden，只有 debugMode 打开时才显出来。
   * 正式玩家路径上这个按钮永远不可见 —— 不会让人问「这是干什么的」。 */
  function syncExportButton(on) {
    const btn = document.getElementById('textExportBtn');
    if (!btn) return;
    btn.hidden = !on;
    if (btn.__arkBound) return;
    btn.__arkBound = true;
    btn.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      exportJson();
    });
  }

  /* state.js#setDebugMode 会在开关切换时调用本函数（typeof 守卫，不会因加载顺序报错）。 */
  function textEditSync() {
    let on = false;
    try { on = (typeof debugMode !== 'undefined') && !!debugMode; } catch (_) {}
    syncExportButton(on);
    if (!on) {
      if (editing) endEdit(false);
      altDown = false;
      document.documentElement.classList.remove('ark-alt-edit');
      return;
    }
    install();
    applyAll();     // debugMode 打开时补一次应用：面板可能是刚重建的
  }

  /* ---------------- 启动 ---------------- */

  load();
  /* 首屏应用两次：DOMContentLoaded 之后静态节点已在；再等一拍，避开各模块自己的首次 render。 */
  function bootApply() {
    applyAll();
    syncExportButton(false);   // 首屏一定是关的（debugMode 默认 false），保险起见对齐一次
    setTimeout(applyAll, 800);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bootApply, { passive: true });
  } else {
    bootApply();
  }

  /* 控制台出口（开发者用）：
   *   __ARK_TEXT_OVERRIDES.apply()   手动重放（面板重建后可以再跑一次）
   *   __ARK_TEXT_OVERRIDES.export()  导出 JSON
   *   __ARK_TEXT_OVERRIDES.clear()   清空
   *   __ARK_TEXT_OVERRIDES.list()    看当前有哪些条目 */
  window.__ARK_TEXT_OVERRIDES = {
    apply: applyAll,
    export: exportJson,
    list: function () { return Object.assign({}, overrides); },
    clear: function () { overrides = {}; save(); },
    sync: textEditSync,
  };
})();

/* src: src/ui/mobile-pad.js */
/* =========================================================================
 * ISSUE-20261101-152：**手机虚拟圆钮底栏已整体删除**（人类 20:43 原话：
 *   「删掉手机端的圆形按钮，整个底栏都删掉」）。
 *
 * 删掉的东西（不要再加回来，除非人类重新要求）：
 *   #vpadHost 这块 position:fixed 底栏面板、方向圆钮（▲◀▼▶）、等待 / 攻击 / 技能 /
 *   重置路径四个圆钮、技力环 SVG、--vpad-h 底部高度补偿、body.vpad-on 类。
 *   桌面与手机现在共用**同一套** UI：11×11 格栅里的攻击 / 技能 / 闪避三个方形键
 *   （templates/game.html 的 .act-key，ISSUE-20261101-151）+ 操作格里的「开始行动」。
 *   手机端移动 = 直接在棋盘上点击 / 拖拽（boardEl 的 pointerdown / pointermove 那套
 *   freeMoveSetTarget / handleCellDrag），不再需要方向键。
 *
 * 本文件现在只剩**两个读数出口**（名字沿用旧的，调用方遍布模板与测试，改名收益为零）：
 *   vpadSpInfo()       → 当前角色的技力 { cur, max }，没有技力机制返回 null
 *   vpadDamageValue()  → 当前出手的骰子文案（2d4+1 / 1d8+1）
 * 唯一消费方 = templates/game.html#syncActionKeys()（技能键的分段条 + 攻击键的数字）。
 * ========================================================================= */

/* 触屏判定（原 vpadShouldMount 的内核，收敛成一个可复用的判据）。
 * 底栏删除后它只剩一个消费方：templates/game.html#phaseInfoTip() —— 决定要不要在信息格
 * 显示「点棋盘移动 · 点路径节点 = 攻击 · 技能与等待用操作格三键」。桌面/带鼠标的触屏笔记本一律 false，
 * 与删除前「底栏只在纯触屏挂载」的判据逐条等价。 */
function isCoarsePointer() {
  try {
    if (typeof window.matchMedia !== 'function') return window.innerWidth <= 760;
    const coarse = window.matchMedia('(pointer: coarse)').matches;
    const fine = window.matchMedia('(any-pointer: fine)').matches;
    if (coarse && !fine) return true;
    // 部分老浏览器不识别 any-pointer，此时 fine 恒 false：用宽度兜底
    return coarse && window.innerWidth <= 760;
  } catch (_) { return false; }
}

function vpadSpInfo() {
  if (!player) return null;
  if (selectedChar === 'fencer') return { cur: fencerSp, max: FENCER_SP_MAX };
  if (selectedChar === 'amiya') return { cur: amiyaBonusTargets, max: amiyaSpMax() };
  if (selectedChar === 'wheelchair') return { cur: wheelchairPreviewSp(), max: WHEELCHAIR_SP_MAX };
  if (selectedChar === 'vampire') return { cur: vampireSp, max: VAMPIRE_SP_MAX };
  if (selectedChar === 'rookie') return { cur: rookieSp, max: ROOKIE_SP_MAX };
  return null;
}

function vpadDamageValue() {
  if (!player) return '—';
  /* 显示骰子文案（2d4+1 / 1d8+1）而不是定值：实际每次出手都掷骰，写死数字会骗人 */
  const ranged = playerIsRanged();   /* ISSUE-20261028-19：动态角色按六维现算 */
  return ranged ? playerRangedDmgLabel() : playerMeleeDmgLabel();
}

/* =========================================================
 * ★ 结算收尾工具（击杀 / 落败 / 通关 / 玩家受伤反馈）
 *
 * 这些「收尾动作」原先在 resolveStep 里被复制了 6~8 份，
 * 且各份细节并不一致（有的漏了阿米娅技力、有的漏了击杀特效）。
 * 统一入口后，新增角色或调整规则只需要改一处。
 * ========================================================= */
const IMMUNE_CHARGE = '冲锋免疫';
const IMMUNE_COUNTER = '满技力免疫';

/* 敌人死亡：清血、标记、可选特效与日志、阿米娅击杀技力。
 * opts.killedIds 传入本 tick 的击杀集合（相杀 / 冲锋撞击需要额外记账）。 */
/* === ISSUE-20261031-119：飞碟🛸 + 外星人👽 运行时增敌与经验分组 === */
let nextEnemyId = 0;                  // 运行时增敌唯一 id（不依赖 enemies.length，死敌不移除）
const creditedKillGroups = new Set(); // 飞碟与其投放的👽同组，击杀只记一次
const UFO_SPAWN_EVERY = 2;           // 飞碟每 2 回合投放 1 只👽

function killEnemy(e, opts = {}) {
  if (!e || !e.alive) return false;
  const {
    showRing = true, showFloat = true, floatMsg = '击杀!',
    logText = true, amiyaSp = true, killedIds = null,
 } = opts;
  e.alive = false;
  /* ★ ISSUE-20261029-53：整局击杀累计（runKills 声明在 src/rules/state.js）。
   * 计数写在**函数体内**而不是让外壳 hook 记一笔：成绩上报改成事件驱动后只认
   * killEnemy() 这一条路，任何绕过它直接置 alive=false 的击杀都会漏计
   * （泥岩反击 / 阿米娅精神爆发就是这么漏的，见本文件 triggerFencerCounter /
   * executeAmiyaBurst）。外壳那层 hook 已同步删除，否则这里会二重计数。 */
  /* ★ ISSUE-20261031-119：飞碟与其投放的外星人同组（groupId），击杀只计一次。
   * 经验(xp) 本身按「失血」结算、与击杀数无关，不受影响；此处仅对
   * 击杀计数类收益（runKills / 排行榜 kills / 金币）去重，避免「1 飞碟 + N 只👽」刷爆击杀数。 */
  const _g = (e.groupId != null) ? e.groupId : e.id;
  if (!creditedKillGroups.has(_g)) {
    runKills += 1;
    /* ★ ISSUE-20261030-80：金币产出（击杀收口），与 runKills / 汲取核心 / 教程击杀计数同收口 */
    if (typeof currencyOnKill === 'function') currencyOnKill(e);
    creditedKillGroups.add(_g);
  }
  /* ★ ISSUE-20261031-100-①：击杀带词缀敌人累计关后经验加成（与 currency 同源收口） */
  if (typeof grantAffixKillXp === 'function') grantAffixKillXp(e);
  /* ISSUE-20261028-06 汲取核心：每次击败敌人回 1 HP/层。
   * 挂在这里 = 所有击杀来源（攻击/技能/反击/爆发）统一生效，不需要逐分支补。 */
  if (typeof relicHealOnKill === 'function') relicHealOnKill();
  if (killedIds) killedIds.add(e.id);
  if (showRing) ringFx(e.x, e.y, '#ff6b6b');
  if (showFloat) floatText(e.x, e.y, floatMsg, '#ff6b6b');
  if (logText) log(logText === true ? `敌人${e.id + 1}被击败` : logText);
  /* 精英击杀奖励（ISSUE-20261028-05）：在死亡格留下一个恢复道具 ❤️。
   * 只碰 rewardItems 数组，不新增单位、不动 enemyPathOrder —— 这是首轮排除「分裂」词缀的原因。 */
  if (e.isElite && typeof rewardItems !== 'undefined') {
    if (!rewardItems.some(r => r.x === e.x && r.y === e.y)) rewardItems.push({ x: e.x, y: e.y });
    log('★ 精英被击败，掉落了恢复道具 ❤️！');
 }
  /* ★ ISSUE-20261031-132：骷髅的「留骸」。
   *   必须挂在**击杀收口**而不是 `enemyTakeDamage` 里：
   *     ① 只有真的死了才留骸（挨打不掉东西 —— 旧 #118 的八格掉骨已下线）；
   *     ② 攻击 / 技能 / 反击 / 精神爆发 / 相杀 / 自爆连锁 / 调试秒杀 七条路径全覆盖，
   *        与 runKills / currencyOnKill / relicDeathBurst 完全同一个收口。
   *   判据用 `e.lastHitWeak`（由 enemyTakeDamage 在血线归零那一刻写下），
   *   **不在这里按朝向重算** —— 致死瞬间的朝向/位置可能已被相杀、冲锋位移改过。
   *   被弱点打死的骷髅什么都不留（人类拍板 2：「打骷髅要正面打」）。 */
  if (typeof skeletonLeavesRemains === 'function' && skeletonLeavesRemains(e)) {
    if (!e.lastHitWeak) {
      if (typeof spawnRemains === 'function') spawnRemains(e);
    } else if (logText) {
      /* ★ 人类拍板 2「打骷髅要正面打」—— 这条规则如果不写出来，玩家只会觉得
       *   「骷髅怎么有时候碎有时候复活」是 bug。正/非正面两种结果各给一句日志，规则才可学。 */
      log('☠️ 正面击杀：骷髅被彻底打碎，什么都没留下。');
    }
  }
  if (amiyaSp && selectedChar === 'amiya') amiyaGainKillBonus();
  /* ★ ISSUE-20261028-14：教程击杀计数（挂在 killEnemy 内 = 所有击杀来源统一生效，
   * 与上面 runKills 同一个收口，反击 / 精神爆发打死的也算） */
  if (typeof tutorialOnKill === 'function') tutorialOnKill();
  /* ★ ISSUE-20261031-100：自爆词条 —— 死亡时炸相邻四格的敌我单位。
   * 挂在这里 = 攻击 / 技能 / 反击 / 精神爆发 / 调试秒杀 / 相杀 六条击杀路径全覆盖，
   * 与 runKills / currencyOnKill / relicHealOnKill 完全同一个收口。
   * ⚠️ 函数内部只造成伤害、**绝不改 enemies 数组长度**（见 src/data/enemies.js 的注释）；
   *    它顺手炸死的敌人在本函数返回后由 sweepDeadEnemies() 正常收口。 */
  enemyDeathBurst(e);
  return true;
}

/* 玩家落败：统一置阶段、清箭头、写日志、重绘。 */
function endGame(message = '你死了。游戏结束。', markDead = true) {
  /* ★ ISSUE-20261031-110（人类 14:5x「教程关本质是另一个游戏方式」）：
   * 教程里没有「战死」这个结局，也**不派发 ark:gameover**（那是成绩上报的唯一入口）。
   * damagePlayer 已有 tutorialHpFloor() 把血夹在 1，能拦住常规伤害；这里是最后一道，
   * 兜住绕过夹血的自伤（阿米娅不稳定血浆、泥岩耗血之类），
   * 否则新手会在教程里被丢进「重新开始」，而且顺带上报一份 level=1 的失败成绩。 */
  if (typeof tutorialIsOn === 'function' && tutorialIsOn()) {
    if (player) { player.hp = 1; player.alive = true; }
    log('📖 教程模式：不会真的阵亡（HP 恢复到 1），跟着光标继续走。');
    updateStats();
    return;
  }
  if (markDead && player) player.alive = false;
  /* ★ ISSUE-20261031-128：合作局里自己阵亡 = 退出这一局（释放座位）。
   * 不退出的话，房间会一直等你交计划，队友得等到 60s 超时兜底才能推进；
   * 退出后队友立刻收到 peer_left，屏幕上你的角色直接倒下。 */
  if (mode === 'coop') {
    log('💀 你倒下了，本局合作对你结束（队友可以继续打）。');
    try { PVP_NET.quit(); } catch (e) {}
  }
  phase = PHASE.GAMEOVER;
  /* 玩家操作录制（ISSUE-83 强制开）：本局失败 = 玩家挂在这一关，记下 outcome=failed 并直传服务端 */
  if (window.ARK_REC) window.ARK_REC.failed({ level: level, player: player, enemies: enemies, kills: runKills });
  clearEnemyArrows();
  log(message);
  render();
  /* ★ ISSUE-20261030-52 / 20261029-53：结算事件改在函数体内直接派发
   * （原来由 src/shell/05-score.js 给 endGame 包一层 hook，那层已删，避免重复派发）。
   * 判据仍然是「只有走 endGame() 的才算真死亡」—— initLevel() 的 catch 是直接置
   *   phase = PHASE.GAMEOVER，永远不会走到这里，所以初始化异常不会灌假成绩。 */
  try {
    window.dispatchEvent(new CustomEvent('ark:gameover', { detail: { level: level, kills: runKills } }));
 } catch (e) {}
}

/* 通关：先刷新一帧让最后一次击杀可见，再进入通关结算。 */
async function finishLevel() {
  render();
  await sleep(300);
  onLevelClear();
}

/* 玩家承伤的浮动文字：护盾抵消 / 正常伤害 两态统一在这里判定。
 * 调试无敌分支已移除（ISSUE-20261028-11 B4）：隐藏开关下不弹任何浮字，玩家侧零感知。 */
function showPlayerDamage(res, normalText, opts = {}) {
  const { color = '#ff6b6b', crit = false, x = player.x, y = player.y } = opts;
  if (res.immune) return;
  /* ISSUE-20261030-56：'player' 让浮字落进玩家自己那条斜带 —— 同格时「护盾抵消」和
   * 成员的「-3」不会精确叠在一起（默认坐标就是 player.x/y，所以这里不用判 opts.x/y）。 */
  floatText(x, y, res.shielded ? '护盾抵消' : normalText, res.shielded ? '#ffffff' : color, !res.shielded && crit, 0, 'player');
}

/* 近战暴击判定：自然20 → 朝向 → 角色暴击率（所有角色同一条 critChance，无角色特例）。
 * 2026-10-28 ISSUE-20：删掉泥岩隐藏的 +42%（原为 0.08 + 0.42 = 50%）。
 * facingMode：'cone' 用于攻击节点范围攻击（面向的 3 格扇形），'target' 用于趁乱打击（正对目标）。
 * 注意 Math.random 的调用顺序：与旧版一致，改动会影响整局随机序列。 */
function meleeCritTag(target, atk, facingMode = 'target') {
  if (atk.nat20) return '自然20暴击';
  /* ★ ISSUE-20261031-120（🙉 猴王形态）：弱点暴击失效。
   * 只掐「朝向」这一条来源 —— 自然20 与随机暴击照旧（它们是命中骰本身的产物，
   *  与「弱点」无关）。否则 🙉 会连玩家的正常暴击率一起吞掉，等于加了个隐藏 debuff。 */
  const weakOk = !(typeof kingDisablesWeak === 'function' && kingDisablesWeak());
  if (weakOk) {
    const facing = facingMode === 'cone' ? isInFacingCone(player, target) : isFacingTarget(player, target);
    if (facing) return '弱点暴击';
  }
  return rng() < player.critChance ? '暴击' : '';
}

/* 玩家当前是否处于「免疫本次伤害」的状态（风笛冲锋 / 泥岩满技力反击）。 */
function playerImmuneState() {
  if (selectedChar === 'wheelchair' && playerChargingThisTurn) return IMMUNE_CHARGE;
  if (selectedChar === 'fencer' && fencerCounterActive && fencerSp >= FENCER_SP_MAX) return IMMUNE_COUNTER;
  return null;
}

/* 免疫命中时的统一表现（日志文案按来源传入，保持原有措辞）。
 * 泥岩的免疫同样要结算一次反击，否则会「满技力→免疫→不反击→技力永不清零」死锁。 */
function tryPlayerImmuneHit(state, chargeLabel, counterLabel, hitTag) {
  if (!state) return false;
  const tag = hitTag ? `（${hitTag}）` : '';
  log(state === IMMUNE_CHARGE
    ? `${chargeLabel}${tag}，冲锋状态免疫所有伤害！`
    : `${counterLabel}${tag}，但泥岩反击状态+满技力，免疫所有攻击！`);
  floatText(player.x, player.y, state, '#ffd700');
  if (state === IMMUNE_COUNTER && player.hp > 0) triggerFencerCounter();
  return true;
}

/* 敌人攻击玩家：泥岩反击状态下敌人掷骰取劣势。 */
function rollEnemyAttack(attackerMod, prof, targetAC) {
  return (selectedChar === 'fencer' && fencerCounterActive)
    ? attackRollDisadvantage(attackerMod, prof, targetAC)
    : attackRoll(attackerMod, prof, targetAC);
}

function triggerFencerCounter() {
  if (selectedChar !== 'fencer' || !fencerCounterActive) return;
  if (!player || !player.alive || player.hp <= 0) return;
  const targets = enemies.filter(e => e.alive && cheb(e, player) === 1);
  if (targets.length > 0) {
    const target = targets[randInt(targets.length)];
    const dmg = rollPlayerMeleeDamage() * 2;
    /* 护盾词缀（ISSUE-20261028-05）：第一击被完全吸收 */
    const dealt = enemyTakeDamage(target, dmg);
    /* ★ ISSUE-20261028-14：教程反击计数（泥岩课要看「挨打 → 反击」这个闭环真的合上了） */
    if (typeof tutorialOnCounter === 'function') tutorialOnCounter();
    if (dealt > 0) {
      slashFx(target.x, target.y, '#ffd700');
      hitFx(target.x, target.y, dealt, true, '反击暴击');
      log(`泥岩触发反击，对敌人${target.id+1}造成${dealt}点暴击伤害！`);
 }
    /* ★ ISSUE-20261031-100：「荆棘」词条已删除，这里原来那行 `if (enemyThornsReflect(target)) return;`
     * 同步移除（函数本体也已下线 —— 留着调用点会直接 ReferenceError）。 */
    /* ★ ISSUE-20261029-53：这里原来是 `target.alive = false`，绕过 killEnemy()
     *   → runKills 不累加 → 反击打死的敌人在成绩面板上凭空少一个。
     *   改走 killEnemy()：opt 逐条对齐原分支（不画击杀环、浮字「击杀!」、日志同一句），
     *   伤害结算顺序不变 —— enemyTakeDamage 在上面已经跑完了才轮到这里。
     *   ⚠️ 副作用（已知且接受）：精英被反击打死现在也会掉 ❤️，与其余击杀口径一致。 */
    if (target.hp <= 0 && target.alive) {
      killEnemy(target, { showRing: false, showFloat: true, floatMsg: '击杀!', logText: `敌人${target.id+1}被击败` });
 }
    // ★ 技力满 5：眩晕周围 8 格所有敌人 + 回复 1/2 最大 HP
    if (fencerSp >= FENCER_SP_MAX) {
      const stunTargets = enemies.filter(e => e.alive && cheb(e, player) === 1);
      for (const e of stunTargets) {
        e.stunTurns = 2;
        floatText(e.x, e.y, '眩晕！', '#ffcc00');
        ringFx(e.x, e.y, '#ffcc00');
        log(`敌人${e.id+1}被眩晕（本回合剩余 + 下回合无法行动）`);
 }
      const healAmt = Math.floor(player.maxHp / 2);
      const oldHp = player.hp;
      player.hp = Math.min(player.maxHp, player.hp + healAmt);
      const actualHeal = player.hp - oldHp;
      if (actualHeal > 0) {
        floatText(player.x, player.y, `+${actualHeal} HP`, '#2ecc71');
        log(`💚 「岩崩锤」回复 ${actualHeal} HP（1/2 最大 HP）`);
 }
      fencerSp = 0;
      fencerCounterActive = false;  // 发动后退出反击状态，避免「SP 已清零却仍处反击态」的门槛失效
      floatText(player.x, player.y, '岩崩锤！', '#ffd700', true);
      ringFx(player.x, player.y, '#ffd700');
      log(`⚡ 泥岩发动「岩崩锤」！周围 ${stunTargets.length} 名敌人被眩晕，回复HP后技力清零，反击状态结束。`);
 }
 } else {
    log(`泥岩触发反击，但周围8格没有敌人。`);
    floatText(player.x, player.y, '反击落空', '#bbb');
 }
}

/* ISSUE-20261030-58：精神爆发的目标选择 —— **严格轮流攻击**。
 *   做法是一个会转圈的候选队列（存 id）：每次发动按「距离升序、同距离按 id 升序」建初始序，
 *   射一次就把队首挪到队尾 —— 于是三人相邻时必然是 A→B→C→A→B→C，不会连着同一个砸两次。
 *   只剩 1 个目标时队列长度 1，自然就是连打它自己。
 *   中途有目标被打死：下一轮重建队列时会把它剔掉，剩余目标继续转圈。
 *  ★ 为什么不写「排除上一次、取最近的」：那样会退化成 A→B→A→B，永远轮不到最远的第三个。 */
function buildBurstQueue(targets, prevQueue) {
  const sorted = targets.slice().sort((a, b) => (cheb(a, player) - cheb(b, player)) || (a.id - b.id));
  const aliveIds = sorted.map((e) => e.id);
  const q = (prevQueue || []).filter((id) => aliveIds.includes(id));
  for (const id of aliveIds) if (!q.includes(id)) q.push(id);
  return q;
}

async function executeAmiyaBurst(count) {
  /* ① ISSUE-20261030-58：精神爆发射程**无限** —— 不再取 player.range（= PLAYER_RANGE 3）。
   *   ★ 注意：无限只指「距离这一条」，`canRangedAttack` 里那道 `hasLineOfSight` 仍然生效 ——
   *     墙后面的敌人看不见就打不着，和普通远程攻击保持同一把尺。 */
  const burstRange = Infinity;
  const intMod = abilityMod(player.abilities.int);
  /* ★ ISSUE-20261031-132：目标池在**发动那一刻**就定下来（本轮敌人快照）。
   *   为什么必须快照：骷髅被非弱点击杀会当场往 `enemies` 末尾 push 一具 💀 骸骨（#132），
   *   若每段都重新 `enemies.filter(...)`，倾泻途中就会凭空多出一个候选目标 ——
   *   剩下的段数被一具刚倒下的 1 HP 尸体抢走，玩家看到的是「连着打的目标突然变了」。
   *   快照口径与近战/远程那两条路径一致（它们的 `targets` 本来也只在出手时算一次）。 */
  const burstRoster = enemies.filter(e => e.alive).slice();
  let burstQueue = [];
  for (let i = 0; i < count; i++) {
    if (!player.alive || player.hp <= 0) break;
    if (burstRoster.every(e => !e.alive)) break;
    let targets = burstRoster.filter(e => e.alive && canRangedAttack({ x: player.x, y: player.y }, e, burstRange));
    if (targets.length === 0) {
      log(`「精神爆发」${i + 1}/${count}：视线内无有效目标，停止攻击。`);
      break;
 }
    /* ③ 轮流攻击：候选队列转圈，多目标时不连打同一个 */
    burstQueue = buildBurstQueue(targets, burstQueue);
    const target = enemies.find(e => e.id === burstQueue[0]);
    burstQueue.push(burstQueue.shift());
    /* ② ISSUE-20261030-58：取消「必定命中 + 必定暴击」，完全走 d20。
     *   自然 1 必失、自然 20 必中且必暴；暴击率每次射击独立掷（N 次攻击 = N 次掷骰）。
     *   ★ 这里连「弱点必中」（applyFacingGuaranteedHit）也不套 —— 人类要求取消必定命中。
     *     若哪天要恢复朝向补偿，在下面补 applyFacingGuaranteedHit(atk, target, player) 即可。 */
    const atk = attackRoll(intMod, player.rangedProf || 0, target.ac);
    const isCrit = atk.hit && (atk.nat20 || rng() < player.critChance);
    /* 只要出手就能看到目标意图 */
    amiyaMarkReveal(target);
    await animateBullet({ x: player.x, y: player.y }, 'enemy-' + target.id, target, isCrit, false, 'player', 'musical_notes');
    if (!atk.hit) {
      /* ④ MISS 分支：取消必中后，高 AC 与自然 1 现在真的会打空（技力已消耗，不返还） */
      missFx(target.x, target.y);
      log(`「精神爆发」${i + 1}/${count}：未命中敌人${target.id + 1} (${fmtRoll(atk, target.ac)})`);
      refreshUnits();
      await sleep(180);
      continue;
 }
    const dmg = rollPlayerRangedDamage() * (isCrit ? 2 : 1);
    const dealt = enemyTakeDamage(target, dmg);
    /* ★ ISSUE-20261029-53：原来直接 `target.alive = false` → 不计入 runKills。
     *   改走 killEnemy()，并用 amiyaSp:false 保住原注释那条手感
     *   「精神爆发的击杀不给技力（否则倾泻过程中边杀边攒会滚雪球）」。
     *   不额外画击杀环 / 浮字：这一段已经打过 hitFx('爆发暴击')，
     *   再叠一个「击杀!」会把伤害数字糊住（原分支本来也没画）。 */
    if (target.hp <= 0 && target.alive) {
      killEnemy(target, { showRing: false, showFloat: false, logText: false, amiyaSp: false });
 }
    if (dealt > 0) {
      hitFx(target.x, target.y, dealt, isCrit, '爆发暴击');
      log(`「精神爆发」${i + 1}/${count}：${isCrit ? '暴击' : '命中'}敌人${target.id + 1}，造成${dealt}伤害 (${fmtRoll(atk, target.ac)})`);
 } else {
      log(`「精神爆发」${i + 1}/${count}：被护盾词缀吸收，未造成伤害。`);
 }
    refreshUnits();
    await sleep(180);
 }
}

/* 阿米娅技力上限 = 感知：击败敌人攒技力，「等待 → 攻击」倾泻消耗 */
function amiyaSpMax() {
  const ab = (player && player.abilities) || (playerStats && playerStats.abilities);
  const wis = (ab && ab.wis != null) ? ab.wis : CHARACTERS.amiya.abilities.wis;
  return Math.max(1, wis);
}

/* 技力上限 = 感知：击败敌人攒技力，「等待 → 攻击」倾泻消耗 */
const AMIYA_KILL_SP_GAIN = 2;
/* ISSUE-20261030-58 被动：**打出弱点攻击额外 +5 技力**（与普通「每次攻击 +1」叠加，合计 +6）。
 * 判定用 isFacingCross —— 远程「弱点攻击」= 十字（四个直线方向，无限格）：目标与玩家同行或同列、
 *   中间无墙遮挡（需视线）即算。出手就给，不看有没有命中（与 +1 的口径一致）。
 * 只在**攻击节点出手**处结算，精神爆发的连射不给自己攒技力。 */
const AMIYA_FACING_SP_GAIN = 5;

function amiyaGainKillBonus() {
  if (selectedChar !== 'amiya') return;
  const cap = amiyaSpMax();
  if (amiyaBonusTargets >= cap) {
    log(`阿米娅技力已满（${cap}/${cap}），击败敌人不再增加技力。`);    updateStats();
    return;
 }
  const before = amiyaBonusTargets;
  const sass = sassExtraSp();
  amiyaBonusTargets = Math.min(cap, amiyaBonusTargets + AMIYA_KILL_SP_GAIN + sass);
  const gained = amiyaBonusTargets - before;
  log(`阿米娅技力 +${gained}（${amiyaBonusTargets}/${cap}）：每击败 1 个敌人获得 ${AMIYA_KILL_SP_GAIN} 点技力，等待后接攻击节点即可倾泻。`);
  if (sass) log('🥤 香草沙士：额外获得 1 点技力！');
  updateStats();
}

/* 阿米娅：每次攻击（攻击节点出手，命中与否都算）+1 技力；精神爆发自身连射不额外加。
 * ★ ISSUE-20261030-58：`facingBonus` 为真时额外 +AMIYA_FACING_SP_GAIN —— 「打出弱点攻击 +5 技力」
 *   被动。调用方（远程出手结算）已判定好本次是不是弱点攻击；不传就是原来那条 +1。 */
function amiyaGainAttackSp(facingBonus) {
  if (selectedChar !== 'amiya') return;
  const cap = amiyaSpMax();
  if (amiyaBonusTargets >= cap) return;
  const before = amiyaBonusTargets;
  const sass = sassExtraSp();
  const facing = facingBonus ? AMIYA_FACING_SP_GAIN : 0;
  amiyaBonusTargets = Math.min(cap, before + 1 + facing + sass);
  const gained = amiyaBonusTargets - before;
  log(`阿米娅技力 +${gained}（${amiyaBonusTargets}/${cap}）：每次攻击积攒技力${facing ? `，打出弱点攻击额外 +${facing}` : ''}。${sass ? ' 🥤 香草沙士 +1' : ''}`);
  updateStats();
}

function amiyaMarkReveal(enemy) {
  if (selectedChar !== 'amiya' || !enemy) return;
  enemy.amiyaRevealBonus = (enemy.amiyaRevealBonus || 0) + 3;
  enemy.amiyaRevealForNext = true;
  log(`阿米娅标记敌人${enemy.id + 1}：下一次移动意图额外显示 3 步（累计 +${enemy.amiyaRevealBonus}）。`);
}

/* src: src/rules/mapgen.js */
/* P0.1-4 拆分 · 20261028c 基线（templates/game.html）701-927 行 · 地图生成：bfsReachable / growRegion / smoothRegion / clearSpawnArea / countWalkable / placeObstacles / generateMap（纯逻辑，不碰 DOM） */
function bfsReachable(m, sx, sy) {
  const visited = new Set();
  const q = [[sx, sy]];
  visited.add(key(sx, sy));
  while (q.length) {
    const [x, y] = q.shift();
    for (const [dx, dy] of DIR4) {
      const nx = x + dx, ny = y + dy;
      if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) continue;
      if (m[ny][nx] !== 0) continue;
      const k = key(nx, ny);
      if (visited.has(k)) continue;
      visited.add(k);
      q.push([nx, ny]);
    }
  }
  return visited;
}
function growRegion(startX, startY, target) {
  const m = Array.from({ length: ROWS }, () => Array(COLS).fill(1));
  const region = new Set();
  const frontierSet = new Set();
  const frontier = [];
  function scoreOf(c) {
    let cnt = 0;
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue;
      const nx = c.x + dx, ny = c.y + dy;
      if (nx >= 0 && nx < COLS && ny >= 0 && ny < ROWS && m[ny][nx] === 0) cnt++;
    }
    return cnt;
  }
  function openCell(x, y) {
    m[y][x] = 0; region.add(key(x, y));
    for (const [dx, dy] of DIR4) {
      const nx = x + dx, ny = y + dy;
      if (nx < 1 || nx >= COLS - 1 || ny < 1 || ny >= ROWS - 1) continue;
      const k = key(nx, ny);
      if (region.has(k) || frontierSet.has(k)) continue;
      frontierSet.add(k); frontier.push({ x: nx, y: ny });
    }
  }
  openCell(startX, startY);
  while (region.size < target && frontier.length > 0) {
    const sampleSize = Math.min(5, frontier.length);
    let bestIdx = 0, bestScore = -1;
    for (let i = 0; i < sampleSize; i++) {
      const idx = randInt(frontier.length);
      const s = scoreOf(frontier[idx]);
      if (s > bestScore) { bestScore = s; bestIdx = idx; }
    }
    const c = frontier[bestIdx];
    frontier[bestIdx] = frontier[frontier.length - 1];
    frontier.pop();
    frontierSet.delete(key(c.x, c.y));
    if (region.has(key(c.x, c.y))) continue;
    openCell(c.x, c.y);
  }
  return { m, region };
}
function smoothRegion(m, sx, sy) {
  for (let round = 0; round < 3; round++) {
    const changes = [];
    for (let y = 1; y < ROWS - 1; y++) for (let x = 1; x < COLS - 1; x++) {
      if (Math.abs(x - sx) + Math.abs(y - sy) <= SPAWN_CLEAR_RADIUS) continue;
      let wc = 0;
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx, ny = y + dy;
        if (nx >= 0 && nx < COLS && ny >= 0 && ny < ROWS && m[ny][nx] === 0) wc++;
      }
      if (m[y][x] === 1 && wc >= 6) changes.push([x, y, 0]);
      else if (m[y][x] === 0 && wc <= 2) changes.push([x, y, 1]);
    }
    if (changes.length === 0) break;
    for (const [x, y, v] of changes) m[y][x] = v;
  }
}
function clearSpawnArea(m, sx, sy, radius) {
  for (let y = Math.max(1, sy - radius); y <= Math.min(ROWS - 2, sy + radius); y++) for (let x = Math.max(1, sx - radius); x <= Math.min(COLS - 2, sx + radius); x++) {
    if (Math.abs(x - sx) + Math.abs(y - sy) <= radius) m[y][x] = 0;
  }
}
function countWalkable(m) {
  let n = 0;
  for (let y = 0; y < ROWS; y++) for (let x = 0; x < COLS; x++) if (m[y][x] === 0) n++;
  return n;
}
function placeObstacles(m, spawnX, spawnY) {
  const obstacleCells = new Set();
  /* ★ ISSUE-20261029-29：障碍组数按内部面积自适应。
   * 旧值写死 8 组（每组 1-4 格，平均吃掉 ~16 格）是为 16×16 / 25×25 的大图定的；
   * 9×9 内部只有 49 格，照搬会把近 1/3 的可走区变成石头堆（实测可走只剩 29 格）。
   * 公式在 25×25 时算出 44 → 仍取 OBSTACLE_GROUPS_TRY(8)，与旧行为逐格一致；
   * 9×9 时 49/12 ≈ 4 组，够做掩体又不至于堵死。 */
  const maxGroups = Math.max(2, Math.min(OBSTACLE_GROUPS_TRY, Math.round((ROWS - 2) * (COLS - 2) / 12)));
  let groupsPlaced = 0, attempts = 0;
  while (groupsPlaced < maxGroups && attempts < 60) {
    attempts++;
    const candidates = [];
    for (let y = 1; y < ROWS - 1; y++) for (let x = 1; x < COLS - 1; x++) {
      if (m[y][x] !== 0) continue;
      if (Math.abs(x - spawnX) + Math.abs(y - spawnY) <= SPAWN_CLEAR_RADIUS) continue;
      let ao = 0;
      for (const [dx, dy] of DIR4) if (obstacleCells.has(key(x + dx, y + dy))) ao++;
      if (ao > 0) continue;
      candidates.push({ x, y });
    }
    if (candidates.length === 0) break;
    const seed = candidates[randInt(candidates.length)];
    const size = 1 + randInt(OBSTACLE_MAX_GROUP);
    const group = [seed];
    const localSet = new Set([key(seed.x, seed.y)]);
    m[seed.y][seed.x] = 1;
    obstacleCells.add(key(seed.x, seed.y));
    for (let i = 1; i < size; i++) {
      const frontier = [];
      for (const c of group) for (const [dx, dy] of DIR4) {
        const nx = c.x + dx, ny = c.y + dy;
        if (nx < 1 || nx >= COLS - 1 || ny < 1 || ny >= ROWS - 1) continue;
        if (m[ny][nx] !== 0) continue;
        if (localSet.has(key(nx, ny))) continue;
        if (Math.abs(nx - spawnX) + Math.abs(ny - spawnY) <= SPAWN_CLEAR_RADIUS) continue;
        let ao = 0;
        for (const [ddx, ddy] of DIR4) {
          const k2 = key(nx + ddx, ny + ddy);
          if (obstacleCells.has(k2) && !localSet.has(k2)) ao++;
        }
        if (ao > 0) continue;
        frontier.push({ x: nx, y: ny });
      }
      if (frontier.length === 0) break;
      const next = frontier[randInt(frontier.length)];
      m[next.y][next.x] = 1;
      obstacleCells.add(key(next.x, next.y));
      localSet.add(key(next.x, next.y));
      group.push(next);
    }
    const reach = bfsReachable(m, spawnX, spawnY);
    if (reach.size < countWalkable(m)) {
      for (const c of group) { m[c.y][c.x] = 0; obstacleCells.delete(key(c.x, c.y)); }
      continue;
    }
    groupsPlaced++;
  }
  return obstacleCells;
}
function generateMap(numEnemies, targetWalkable) {
  for (let attempt = 0; attempt < 400; attempt++) {
    const candidates = [];
    for (let y = Math.max(2, Math.floor(ROWS * 0.5)); y < ROWS - 2; y++) for (let x = 2; x < Math.min(COLS - 2, Math.floor(COLS * 0.55) + 1); x++) candidates.push({ x, y });
    if (candidates.length === 0) continue;
    const playerStart = candidates[randInt(candidates.length)];
    const { m } = growRegion(playerStart.x, playerStart.y, targetWalkable);
    clearSpawnArea(m, playerStart.x, playerStart.y, SPAWN_CLEAR_RADIUS);
    smoothRegion(m, playerStart.x, playerStart.y);
    clearSpawnArea(m, playerStart.x, playerStart.y, SPAWN_CLEAR_RADIUS);
    let reach = bfsReachable(m, playerStart.x, playerStart.y);
    for (let y = 0; y < ROWS; y++) for (let x = 0; x < COLS; x++) if (m[y][x] === 0 && !reach.has(key(x, y))) m[y][x] = 1;
    let changed = true, rounds = 0;
    while (changed && rounds < 5) {
      changed = false; rounds++;
      for (let y = 1; y < ROWS - 1; y++) for (let x = 1; x < COLS - 1; x++) {
        if (m[y][x] !== 0) continue;
        if (Math.abs(x - playerStart.x) + Math.abs(y - playerStart.y) <= SPAWN_CLEAR_RADIUS) continue;
        let cnt = 0;
        for (const [dx, dy] of DIR4) if (m[y+dy][x+dx] === 0) cnt++;
        if (cnt <= 1) { m[y][x] = 1; changed = true; }
      }
    }
    reach = bfsReachable(m, playerStart.x, playerStart.y);
    for (let y = 0; y < ROWS; y++) for (let x = 0; x < COLS; x++) if (m[y][x] === 0 && !reach.has(key(x, y))) m[y][x] = 1;
    placeObstacles(m, playerStart.x, playerStart.y);
    let spawnOk = true;
    for (let y = Math.max(1, playerStart.y - SPAWN_CLEAR_RADIUS); y <= Math.min(ROWS - 2, playerStart.y + SPAWN_CLEAR_RADIUS); y++) for (let x = Math.max(1, playerStart.x - SPAWN_CLEAR_RADIUS); x <= Math.min(COLS - 2, playerStart.x + SPAWN_CLEAR_RADIUS); x++) {
      if (Math.abs(x - playerStart.x) + Math.abs(y - playerStart.y) <= SPAWN_CLEAR_RADIUS && m[y][x] !== 0) spawnOk = false;
    }
    if (!spawnOk) continue;
    const count = countWalkable(m);
    if (count < targetWalkable - 15 || count > targetWalkable + 15) continue;
    for (let x = 0; x < COLS; x++) { m[0][x] = 1; m[ROWS - 1][x] = 1; }
    for (let y = 0; y < ROWS; y++) { m[y][0] = 1; m[y][COLS - 1] = 1; }
    const cells = [...reach].map(k => { const [x, y] = k.split(',').map(Number); return { x, y }; });
    /* ★ ISSUE-20261029-29：定版 9×9 后「离玩家 ≥6 格」太苛刻 —— 内部只有 7×7，
     * 硬卡 6 会让 5 个起点经常凑不齐（每次都掉进下面的兜底空房间）。
     * 改成按棋盘短边自适应：25 格时代 ≈ 6（与原值一致），9×9 时 = 5。 */
    const farDist = Math.max(4, Math.round(Math.min(ROWS, COLS) * 0.55));
    const far = cells.filter(c => dist(c, playerStart) >= farDist && m[c.y][c.x] === 0);
    if (far.length < numEnemies) continue;
    const shuffled = far.sort(() => rng() - 0.5);
    const enemyStarts = [];
    for (const c of shuffled) {
      if (enemyStarts.every(s => dist(s, c) >= 2)) {
        enemyStarts.push(c);
        if (enemyStarts.length >= numEnemies) break;
      }
    }
    if (enemyStarts.length < numEnemies) continue;
    let rewards = [];
    {
      const validSpots = [];
      for (const c of cells) {
        if (m[c.y][c.x] !== 0) continue;
        if (Math.abs(c.x - playerStart.x) + Math.abs(c.y - playerStart.y) <= SPAWN_CLEAR_RADIUS) continue;
        if (enemyStarts.some(es => es.x === c.x && es.y === c.y)) continue;
        let wc = 0;
        for (const [dx, dy] of DIR4) {
          const nx = c.x + dx, ny = c.y + dy;
          if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS || m[ny][nx] === 1) wc++;
        }
        if (wc >= 3) validSpots.push(c);
      }
      /* 基础恢复道具：第 3 关起 70% 概率出现 1 个；
         「急救药箱」每层再额外保证 1 个（必定出现） */
      const baseCount = (level >= 3 && rng() < 0.7) ? 1 : 0;
      /* ISSUE-20261028-06：「急救药箱」已并入统一收藏品池（buff → relic），这里改读 relics.kit。 */
      const want = Math.min(baseCount + relicCount('kit'), validSpots.length);
      const pool = validSpots.slice();
      for (let i = 0; i < want; i++) {
        rewards.push(pool.splice(randInt(pool.length), 1)[0]);
      }
    }
    return { map: m, playerStart, enemyStarts, rewards };
  }
  /* ★ 兜底图（400 次都没生成出合格地图时）也按新尺寸重做：
   * 旧写法硬编码 `playerStart.x + 4 + i` / `playerStart.y - 4 - i`，在 9×9 下会算出 (7,2)、(7,2)…
   * 两个敌人重叠在同一格（后面 spawn 时两只怪叠一起，谁也走不动）。
   * 改成「内部全开 → 按离玩家的距离从远到近挑起点、两两保持 ≥2 格」，与原兜底语义一致但不会撞车。 */
  const m = Array.from({ length: ROWS }, () => Array(COLS).fill(1));
  const playerStart = { x: 1, y: ROWS - 2 };
  for (let y = 1; y < ROWS - 1; y++) for (let x = 1; x < COLS - 1; x++) m[y][x] = 0;
  clearSpawnArea(m, playerStart.x, playerStart.y, SPAWN_CLEAR_RADIUS);
  for (let x = 0; x < COLS; x++) { m[0][x] = 1; m[ROWS - 1][x] = 1; }
  for (let y = 0; y < ROWS; y++) { m[y][0] = 1; m[y][COLS - 1] = 1; }
  const cells = [];
  for (let y = 1; y < ROWS - 1; y++) for (let x = 1; x < COLS - 1; x++) if (m[y][x] === 0) cells.push({ x, y });
  cells.sort((a, b) => dist(b, playerStart) - dist(a, playerStart));
  const enemyStarts = [];
  for (const c of cells) {
    if (dist(c, playerStart) < 3) continue;
    if (enemyStarts.every(s => dist(s, c) >= 2)) {
      enemyStarts.push(c);
      if (enemyStarts.length >= numEnemies) break;
    }
  }
  return { map: m, playerStart, enemyStarts, rewards: [] };
}

/* 联机 9×9 竞技场（ISSUE-20261028-13 方案 A）。
 * 选角大厅内部不再有障碍物后，联机战场改用它自己的快照 —— 保证联机地形与
 * 改动前「逐格相同」（含 4 根角柱 + 中间 2 块），不会因为一次 UI 清理动到平衡。 */
function buildPvpArena() {
  const m = Array.from({ length: 9 }, () => Array(9).fill(0));
  for (let i = 0; i < 9; i++) { m[i][0] = 1; m[i][8] = 1; m[0][i] = 1; m[8][i] = 1; }
  m[2][3] = 1; m[2][5] = 1; m[6][3] = 1; m[6][5] = 1;
  m[3][4] = 1; m[5][4] = 1;
  return m;
}

function initLevel() {
  try {
    /* ★ ISSUE-20261031-126：进战斗关先把「第几个战斗关」+1。
     * ⚠️ `level`（总关卡数）**不在这里动** —— 它在 onLevelClear 里 +1（事件关也会 +1），
     *    initLevel 只负责读。两者分工见 src/rules/state.js 里 battleLevel 的声明注释。 */
    battleLevel += 1;
    /* 玩家操作录制（默认关）：在 generateMap 之前抓种子，回放时据此还原同一张图。
     * level 传的是**总关卡数**（含事件关）—— 排行榜报的就是它（人类拍板 7），
     * 回放只是用它当标签，事件关本身不录，所以数字跳 3→5→8 是预期现象。 */
    if (window.ARK_REC) window.ARK_REC.levelStart({ level: level, char: selectedChar, seed: RUN_SEED, rngSeed: RNG_SEED });
    battleRound = 1;
    clearEnemyArrows();
    clearUnitLayer();
    pendingAttack = false;
    pendingChargeInfo = null;
    vampireSkillActive = false;   // 不稳定血浆只在本关内持续
    /* ISSUE-20261028-06：关卡事件给的敌人数修正（野战维修 +1 / 战术规避 -1）。
     * **用完即清**，只影响紧接的这一关；夹到上限之内，别让「+1」在高关卡变成空头承诺也说不过去，
     * 所以上限放宽 1 个，其余仍受 MAX_ENEMIES_PER_LEVEL 约束。 */
    const enemyDelta = nextLevelEnemyDelta;
    nextLevelEnemyDelta = 0;
    /* ★ ISSUE-20261028-14：教程关的地图与敌人数都来自手写数据（src/rules/tutorial.js），
     * 这里只把「程序生成」换成「手写数据」，后面的玩家/敌人/render 流程一行都不动。 */
    const tutMap = (typeof tutorialMapOverride === 'function') ? tutorialMapOverride() : null;
    /* ★ ISSUE-20261031-128：合作模式敌人数量 = 单人基数 + 2×(人数−1)（人类 23:42 拍板）。
     *   `coopEnemyCount` 在单人局（coopPartySize === 1）恒等返回 base，所以这行对单人数值
     *   **零影响**；教程关走 tutMap，本来就不吃这条公式。
     * ★ ISSUE-20261031-126：基数读 battleLevel（不是 level）—— 事件关不让它 +1，
     *   所以「第 N 个战斗关的敌人数量」与改动前完全一致，难度曲线一格未变。 */
    const baseEnemyCount = Math.max(1, Math.min(
      3 + Math.floor((battleLevel - 1) / 2) + enemyDelta, MAX_ENEMIES_PER_LEVEL + 1));
    const numEnemies = tutMap ? tutMap.enemyStarts.length : coopEnemyCount(baseEnemyCount);
    /* ★ ISSUE-20261029-29：棋盘固定 9×9（人类 04:42）。
     * 旧的「按关卡长地图」公式整段删除 —— 现在行 / 列恒为 9，
     * 随机地形、起点筛选、奖励摆放全部沿用原逻辑，只是尺寸参数换成了常量。
     * 视觉侧不受影响：updateCellSize() 仍按可用区域短边算正方形格边长，格子只会更大更清楚。 */
    const targetWalkable = BOARD_TARGET_WALKABLE;
    ROWS = BOARD_ROWS;
    COLS = BOARD_COLS;
    const gen = tutMap || generateMap(numEnemies, targetWalkable);
    map = gen.map;
    rewardItems = gen.rewards || [];
    bloodDrops = [];
    /* ISSUE-20261031-118：骨头**不跨关**（和血迹一样是当关资源） */
    boneDrops = [];
    recomputePlayerDerivedStats();
    /* 药枚：每关开始时获得 1 层护盾（层数 = 收藏品层数，不跨关累积） */
    playerShield = relics.pill;
    /* ISSUE-20261028-06：「每关一次」的账进关清零 ——
     * 硬化外壳（本关首伤免疫）、回响回路（施法装填，不带进新关） */
    relicShieldUsedThisLevel = false;
    relicEchoArmed = false;
    if (playerStats.currentHp > playerStats.maxHp) playerStats.currentHp = playerStats.maxHp;
    if (playerStats.currentHp <= 0) playerStats.currentHp = playerStats.maxHp;
    player = createPlayerUnit(gen.playerStart);
    /* ★ ISSUE-20261031-128 §十六：合作闯关 —— 队友上场。
     *
     * 为什么放在 `createPlayerUnit` 之后、敌人 for 循环之前：
     *   · 出生点要用 `gen.playerStart`（相邻逐圈找空格），玩家单位必须先存在；
     *   · 又要避开 `gen.enemyStarts`，所以必须在敌人真正落位之前就把队友的格子占掉，
     *     否则会出现「队友和骷髅叠在同一格」（渲染层斜分后看着像两个人，实际是敌人）。
     * 跨关语义：队友**不重建**（HP / 座位 / 计划都带过去），只在新地图上重新找空格 ——
     *   与 `squadRelocateToPlayer` 同思路，但绝不叠在玩家脚下。
     * 单人局：`coopIsActive()` 为 false，这一段整块跳过，对既有对局零影响。 */
    if (typeof coopIsActive === 'function' && coopIsActive()) {
      const coopBlocked = (gen.enemyStarts || []).concat(rewardItems || []);
      if (coopAllies.length) {
        coopRelocateAllies(gen.playerStart, coopBlocked);
      } else if (coopGetAllyInfos().length) {
        coopSpawnAllies(coopGetAllyInfos(), gen.playerStart, coopBlocked);
      }
      if (coopAllies.length) {
        log('🤝 合作闯关：' + (coopAllies.length + 1) + ' 人同场（你 + ' +
            coopAliveAllies().length + ' 名队友），本关敌人 ' + numEnemies + ' 只。');
      }
    }
    /* ★ ISSUE-20261028-14：教程进关补丁（预置技力 / 预置血迹）。
     * 必须在 createPlayerUnit 之后 —— 血迹要落在「教程地图已经生效」的坐标上。 */
    if (typeof tutorialAfterInit === 'function') tutorialAfterInit(gen);
    /* 经验制口径（ISSUE-20261028-10）：失血 = 关卡开始时血量 − 关卡结束时血量。
     * 必须取 player.hp（战斗中的唯一真实血量），且时机在 createPlayerUnit 之后：
     * playerStats.currentHp 是跨关持久值，前面还有「>maxHp 夹取」「<=0 兜底成满血」两步。 */
    levelStartHp = player.hp;
    levelActions = 0;
    enemies = [];
    /* ISSUE-20261028-10-B：粗圆岩是跨关的全局集合，map 虽然每关重生成，但集合必须显式清空，
     * 否则上一关的坐标会落到新地图上，把随机一格错误地标成石头。 */
    roughRocks.clear();
    /* ★ ISSUE-20261030-54（推翻 ISSUE-20261029-28 的「小队成员不跨关」）：
     * 小队成员**跨关保留** —— 成员是消耗品但不必每关重攒，技力同样跨关继承（rookieSp 不在这里清）。
     * ⚠️ 只有「换角色 / 整局重开」才清 squadUnits，那条在 src/rules/reset.js#resetSkillState，
     *   千万别挪到这里 —— initLevel 同时被 selectCharacter（重开）与 enterAllocGate（进下一关）调用，
     *   在这里清空等于把「重开」和「进下一关」混成一回事。
     * 数值是**冻结**的：跨关带过去的是召唤当时的数值（含受伤后的当前 HP，不回满）；
     * 只有 prof 跟着 heroLevel 刷新（squadRelocateToPlayer 内）。
     * 落点一律回到预备干员本格 —— 同时自愈「上一关坐标落在新地图的墙里 / 越界」。 */
    squadRelocateToPlayer();
    /* ★ 同上：BOSS 仍在**第 10 个战斗关**起、每 5 关一个。改用 level 的话，事件关会把 BOSS 提前到第 8 个战斗关。
     * ★ ISSUE-20261031-120：不再写死 BOSS_TYPE —— 按排班表查本关该上谁（10/20/30 巨像、15/25/35 猴王）。 */
    const bossHere = isBossLevel(battleLevel) && numEnemies > 0;
    const bossType = bossHere ? bossTypeForLevel(battleLevel) : null;
    let ufoSpawnedThisLevel = false;
    for (let i = 0; i < numEnemies; i++) {
      const s = gen.enemyStarts[i];
      /* 类型按关卡解锁 + 权重（ISSUE-20261028-04）：L1-2 只有骷髅，L3 起幽灵，
       * L5 起外星怪物（远程狙击），L6 起外星人👽（近战），L8 起盾卫，L12 起自爆虫。 */
      /* ★ ISSUE-20261028-10-B：Boss 关把**最后一只**换成 Boss，而不是额外加一只
       * （否则第 10 关等于「6 普通 + 1 Boss」，难度直接崩）。
       * Boss 不参与词缀/精英抽取：它自己就是关底，再叠 2 个词缀会失控。
       * ★ ISSUE-20261031-120：`BOSS_TYPE` → `bossType`（本关按排班表查出来的那一个）。 */
      const isBossSlot = bossHere && i === numEnemies - 1;
      let type = isBossSlot ? bossType : pickEnemyType(battleLevel);   /* 类型解锁看战斗关数 */
      /* ★ ISSUE-20261031-119：每关最多 1 只飞碟（超限回落为普通骷髅） */
      if (type === 'ufo') {
        if (ufoSpawnedThisLevel) type = 'skeleton';
        else ufoSpawnedThisLevel = true;
      }
      /* 成长面板（ISSUE-20261028-03）：第 battleLevel 个战斗关的敌人已推演过 battleLevel 次属性提升 + 每 3 关的升级 */
      const grow = computeEnemyGrowth(type, battleLevel, i, RUN_SEED);
      const eAbilities = grow.abilities;
      const eProf = getEnemyProf(type);
      const eAC = computeAC(eAbilities);
      const eMove = Math.max(1, Math.floor(eAbilities.dex / 2));
      /* 词缀与精英（ISSUE-20261028-05）：L5 起每关 1 个精英（HP×1.5、必带 2 词缀），
       * 普通敌人按关卡概率带 1 个词缀。全部由 RUN_SEED 派生 → 同种子重开完全一致。 */
      const affixPlan = isBossSlot
        ? { isElite: false, affixes: [] }
        /* ★ ISSUE-20261031-128：合作模式下「词条敌人」数量随人数增加（每多 1 人 +1 只强制带词条），
         * 单人局 coopAffixQuota() === 0 → 恒为 false → 与改动前完全一致。 */
        : rollEnemyAffixPlan(battleLevel, i, numEnemies, RUN_SEED, coopAffixForced(i, numEnemies, battleLevel, RUN_SEED));
      /* ★ ISSUE-20261031-120（人类 2.2 新增规则①）：**所有 Boss 生成时 HP 上限 ×2**。
       * 只对 `ENEMY_STATS[type].boss === true` 的类型生效（圆岩巨像 + 猴王），
       * 是全局 Boss 规则而不是某个 Boss 的特性。⚠️ 巨像也一起翻倍，有意为之。 */
      const hpBase = affixPlan.isElite ? Math.ceil(grow.maxHp * ELITE_HP_MUL) : grow.maxHp;
      const hp = bossAdjustedHp(type, hpBase);
      /* 伤害骰（ISSUE-20261028-04）：结算走 rollEnemyDamage(e, kind) 掷骰，
       * meleeDmg/rangedDmg 保留为**骰子期望值**，供 AI 估值与日志面板展示。 */
      const baseDice = ENEMY_STATS[type].dice || {};
      const meleeDice = baseDice.melee ? { n: baseDice.melee[0], s: baseDice.melee[1] } : null;
      const rangedDice = baseDice.ranged ? { n: baseDice.ranged[0], s: baseDice.ranged[1] } : null;
      enemies.push({
        id: i, groupId: i, x: s.x, y: s.y, hp, maxHp: hp, type,
        move: eMove,
        abilities: { ...eAbilities },
        ac: eAC,
        prof: eProf,
        enemyLevel: grow.level,
        enemyGrowths: battleLevel,
        meleeDmg: diceAvg(meleeDice),
        rangedDmg: diceAvg(rangedDice),
        meleeDice,
        rangedDice,
        explodeDmg: ENEMY_STATS[type].explode || 0,
        isElite: affixPlan.isElite,
        affixes: affixPlan.affixes,
        shieldLeft: affixPlan.affixes.indexOf('shield') >= 0 ? 1 : 0,
        alive: true, attackedThisRound: false,
        facing: faceToward(s, player),
        amiyaRevealBonus: 0,
        amiyaRevealForNext: false,
        amiyaRevealActive: 0,
        stunTurns: 0,
        /* ISSUE-20261028-10-B：Boss 落石计时（回合末递减，到 0 就落一块并重置）。
         * 首回合不落 —— 让玩家先看清它长什么样、意图往哪走，再开始被堵。
         * ★ ISSUE-20261031-120：落石是**圆岩巨像专属**，所以判 `type === BOSS_TYPE`（='colossus'），
         *   不能用 isBossSlot —— 否则猴王也会开始落石头。 */
        rockCd: (isBossSlot && type === BOSS_TYPE) ? COLOSSUS_ROCK_EVERY : 0,
        /* ★ ISSUE-20261031-120：猴王的技能计时与当前形态。
         * kingForm 为空 = 还没开过技能（没有形态效果）；第一次开技能从 🙊 起。
         * 计时口径照抄 rockCd：endRound 里递减，到 0 就开技能并重置。 */
        kingForm: '',
        skillCd: (isBossSlot && type === 'monkey_king') ? MONKEY_KING_SKILL_EVERY : 0,
 });
 }
    /* ★ ISSUE-20261028-14：教程敌人参数（木桩不动/打不死、巡逻敌 s5 之前不动）。
     * 放在这里而不是在循环里加 if —— 程序生成与手写教程共用同一段造人代码，
     * 教程的差异全部收敛到 src/rules/tutorial.js 一个函数里。 */
    if (typeof tutorialDecorateEnemies === 'function') tutorialDecorateEnemies(enemies);
    playerPath = [{ x: player.x, y: player.y }];
    attackIndices = [];
    skillIndices = [];
    actionPlacements = [];
    enemyPaths = [];
    lastPathSignature = '';
    phase = PHASE.PLANNING;
    playerChargingThisTurn = false; playerAttacksDone = 0; fencerCounterActive = false;
    playerChargeStopReason = null;
    playerChargeCausedDamage = false;
    logLines = logLines.slice(-5);
    if (logLines.length > 0) logLines.push('');
    renderLogAll();   // 保留上一关最近 5 行作为上下文，再重绘可视区
    const charName = CHARACTERS[selectedChar] ? CHARACTERS[selectedChar].name : '未知';
    log(`=== 第 ${level} 关　角色：${charName}　地图 ${COLS}×${ROWS}　敌人 ${numEnemies} 个 ===`);
    if (selectedChar === 'amiya' && amiyaBonusTargets > 0) {
      log(`阿米娅继承了 ${amiyaBonusTargets}/${amiyaSpMax()} 点技力（跨关继承）。`);
 }
    if (selectedChar === 'fencer') {
      log(`泥岩技力：${fencerSp}/${FENCER_SP_MAX}（跨关继承）`);
 }
    if (selectedChar === 'rookie' && rookieSp > 0) {
      log(`😶 预备干员技力：${rookieSp}/${ROOKIE_SP_MAX}（跨关继承）`);
 }
    /* ★ ISSUE-20261030-54：成员跨关保留，进关时提示还带着谁（否则玩家以为他们没了） */
    if (selectedChar === 'rookie' && typeof squadAliveUnits === 'function' && squadAliveUnits().length > 0) {
      const alive = squadAliveUnits();
      log(`😶 小队随你进入第 ${level} 关（${alive.length}/4）：${alive.map(s => `${s.icon}${s.hp}/${s.maxHp}`).join('、')}`);
 }
    /* 敌人面板按「本关实际生成的单位」打印（ISSUE-20261028-03）：
     * 成长是个体化的（依赖实例下标），所以不能再打印一份固定的三类模板，否则日志与场上数值对不上。 */
    const eLv = Math.floor(level / LEVELUP_EVERY_N_LEVELS);
    const fmtMod = (v) => (v >= 0 ? '+' + v : String(v));
    log(`敌人面板（第 ${level} 关 · 每个敌人已成长 ${level} 次属性${eLv > 0 ? ` · 等级 Lv.${eLv}` : ''}）：`);
    enemies.forEach(e => {
      const a = e.abilities;
      log(`  ${e.isElite ? '★精英 ' : ''}${ENEMY_STATS[e.type].name}#${e.id + 1}：STR${a.str}(${fmtMod(abilityMod(a.str))}) DEX${a.dex}(${fmtMod(abilityMod(a.dex))}) CON${a.con}(${fmtMod(abilityMod(a.con))}) INT${a.int}(${fmtMod(abilityMod(a.int))}) AC${e.ac} 熟练+${e.prof} 移动${enemyMoveOf(e)} HP${e.maxHp} 近战${e.meleeDice ? diceLabel(e.meleeDice) + '(' + e.meleeDmg + ')' : e.meleeDmg} 远程${e.rangedDice ? diceLabel(e.rangedDice) + '(' + e.rangedDmg + ')' : e.rangedDmg}${e.explodeDmg ? ' 自爆' + e.explodeDmg : ''}${e.affixes.length ? '　词缀：' + enemyAffixLabel(e) : ''}`);
 });
    log(`规则：攻击检定 = d20 + 属性修正 + 熟练加值 ≥ 目标AC；自然20暴击；自然1必失。`);
    log(`朝向（ISSUE-15 / 61）：**正对目标出手必定命中**（连自然1也算中），且伤害 ×2（弱点暴击）。远程的「正对」= 正前方**一条直线**上的目标（同向同行/同列，不限距离）；近战的「正对」= 正面 ±1 格扇形。侧身、背后仍按上面掷骰。`);
    log(`动作预算（ISSUE-25）：每回合可以做 ${BASE_ACTIONS_PER_TURN} 件事 —— 攻击 / 技能 / 闪避各占 1 件，所以「打一拳 + 闪一次」是允许的；但**攻击次数上限仍是每回合 1 次**（收藏品可加）。`);
    if (level === 1) {
      log(`升级规则：通关得经验，本关掉血越少经验越多（满血开局时以「本关开始血量 × 40%」为失血基准，少掉 1 血 +${XP_PER_STEP} 经验，保底 ${XP_CLEAR_BASE}）。经验满即升级：HP 上限 + 体质加值并回满血，同时从奖励池 3 选 1 个 buff、获得 ${ABILITY_POINTS_PER_LEVELUP} 点属性点。`);
      log(`敌人成长：每关每个敌人随机 +1 项属性（只从当时最高的 4 项里选，相邻两次不重复），每 ${LEVELUP_EVERY_N_LEVELS} 关升级一次（HP 上限 + 体质加值）。`);
 }
    log(`你的属性：力${abilityLabel(player.abilities.str)} 智${abilityLabel(player.abilities.int)} 敏${abilityLabel(player.abilities.dex)} 感${abilityLabel(player.abilities.wis)} 体${abilityLabel(player.abilities.con)} 魅${abilityLabel(player.abilities.cha)}`);
    log(`AC ${player.ac}　熟练+${player.prof}（近战${player.meleeProf}／远程${player.rangedProf}）　HP = 体质${player.abilities.con} + 基础${BASE_HP_BONUS} + 升级加成${levelHpBonus}${relicHpBonus() ? ' + 热水壶' + relicHpBonus() : ''} = ${player.maxHp}`);
    if (rewardItems.length > 0) log(`地图中发现了 ${rewardItems.length} 个恢复道具 ❤️！`);
    if (playerShield > 0) log(`💊 药枚：本关开始获得 ${playerShield} 层护盾（可抵消 ${playerShield} 次伤害）。`);
    nextEnemyId = enemies.length;
    creditedKillGroups.clear();
    generateEnemyPaths();
    logEnemyMainDirections();
    /* ★ ISSUE-20261028-14：教程提示条的首次渲染。
     * 放在这里而不是 render() 里 —— render() 每帧都跑，bar 不需要跟着重排。 */
    if (typeof renderTutorialBar === 'function') renderTutorialBar();
    setTimeout(() => { updateCellSize(); render(); }, 50);
 } catch (err) {
    console.error(err);
    clearLog();
    log('初始化错误：' + (err && err.message ? err.message : err));
    log(String(err && err.stack ? err.stack : ''));
    phase = PHASE.GAMEOVER;
    try { render(); } catch (e) {}
 }
}

// ===== 地图 / UI 拖动调整块（仅桌面端，手机端隐藏） =====
const dragHandle = document.getElementById('dragHandle');
const sidebarEl = document.getElementById('sidebar');
const SIDE_W_KEY = 'ark_side_w';
function sideWBounds() {
  const min = 300;
  const max = Math.max(min + 80, window.innerWidth - 420);
  return { min, max };
}
// 六维图已移入右侧抽屉（ISSUE-20261028-09 G）：画布尺寸固定，不再随侧栏宽度缩放。
// 保留空实现是因为 resize / setLayout / applySidebarWidth 仍在调用。
function fitSidebarToWidth() {}
function applySidebarWidth(w, save) {
  const { min, max } = sideWBounds();
  w = Math.round(Math.max(min, Math.min(max, w)));
  sidebarEl.style.width = w + 'px';
  if (save) { try { localStorage.setItem(SIDE_W_KEY, String(w)); } catch (_) {} }
  fitSidebarToWidth();
  updateCellSize();
  return w;
}
(function initSidebarWidth() {
  if (window.innerWidth <= 760) return;
  let saved = NaN;
  try { saved = parseInt(localStorage.getItem(SIDE_W_KEY), 10); } catch (_) {}
  if (!isNaN(saved) && saved > 0) applySidebarWidth(saved, false);
  else fitSidebarToWidth();
})();
/* src: src/ui/layout.js 第 1 段/beforeLayoutV */
/* P0.1-4 拆分 · 20261028c 基线 · 竖版地图高度拖动已于 ISSUE-20261028-09 废除：
 * 正方形棋盘「总是取最大」，高度不能由用户拖动决定，#dragHandle 在 layout-v 下直接不渲染。
 * 保留 applyMapVHeight / syncMapVHeight / clearMapVHeight 三个函数名是因为 resize 与 setLayout
 * 仍有调用；它们不再写 boardWrap.style.height —— 尺寸的唯一来源是 updateCellSize()。 */
const gameEl = document.getElementById('game');
const MAP_V_KEY = 'ark_map_v_ratio';

function applyMapVHeight() { clearMapVHeight(); return boardWrap.offsetHeight; }
function syncMapVHeight() { clearMapVHeight(); }
function clearMapVHeight() {
  // 清掉旧版留下的内联高度与比例：老用户的 ark_map_v_ratio 会把正方形锁死成历史高度
  if (boardWrap.style.height) boardWrap.style.height = '';
  if (boardWrap.style.maxHeight) boardWrap.style.maxHeight = '';
  try { localStorage.removeItem(MAP_V_KEY); } catch (_) {}
  updateCellSize();
}
clearMapVHeight();   // 启动即清，避免旧值影响首屏

let sideDragging = false, sideDragRaf = 0, sideDragPendingW = null;
function sideDragFlush() {
  sideDragRaf = 0;
  if (sideDragPendingW != null) { applySidebarWidth(sideDragPendingW, false); sideDragPendingW = null; }
}
dragHandle.addEventListener('pointerdown', (e) => {
  // 竖版已无拖动条（CSS display:none），这里只剩横版的侧栏宽度拖动；手机端不开放
  if (window.innerWidth <= 760) return;
  sideDragging = true;
  dragHandle.classList.add('dragging');
  try { dragHandle.setPointerCapture(e.pointerId); } catch (_) {}
  e.preventDefault();
});
dragHandle.addEventListener('pointermove', (e) => {
  if (!sideDragging) return;
  // 右侧内边距16 + 半个调整块5 + 两个gap 8*2 ≈ 29
  sideDragPendingW = window.innerWidth - e.clientX - 29;
  if (!sideDragRaf) sideDragRaf = requestAnimationFrame(sideDragFlush);
});
function endSideDrag() {
  if (!sideDragging) return;
  sideDragging = false;
  dragHandle.classList.remove('dragging');
  if (sideDragRaf) { cancelAnimationFrame(sideDragRaf); sideDragRaf = 0; sideDragFlush(); }
  const cur = parseFloat(sidebarEl.style.width) || sidebarEl.offsetWidth;
  applySidebarWidth(cur, true);
  if (player || phase === PHASE.CHAR_SELECT) render();
}
dragHandle.addEventListener('pointerup', endSideDrag);
dragHandle.addEventListener('pointercancel', endSideDrag);

let resizeTimeout;
window.addEventListener('resize', () => {
  clearTimeout(resizeTimeout);
  resizeTimeout = setTimeout(() => {
    /* 旋转 / 尺寸变化：按设备形态自动重选横竖版，避免横屏手机被当成竖版导致棋盘压扁
     * （泽雨 ISSUE-67 / 标注 ISSUE-20261101）。pickLayout() 在 src/ui/layout.js，
     * 本槽位 beforeLayoutV 先于这段执行，函数声明已可用。 */
    const want = pickLayout();
    const isV = document.body.classList.contains('layout-v');
    if ((want === 'v') !== isV) setLayout(want, false);
    // 窗口尺寸变化 / 旋转后棋盘必须重新填满可用短边，不能残留旧尺寸
    if (window.innerWidth > 760 && sidebarEl.style.width) {
      applySidebarWidth(parseFloat(sidebarEl.style.width) || sidebarEl.offsetWidth, false);
 }
    updateCellSize();
    if (player || phase === PHASE.CHAR_SELECT) render();
 }, 100);
});
// 横竖屏切换兜底：部分浏览器（尤其 iOS Safari）旋转时不保证先触发 resize，补一发
window.addEventListener('orientationchange', () => {
  setTimeout(() => window.dispatchEvent(new Event('resize')), 200);
});

/* ★ ISSUE-20261101-137：首屏必须再算一次，否则格子锁死在错误的边长上。
   updateCellSize() 第一次是在 src/ui/layout.js 顶层同步跑的（clearMapVHeight），
   那一刻字体与图片还没加载完，`#game.clientWidth/Height` 不是最终值 ——
   实测 1500×676（算得 cell=50）而布局稳定后是 1550×794（应为 cell=59）。
   原来按 21×11 算，误差被「能塞多大塞多大」吸收掉了；改成「短边正好 13 格」之后，
   一次算错就是整整差一格，肉眼可见。 */
function arkRefitAfterLoad() {
  updateCellSize();
  if (player || phase === PHASE.CHAR_SELECT) render();
}
if (document.readyState === 'complete') {
  requestAnimationFrame(arkRefitAfterLoad);
} else {
  window.addEventListener('load', () => requestAnimationFrame(arkRefitAfterLoad), { once: true });
}

/* 棋盘可用区域（ISSUE-20261028-09 A）：返回能放下正方形的最大边长。
 * 横版：宽度 = #game 内容宽 − 侧栏 − 竖分隔条 − 两个 gap；高度 = #game 内容高。
 * 竖版：宽度 = 内容宽；高度 = 内容高 − 侧栏最小高度 − gap。
 * 取两者短边并 floor 成整数像素，保证 #boardWrap 严格 1:1 且不溢出。 */
function boardAvailSize() {
  const cs = getComputedStyle(gameEl);
  const padX = (parseFloat(cs.paddingLeft) || 0) + (parseFloat(cs.paddingRight) || 0);
  const padY = (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0);
  const gap = parseFloat(cs.columnGap || cs.gap) || 0;
  let w = gameEl.clientWidth - padX;
  let h = gameEl.clientHeight - padY;
  if (document.body.classList.contains('layout-v')) {
    /* 侧栏在下方：用它的最小高度做预算（超出部分由 #stats 自己滚动）。
     * ★ ISSUE-20261030-66：预算必须**随可用高自适应**，否则矮屏（手机横过来、
     * 微信内置浏览器、虚拟键盘）上（ISSUE-20261101-152 起底部不再有任何浮层补偿）
     * h 会被这 210 直接扣成负数 → 落到下面的 120 兜底 → 棋盘被裁成「只剩中间」。
     * 上限仍是 210/240：正常机型 contentH ≥ 620 时 min(210, 0.34×620≈211) = 210，
     * 与旧行为逐像素一致（桌面横版不经过这条分支，零影响）。 */
    const base = window.innerWidth <= 760 ? 210 : 240;
    const contentH = Math.max(0, gameEl.clientHeight - padY);
    const minSide = Math.min(base, Math.max(120, Math.round(contentH * 0.34)));
    h -= minSide + gap;
 } else {
    const sw = sidebarEl ? sidebarEl.offsetWidth : 0;
    const dh = (dragHandle && getComputedStyle(dragHandle).display !== 'none') ? dragHandle.offsetWidth : 0;
    w -= sw + dh + gap * 2;
 }
  return { w: Math.max(120, w), h: Math.max(120, h) };
}

/* ★ ISSUE-20261030-66：棋盘几何的**唯一算法**（纯函数，不读 DOM，便于单测）。
 *
 * 出过的 P1：手机进第二关「只能看见地图中间」。链条是两处兜底互相打架 ——
 *   ① boardAvailSize() 把可用高兜到 120 → side = 120 → #boardWrap 写成 120×120；
 *   ② 这里把 cell 兜到 16 → 棋盘实际 11×16 + 10×2 = 196px。
 *   ③ #boardWrap 是 overflow:hidden + flex 居中 → 196 塞进 120，四周各裁 38px。
 * 根因是**缺少「容器必须装得下棋盘」这条不变式**：只要 side 与 cell 的兜底不一致，
 * 棋盘就会默默被裁掉，而界面上没有任何滚动条或提示。
 *
 * 现在两条约束同时成立：
 *   · 正常路径（side ≥ 棋盘所需）→ wrap === side，与原实现**逐像素一致**；
 *   · 空间不足 → 先把格子压到 MIN_BOARD_CELL，仍装不下就把 wrap 撑到棋盘尺寸。
 *     「格子小到看不清」好过「只能看见中间」——前者至少还能看清地形与敌人位置。
 */
/* ⚠️ 三个数字必须是**函数内字面量**，不能提到顶层 const：
 * layout.js 的槽位（@inject:scripts:beforeLayoutV，本文件 1645 行）比这个函数更早，
 * 模块加载期就经 clearMapVHeight() → updateCellSize() 调进来一次，
 * 那时顶层的 const 还在 TDZ 里，会直接 ReferenceError（打包后是同一个 script）。
 *
 * preferWidth（人类 2026-10-30 05:14 拍板「地图要始终保持最大，宽度就是手机屏幕的宽度，
 * 稍微留一点点空隙」）：只有**手机竖版**（layout-v）传 true —— 边长只由宽度决定，
 * 不再被可用高度压小；高度不够由 #game 自己纵向滚动消化。
 * 横版仍取短边：横屏时可用宽必然大于可用高，按宽度走会让棋盘比视口还高，又一次被裁。
 */
/* ISSUE-20261101-137：★ 全平台铺满格栅的几何解算（纯函数，门禁直接调用 —— 别内联回 updateCellSize，
   否则门禁只能跑 jsdom 量 DOM，一旦渲染条件不满足就假绿）。

 * 口径（人类 2026-11-01 02:12 / 02:22 两次拍板）：
 *   · **横版短边必须正好 13 格** —— cell 由短边反算，不是「能塞多大塞多大」；
 *   · **长边一直填格子**，填不满的零头留成纯色窄边（#game 的 --frame 背景，不画格线）；
 *   · **地图 11×11 与 UI 11×11 等大**，**两边直接相邻**（ISSUE-20261101-154 删掉了原来
 *     夹在中间的 1 格分隔）→ 横版内容块 22 列、竖版 22 行；
 *   · 内容放不进长边时（4:3 那种方屏）反过来由长边定 cell，短边格数顺势涨到 14~17 格。
 *     宁可短边多于 13 格，也不许内容溢出画面 —— 「铺满」优先于「正好 13」。
 *
 * ★ ISSUE-20261101-154（人类 2026-11-01 22:2x「让手机端点开就是竖屏布局，画面放大到
 *   地图 11×11 加上 UI 11×11」）：**竖版不再按短边 13 格反算**，改成
 *   「宽正好 11 格（地图宽）·高正好 22 行（地图 11 + UI 11）」两条同时约束、取小：
 *     cell = min( (w − 10·gap)/11 , (h − 21·gap)/22 )
 *   于是手机竖屏的格子比原来（13 格反算）大 18% 左右，且内容块永远是完整的 11×22，
 *   不会为了塞进高度而把信息格丢掉（只有 cell 掉到看不清时才有那层兜底）。
 *
 * 返回的 bx1/bx2… 全是 **1-based 的 grid line**，直接喂 grid-column / grid-row。
 */
function computeGridFit(avail, gap, view) {
  const MIN_CELL = 6;
  const SHORT_CELLS = 13;          // 横版短边目标格数（地图 11 + 上下各 1 圈地板）
  const MIN_COMFY = 18;            // 竖版 cell 低于这个值才考虑掉信息格换尺寸
  const BOARD = 11;                // 地图边长（格）
  /* ★ ISSUE-20261101-144（人类 2026-11-01 15:48 规格 + 16:0x 三条拍板）：
     **UI 宽度锁死 11 列** —— 状态 11×3 / 信息 11×3 / 操作 11×5。
     空间不够时按这个顺序让步，顺序不能反：
       ① 先移除信息面板（少 3 行，格子大小一个像素都不动）；
       ② 还不够才缩 cell（地图与 UI 一起变小，但两者始终是完整的 11 格）。
     「UI 缩到 5 列」那条分支已废除：5 列时状态/信息/操作三条全部挤成细缝，两行字都放不下。 */
  const UI_COLS = 11;              // UI 宽度：恒 11 列
  const UI_ROWS_FULL = 11;         // 3 状态 + 3 信息 + 5 操作
  const UI_ROWS_NOINFO = 8;        // 掉信息格后：3 状态 + 5 操作
  /* ★ ISSUE-20261101-154：**分隔 = 0**。人类「删掉地图和 UI 中间的一条格子，两边并在一起」
     —— 地图最后一列与 UI 第一列直接相邻，中间只剩其他格子也有的那一道 --gap 缝。 */
  const SEP = 0;

  const vertical = view === 'v';
  const w = Math.max(1, Math.floor(avail && avail.w || 0));
  const h = Math.max(1, Math.floor(avail && avail.h || 0));
  const shortSide = Math.min(w, h);
  const longSide = Math.max(w, h);

  /* 横版：长边 = 宽度，UI 在右侧 → 掉信息格**不省列**（列需求恒 22），只能缩 cell。
     这就是为什么 4:3 方屏横版是「整块小一圈」而不是「少一块面板」。 */
  const needCols = BOARD + SEP + UI_COLS;               // 横版长边至少要 22 列
  const needRowsFull = BOARD + SEP + UI_ROWS_FULL;      // 竖版长边至少要 22 行
  const needRowsNoInfo = BOARD + SEP + UI_ROWS_NOINFO;  // 掉信息格后只要 19 行

  let noInfo = false;
  let cell;
  if (vertical) {
    /* ★ ISSUE-20261101-154：竖版由**两条**约束同时定 cell，取小 ——
     *   宽度方向「正好 11 格」（地图宽，两侧不留地板圈）、高度方向「正好 22 行」。
     *   这样内容块恒为完整的 11×22，格子比旧的「短边 13 格」反算大 ~18%。
     *   只有 cell 掉到 MIN_COMFY 以下（极矮的视口）才考虑掉信息格换尺寸，
     *   而且**必须真能换来更大的 cell** —— 白丢一块面板没有任何收益。 */
    const cellW = Math.floor((w - (BOARD - 1) * gap) / BOARD);
    const cellH = Math.floor((h - (needRowsFull - 1) * gap) / needRowsFull);
    cell = Math.max(MIN_CELL, Math.min(cellW, cellH));
    if (cell < MIN_COMFY) {
      const cellHNoInfo = Math.floor((h - (needRowsNoInfo - 1) * gap) / needRowsNoInfo);
      const cellNoInfo = Math.max(MIN_CELL, Math.min(cellW, cellHNoInfo));
      if (cellNoInfo > cell) { noInfo = true; cell = cellNoInfo; }
    }
  } else {
    /* 横版：短边（高）13 格反算 → 再看 22 列装不装得下宽的可用区，装不下才缩 cell */
    cell = Math.floor((shortSide - (SHORT_CELLS - 1) * gap) / SHORT_CELLS);
    cell = Math.max(MIN_CELL, cell);
    const cellFitCols = Math.floor((longSide - (needCols - 1) * gap) / needCols);
    if (cellFitCols < cell) cell = Math.max(MIN_CELL, cellFitCols);
  }

  const longCells = Math.floor((longSide + gap) / (cell + gap));
  /* 短边下限：横版 13 格（地板圈）、竖版 11 格（地图宽）。小于下限时按「能放几格」铺满。 */
  const shortCells = Math.max(vertical ? BOARD : SHORT_CELLS, Math.floor((shortSide + gap) / (cell + gap)));
  const uiRows = noInfo ? UI_ROWS_NOINFO : UI_ROWS_FULL;

  const contentCols = vertical ? BOARD : BOARD + SEP + UI_COLS;
  const contentRows = vertical ? BOARD + SEP + uiRows : BOARD;
  const cols = vertical ? shortCells : longCells;
  const rows = vertical ? longCells : shortCells;

  /* 内容块在格栅里居中；多出来的格子一律闲置铺地板（人类 02:21「闲置，单纯的格子」） */
  const offX = Math.floor((cols - contentCols) / 2);
  const offY = Math.floor((rows - contentRows) / 2);

  const bx1 = offX + 1;
  const bx2 = bx1 + BOARD;
  const by1 = offY + 1;
  const by2 = by1 + BOARD;

  /* 横屏 UI 在地图右侧、竖屏 UI 在地图正下方；SEP=0 → **紧贴**（154）。 */
  const sx1 = vertical ? bx1 : bx2 + SEP;
  const sy1 = vertical ? by2 + SEP : by1;

  const usedW = cols * cell + (cols - 1) * gap;
  const usedH = rows * cell + (rows - 1) * gap;

  return {
    cell: cell, gap: gap, cols: cols, rows: rows, vertical: vertical,
    boardCells: BOARD, uiCells: uiRows, noInfo: noInfo,
    boardPx: BOARD * cell + (BOARD - 1) * gap,
    bx1: bx1, bx2: bx2, by1: by1, by2: by2,
    sx1: sx1, sx2: vertical ? bx1 + BOARD : sx1 + UI_COLS,
    sy1: sy1, sy2: vertical ? sy1 + uiRows : sy1 + BOARD,
    /* UI 恒 11 列；高度 11（三块全在）或 8（掉了信息格） */
    uiCols: UI_COLS,
    uiRows: uiRows,
    /* 余量并入边框的宽度（每边）。place-content:center 会自动对半分，这里给出真值供门禁核对 */
    frameX: Math.max(0, Math.floor((w - usedW) / 2)),
    frameY: Math.max(0, Math.floor((h - usedH) / 2)),
    usedW: usedW, usedH: usedH
  };
}

/* 旧接口：115 稿的「棋盘取最大正方形」算法。140 起 updateCellSize 不再调用它，
   但 board_fit 门禁仍在测它（纯函数），保留以免断链；新代码请一律用 computeGridFit。 */
function computeBoardFit(avail, bc, br, gap, preferWidth) {
  const MIN_CELL = 6;          // 格边长下限：11 列 × 6 + 间隙 = 86px，120 容器装得下
  const MAX_CELL = 80;
  const PAD = 16;              // 与旧版一致的四周内边距预算
  const shortSide = Math.floor(Math.min(avail.w, avail.h));
  const side = Math.max(120, preferWidth ? Math.floor(avail.w) : shortSide);
  const wl = (side - PAD - (bc - 1) * gap) / bc;
  const hl = (side - PAD - (br - 1) * gap) / br;             // 不再 /1.12：格子必须正方
  let cell = Math.floor(Math.min(wl, hl));
  cell = Math.max(MIN_CELL, Math.min(cell, MAX_CELL));
  const bw = bc * cell + (bc - 1) * gap;
  const bh = br * cell + (br - 1) * gap;
  /* 不变式：wrap 必须装得下棋盘（+内边距），否则 overflow:hidden 会裁掉四周 */
  const wrap = Math.max(side, bw + PAD, bh + PAD);
  return { side, cell, wrap, bw, bh };
}

/* ISSUE-20261031-131 / 20261101-137：全屏地板层。
   用 <i> 而不是 .cell：.cell 会被 paintBoard() 的 innerHTML 重刷、也会被门禁按 `.cell`
   计数（lobby_shell 等断言「棋盘格数 = 行×列」），混进来会假红。
   ★ 140 起格数随屏幕变（短边 13 格、长边能放几格放几格），所以改成「格数变了才重建」，
   不能像 131 那样只建一次 —— 否则转屏后右侧那片地板是空的，直接露出边框色。 */
/* ★ 必须是 var 不是 let：layout.js 在模块顶层就同步调了一次 updateCellSize()（clearMapVHeight），
   那时本脚本还没执行到这里，let 会撞 TDZ 抛「Cannot access before initialization」→ 首屏白屏。 */
var arkFloorFillCols = 0, arkFloorFillRows = 0;
function buildFloorFill(cols, rows) {
  const el = document.getElementById('floorFill');
  if (!el || !cols || !rows) return;
  if (cols === arkFloorFillCols && rows === arkFloorFillRows) return;
  arkFloorFillCols = cols;
  arkFloorFillRows = rows;
  let s = '';
  for (let i = 0; i < cols * rows; i++) s += '<i></i>';
  el.innerHTML = s;
}

function updateCellSize() {
  const gap = 2;
  /* ★ ISSUE-20261101-138：`clientWidth/Height` **含 padding** ——
     #game 现在用 padding-bottom 给虚拟按钮留高度，不减掉就等于白留：
     格栅仍按整屏高度排，最后几行照样沉到按钮底下。 */
  const gcs = getComputedStyle(gameEl);
  const padX = (parseFloat(gcs.paddingLeft) || 0) + (parseFloat(gcs.paddingRight) || 0);
  const padY = (parseFloat(gcs.paddingTop) || 0) + (parseFloat(gcs.paddingBottom) || 0);
  const availW = Math.max(1, (gameEl.clientWidth || window.innerWidth) - padX);
  const availH = Math.max(1, (gameEl.clientHeight || window.innerHeight) - padY);
  const view = document.body.classList.contains('layout-v') ? 'v' : 'h';
  const fit = computeGridFit({ w: availW, h: availH }, gap, view);
  const cell = fit.cell;

  const root = document.documentElement.style;
  root.setProperty('--cell', cell + 'px');
  root.setProperty('--gap', gap + 'px');
  /* 格栅行列数：CSS 里 repeat(var(--gcols), var(--cell)) 直接吃这两个值，不许再写死 21/11 */
  root.setProperty('--gcols', String(fit.cols));
  root.setProperty('--grows', String(fit.rows));
  /* 内容块位置：1-based grid line，横竖屏两套，全部由 computeGridFit 算 */
  root.setProperty('--bx1', String(fit.bx1));
  root.setProperty('--bx2', String(fit.bx2));
  root.setProperty('--by1', String(fit.by1));
  root.setProperty('--by2', String(fit.by2));
  root.setProperty('--sx1', String(fit.sx1));
  root.setProperty('--sx2', String(fit.sx2));
  root.setProperty('--sy1', String(fit.sy1));
  root.setProperty('--sy2', String(fit.sy2));
  /* UI 自己的格栅行列数：#sidebar 内部就是另一块棋盘（恒 11 列；高度 11 或 8 = 掉了信息格） */
  root.setProperty('--scols', String(fit.uiCols));
  root.setProperty('--srows', String(fit.uiRows));
  /* ★ ISSUE-20261101-144：信息格在不在，由几何解算一处决定 —— 别在别处再算一遍条件。 */
  document.body.classList.toggle('no-info', !!fit.noInfo);
  /* ISSUE-20261101-137：动作方块不再单独封顶 22px —— UI 既然「嵌在格子里」，
     方块边长就等于一格（77 号的封顶常量是 21 格栅时代的补丁，140 起作废）。 */
  root.setProperty('--apip', cell + 'px');

  buildFloorFill(fit.cols, fit.rows);

  /* #boardWrap 的尺寸交给 grid（正好 11 列 × 11 行），这里不再写死像素 —— 尺寸单一来源 */
  if (boardWrap.style.width) boardWrap.style.width = '';
  if (boardWrap.style.height) boardWrap.style.height = '';
  /* 角标贴棋盘四角：#boardWrap 与棋盘等大，偏移恒为 0 */
  root.setProperty('--corner-x', '0px');
  root.setProperty('--corner-y', '0px');
  /* ★ ISSUE-20261101-137：教程 chip 跟棋盘居中。原来是视口居中（left:50%），
     格栅铺满后视口中心落在「地图与 UI 的交界」，教程 chip 会压到 UI 提示条上。
     这里按 #boardWrap 的实时矩形写，棋盘移到哪 chip 就跟到哪。 */
  try {
    const br = boardWrap.getBoundingClientRect();
    if (br.width > 0) {
      root.setProperty('--tut-chip-x', Math.round(br.left + br.width / 2) + 'px');
      root.setProperty('--tut-chip-top', Math.round(br.top + cell * 0.12) + 'px');
    }
  } catch (_) {}

  const m = phase === PHASE.CHAR_SELECT ? selMap : map;
  if (!m || m.length === 0) return;
  /* 棋盘尺寸刚变过 → 覆盖棋盘的「设置面板」矩形也要跟着变（ISSUE-20261029-29）。
   * 转屏/换布局时窗口尺寸不一定变，只靠 resize 监听会漏，所以在这里补一次。 */
  try { if (typeof syncBoardOverlayRect === 'function') syncBoardOverlayRect(); } catch (_) {}
  /* 选角厅的技能说明层是按格子矩形实算的，格子一变它也要重新贴一次 */
  try { if (typeof layoutCharInfoSheet === 'function') layoutCharInfoSheet(); } catch (_) {}
}

function logEnemyMainDirections() {
  if (phase !== PHASE.PLANNING) return;
  /* ★ ISSUE-20261031-120（人类拍板 Q4 + 2.4）：**恢复主方向日志**。
   *   这里原来是 `ISSUE-20261031-100-③` 的全局 `return`（意图全部不显示）。
   *   现在「看不到意图」改由**猴王 🙈 形态**负责 —— 它不是全局开关。
   * ⚠️ 与 board-fx.js#showEnemyFirstStepArrows 成对：那边恢复画箭头，这边恢复打日志。 */
  if (typeof kingHidesIntent === 'function' && kingHidesIntent()) {
    log('🙈 猴王捂眼：看不到任何敌人的意图。');
    return;
  }
  enemies.forEach((e, i) => {
    if (!e.alive) return;
    if (e.stunTurns > 0) { log(`敌人${i+1} 眩晕中（无意图）`); return; }
    const path = enemyPaths[i];
    if (!path || path.length < 2) { log(`敌人${i+1} 主方向：无`); return; }
    const counts = {};
    for (let j = 1; j < path.length; j++) {
      const dx = path[j].x - path[j-1].x, dy = path[j].y - path[j-1].y;
      const d = DIR_NAMES[`${dx},${dy}`] || '?';
      counts[d] = (counts[d] || 0) + 1;
 }
    let max = 0, main = [];
    for (const d in counts) { if (counts[d] > max) { max = counts[d]; main = [d]; } else if (counts[d] === max) main.push(d); }
    log(`敌人${i+1} 主方向：${main.join('/') || '无'}`);
 });
}

/* ★ ISSUE-20261030-64 补齐：⏳（U+23F3，真 emoji）矢量化。
 * ✦ / ✧ 是普通文本符号，按 64 号既定口径（icons.js 文件头「箭头 / 星 / 警告三角不换，
 * 人类拍板」）**保持字符不动**；这里只处理真正的 emoji。
 * 为什么内联 SVG 而不走 sprite：这个标记要跟着格子尺寸（1em）与格内文字色（currentColor）走，
 * sprite 里的实体图标是固定配色 + 固定 32×32，套不进棋盘这套尺寸/配色体系。
 * ⚠️ 函数内直接写 path 常量，不引用模块级 const —— 本函数是 function 声明会被 hoist，
 *    而 mobile-pad 在顶层就调它；引用外部 const 会踩 TDZ（构建能过、一进游戏就崩）。 */
function hourglassTag() {
  return '<svg viewBox="0 0 24 24" width="1em" height="1em" aria-hidden="true" focusable="false"'
    + ' style="display:block;vertical-align:-0.12em"><path fill="currentColor"'
    + ' d="M6.5 2.6h11v2.1h-1.2v1.4c0 1.9-1.5 3.6-3.3 4.9 1.8 1.3 3.3 3 3.3 4.9v1.4h1.2v2.1h-11v-2.1h1.2v-1.4c0-1.9 1.5-3.6 3.3-4.9-1.8-1.3-3.3-3-3.3-4.9V4.7H6.5V2.6Zm3.3 2.1v1.9c0 1.2 1 2.4 2.2 3.3 1.2-.9 2.2-2.1 2.2-3.3V4.7H9.8Zm2.2 7.6c-1.2.9-2.2 2.1-2.2 3.3v1.9h4.4v-1.9c0-1.2-1-2.4-2.2-3.3Z"/></svg>';
}
/* 等待步：沙漏图标 + 步序号（原来是 `⏳2` 两个字符） */
function stepWaitMarkHtml(n) { return hourglassTag() + `<span>${n}</span>`; }

/* ★ ISSUE-20261030-56：给「有单位站在上面」的格子生成动作标记（✦ / 🎯 / 💨 / ⏳n）。
 * 原来这段只在「格子空着」时才跑，有单位就整段跳过 —— 于是同格时玩家完全看不出
 * 这一步是攻击 / 技能 / 闪避 / 等待。现在照样生成，只是包一层 .cell-mark：
 *   · z-index 41 > #unitLayer(40) → 不会被单位图标盖住；
 *   · 若这一格还叠了小队成员，标记会跟着玩家挪到**玩家自己那条斜带**里
 *     （槽位来自 stackSlotStyleAttr，与 renderUnits 同一张表，不会跑到别人的带上）。
 * 没有标记要画时返回 ''（例如起点格 stepsAtCell = [0]），保持原来的「什么都不画」。 */
/* ★ ISSUE-20261030-74：同格多动作的「嵌套方框」渲染 + 放置顺序记录。
 * 动作预算仍保持 2（BASE_ACTIONS_PER_TURN），故同格最多出现 2 个动作的嵌套框；
 * 顺序按「玩家放置/操作的先后」—— 外圈=最先用的那件，内圈=最后用的那件。
 * actionPlacements 是有序数组 [{kind, idx}]，只在三个"放置动作"的语义点上追加，
 * 渲染前由 reconcilePlacements() 剪掉失效项，避免去碰十几处路径截断入口。 */
function recordPlacement(kind, idx) {
  if (!actionPlacements.some(e => e.kind === kind && e.idx === idx)) {
    actionPlacements.push({ kind, idx });
 }
}
function removePlacement(kind, idx) {
  actionPlacements = actionPlacements.filter(e => !(e.kind === kind && e.idx === idx));
}
/* 等待步添加后调用：若这一步成了"第一等待步"（=闪避），按放置时刻记录其顺序 */
function afterWaitAdded() {
  const w = firstWaitIndex(playerPath);
  if (w >= 0) recordPlacement('dodge', w);
}
/* 每次渲染前对账：剪掉已失效（下标越界 / 不再是攻击或技能 / 不再是第一等待步）的项，
 * 并补回当前第一等待步（极端情况下如读档后缺失）。 */
function reconcilePlacements() {
  const plan = plannedActionInfo(playerPath, attackIndices, skillIndices);
  const keep = new Set();
  attackIndices.forEach(i => keep.add('a' + i));
  skillIndices.forEach(i => keep.add('s' + i));
  actionPlacements = actionPlacements.filter(e => {
    if (e.kind === 'dodge') return plan.dodgeIndex >= 0 && e.idx === plan.dodgeIndex;
    return keep.has((e.kind === 'attack' ? 'a' : 's') + e.idx);
 });
  if (plan.dodgeIndex >= 0 && !actionPlacements.some(e => e.kind === 'dodge' && e.idx === plan.dodgeIndex)) {
    actionPlacements.push({ kind: 'dodge', idx: plan.dodgeIndex });
 }
}
/* 取某格上"实际存在的动作"列表，并按放置顺序（外→内）排序；未追踪到放置顺序时回退到
 * 闪避→攻击→技能（同时也恰好匹配截图"先闪避→攻击→技能"的默认观感）。 */
function cellActionsAtCell(stepsAtCell, ctx) {
  const res = [];
  for (const i of stepsAtCell) {
    if (ctx.isSkillStep(i)) res.push({ kind: 'skill', idx: i });
    if (ctx.isAttackStep(i)) res.push({ kind: 'attack', idx: i });
 }
  if (ctx.dodgeIdx >= 0 && stepsAtCell.includes(ctx.dodgeIdx)) res.push({ kind: 'dodge', idx: ctx.dodgeIdx });
  const posOf = (e) => {
    const p = actionPlacements.findIndex(x => x.kind === e.kind && x.idx === e.idx);
    return p < 0 ? 999 : p;
 };
  const kindOrd = { dodge: 0, attack: 1, skill: 2 };
  res.sort((a, b) => {
    const pa = posOf(a), pb = posOf(b);
    if (pa !== pb) return pa - pb;
    return kindOrd[a.kind] - kindOrd[b.kind];
 });
  return res;
}
/* 同格动作标记：0/1 件沿用旧角标；≥2 件画同心方框（外圈先放、内圈后放、等线宽、按类型配色）。 */
function cellActionHtml(stepsAtCell, x, y, ctx) {
  if (!stepsAtCell || stepsAtCell.length === 0) return '';
  const acts = cellActionsAtCell(stepsAtCell, ctx);
  if (acts.length <= 1) {
    /* 单件（或无动作）：沿用旧 cell-mark 角标，保持既有观感、不扩大回归面 */
    const lastIdx = stepsAtCell[stepsAtCell.length - 1];
    const atkIdx = stepsAtCell.find(ctx.isAttackStep);
    const sklIdx = stepsAtCell.find(ctx.isSkillStep);
    let text = '';
    if (sklIdx !== undefined) text = ctx.nodeReady ? '✦' : '✧';
    else if (atkIdx !== undefined) text = iconify('🎯');
    else if (ctx.dodgeIdx >= 0 && stepsAtCell.includes(ctx.dodgeIdx)) text = iconify('💫');
    else if (stepsAtCell.length > 1) text = stepWaitMarkHtml(lastIdx);
    else if (lastIdx > 0) text = `${lastIdx}`;
    if (!text) return '';
    return `<span class="cell-mark"${stackSlotStyleAttr('player', x, y)}>${text}</span>`;
 }
  /* 多件：同心方框，从外到内 = acts 顺序（先放→外） */
  const n = acts.length;
  const frames = acts.map((a, k) => {
    const sizePct = (n - k) / (n + 1) * 100;
    return `<i class="af af-${a.kind}" style="width:${sizePct}%;height:${sizePct}%"></i>`;
 }).join('');
  return `<span class="act-frames"${stackSlotStyleAttr('player', x, y)}>${frames}</span>`;
}

/* ★ ISSUE-20261029-46：联机房间地图里房间码的起始列。
 * 人类口径「最底下一行，从 (0,3) 到 (0,7)」→ 人类 y=0 是最底一行 → **代码 y = 10 − 0 = ROWS-1**，
 * x 不受上下翻转影响。5 位时 x = 3..7，与人类口径逐格对齐。
 * ★ DEBUG-20261030-02：这里原本是常量 3，隐含「房间码恒 5 位」的假设。
 *   现在按实际位数居中算，**服务端给几位就画几位**：画歪还能凑合，画少一位
 *   等于让对手抄一个不存在的房间号（实测直接 404「房间不存在或已回收」）。 */
function onlineCodeX0() {
  const n = (typeof onlineRoomCode === 'string') ? onlineRoomCode.length : 0;
  return Math.floor((COLS - n) / 2);
}

function buildBoardHtml() {
  let html = '';
  const bbox = getBoundingBox();
  const m = phase === PHASE.CHAR_SELECT ? selMap : map;
  /* 攻击节点 / 技能节点 / 闪避节点 / 攻击范围（只在规划阶段生效） */
  const isAttackStep = (idx) => attackIndices.includes(idx);
  const isSkillStep = (idx) => skillIndices.includes(idx);
  const rangeSet = (phase === PHASE.PLANNING && showRangeOverlay) ? playerAttackRangeCells() : null;
  const planInfo = (phase === PHASE.PLANNING) ? plannedActionInfo(playerPath, attackIndices, skillIndices) : null;
  const dodgeIdx = planInfo ? planInfo.dodgeIndex : -1;
  const nodeReady = (phase === PHASE.PLANNING) ? skillReadyInfo(playerPath).ready : false;
  /* ★ ISSUE-20261030-74：渲染前对账"放置顺序"记录，剪掉失效项 */
  if (phase === PHASE.PLANNING) reconcilePlacements();
  for (let y = bbox.minY; y <= bbox.maxY; y++) {
    for (let x = bbox.minX; x <= bbox.maxX; x++) {
      let cls = 'cell';
      let content = '';
      let dirHtml = '';
      if (m[y][x] === 1) {
        const hw = DIR4.some(([dx,dy]) => isWalkable(x+dx, y+dy));
        if (hw) cls += ' wall'; else cls += ' void';
        /* ISSUE-20261028-10-B：粗圆岩标记在 roughRocks 里，渲染成石头而不是灰墙。
         * 它在 map 里同样是 1，所以寻路 / 视线 / 站位全部自动当墙处理。 */
        if (phase !== PHASE.CHAR_SELECT && roughRocks.has(key(x, y))) {
          cls += ' rock';
          /* ⚠️ 别换回 🪨：那是 Emoji 13.0（2020），本机 Chrome 的 Segoe UI Emoji 没有这个字形，
           * 实测渲染成豆腐块「□」—— 截图上就是两个褐色格子中间一个空方框。
           * ⛰️ 是 Emoji 1.0，和骷髅/幽灵同代，同一字体栈下必然可显示。
           * （同类坑见 ISSUE-19 的 🪖 → 💂。） */
          content = iconify('⛰️');
 }
 } else cls += ' empty';
      if (rangeSet && rangeSet.has(key(x, y))) cls += ' in-range';
      /* ★ ISSUE-20261031-126：事件关只画「地形 + 出口 + ❓」。
       * 战斗层的东西（路径节点 / 攻击范围 / 敌人意图 / 奖励格 / 石头）在事件相位里语义上不存在 ——
       * 进关时已把 playerPath / enemies / rewardItems 清空，这里再显式分一支，
       * 免得以后有人在 else 分支加东西时不小心把战斗渲染漏进房间。 */
      if (phase === PHASE.EVENT) {
        if (m[y][x] !== 1) cls += ' event-floor';
        if (eventExit.x === x && eventExit.y === y) {
          /* 锁态纯靠 CSS 表现（暗 + 灰度 + 虚线框），不额外加 🔒 图标 ——
           * 图标系统里没有登记锁，加一个要动五件套（symbol / ICON_SVG / ICON_CHAR /
           * EMOJI_TO_ICON / 手写正则），为一个状态角标不值得。 */
          cls += ' event-exit open';
          content = iconify('🚪');
        } else {
          const eo = eventObjects.find(o => o.x === x && o.y === y);
          if (eo) { cls += eo.used ? ' event-obj used' : ' event-obj'; content = iconify('❓'); }
        }
      } else if (phase === PHASE.CHAR_SELECT) {
        /* ★ ISSUE-20261029-46：联机地图（大厅 / 房间）里 🚪 是「返回选角厅」，
         *   且不再画 🌐 入口（已经在联机里了）；房间地图额外在**底行**渲染五位房间码。
         *   坐标：房间码 = 代码 y = ROWS-1（人类最底一行 y=0），x = 3..7，一格一位。 */
        /* ★ ISSUE-20261031-94（v2）：正式入口 🚪 **永远可见**。
         * 人类 2026-10-31 拍板：「没有进教程也可以直接点 🚪 开始游戏」——
         * 上一版「没上完课就整格不渲染」的强制策略已整体拆除，教程退回成可选入口。 */
        if (selExit.x === x && selExit.y === y) { cls += ' exit-cell'; content = iconify('🚪'); }
        /* ★ ISSUE-20261031-94（v2）：教程入口是一个 **(4,7)~(6,9) 的 3×3 区域**，
         *   但只画**中心格**一个节点 —— 9 格各画一个 🎓 会变成「九宫格贴纸」，
         *   靠中心格 overflow:visible + 绝对定位覆盖层才画得出一块连续的 3×3 面板
         *   （CSS 见 .cell.tut-core）。另外 8 格保持普通地面，被覆盖层盖住。 */
        if (!onlineStage && selTutExit.x === x && selTutExit.y === y) {
          cls += ' tut-cell tut-core';
          content = `<span class="tut-big">${iconify('🎓')}</span>`;
 }        if (!onlineStage && selOnlineExit.x === x && selOnlineExit.y === y) {
          cls += ' online-cell'; content = iconify('🌐');
 }
        if (onlineRoomCode && y === ROWS - 1) {
          const ci = x - onlineCodeX0();
          if (ci >= 0 && ci < onlineRoomCode.length) { cls += ' code-cell'; content = onlineRoomCode[ci]; }
 }
        /* 角色不再画进格子里（ISSUE-20261028-12）：位置是连续的，
         * 由 unitLayer 里的 .cand-unit 绝对定位渲染，这里只画地形。 */
 } else {
        const stepsAtCell = [];
        playerPath.forEach((p, idx) => { if (p.x === x && p.y === y) stepsAtCell.push(idx); });
        if (stepsAtCell.length > 0) {
          cls += ' path';
          const hasAttack = stepsAtCell.some(isAttackStep);
          const hasSkill = stepsAtCell.some(isSkillStep);
          if (hasAttack) cls += ' attack';
          if (hasSkill) cls += ' skill';
          /* 攻击节点的「已用」要按攻击次数上限判，不是动作预算（ISSUE-20261029-25：2 动作但 1 攻击） */
          if (playerAttacksDone >= maxAttacksThisTurn()) cls += ' used';
          /* 闪避节点：第一次等待 → 蓝色标记 */
          if (dodgeIdx >= 0 && stepsAtCell.includes(dodgeIdx)) cls += ' dodge';
          /* ISSUE-20261029-41：朝向箭头（起点格不画 —— 单位自身的朝向指示已经够了）。
           * 取该格**最小**步号：等待步会返回同一格里重复的下标，facingAt 内部已跳过等待步，
           * 所以「落地格 + 之后的等待」得到的是同一个方向。终点格 = 进入方向。 */
          const dirIdx = stepsAtCell[0];
          if (dirIdx > 0) {
            const f = facingAt(playerPath, dirIdx, null);
            if (f.dx || f.dy) {
              const dCls = f.dy < 0 ? 'u' : f.dy > 0 ? 'd' : f.dx > 0 ? 'r' : 'l';
              dirHtml = `<i class="cell-dir ${dCls}"></i>`;
 }
 }
 }
        const playerHere = player.alive && player.x === x && player.y === y;
        const enemyHere = enemies.find(e => e.alive && e.x === x && e.y === y);
        const bloodHere = bloodDrops.some(b => b.x === x && b.y === y);
        /* ★ ISSUE-20261031-118：骨头独立于血迹（骷髅的被动资源，只有骷髅捡）。
         * 底色和血迹同一个道理 —— 必须先于单位判断加上，否则「骷髅站在自己的骨头上」
         * 会完全没有提示，等它走开才突然冒出来。 */
        const boneHere = (typeof boneDrops !== 'undefined' && boneDrops)
          ? boneDrops.some(b => b.x === x && b.y === y) : false;
        /* ★ ISSUE-20261029-29：血迹的底色**必须先于单位判断**加上。
         * 旧写法把 blood-cell 放在「格子空着」的分支里，结果是：敌人踩在自己流的血上时
         * 整格一点提示都没有，等它走开、另一个敌人路过，那格才突然冒出 🩸
         * —— 玩家看到的就是「血迹显示在另一个敌人的位置」。
         * 现在血迹格永远带底色（单位站上去只是盖住图标，底色照旧），
         * 「血是谁流的」一眼可辨，拾取点也不会因为敌人走位而错位。 */
        if (bloodHere) cls += ' blood-cell';
        if (boneHere) cls += ' bone-cell';
        if (playerHere) {
          /* ★ ISSUE-20261030-56：原来这里是「if (playerHere || enemyHere) 就什么都不画」，
           * 只要有单位站上去，✦ / 🎯 / 💨 / ⏳n 整段不画，同格时更是完全分不清
           * 「这一步是攻击还是等待」。现在改成把标记画进**玩家自己那条斜带**（见 cellActionHtml），
           * z-index 41 高于 #unitLayer(40)，不会被图标盖住。
           * ★ ISSUE-20261030-74：同格多动作改画同心方框（cellActionHtml 内部分流）。
           * 敌人独占的格子保持原样不画（路径标记是玩家的，画在敌人头上反而误导）。 */
          content = cellActionHtml(stepsAtCell, x, y, { isAttackStep: isAttackStep, isSkillStep: isSkillStep, dodgeIdx: dodgeIdx, nodeReady: nodeReady });
 } else if (enemyHere) {
          /* 敌人独占：维持原行为，节点靠底色 + 描边提示 */
 } else if (rewardItems.some(r => r.x === x && r.y === y)) {
          /* ★ ISSUE-20261031-120：道具格现在有两种 —— ❤️ 回 3、🍌 回 1（猴子撒的）。
           * 以前写死 `iconify('❤️')`，加进来 🍌 之后必须按 `type` 分流，
           * 否则地图上会出现「长得像爱心、捡起来只回 1 血」的怪东西。
           * ⚠️ 旧数据（事件关生成器给的爱心）**没有 type 字段** → 一律按 ❤️ 读。 */
          const _it = rewardItems.find(r => r.x === x && r.y === y);
          const _isBanana = !!_it && _it.type === 'banana';
          cls += _isBanana ? ' item-cell banana-cell' : ' item-cell';
          content = `<span class="item-pulse" style="font-size:calc(var(--cell)*0.5);">${iconify(_isBanana ? '🍌' : '❤️')}</span>`;
 } else if (bloodHere) {
          content = `<span class="item-pulse" style="font-size:calc(var(--cell)*0.5);">${iconify('🩸')}</span>`;
 } else if (boneHere) {
          /* ISSUE-20261031-118：骨头画法照抄血迹（同一套 item-pulse 脉动壳，不新造样式） */
          content = `<span class="item-pulse" style="font-size:calc(var(--cell)*0.5);">${iconify('🦴')}</span>`;
 } else if (stepsAtCell.length > 0) {
          content = cellActionHtml(stepsAtCell, x, y, { isAttackStep: isAttackStep, isSkillStep: isSkillStep, dodgeIdx: dodgeIdx, nodeReady: nodeReady });
 }
 }
      html += `<div class="${cls}" data-x="${x}" data-y="${y}">${content}${dirHtml}</div>`;
 }
 }
  return html;
}

/* =========================================================================
 * 角色信息面板 —— 全屏唯一的「一份 HTML」
 *
 * ISSUE-20261029-38（人类 15:41 / 15:52）：两块重复面板合并成一块。
 *   · 位置 = 「开始行动」按钮正上方（.action-wrap > .hud，#hud）；
 *   · 外观逐项照抄原侧栏 #hero 卡；旧 .hud-line/.hud-* 那套半透明黑底作废；
 *   · 侧栏 #hero 整块删除；SP 条下整排胶囊（技力数值 / 闪避 / 技能节点 / 护盾 /
 *     小队 / buff 药丸 …）按人类 15:52 拍板**一个都不留**。
 *
 * ISSUE-20261029-42：角色面板（♟️ #drawerChar）顶部要「和操作界面一样的 UI」——
 *   直接吃这里的 heroInnerHtml()，**不允许再写第二套标记**。
 *   想改面板长相只改这一个函数，两个调用点自动跟着变。
 * ========================================================================= */
function hpStateClass(hp, maxHp) {
  const r = maxHp > 0 ? hp / maxHp : 0;
  if (r <= 0.3) return 'danger';
  if (r <= 0.6) return 'warn';
  return '';
}

/* 面板 HTML（纯函数：只吃 opt 与相位，不吃别的 UI 状态） */
function heroInnerHtml(opt) {
  const maxHp = opt.maxHp || 0;
  const pct = maxHp > 0 ? Math.max(0, Math.min(100, (opt.hp / maxHp) * 100)) : 0;
  const hpText = opt.hpText || (maxHp > 0 ? `${Math.max(0, opt.hp)} / ${maxHp}` : '—');
  const shieldN = opt.shield || 0;
  const shieldBar = shieldN > 0
    ? `<div class="hp-shield" style="width:${Math.min(100, shieldN * 12)}%" title="护盾 ${shieldN} 层"></div>`
    : '';
  const hpBar = maxHp > 0
    ? `<div class="hp-track ${hpStateClass(opt.hp, maxHp)}"><div class="hp-fill-lg" style="width:${pct}%"></div>${shieldBar}<span class="hp-text"><i class="bar-lbl">HP</i>${hpText}</span></div>`
    : '';
  /* ★ ISSUE-20261101-151（人类 19:40「删掉技力条」）：spBar 整块删除。
     技力不再用「一条百分比横条」表达 —— 它改由行动 UI 的技能键（.act-key.skill 上的
     .ak-sp 等分块，格数 = spMax）承担。数据源不变（vpadSpInfo() 仍是唯一出口），
     只是换了显示位置与形态：状态格回归「名字 / HP / 经验」三样，不再挤技力。
     ⚠️ opt.sp 仍由 heroCardOpt() 等调用方提供，不要顺手删 —— 技能键要用它。 */
  /* ★ ISSUE-20261031-110（人类 14:5x）：**教程关是独立模式 —— 没有遗物、没有升级、没有经验**。
   * 上一版虽然已经拦住了「结算」本身（onLevelClear 早退、currency 钩子归零），
   * 但 HUD 还在照常画 Lv.1 / 金币 0 / 经验条 0%，玩家看到的是「我在玩正式局，只是没长进」。
   * 表现层必须一起摘干净，否则「另一个游戏方式」只写在注释里。
   * 判据用 tutorialIsOn()（教程态唯一真相），不要在渲染层另算条件。 */
  const tutMode = (typeof tutorialIsOn === 'function') && tutorialIsOn();
  const lvBadge = (phase === PHASE.CHAR_SELECT || tutMode)
    ? ''
    : `<span class="hero-lv-gold" title="等级">Lv.${heroLevel || 1}</span>`;
  /* ★ ISSUE-20261030-80：金币单元，钉在窗口顶部右上角（绝对定位，不吃 flex 排版）。
   * 选角相位不显示 —— 那时还没开局，货币一定是 0，摆一个「0」只会让人以为漏掉了什么。
   * 数值由 currency（src/rules/currency.js）提供；变动时的局部刷新走 syncCurrencyUI()，
   * 不要在这里读别的状态凑数。 */
  const coinChip = (phase === PHASE.CHAR_SELECT || tutMode)
    ? ''
    : `<span class="hero-coin" data-debug-name="hud-coin" title="${CURRENCY_NAME}：击杀与通关获得，可在关卡事件（落单商人 / 古老装置）里消费"><span class="coin-ico">${iconify(CURRENCY_ICON)}</span><b class="coin-num">${currency}</b></span>`;
  /* 经验条（ISSUE-20261028-10 引入；ISSUE-20261101-151 改位置）：
     方形细条，**厚度不变（4px）**，但改为「长度与 HP 一致 + 紧贴 HP 正下方」
     —— 人类 19:40 原话「经验宽度不变,长度和HP一样贴在HP下方」。
     横向满格由 CSS 的 grid-area 承担（#stats 行 3 全宽），这里只负责填充比例。 */
  let xpBar = '';
  if (phase !== PHASE.CHAR_SELECT && !tutMode) {
    const xpNeed = xpThresholdForLevel(heroLevel || 1);
    const xpPct = xpNeed > 0 ? Math.max(0, Math.min(100, (xp / xpNeed) * 100)) : 0;
    xpBar = `<div class="xp-track" title="经验 ${xp}/${xpNeed}（升到 Lv.${(heroLevel || 1) + 1}）"><div class="xp-fill" style="width:${xpPct}%"></div></div>`;
  }
  /* 顺序 = 视觉上下：名称 → HP → 经验。技力条已删（ISSUE-151），别再往这里加第三条。 */
  return `
    <div class="hero-top">
      <span class="hero-name">${opt.name}</span>${lvBadge}
      <span class="hero-lv">${opt.tag || ''}</span>${coinChip}
    </div>
    ${hpBar}
    ${xpBar}
  `;
}

/* 选角相位的数据源（未选角色时也给一份占位，面板不会空着） */
function heroOptCharSelect() {
  if (!selectedCandidate) return { name: '选择角色', tag: '', hp: 0, maxHp: 0, hpText: '—' };
  const char = CHARACTERS[selectedCandidate.id] || null;
  /* ISSUE-20261028-19：动态角色读「候选副本」（加点后立刻反映），静态角色仍读常量对象 */
  const a = candidateAbilitiesOf(selectedCandidate.id);
  const selRanged = isRangedCharOf(selectedCandidate.id, a);
  /* 选角阶段预览技力槽：泥岩/风笛/华法琳 5、阿米娅上限 = 感知、预备干员 = ROOKIE_SP_MAX，其余角色无技力机制。
   * ★ ISSUE-20261031-51：人类要求选角界面 SP 直接显示「满状态」——预览即满槽（cur = max），用每个角色真实的技力上限。 */
  let spMax = 0;
  if (selectedCandidate.id === 'amiya') spMax = Math.max(1, a.wis);
  else if (selectedCandidate.id === 'rookie') spMax = ROOKIE_SP_MAX;
  else if (selectedCandidate.id === 'fencer') spMax = FENCER_SP_MAX;
  else if (selectedCandidate.id === 'wheelchair') spMax = WHEELCHAIR_SP_MAX;
  else if (selectedCandidate.id === 'vampire') spMax = VAMPIRE_SP_MAX;
  const spPreview = spMax > 0 ? { cur: spMax, max: spMax } : null;
  const hp = a.con + BASE_HP_BONUS;
  return {
    name: `${char ? char.name : '?'} ${char ? iconify(char.icon) : ''}`,
    /* 预备干员把「熟练 / 攻击方式」直接写在 tag 上：加点会实时翻转，玩家不用自己推 */
    tag: charIsDynamic(selectedCandidate.id)
      ? (selRanged ? '待选择 · 远程熟练' : '待选择 · 近战熟练')
      : '待选择',
    hp: hp, maxHp: hp, sp: spPreview,
 };
}

/* 对局相位的数据源 */
function heroOptBattle() {
  if (!player) return null;
  const charInfo = CHARACTERS[selectedChar] || null;
  /* 技力槽：泥岩固定上限 5；阿米娅上限 = 感知；风笛上限 5（沿直线移动积累，规划时预览增量）；华法琳上限 5（捡血迹） */
  let spInfo = null;
  /* ★ ISSUE-20261031-117 方案 B（人类 16:28「联机模式风笛每回合技力清空」等三条反馈）：
   * 联机（src/net/pvp-core.js）**根本没有角色的技力 / 被动系统** —— 结算里只有移动、攻击、闪避、相杀。
   * 照旧画槽会出现：风笛规划时涨、交计划后掉回 0（`playerPath` 重置）；
   * 泥岩/华法琳则永远是 0（`gainFencerSp` / `addBloodAt` 只挂在 PvE 的 enemyTurn 与攻击结算里）。
   * 那不是数值 bug，是「UI 在演示一个不存在的机制」。所以联机一律不画技力槽，
   * 改由 pvpStartMatch() 开一句日志说明；真接技力是方案 A，另立 issue。 */
  if (mode !== 'pvp') {
    if (selectedChar === 'fencer') spInfo = { cur: fencerSp, max: FENCER_SP_MAX };
    else if (selectedChar === 'amiya') spInfo = { cur: amiyaBonusTargets, max: amiyaSpMax() };
    else if (selectedChar === 'wheelchair') spInfo = { cur: wheelchairPreviewSp(), max: WHEELCHAIR_SP_MAX };
    else if (selectedChar === 'vampire') spInfo = { cur: vampireSp, max: VAMPIRE_SP_MAX };
    else if (selectedChar === 'rookie') spInfo = { cur: rookieSp, max: ROOKIE_SP_MAX };
  }
  return {
    name: `${charInfo ? charInfo.name : '未知'} ${charInfo ? iconify(charInfo.icon) : ''}`,
    /* ★ ISSUE-20261031-110（人类 14:5x「教程关本质是另一个游戏方式」）：教程里没有「第几关」，
     * 它是独立模式，不是局内进度 —— 写「第 1 关」会让玩家以为教程算进了正式局。 */
    tag: `${(typeof tutorialIsOn === 'function' && tutorialIsOn()) ? '教程 · 练习' : `第 ${level} 关`} · AC ${playerEffectiveAC()}${playerDodging ? ` (+${playerDodgeACBonus})` : ''}`,
    hp: player.hp, maxHp: player.maxHp,
    shield: playerShield,
    sp: spInfo,
 };
}

/* ★ ISSUE-20261031-126：事件关的面板数据。
 * 与 heroOptBattle 的差别（人类拍板：隐藏战斗三件套与技力槽，保留角色面板 / 金币 / 关卡徽章）：
 *   · `sp: null` → 不画技力槽（事件关没有技力这回事）
 *   · `shield: 0` → 不画护盾条（进关时已清零）
 *   · `tag` 写「第 N 关 · 事件」—— N 是**总关卡数**（含事件关），与 HUD 徽章同源。
 * 为什么不复用 heroOptBattle：那个函数会读技力 / 闪避 / 行动次数，在事件相位里全是无意义的值
 * （比如闪避加成会残留上一回合的），画出来就是「演示一个不存在的状态」。 */
function heroOptEvent() {
  if (!player) return null;
  const charInfo = CHARACTERS[selectedChar] || null;
  return {
    name: `${charInfo ? charInfo.name : '未知'} ${charInfo ? iconify(charInfo.icon) : ''}`,
    tag: `第 ${level} 关 · 事件`,
    hp: player.hp, maxHp: player.maxHp,
    shield: 0,
    sp: null,
 };
}

/** 当前相位的面板数据 */
function heroCardOpt() {
  if (phase === PHASE.CHAR_SELECT) return heroOptCharSelect();
  if (phase === PHASE.EVENT) return heroOptEvent();
  return heroOptBattle();
}

/* 唯一写入点：#hud（行动按钮正上方）+ #charTop（角色面板顶部，ISSUE-20261029-42）。
 * 两处内容完全同源 —— 这就是「面板 HTML 只留一份」的落点。 */
function renderHeroCard(opt) {
  let html = '';
  if (opt === undefined) {
    const o = heroCardOpt();
    html = o ? heroInnerHtml(o) : '';
 } else if (opt) {
    html = heroInnerHtml(opt);
 }
  /* ★ ISSUE-20261101-144：角色数值不再挂在「行动按钮上方那张卡片」—— 宿主就是状态格 #stats。
     仍然是同一份 heroInnerHtml（全屏只有一份角色信息标记），只是换了挂载点；
     3 行的分工由 CSS 的 grid-area 决定，JS 这边不需要知道哪块排第几行。 */
  const host = document.getElementById('stats');
  if (host) host.innerHTML = html;
  const top = document.getElementById('charTop');
  if (top) top.innerHTML = html;
}

/* ★ ISSUE-20261101-144：信息格（11×3）的唯一写入口。
 * 行 1 = 当前关卡（取自 heroCardOpt().tag，与 HUD 徽章同源，别算第二遍）；
 * 行 2–3 = 一句场景提示。战斗日志按人类 16:0x 拍板移回设置抽屉，不进这里
 * （信息格只有 3 行，被日志吃掉就装不下关卡了）。
 * `tip === undefined` 时按当前相位自动取提示；传 '' 表示「这次只要关卡标题」。 */
function phaseInfoTip() {
  if (phase === PHASE.CHAR_SELECT) {
    return selectedCandidate ? '' : '点击地图上的角色，然后移动至 🚪 出口。六维图中绿色 = 熟练项与最高属性。';
  }
  if (phase === PHASE.EVENT) return '自由走动 · 走到 ❓ 触发事件，或直接走向对面的 🚪 离开。';
  if (phase === PHASE.LEVELCLEAR) return '关卡通过，选择奖励后进入下一关。';
  if (phase === PHASE.GAMEOVER) return '本局结束。';
  /* ★ ISSUE-20261101-152：判据原来是「虚拟底栏是否挂载」，底栏删除后改成「是否触屏」——
     手机没有方向键了，这条「点棋盘移动」的提示反而更该留着；桌面上鼠标一贯可用，不必占格。 */
  if (phase === PHASE.PLANNING && isCoarsePointer()) {
    return '点棋盘移动 · 点路径节点 = 攻击 · 技能与等待用操作格三键';
  }
  return '';
}

function renderInfoGrid(tip) {
  if (!infoEl) return;
  let title = '';
  try {
    const o = (typeof heroCardOpt === 'function') ? heroCardOpt() : null;
    title = (o && o.tag) ? String(o.tag) : '';
  } catch (_) {}
  const body = (tip === undefined) ? phaseInfoTip() : (tip == null ? '' : String(tip));
  if (!title && !body) { infoEl.innerHTML = ''; return; }
  infoEl.innerHTML =
    (title ? '<div class="info-title">' + title + '</div>' : '') +
    (body ? '<div class="info-tip">' + body + '</div>' : '');
}

/* 技能说明列表：「技力/技能/被动/」前缀和「[技能名]」上色，其余保持普通文本 */
function renderTips(tips) {
  const labelRe = /^(\[[^\]]{1,14}\]|[^：:]{1,4})[：:]\s*/;
  return (tips || []).map(t => {
    const s = String(t);
    const m = s.match(labelRe);
    if (!m) return `<li>${s}</li>`;
    const key = m[1];
    const rest = s.slice(m[0].length);
    const cls = key.startsWith('[') ? 'tip-k skill' : 'tip-k';
    return `<li><span class="${cls}">${key}：</span>${rest}</li>`;
 }).join('');
}

/* 点仪表格已废弃（ISSUE-20261028-09 E）。本函数保留为「主动行动」的唯一出口：
 *   手机圆钮 → wait / attack / skill；键盘 V 与手机长按攻击钮 → range。
 * 不允许再新增第二套语义（同一函数出口是这条 UI 重构的硬要求）。 */
function handleKvAction(action) {
  if (phase !== PHASE.PLANNING || isMoving || !player) return;
  if (action === 'wait') {
    if (countWaitSteps(playerPath) >= player.move) { log('等待次数已用完（等待上限 = 移动力）。'); return; }
    /* ★ ISSUE-20261029-34：等待步 = 闪避动作，第一个等待步要占 1 件动作预算。
     * 旧版这里直接 push，完全不查预算 → 「攻击 + 技能 + 闪避」三件能被规划出来。 */
    const gate = canAddWaitStep(playerPath, attackIndices, skillIndices);
    if (!gate.ok) { log(`⚠️ ${gate.reason}`); return; }
    const last = playerPath.length ? playerPath[playerPath.length - 1] : { x: player.x, y: player.y };
    playerPath.push({ x: last.x, y: last.y });
    afterWaitAdded();
    refreshBoardOnly();
 } else if (action === 'attack') {
    if (playerPath.length === 0) return;
    toggleAttack(playerPath.length - 1);
    refreshBoardOnly();
 } else if (action === 'skill') {
    /* ★ ISSUE-20261029-34：起点（原地）也能放技能节点了 —— 只剩起点时按 R 就是「原地施法」。 */
    if (playerPath.length < 1) { log('先在棋盘上规划路径，再在路径节点上设置技能节点。'); return; }
    toggleSkill(playerPath.length - 1);
    refreshBoardOnly();
 } else if (action === 'reset') {
    /* ★ ISSUE-20261029-36：虚拟按钮「重置路径」键（攻击键上方）—— 与键盘 X 等价。 */
    if (playerPath.length > 1 || attackIndices.length > 0 || skillIndices.length > 0) {
      playerPath = [{ x: player.x, y: player.y }];
      attackIndices = [];
      skillIndices = [];
      refreshBoardOnly();
 }
 } else if (action === 'range') {
    showRangeOverlay = !showRangeOverlay;
    log(showRangeOverlay ? '📐 显示攻击范围（蓝色地块）。' : '关闭攻击范围显示。');
    refreshBoardOnly();
 }
}

/* 方向移动的唯一出口：键盘 WASD 与手机方向钮都走这里（避免两套寻路逻辑打架） */
function stepPathByDir(k) {
  if (!player || phase !== PHASE.PLANNING) return;
  const dir = KEY_DIRS[k];
  if (!dir) return;
  const last = playerPath.length ? playerPath[playerPath.length - 1] : { x: player.x, y: player.y };
  const nx = last.x + dir.dx, ny = last.y + dir.dy;
  const idx = findLastIndex(playerPath, p => p.x === nx && p.y === ny);
  if (idx >= 0) {
    if (idx === 0 && playerPath.length > 1) return;
    if (idx < playerPath.length - 1) {
      playerPath = playerPath.slice(0, idx + 1);
      attackIndices = attackIndices.filter(i => i < playerPath.length);
      skillIndices = skillIndices.filter(i => i < playerPath.length);
      refreshBoardOnly();
 }
    return;
 }
  if (countMoveSteps(playerPath) < player.move && isWalkable(nx, ny) && !(nx === player.x && ny === player.y)) {
    playerPath.push({ x: nx, y: ny });
    refreshBoardOnly();
 }
}

/* 选角阶段的侧栏：只剩「行为提示 + 未分配点数」。
 * 角色信息本体已并入共用面板（heroInnerHtml），这里不再各画一套（ISSUE-20261029-38）。 */
function renderCharSelectStats() {
  renderHeroCard();
  /* ★ ISSUE-20261101-144：选角提示不再塞进 #stats（那是状态格，放数值的），改走信息格。
     以前两个都写 #stats，靠「后写覆盖」维持，一旦渲染顺序变了就互相冲掉。 */
  if (!selectedCandidate) {
    renderInfoGrid('点击地图上的角色，然后移动至 🚪 出口。六维图中绿色 = 熟练项与最高属性。');
    return;
  }
  /* ISSUE-20261028-19：动态角色在选角阶段显示剩余点数（没加完也能直接出门，点数带进第 1 关） */
  const ptsLeft = candidatePointsLeft();
  const ptsLine = (charIsDynamic(selectedCandidate.id) && ptsLeft > 0)
    ? `剩余 ${ptsLeft} 点属性未分配 · 点六维图上的属性名加点`
    : '';
  /* ★ ISSUE-20261029-29（人类 04:16 / 04:42）：原先这里还挂着一张「技能说明」卡片
   * （char.desc + tips 列表）。现在技能说明改由棋盘上那块 #charInfoSheet 展开层承担
   * ——「点击角色之后，角色这一行以上的部分展开角色技能说明文字，可以滚轮滑动查看，
   * 删掉之前的技能说明面板」。侧栏只留点数提醒，避免同一份文字两处各写一遍。 */
  renderInfoGrid(ptsLine);
}

function updateStats() {
  drawRadar();
  if (phase === PHASE.CHAR_SELECT) {
    renderCharSelectStats();
    return;
 }

  /* ---------- 对局中 ---------- */
  if (!player) return;
  if (player.hp > 0 && player.alive) playerStats.currentHp = player.hp;
  const isRanged = playerIsRanged();   /* ISSUE-20261028-19：动态角色按六维现算，别读静态表 */

  /* ★ ISSUE-20261029-38：角色信息全屏只有一份（heroInnerHtml），renderHeroCard() 同时写
   * #hud（行动按钮正上方）与角色面板顶部 #charTop。
   * SP 条下那排徽章按人类 15:52 拍板**整排删除**（技力数值 / 闪避中 / 闪避节点 /
   * 技力满提示 / 护盾 / 小队 / 技能节点 / 动作超限 / 技能未就绪 / buff 药丸 全不留）：
   *   · buff 改在 ♟️ 角色面板右下角常驻显示（ISSUE-20261029-42）；
   *   · 动作计数与节点提示由「开始行动」按钮文案承担（buildActionLabel）；
   *   · 护盾在血条右侧还有一道白条（.hp-shield）。 */
  renderHeroCard();

  /* ★ ISSUE-20261101-144：信息格显示当前关卡（行 1）+ 场景提示（行 2–3）。
     人类 15:48「信息单元格:简单的文字信息，当前关卡之类的」。
     战斗日志按 16:0x 拍板移回设置抽屉，主面板不再有 .log-mini。
     ISSUE-20261031-97 删掉的「回合 / 敌人 / 阶段 / 格」那串状态文本不复活。 */
  renderInfoGrid('');
  if (footEl) footEl.innerHTML = '';
  // 角色面板开着时同步六维图与 BUFF 池（ISSUE-152：虚拟圆钮已删，不再有 syncVirtualPad）
  if (typeof drawerIsOpen === 'function' && drawerIsOpen('char')) renderCharPanel();
}

/* ★ ISSUE-20261029-42：角色面板内容。
 *   顶部 #charTop —— 由 renderHeroCard() 写入，和「行动按钮上方 HUD」同一份 HTML；
 *   左下 #charRadarCanvas —— 六维图，点属性名直接加点（drawRadar 记 charRadarLabelHits）；
 *   右下 #charRelics —— 升级获得的 BUFF 奖励池（33 号之前它是 #stats 里的胶囊，已被 38 号删掉）。
 * 选角相位显示当前候选角色，对局中显示当前玩家：两者都由 heroCardOpt() 统一给出。 */
function renderCharPanel() {
  renderHeroCard();
  const canvas = document.getElementById('charRadarCanvas');
  if (canvas) {
    /* 不传 forceAbilities → canAlloc 按 phase 自动判定，六维顶点金框 = 可加点 */
    try { drawRadar(canvas); } catch (_) {}
 }
  const hint = document.getElementById('charAllocHint');
  if (hint) {
    /* ★ 选角相位时 playerStats 还没建好，必须用 pointsLeftNow()（已分相位），
     * 否则预备干员在大厅那 5 点「剩余 N 点」提示永远为空、雷达也点不动。 */
    const pts = pointsLeftNow();
    hint.textContent = pts > 0 ? `剩余 ${pts} 点属性 · 点六维图上的属性名加点` : '';
 }
  /* ISSUE-20261030-74 ②：六维图上方 AC / 熟练方框填值 */
  try {
    const acEl = document.getElementById('charAcVal');
    const profEl = document.getElementById('charProfVal');
    let ac = 10;
    if (phase === PHASE.CHAR_SELECT && selectedCandidate) {
      ac = computeAC(candidateAbilitiesOf(selectedCandidate.id));
 } else {
      ac = playerEffectiveAC();
 }
    /* 熟练恒等于 4 + max(0, heroLevel-1)（dnd.js 不变量），直接用 heroLevel 算，
       避免选角相位 playerStats.prof 尚未赋值导致「+undefined」。 */
    const prof = 4 + Math.max(0, (typeof heroLevel === 'number' ? heroLevel : 1) - 1);
    if (acEl) acEl.textContent = ac;
    if (profEl) profEl.textContent = '+' + prof;
    /* ISSUE-20261031-121：六维图上方第三框 = 伤害骰（2d4 / 2d4+n；远程 1d8 / 1d8+n）。
     * 与属性无关，只反映收藏品固定加成（锈蚀刀片 / 战术目镜）。 */
    const dmgEl = document.getElementById('charDmgVal');
    const dmgLblEl = document.getElementById('charDmgLbl');
    if (dmgEl) {
      let ranged;
      if (phase === PHASE.CHAR_SELECT && selectedCandidate) {
        ranged = isRangedCharOf(selectedCandidate.id, candidateAbilitiesOf(selectedCandidate.id));
      } else {
        ranged = playerIsRanged();
      }
      dmgEl.textContent = ranged ? playerRangedDmgLabel() : playerMeleeDmgLabel();
      if (dmgLblEl) dmgLblEl.textContent = ranged ? '远程' : '近战';
    }
  } catch (_) {}
  const box = document.getElementById('charRelics');
  if (box) {
    /* ★ ISSUE-20261030-59：右下格两种状态二选一 ——
     *   charAbilityInfoKey 为空 → 收藏品列表（原行为）；
     *   点过某个属性顶点且当时不可加点 → 该属性的说明卡。 */
    box.innerHTML = charAbilityInfoKey ? charAbilityInfoHtml(charAbilityInfoKey) : charRelicPoolHtml();
 }
}

/* ★ ISSUE-20261030-59：右下格显示「某个属性的说明」（代替收藏品列表）。
 *   文案复用 src/ui/panels.js 的 ABILITY_INFO（属性抽屉被 37 号删掉后它只剩数据，
 *   没理由再抄一份），CSS 也复用当年留下的 .ab-info-* / .ab-back。 */
let charAbilityInfoKey = null;
function charAbilityInfoHtml(k) {
  const info = ABILITY_INFO[k] || { name: String(k || '').toUpperCase(), desc: '' };
  const v = currentAbilityValue(k);
  const capLine = (typeof ABILITY_CAP === 'number') ? ' / 上限 ' + ABILITY_CAP : '';
  return '<div class="char-relics-title">属性</div>'
    + '<div class="ab-info-card">'
    + '<div class="ab-info-head">'
    + '<span class="ab-info-name">' + info.name + '</span>'
    + '<span class="ab-info-val">当前 <b>' + v + '</b><span class="ab-info-cap">' + capLine + '</span></span>'
    + '</div>'
    + '<div class="ab-info-desc">' + info.desc + '</div>'
    + '</div>';
}
/* 右下格状态切换的唯一入口：传 key → 显示该属性说明，传 null → 回收藏品列表。
   ISSUE-20261030-74 ③：人类要求删掉「← 返回收藏品」按钮，改为「再点同一顶点关闭」（toggle），
   所以顶点点击走 toggleCharAbilityInfo()，本函数只做「置值 + 重绘」。 */
function setCharAbilityInfo(k) {
  charAbilityInfoKey = k || null;
  renderCharPanel();
}
/* ISSUE-20261030-74 ③：再点同一个属性顶点 → 关闭说明卡（回收藏品列表） */
function toggleCharAbilityInfo(k) {
  charAbilityInfoKey = (charAbilityInfoKey === k) ? null : k;
  renderCharPanel();
}

/* 右下 BUFF 池：数据源与升级奖励同一个 RELIC_POOL × relics 层数。
 * 一层都没有时给灰色占位（人类 2026-10-29 16:2x 拍板），不留半块空白。 */
function charRelicPoolHtml() {
  /* 教程关是独立模式（ISSUE-110，人类 14:5x）：不进收藏品体系，也就不该显示「暂无收藏品」——
   * 那读起来像「你还没拿到」，实际是「这一模式没有收藏品」。 */
  if (typeof tutorialIsOn === 'function' && tutorialIsOn()) {
    return '<div class="char-relics-title">收藏品</div>'
      + '<div class="char-relics-empty">教程关是独立模式，不提供收藏品（也不结算经验与升级）</div>';
  }
  const owned = RELIC_POOL.filter(b => (relics[b.id] || 0) > 0);
  const head = '<div class="char-relics-title">收藏品</div>';
  if (!owned.length) return head + '<div class="char-relics-empty">暂无收藏品</div>';
  /* ISSUE-20261028-06：图标 + 名称 + 层数 + **描述正文**（不再只放 title 里）。
   * 这是「收藏品栏可查看全部已持有收藏品」这条验收的唯一落点，别把 .ds 删了。 */
  return head + owned.map(b =>
    `<div class="char-relic" title="${b.name}：${b.desc}"><span class="ico">${iconify(b.icon)}</span><span class="nm">${b.name}</span><span class="ct">×${relics[b.id]}</span><span class="ds">${b.desc}</span></div>`
  ).join('');
}

function allocateAbilityPoint(abilityKey) {
  /* ISSUE-20261028-19：选角阶段加的是「候选副本」，不进 playerStats（那时它还不该存在）。
   * 注意这里只放行**动态角色**（预备干员）：前四个角色在选角相位仍然加不了点，行为与之前完全一致。 */
  if (phase === PHASE.CHAR_SELECT) {
    if (!allocateCandidatePoint(abilityKey)) return;
    renderCharSelectStats();      /* 面板数值实时跟手 */
    if (typeof drawerIsOpen === 'function' && drawerIsOpen('char')) renderCharPanel();
    return;
 }
  if (phase !== PHASE.PLANNING && phase !== PHASE.LEVELCLEAR) return;
  if (playerStats.abilityPoints <= 0) return;
  if (playerStats.abilities[abilityKey] >= ABILITY_CAP) return;
  playerStats.abilities[abilityKey] += 1;
  playerStats.abilityPoints -= 1;
  const oldMaxHp = playerStats.maxHp;
  recomputePlayerDerivedStats();
  const diff = playerStats.maxHp - oldMaxHp;
  if (diff > 0) {
    playerStats.currentHp += diff;
    if (player && player.alive) player.hp += diff;
 } else if (diff < 0) {
    playerStats.currentHp = Math.min(playerStats.currentHp, playerStats.maxHp);
    if (player && player.alive) player.hp = Math.min(player.hp, playerStats.maxHp);
 }
  if (player) syncPlayerFromStats();
  /* 升级加点直接在角色面板（♟️）六维图上点：刷新面板 + 全量重绘（下一关按钮随点数归零启用） */
  if (typeof drawerIsOpen === 'function' && drawerIsOpen('char')) renderCharPanel();
  /* 升级加点全部加完 → 自动收起角色面板，放行下一关（ISSUE-20261029-37） */
  if (phase === PHASE.LEVELCLEAR && playerStats.abilityPoints <= 0 && typeof drawerClose === 'function') drawerClose();
  render();
}

/* ★ ISSUE-20261029-36：动作 UI 合并进「开始行动」按钮（框沿用绿色胶囊）。
 * ★ ISSUE-20261030-77（人类 17:20）：**按钮里不再有任何文字**。
 *   `buildActionLabel()` 那套「攻击×1+技能×1 2/2 / 未规划动作」已整块删除，
 *   取而代之的是 .apips 小方块（src/ui/action-pips.js）。
 *   别再把文本加回来 —— 「删掉所有文本」是人类这次的原话。 */

/* =========================================================================
 * ★ ISSUE-20261101-151（人类 19:40）：操作格前两行 = 攻击 / 技能 / 闪避 三个方形键。
 *
 * 尺寸与位置全部由 CSS 的整数 grid-area 决定（攻击 2×2 / 技能 3×2 / 闪避 2×2，
 * 列序 空1·攻击2·空1·技能3·空1·闪避2·空1 = 11）；这里只管「建节点 / 绑交互 / 刷数字」。
 *
 * ★ 语义必须与手机圆钮（src/ui/mobile-pad.js）逐字一致 —— 同一个 handleKvAction 出口：
 *     攻击 = 'attack'（短按）/ 'range'（长按 400ms，切换攻击范围显示）
 *     技能 = 'skill'
 *     闪避 = 'wait'   ← 不是笔误：ISSUE-20261029-34 定「第一个等待步 = 闪避动作」，
 *                        占一件动作预算，棋盘上画青色标记（ACTION_PIP_COLOR.dodge）。
 *                       所以键名叫「闪避」，落到的仍是 wait 这条既有语义。
 * 不许为桌面另立第二套语义（handleKvAction 头注释里的硬要求）。
 *
 * ★ ISSUE-20261101-152：这段注释原来写的是「为什么建在 #controls 里而不是复用手机底栏的圆钮」，
 * 底栏删除后问题消失 —— 全端只有这一套键，方形整数格与棋盘对得上（144 硬规则）。
 * ========================================================================= */
const ACTION_KEY_DEFS = [
  { kind: 'atk',   act: 'attack', label: '攻击', glyph: function () { return iconify('⚔️'); } },
  { kind: 'skill', act: 'skill',  label: '技能', glyph: function () { return '✦'; } },
  { kind: 'dodge', act: 'wait',   label: '闪避', glyph: function () { return hourglassTag(); } },
];

function buildActionKeys(host) {
  if (!host) return;
  host.classList.add('has-keys');
  ACTION_KEY_DEFS.forEach(function (d) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'act-key ' + d.kind;
    b.setAttribute('aria-label', d.label);
    b.setAttribute('title', d.label);
    b.setAttribute('data-debug-name', d.label + '键');
    b.innerHTML = '<span class="ak-ico">' + d.glyph() + '</span>'
                + '<span class="ak-lbl">' + d.label + '</span>'
                + '<span class="ak-num" data-k="' + d.kind + '">—</span>'
                + (d.kind === 'skill' ? '<span class="ak-sp"></span>' : '');
    if (d.kind === 'atk') {
      /* 长按 ≥400ms = 切换攻击范围显示；短按 = 设攻击节点。判据与手机端完全一致。 */
      let timer = null, longFired = false;
      b.addEventListener('pointerdown', function (e) {
        e.preventDefault();
        longFired = false;
        timer = setTimeout(function () { longFired = true; handleKvAction('range'); }, 400);
      });
      const end = function (e) {
        if (timer) { clearTimeout(timer); timer = null; }
        if (!longFired) { if (e && e.preventDefault) e.preventDefault(); handleKvAction('attack'); }
      };
      b.addEventListener('pointerup', end);
      b.addEventListener('pointercancel', function () { if (timer) { clearTimeout(timer); timer = null; } });
    } else {
      b.addEventListener('pointerdown', function (e) { e.preventDefault(); handleKvAction(d.act); });
    }
    host.appendChild(b);
  });
}

/* 三键数字同步。★ 只在值真的变了才写 DOM（「别每帧重排」的既有约定）。
 * 挂点 = updateStartBtn()（路径每变一次必经），不在渲染循环里轮询。 */
function syncActionKeys() {
  const host = (controlsEl && controlsEl.classList && controlsEl.classList.contains('has-keys')) ? controlsEl : null;
  if (!host) return;
  const planning = phase === PHASE.PLANNING && !isMoving;
  const atkBtn = host.querySelector('.act-key.atk');
  const spBtn = host.querySelector('.act-key.skill');
  const dgBtn = host.querySelector('.act-key.dodge');
  /* 可用性先刷（不依赖 player）：非规划相位一律禁用，避免结算中还能改计划 */
  if (atkBtn) atkBtn.disabled = !planning;
  if (spBtn) spBtn.disabled = !planning;
  if (dgBtn) dgBtn.disabled = !planning;
  if (!player) return;
  /* 闪避 = 剩余可等待步数（移动力 − 已排等待步）。
     已排过等待步 → 键点亮（与棋盘上的青色闪避标记对应）。 */
  const waitLeft = Math.max(0, player.move - countWaitSteps(playerPath));
  if (dgBtn) {
    const n = dgBtn.querySelector('.ak-num');
    if (n && n.textContent !== String(waitLeft)) n.textContent = String(waitLeft);
    dgBtn.classList.toggle('on', waitLeft < player.move);
  }
  /* 攻击：显示骰子文案（2d4+1 / 1d8+1）而不是定值 —— 每次出手都掷骰，写死数字会骗人。
     多个攻击节点时右上角挂 ×N 徽章（与手机端同一个 .vbadge）。 */
  if (atkBtn) {
    const dmg = (typeof vpadDamageValue === 'function') ? vpadDamageValue() : '—';
    const n = atkBtn.querySelector('.ak-num');
    if (n && n.textContent !== dmg) n.textContent = dmg;
    atkBtn.classList.toggle('on', attackIndices.length > 0);
    const atkCount = attackIndices.length;
    let badge = atkBtn.querySelector('.vbadge');
    if (atkCount > 1) {
      if (!badge) { badge = document.createElement('span'); badge.className = 'vbadge'; atkBtn.appendChild(badge); }
      if (badge.textContent !== '×' + atkCount) badge.textContent = '×' + atkCount;
    } else if (badge) badge.remove();
  }
  /* 技能：数字 = 当前技力；底部 .ak-sp 按 spMax **等分**，点亮 cur 段。
     没有技力机制的角色（sp=null / max=0）→ 清空分段条，只留一个「—」，不画假格子。 */
  if (spBtn) {
    const sp = (typeof vpadSpInfo === 'function') ? vpadSpInfo() : null;
    const cur = sp ? Math.max(0, Math.round(sp.cur) || 0) : 0;
    const max = sp ? Math.max(0, Math.round(sp.max) || 0) : 0;
    const n = spBtn.querySelector('.ak-num');
    const txt = max > 0 ? (cur + '/' + max) : '—';
    if (n && n.textContent !== txt) n.textContent = txt;
    spBtn.classList.toggle('on', max > 0 && cur >= max);
    const segs = spBtn.querySelector('.ak-sp');
    if (segs) {
      /* 段数变了才重建（每帧 innerHTML 会打断 CSS 过渡，也白白触发重排） */
      if (segs.childElementCount !== max) {
        let html = '';
        for (let i = 0; i < max; i++) html += '<i></i>';
        segs.innerHTML = html;
      }
      for (let i = 0; i < segs.childElementCount; i++) {
        segs.children[i].classList.toggle('on', i < cur);
      }
    }
  }
}

function updateStartBtn() {
  if (phase !== PHASE.PLANNING) return;
  /* ★ ISSUE-20261101-152：手机底栏（含它的开始行动注入点 vpadStartSlot）删除后，
   * 开始行动按钮只有一个位置 —— 操作格 #controls 里（竖屏 #actionSlot 自 137 起已不填充）。 */
  const btn = controlsEl.querySelector('.start-btn')
    || (actionSlotEl ? actionSlotEl.querySelector('.start-btn') : null);
  if (btn) btn.disabled = playerPath.length === 0;
  /* 路径每变一次就重排格子：规划态是「已排了几件动作」的预览 */
  renderActionPips();
  /* ★ ISSUE-20261101-151：三键的数字/点亮态也跟着路径走（攻击节点数 / 剩余闪避步 / 技力） */
  syncActionKeys();
}

/* ★ ISSUE-20261101-144：buildHud() 与 buildLogMini() 已删除。
 *   · 前者只是给 heroInnerHtml() 套一个 .hud 壳扔进 #controls；现在角色数值直接写进
 *     状态格 #stats（renderHeroCard 改挂载点），壳不需要了。
 *   · 后者是 137 从设置抽屉提上来的「主面板战斗日志」（4 行），人类 2026-11-01 16:0x
 *     拍板「日志移回设置面板」—— 抽屉里的 #log（tools.js 的 log()）本来就是同源全量。
 * 不要为了「少改点」把它们加回来：操作格 5 行已经全给开始按钮了，没有位置。 */

function renderControls() {
  controlsEl.innerHTML = '';
  /* ★ ISSUE-20261101-151：三键只在规划 / 结算相位存在。每次重建先摘掉标记，
     否则上一次留下的 .has-keys 会把别的相位（选角 / 事件 / 通关）的按钮压进 3–5 行。 */
  controlsEl.classList.remove('has-keys');
  if (actionSlotEl) actionSlotEl.innerHTML = '';
  /* ★ ISSUE-20261101-137：竖屏不再单独走 #actionSlot。
     140 之后 #sidebar 是固定的 11×11 格栅，能挂的只有 #stats / #info / #controls 三块（152 起无底栏），
     而 #actionSlot 没有 grid-area —— 它一旦被填上内容，grid 自动流会把整块挤出第 11 行，
     HUD 与开始按钮直接飘到面板外面（手机竖屏实测：HUD 缩成 30px 宽、y=790 跑到面板底下）。
     所以横竖屏统一用 #controls，差别只由 #sidebar 的 grid-area 表达。 */
  /* ★ ISSUE-20261101-138（人类 2026-11-01 05:5x 真机 P1）：**整块 action-wrap 一律留在 #controls**。
     原来这里是 `const btnHost = vpadSlot || controlsEl`（vpadSlot 自 152 起已不存在）—— 手机端把 HUD + 战斗日志 + 开始按钮
     整个塞进了底栏那块 position:fixed 的面板。后果实测（384×736 触屏）：
       · 大厅日志短 → 面板 190px，勉强能用；
       · 战斗日志一长 → `.action-wrap` 是 9 行 1fr 的 grid、高度由内容决定 →
         **面板直接涨到 617px**，把整块地图盖掉（人类截图就是这个）；
       · 而且 UI 永远是一块浮在格子上的板子，跟「UI 11×11 嵌进格子」完全相反。
     现在 UI 全部回到 #controls（第 3–11 行，11 列，逐块对齐格子）；底栏连方向键与动作键也一并删除。
     开始行动按钮也跟着进 UI 面板的第 7–10 行 —— 位置仍在屏幕下方、拇指够得到，
     但不再是「浮层里的一颗按钮」。 */
  const btnHost = controlsEl;
  /* ★ ISSUE-20261101-144：**不再有 .action-wrap 这一层**。
     它自 137 起是「#controls 里再开 9 行 1fr」的容器 —— 面板的 padding/border 先吃掉一圈高度，
     9 行再去均分剩下的，于是每行比一格矮 (2·pad + 2·border)/9，累积到底部正好少一圈 padding
     （实测 cell=80 时少 24.4px ≈ ⅓ 格，这就是「UI 偶尔脱离格子」的物理原因）。
     现在操作格的行由 #controls 自己的 grid-template-rows 定义，子元素只有一条整数 grid-area。
     HUD → 状态格（renderHeroCard 写），战斗日志 → 设置抽屉，关卡 → 信息格。 */
  if (phase === PHASE.EVENT) {
    /* ★ ISSUE-20261031-126：事件关没有「开始行动」按钮（没有回合、没有敌人）——
     * 只给一行状态说明。人类拍板：隐藏战斗三件套，保留角色面板 / 金币 / 关卡徽章。 */
    const tip = document.createElement('div');
    tip.className = 'tip';
    tip.textContent = '自由走动 · 走到 ❓ 触发事件，或直接走向对面的 🚪 离开。';
    btnHost.appendChild(tip);
 } else if (phase === PHASE.PLANNING) {
    const confirm = document.createElement('button');
    /* ★ ISSUE-20261029-36：去掉「开始行动」四字，按钮内部显示动作 UI，框沿用 .start-btn 配色。
     * ★ ISSUE-20261030-77：内部改成小方块，没有任何文字。
     *   容器 id 固定 actionPips —— renderActionPips() 靠它局部重绘，不重建按钮。 */
    confirm.className = 'start-btn action-start-btn apips-host';
    confirm.setAttribute('aria-label', '开始行动');
    confirm.innerHTML = '<div class="apips" id="actionPips"></div>';
    confirm.disabled = playerPath.length === 0;
    confirm.onclick = confirmAction;
    /* ★ ISSUE-20261101-144：按钮 = 操作格整块 5 行（人类「操作单元格:显示开始按钮 11×5」）。
       ISSUE-20261031-93 之后手机端那行触摸说明也不再往这里塞 —— 5 行全给按钮，
       任何附加文字都会把按钮顶出格子；说明改由信息格（phaseInfoTip）承担。 */
    /* ★ ISSUE-20261101-151：三键先进 DOM（占操作格 1–2 行），
       开始行动按钮因此自动落到 3–5 行（CSS 里 .has-keys > .start-btn 的 grid-area）。 */
    buildActionKeys(btnHost);
    btnHost.appendChild(confirm);
 } else if (phase === PHASE.RESOLVING) {
    /* ★ ISSUE-20261030-77：结算中按钮本来会被整块移除（旧版只有 PLANNING 建 .start-btn），
     * 那样「做一件动作亮一格」执行到一半就看不见了。这里保留同一块格子区、降低对比度、不可点。 */
    const box = document.createElement('div');
    box.className = 'start-btn action-start-btn apips-host is-resolving';
    box.innerHTML = '<div class="apips" id="actionPips"></div>';
    /* 结算中也保留三键（禁用态）：玩家要能看见「这一回合排了什么」，而不是键突然消失。 */
    buildActionKeys(btnHost);
    btnHost.appendChild(box);
 } else if (phase === PHASE.GAMEOVER) {
    const btn = document.createElement('button');
    btn.className = 'start-btn';
    btn.textContent = '重新开始';
    btn.onclick = () => initCharSelect();
    btnHost.appendChild(btn);
 } else if (phase === PHASE.LEVELCLEAR) {
    const tip = document.createElement('div');
    tip.className = 'tip';
    tip.style.cssText = 'color:#ffd700;';
    if (pendingLevelUps > 0) {
      tip.textContent = '升级！请选择一项奖励…';
 } else if (playerStats.abilityPoints > 0) {
      tip.textContent = `把 ${playerStats.abilityPoints} 点属性加完就能进下一关`;
      /* 属性抽屉已移除（ISSUE-20261029-37）：奖励选完后若还有属性点，自动弹出 ♟️ 角色面板加点。
         只在当前没有任何抽屉时弹，避免把玩家已经打开的面板顶掉。 */
      if (typeof drawerCurrent !== 'undefined' && !drawerCurrent) {
        setTimeout(() => { if (phase === PHASE.LEVELCLEAR && playerStats.abilityPoints > 0 && !drawerCurrent) drawerOpen('char'); }, 80);
 }
 } else {
      tip.textContent = `关卡通过！（本次未升级，经验 ${xp}/${xpThresholdForLevel(heroLevel)}）即将进入下一关…`;
 }
    btnHost.appendChild(tip);
    // 未选奖励前不显示下一关按钮；选完奖励后若还有属性点，按钮禁用直到加完
    if (pendingLevelUps <= 0) {
      const btn = document.createElement('button');
      btn.className = 'start-btn';
      if (playerStats.abilityPoints > 0) {
        btn.textContent = '⬇️ 下一关（先把属性点加完）';
        btn.disabled = true;
 } else {
        btn.textContent = '⬇️ 下一关';
        btn.onclick = proceedNextLevel;
 }
      btnHost.appendChild(btn);
 } else {
      // 保险：定时器万一被清掉，也不会卡在通关界面（已选过奖励 / 已进入下一关时不再弹）
      setTimeout(() => { if (phase === PHASE.LEVELCLEAR && pendingLevelUps > 0) openLevelUp(); }, 400);
 }
 }
  controlsEl.dataset.phase = phase;
  /* ISSUE-20261030-77：格子必须等 #actionPips 进了文档再画（上面 append 之前 getElementById 取不到） */
  renderActionPips();
  /* ★ ISSUE-20261101-151：刚建出来的三键数字还是占位「—」，立刻刷一次真实值。
     （updateStartBtn 只在 PLANNING 跑，结算相位的数字要靠这里补） */
  syncActionKeys();
  /* 底栏面板里塞进 / 拿掉「开始行动」后高度会变，重新补一次让位高度 */
  try { if (typeof syncVpadInset === 'function') syncVpadInset(); } catch (_) {}
  /* ★ ISSUE-20261030-84：左下 📟 的「有事等你」高亮是**状态出口**，和 ⚙ / ♟ 一样统一由
   * drawerSyncChrome() 写。renderControls 是「相位变化 / 待领奖励变化」必然经过的点，
   * 挂在这里就不用四处补调用（漏一处就会出现「奖励已领但 📟 还在闪」）。 */
  try { if (typeof drawerSyncChrome === 'function') drawerSyncChrome(); } catch (_) {}
  renderHeroCard();
  /* ★ ISSUE-20261101-144：相位一变，信息格的关卡标题与提示也要跟着换 ——
     挂在 renderControls 里就覆盖了所有相位切换（它是「相位变化」的必经点）。 */
  renderInfoGrid();
}

function syncControlsIfNeeded() {
  if (controlsEl.dataset.phase !== phase) {
    renderControls();
    return;
 }
  if (phase === PHASE.PLANNING) updateStartBtn();
}

/* 敌人意图只在「玩家规划路径 / 敌人位置」变化时重算（否则箭头每帧抖动） */
function syncEnemyIntent() {
  if (phase !== PHASE.PLANNING) return;
  if (calcPathSignature() !== lastPathSignature) generateEnemyPaths();
}

/* 棋盘格 + 单位层 + 意图箭头的统一绘制 */
function paintBoard() {
  boardEl.innerHTML = buildBoardHtml();
  renderUnits();
  /* ★ ISSUE-20261031-126：事件关的角色画在**自由移动层**（unitLayer 里的 .cand-unit），
   * 而上一行 renderUnits() 在非战斗相位会 clearUnitLayer() 把它一起清掉。
   * render() / refreshBoardOnly() / resize 都会走到这里，所以重建钩子必须挂在本函数末尾 ——
   * 挂在 render() 里会漏掉 refreshBoardOnly 那条路。
   * 大厅/战斗相位下它是空操作（freeMoveRefreshEls 内部判相位与 freeMoveActive）。 */
  if (typeof freeMoveRefreshEls === 'function') freeMoveRefreshEls();
  if (phase === PHASE.PLANNING) showEnemyFirstStepArrows();
  else clearEnemyArrows();
  /* ISSUE-20261030-91：格子这一层被 innerHTML 重建，说明区 / 光标指引的矩形全部作废，
   * 必须跟着重算（它们在 #fxLayer 上，不会被冲掉，但 left/top 会指向旧布局）。
   * 只在教程态发生，正式局这一句直接短路。 */
  if (typeof tutorialIsOn === 'function' && tutorialIsOn() && typeof renderTutorialBar === 'function') {
    renderTutorialBar();
 }
}

function render(skipControls = false) {
  syncEnemyIntent();
  const bbox = getBoundingBox();
  updateStats();
  boardEl.style.gridTemplateColumns = `repeat(${bbox.maxX - bbox.minX + 1}, var(--cell))`;
  boardEl.style.gridTemplateRows = `repeat(${bbox.maxY - bbox.minY + 1}, var(--cell))`;
  paintBoard();
  if (skipControls) return;
  renderControls();
}

function refreshBoardOnly() {
  syncEnemyIntent();
  updateStats();
  paintBoard();
  syncControlsIfNeeded();
}

/* 选角大厅的逐格移动（moveCandidate）已被「平滑自由移动」取代：
 * 位置模型与 rAF 循环见 src/ui/char-select.js（ISSUE-20261028-12）。
 * findPath 保留 —— 战斗关卡的路径规划仍在用。 */

function handleKeyDown(e) {
  const k = e.key.toLowerCase();
  const isSpace = e.code === 'Space' || k === ' ';
  if (['w','a','s','d','e','q','x','r','v'].includes(k) || isSpace) e.preventDefault();
  if (isMoving) return;
  // 抽屉开着时不响应游戏快捷键（Esc 已由 drawer.js 在捕获阶段拦截）
  if (typeof drawerCurrent !== 'undefined' && drawerCurrent) return;
  if (isFreeMovePhase()) {
    /* 非战斗相位：按住连续走，keyup / blur 在 char-select 模块里统一清键表。
     * ★ ISSUE-20261031-126：「有没有可移动角色」的判定收进 freeMoveKeyDown 内部，
     *   这里不再重复判 selectedCandidate —— 事件关没有那个东西，重复判会让 WASD 全哑。 */
    freeMoveKeyDown(k);
    return;
 }
  if (phase !== PHASE.PLANNING) return;
  /* ISSUE-20261028-10-B：眩晕时键盘同样不能规划（与鼠标同口径，别只在一边拦） */
  if (player && player.stunTurns > 0) { stunBlockOnce(); return; }
  // 方向键与手机方向钮共用同一条移动路径
  if (['w','a','s','d'].includes(k)) stepPathByDir(k);
  if (k === 'q') {
    if (countWaitSteps(playerPath) < player.move) {
      /* ★ ISSUE-20261029-34：等待步 = 闪避动作，必须过动作预算闸门 */
      const gate = canAddWaitStep(playerPath, attackIndices, skillIndices);
      if (!gate.ok) { log(`⚠️ ${gate.reason}`); return; }
      const last = playerPath.length ? playerPath[playerPath.length - 1] : { x: player.x, y: player.y };
      playerPath.push({ x: last.x, y: last.y });
      afterWaitAdded();
      refreshBoardOnly();
 }
 }
  if (k === 'e') {
    if (playerPath.length > 0) { toggleAttack(playerPath.length - 1); refreshBoardOnly(); }
 }
  // R：切换末尾路径节点的技能节点（键盘等价右键）
  if (k === 'r') {
    /* ★ ISSUE-20261029-34：只剩起点时按 R = 设「原地施法」 */
    if (playerPath.length >= 1) { toggleSkill(playerPath.length - 1); refreshBoardOnly(); }
 }
  // X：重置路径（回到起点，清空攻击 / 技能节点）
  if (k === 'x') {
    if (playerPath.length > 1 || attackIndices.length > 0 || skillIndices.length > 0) {
      playerPath = [{ x: player.x, y: player.y }];
      attackIndices = [];
      skillIndices = [];
      refreshBoardOnly();
 }
 }
  // V：切换攻击范围显示（替代被移除的「点伤害格」入口，ISSUE-20261028-09 E）
  if (k === 'v') handleKvAction('range');
  if (isSpace) {
    if (playerPath.length > 0) confirmAction();
 }
}
document.addEventListener('keydown', handleKeyDown);

let dragging = false, dragDownCell = null, hasDragged = false, pressTimer = null;
/* ISSUE-20261028-18：大厅「跟随指针」的按压状态。触屏必须按住 + 拖动才跟随（B1/B4），
   桌面鼠标不需要按下（A1）。moved = 位移已超过 8px → 进入拖动跟随，pointerup 时不再当点击。 */
let freeMovePress = null;

function getCellFromEvent(clientX, clientY) {
  /* ISSUE-20261031-113：从「找 DOM 元素」改为「数学换算」。
   * #board 现在是 11×11 的 CSS Grid（grid + 2px gap），左上角由 getBoundingClientRect() 给出，
   * 每格步长 = cell + gap。点击 / 右键 / 拖拽逻辑全部走这个函数，改写后一行不用动。
   * 只接受有效地图格（0..10）；分隔列 / UI 区 / 边距一律返回 null，不触发任何棋盘事件。 */
  const rect = boardEl.getBoundingClientRect();
  if (!rect.width || !rect.height) return null;
  const cell = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--cell')) || 50;
  const gap = 2;
  const step = cell + gap;
  const x = Math.floor((clientX - rect.left) / step);
  const y = Math.floor((clientY - rect.top) / step);
  if (x < 0 || x > 10 || y < 0 || y > 10) return null;
  return { x, y };
}

/* ★ ISSUE-20261101-153：中键在棋盘上 = 开始行动，得同时按住浏览器的「中键自动滚动」。
 * 只靠 pointerdown 的 preventDefault 在部分 Chromium 上压不住 autoscroll（它挂在 mousedown 上），
 * 所以补一条 mousedown；auxclick 用来挡「中键点击 = 后台新标签」。 */
boardEl.addEventListener('mousedown', (e) => { if (e.button === 1) e.preventDefault(); }, { passive: false });
boardEl.addEventListener('auxclick', (e) => { if (e.button === 1) e.preventDefault(); });

/* PC 右键在路径格上设 / 取消技能节点（ISSUE-20261028-09 B）。
 * 只有「该格在当前规划路径上」才生效；校验全部走现有 toggleSkill（动作上限、
 * 攻击 / 技能共存等规则只此一份，不另写）。
 * ★ ISSUE-20261029-34：起点格也算路径节点 —— 右键自己的脚下 = 设「原地施法」。
 * 右键非路径格：不弹浏览器菜单、不产生节点，给一条日志说明。 */
boardEl.addEventListener('contextmenu', (e) => {
  e.preventDefault();
  if (phase !== PHASE.PLANNING || isMoving || !player) return;
  const cell = getCellFromEvent(e.clientX, e.clientY);
  if (!cell) return;
  const idx = findLastIndex(playerPath, p => p.x === cell.x && p.y === cell.y);
  if (idx < 0) { log('右键只在规划路径的节点上设置技能节点（不在当前路径上）。'); return; }
  toggleSkill(idx);
  refreshBoardOnly();
});

function toggleAttack(idx) {
  /* ★ idx 0 = 玩家脚下那一格（路径起点）= 「原地攻击」：不移动，本回合先在起始格出手。
   * 旧版这里写成 `if (idx < 1) return;`，把起点格和非法下标一起挡掉了 ——
   * 于是「点自己脚下的格子」完全没反应，而 confirmAction() 里 `attackIndices.includes(0)`
   * 那段「原地攻击」的支持代码永远是死分支（ISSUE-20261028-17 / BUG-STARTCELL-ATTACK）。
   * 越界仍然要挡：idx 必须落在当前路径范围内。 */
  if (idx < 0 || idx >= playerPath.length) return;
  if (selectedChar === 'fencer' && fencerCounterActive) {
    log('反击状态不能设置攻击节点。');
    return;
 }
  if (selectedChar === 'wheelchair' && playerChargingThisTurn) {
    log('冲锋中不能设置攻击节点（冲锋会自动撞击前方敌人）。');
    return;
 }
  if (skillIndices.includes(idx)) {
    log('该节点是技能节点：右键（或再按 R）可取消技能节点。');
    return;
 }
  const ai = attackIndices.indexOf(idx);
  if (ai >= 0) {
    attackIndices.splice(ai, 1);
    removePlacement('attack', idx);
    return;
 }
  if (!nodeFitsBudget(playerPath, [...attackIndices, idx], skillIndices)) {
    log(budgetRejectReason(playerPath, [...attackIndices, idx], skillIndices));
    return;
 }
  attackIndices.push(idx);
  recordPlacement('attack', idx);
  log(idx === 0
    ? '🎯 原地攻击：不移动，进入本回合后先在起始格出手（占一次动作）。'
    : `🎯 攻击节点：第 ${idx} 步（占一次动作）。`);
}

/* ★ 技能节点：右键路径节点设置 / 取消（攻击 / 技能可在同一格共存，各算 1 件动作）
 * ★ ISSUE-20261101-153：PC 端左键 = 攻击、右键 = 技能。旧版「双击 = 技能」已删除 ——
 *   双击识别要存上一次点击的格子与节点快照，既增加状态又让「快速点两下移动格」被误判，
 *   而右键本来就能做同一件事，两条路只留一条。
 * ★ ISSUE-20261029-34：起点格（idx 0）现在也允许放技能节点 = 「原地施法」——
 * 本回合第一个 tick 就发动，不移动。旧版这里写的是 `idx < 1`，把起点和非法下标一起挡掉了，
 * 于是「在原地点技能」完全没反应（用户 2026-10-29 报的 bug）。 */
function toggleSkill(idx) {
  if (idx < 0 || idx >= playerPath.length) return;
  /* ★ ISSUE-20261028-14：通用教程期关闭技能节点 —— 新手会乱按，把「朝向/暴击」这节课打断。
   * 角色专属课把同一个开关翻成允许（tutorialSkillsBlocked 一处判，不做两个互相覆盖的变量）。 */
  if (typeof tutorialSkillsBlocked === 'function' && tutorialSkillsBlocked()) {
    log('📖 通用教程先不开放技能：这节课把朝向和暴击练熟就好，学完会立刻教你自己的角色怎么用技能。');
    return;
 }
  /* ★ ISSUE-20261031-120（🙊 猴王形态：人类原话「角色无法使用技能」）——
   * 这里是**入口拦截**（新排的技能节点直接被拒）。
   * ⚠️ 只拦这里不够：玩家完全可能在猴王换形态**之前**就把技能节点排进路径，
   *   等走到那一步时它已经变成 🙊 → 所以 triggerSkillNode（执行时）必须再判一次。 */
  if (typeof kingMuteSkills === 'function' && kingMuteSkills()) {
    log('🙊 猴王捂嘴：本回合无法排入技能节点（它每 2 回合换一次形态，等它换走）。');
    floatText(player.x, player.y, '技能被禁', '#bbb');
    return;
 }
  /* 风笛的「高效冲击」必须有冲锋方向，起点没有方向 → 起点不放技能节点 */
  if (idx === 0 && selectedChar === 'wheelchair') {
    log('✦ 起点不能放技能节点：风笛的「高效冲击」需要沿移动方向冲锋，请放在移动节点上。');
    return;
 }
  const si = skillIndices.indexOf(idx);
  if (si >= 0) {
    skillIndices.splice(si, 1);
    removePlacement('skill', idx);
    log(`✧ 已取消${idx === 0 ? '原地' : `第 ${idx} 步`}的技能节点。`);
    return;
 }
  /* ★ 攻击 / 技能不再同格互斥：两者是独立数组，可在同一格共存（各算 1 件动作，
   * 受 maxActionsThisTurn() 预算限制 —— 同格「攻击+技能」= 2 件正好到顶）。
   * 旧版这里会 `attackIndices.filter(i => i !== idx)` 把同格攻击删掉，
   * 导致「设技能 = 顶掉攻击」，两种动作无法在路径格上共存。 */
  if (!nodeFitsBudget(playerPath, attackIndices, [...skillIndices, idx])) {
    log(budgetRejectReason(playerPath, attackIndices, [...skillIndices, idx]));
    return;
  }
  skillIndices.push(idx);
  recordPlacement('skill', idx);
  const info = skillReadyInfo(playerPath);
  const where = idx === 0 ? '原地（起点，本回合先施法）' : `第 ${idx} 步`;
  log(`✦ 技能节点：${where}（占一次动作，到达该步才发动）${info.ready ? ` ·「${info.name}」就绪` : ` ·「${info.name}」未就绪`}。`);
}
function tryExtendPath(x, y) {
  if (countMoveSteps(playerPath) >= player.move) return false;
  const last = playerPath.length ? playerPath[playerPath.length - 1] : { x: player.x, y: player.y };
  if (dist(last, { x, y }) !== 1) return false;
  if (x === player.x && y === player.y) return false;
  playerPath.push({ x, y });
  return true;
}
function handleCellDrag(x, y) {
  if (!isWalkable(x, y)) return;
  if (x === player.x && y === player.y) return;
  const idx = findLastIndex(playerPath, p => p.x === x && p.y === y);
  if (idx >= 0) {
    if (idx === 0 && playerPath.length > 1) return;
    if (idx < playerPath.length - 1) {
      playerPath = playerPath.slice(0, idx + 1);
      attackIndices = attackIndices.filter(i => i < playerPath.length);
      skillIndices = skillIndices.filter(i => i < playerPath.length);
      refreshBoardOnly();
 }
    return;
 }
  if (tryExtendPath(x, y)) refreshBoardOnly();
}
/* 调试秒杀：复用普通击杀反馈（ISSUE-20261028-11 B3）—— 无专属浮字/日志，
 * 与正常击杀走同一入口（阿米娅技力、精英掉落等逻辑均一致）。 */
function killEnemyByDebug(enemy) {
  if (killEnemy(enemy, { showRing: true, showFloat: true })) {
    render();
    if (enemies.filter(e => e.alive).length === 0) onLevelClear();
 }
}

document.addEventListener('pointerdown', (e) => {
  if (phase !== PHASE.PLANNING || isMoving) return;
  /* ★ ISSUE-20261101-153：只认左键。中键（开始行动）与右键（技能节点）各有归属，
   * 让它们走到下面那条「点到棋盘外 = 清空路径」会把玩家刚排好的路径一次性清掉。
   * 触摸的 pointerdown 本来就是 button 0，这条对触屏是空操作。 */
  if (e.button !== 0) return;
  if (e.target.closest('button') || e.target.closest('#heroKv') || e.target.closest('.drawer')) return;
  const cell = getCellFromEvent(e.clientX, e.clientY);
  if (!cell) {
    playerPath = [{ x: player.x, y: player.y }];
    attackIndices = [];
    skillIndices = [];
    actionPlacements = [];
    refreshBoardOnly();
 }
});

boardEl.addEventListener('pointerdown', (e) => {
  /* ★ ISSUE-20261101-153：PC 中键 = 开始行动。
   * 放在 getCellFromEvent 之前 —— 中键按在格子间隙 / 单位层上时它可能返回 null，
   * 那时不该「按了没反应」。也不判格子：整个棋盘都是这颗键的触发区。 */
  if (e.button === 1) {
    e.preventDefault();
    if (phase === PHASE.PLANNING && !isMoving && playerPath.length > 0) confirmAction();
    return;
  }
  if (isMoving) return;
  /* ★ ISSUE-20261101-153：右键交给 contextmenu 那条路（= 技能节点）。
   * 不在这里早退的话，右键会顺手置 dragging 并起长按计时器 —— 按住右键 400ms 会塞一个
   * 等待步，松手还会被 pointerup 当成一次左键单击去 toggleAttack。
   * 触摸的 pointerdown 本来就是 button 0，这条对触屏是空操作。 */
  if (e.button !== 0) return;
  const cell = getCellFromEvent(e.clientX, e.clientY);
  if (!cell) return;
  if (phase === PHASE.CHAR_SELECT) {
    /* ★ ISSUE-20261029-46 E：两个入口都支持「点一下直接进入」——
     *   点 🌐 → 进联机大厅；点 🚪 → 开始游戏（联机地图里则是返回选角厅）。
     *   「走过去进入」的判定在 freeMoveTick / freeMoveTouchesOnline（src/ui/char-select.js），
     *   两条路径都要成立，所以这里要在「设移动目标」之前拦下来（否则只是走过去而已）。 */
    if (!onlineStage && selOnlineExit.x === cell.x && selOnlineExit.y === cell.y) {
      freeMovePress = null;
      if (typeof enterOnlineLobby === 'function') enterOnlineLobby();
      e.preventDefault();
      return;
 }
    if (!onlineStage && typeof selTutInZone === 'function' && selTutInZone(cell.x, cell.y)) {
      /* ★ ISSUE-20261031-94（v2）：3×3 区域整块都能点（视觉上它就是一个大按钮，
       * 点大按钮却只有正中心那一格有反应会被当成 bug）。
       * 走位触发已移除 —— 这块区域压在通往 🚪 的必经路上，走过去就自动进教程会反复劫持玩家。 */
      freeMovePress = null;
      if (typeof startTutorialFromLobby === 'function' && startTutorialFromLobby()) {
        if (typeof stopFreeMove === 'function') stopFreeMove();
        setTimeout(() => { selectCharacter(selectedCandidate.id); }, 60);
      }
      e.preventDefault();
      return;
 }
    if (selExit.x === cell.x && selExit.y === cell.y) {
      freeMovePress = null;
      if (onlineStage) {
        if (typeof onlineQuit === 'function') onlineQuit();
 } else if (selectedCandidate) {
        /* selectCharacter() 内部已经 stopFreeMove() + freeMoveClearEls()，别在这里重复清 */
        const id = selectedCandidate.id;
        log(`你选择了 ${CHARACTERS[id].name}！进入关卡。`);
  /* ★ ISSUE-20261030-62：开局前把还开着的面板收干净。
   * 最显眼的是角色说明面板（#charInfoSheet，点角色弹出来的）—— 它挂在 body 直属、
   * 绝对定位，不清的话会跟着切到战斗棋盘上浮着。
   * drawerClose() 是抽屉的统一出口，里面已经拦住「升级奖励没选完不许关」。 */
  try { if (typeof closeCharInfoSheet === 'function') closeCharInfoSheet(); } catch (_) {}
  try { if (typeof drawerClose === 'function') drawerClose(); } catch (_) {}
        selectCharacter(id);
 } else {
        log('请先点一个角色，再点 🚪 出口开始游戏。');
 }
      e.preventDefault();
      return;
 }
    /* 跟随指针（ISSUE-18）：先记按压起点，pointermove 拿它算位移判「拖动 vs 点击」（B4） */
    freeMovePress = { x: e.clientX, y: e.clientY, t: Date.now(), moved: false, id: e.pointerId };
    /* ★ ISSUE-20261029-47 根因①：选角这一支原来没设 pointer capture（只有下面 PHASE.PLANNING
     * 那支设了），于是指针一离开 #board，pointermove 就不再投递给 boardEl ——
     * 「鼠标稍微移出地图就跟丢了」。这里补上与规划分支同款的 capture。
     * pointerup 里已有 releasePointerCapture，无需另加释放；
     * 触屏本身是「隐式 capture」，这条对它等价无操作，不会碰到触屏那支的手感。 */
    try { boardEl.setPointerCapture(e.pointerId); } catch (_) {}
    /* 选中角色：按「与角色中心的距离」判定，角色停在格与格之间也能点中 */
    const cand = freeMoveCandidateAt(cell.x, cell.y);
    /* ISSUE-20261029-29：点角色 = 选中 + 在角色行以上展开技能说明（可滚轮；点空白处收起） */
    if (cand) {
      selectedCandidate = cand;
      candidateSelect(cand.id);
      render();
      freeMoveRenderAll();
      openCharInfoSheet();
      e.preventDefault();
      return;
 }
    /* 点地图 = 设一个「走到这里」的目标点（可连续改向，不等走完） */
    if (selectedCandidate) {
      if (!freeMoveGeom && !freeMoveMeasure()) return;
      const p = freeMoveClientToCell(e.clientX, e.clientY);
      freeMoveSetTarget(p.fx, p.fy);
 }
    e.preventDefault();
    return;
 }
  /* ★ ISSUE-20261031-126：事件关 —— 点地图 = 走过去（与大厅同一套 freeMoveSetTarget），
   * 没有大厅那些「点角色选中 / 点出口直接进入」的专有逻辑。
   * ⚠️ 必须放在下面 `if (phase !== PHASE.PLANNING) return;` **之前**，
   *   否则事件关里点地图完全没反应（PLANNING 之外一律早退）。 */
  if (phase === PHASE.EVENT) {
    freeMovePress = { x: e.clientX, y: e.clientY, t: Date.now(), moved: false, id: e.pointerId };
    try { boardEl.setPointerCapture(e.pointerId); } catch (_) {}
    /* 几何没量到（刚进关 / 刚切横竖屏）就先补量一次；仍量不到就放弃本次点击，
     * 下一帧的 initFreeMoveEvent 会重试，不会把角色摆到一个错的位置上。 */
    if (freeMoveGeom || freeMoveMeasure()) {
      const p = freeMoveClientToCell(e.clientX, e.clientY);
      freeMoveSetTarget(p.fx, p.fy);
    }
    e.preventDefault();
    return;
  }
  if (phase !== PHASE.PLANNING) return;
  if (debugMode) {
    const enemy = enemies.find(en => en.alive && en.x === cell.x && en.y === cell.y);
    if (enemy) { killEnemyByDebug(enemy); e.preventDefault(); return; }
 }
  /* ISSUE-20261028-10-B：眩晕时不许规划路径 / 设节点，只能点「开始」原地结算 */
  if (player && player.stunTurns > 0) { stunBlockOnce(); e.preventDefault(); return; }
  /* ★ ISSUE-20261031-110 入门三关：只许点光标指引的那一格（人类原话「禁止玩家点其他地方」）。
   * 白名单在 rules 层（tutorialClickAllowed），这里只负责「拦下 + 说一句为什么」。
   * 拦在 pointerdown 而不是 pointerup：长按（等待步）和拖拽也都从这里进，
   * 一处拦住就同时封住三条路径，不用在 pressTimer / pointerup 里各补一遍。 */
  if (typeof tutorialClickAllowed === 'function' && !tutorialClickAllowed(cell.x, cell.y)) {
    tutBlockHint();
    e.preventDefault();
    return;
  }
  dragging = true; dragDownCell = cell; hasDragged = false;
  try { boardEl.setPointerCapture(e.pointerId); } catch (_) {}
  clearTimeout(pressTimer);
  pressTimer = setTimeout(() => {
    if (dragging && !hasDragged && phase === PHASE.PLANNING) {
      if (countWaitSteps(playerPath) < player.move) {
        /* ★ ISSUE-20261029-34：长按 = 等待步 = 闪避动作，同样必须过动作预算闸门 */
        const gate = canAddWaitStep(playerPath, attackIndices, skillIndices);
        if (!gate.ok) { log(`⚠️ ${gate.reason}`); return; }
        const last = playerPath.length ? playerPath[playerPath.length - 1] : { x: player.x, y: player.y };
        playerPath.push({ x: last.x, y: last.y });
        afterWaitAdded();
        refreshBoardOnly();
        hasDragged = true;
 }
 }
 }, 400);
  e.preventDefault();
}, { passive: false });

boardEl.addEventListener('pointermove', (e) => {
  /* ★ ISSUE-20261029-39（人类 16:02 / 16:18「1 是」，**推翻** ISSUE-20261028-18 的 A1 口径）：
   * 「非战斗关卡自由移动改成鼠标按下才会跟随」——
   *   · 桌面（mouse）：**必须按住左键**才跟随。旧口径是「指针一动就跟」，导致想点某处时
   *     角色早被鼠标扫过去带偏了；松手立刻停（pointerup 里 freeMoveClearTarget，未改）；
   *   · 触屏：仍是「按住 + 拖过 8px 才跟随」（8px 死区用来区分「点击选角色」和「拖动移动」，
   *     人类 16:18 确认**只改鼠标**，触屏这一支一行未动）。
   * ⚠️ 这里只写变量，绝不做布局计算 / DOM 重建 —— 120Hz 鼠标每秒 500+ 次事件（约束 1）。 */
  if (isFreeMovePhase()) {
    /* ★ ISSUE-20261031-126：判据从「有没有选候选角色」改成「当前相位有没有可移动的角色」——
     *   事件关没有 selectedCandidate（大厅概念），沿用旧判据会让鼠标拖动在房间里完全无效。 */
    if (!freeMoveActor()) return;
    const isTouch = e.pointerType && e.pointerType !== 'mouse';
    /* 两种指针都必须「按下」才跟随：freeMovePress 由 pointerdown 对全部指针类型记录 */
    if (!freeMovePress || freeMovePress.id !== e.pointerId) return;
    /* ★ ISSUE-20261029-47 根因②：「移到操作 UI 上就停」必须判在这里，不能判在 pointerleave。
     * 命中 UI → 只清目标（角色原地停住），不动画面；移回非 UI 区且仍按着 → 下一帧自然恢复跟随。
     * 只判鼠标指针：触屏那支（8px 死区 + 目标上移 FREE_MOVE_TOUCH_LIFT）本 issue 一行未动。 */
    if (!isTouch && freeMoveOverUi(e.clientX, e.clientY)) {
      freeMoveClearTarget();
      e.preventDefault();
      return;
 }
    let lift = 0;
    if (isTouch) {
      if (!freeMovePress.moved) {
        const dx = e.clientX - freeMovePress.x, dy = e.clientY - freeMovePress.y;
        if (Math.hypot(dx, dy) < FREE_MOVE_DRAG_THRESHOLD) return;   /* 仍算点击，不跟随 */
        freeMovePress.moved = true;
 }
      lift = FREE_MOVE_TOUCH_LIFT;   /* 触屏拖动：目标点上移，别让手指盖住角色（§待确认 2 推荐 B） */
 }
    const p = freeMoveClientToCell(e.clientX, e.clientY);
    freeMoveSetTarget(p.fx, p.fy - lift, true);   /* follow=true → 用较大死区，不抖 */
    e.preventDefault();
    return;
 }
  if (!dragging || phase !== PHASE.PLANNING) return;
  const cell = getCellFromEvent(e.clientX, e.clientY);
  if (!cell) return;
  if (dragDownCell && cell.x === dragDownCell.x && cell.y === dragDownCell.y) return;
  hasDragged = true;
  clearTimeout(pressTimer);
  handleCellDrag(cell.x, cell.y);
  e.preventDefault();
}, { passive: false });

boardEl.addEventListener('pointerup', (e) => {
  clearTimeout(pressTimer);
  /* ISSUE-18：大厅里「拖动过」的松手 = 立即停（B2）；只点了一下（<8px）则保留点击补位行为（A5） */
  if (isFreeMovePhase()) {
    const dragged = !!(freeMovePress && freeMovePress.moved);
    freeMovePress = null;
    /* ISSUE-20261029-44 第2项：拖动跟随（含鼠标按住跟随）一松手就立即停；
     * 纯点击未移动时 freeMoveIsFollowing() 为 false，保留「点击走到目标」。 */
    if (dragged || freeMoveIsFollowing()) freeMoveClearTarget();
    return;
 }
  if (!dragging) return;
  dragging = false;
  if (!hasDragged && dragDownCell && phase === PHASE.PLANNING) {
    const x = dragDownCell.x, y = dragDownCell.y;
    const idx = findLastIndex(playerPath, p => p.x === x && p.y === y);
    if (idx >= 0) {
      /* ★ 左键单击路径节点 = 攻击节点；技能节点走右键（见 contextmenu 监听）。
       * ISSUE-20261101-153 删掉了「双击 = 技能」：路径格上的三种动作现在各有一颗键，
       * 单击不必再猜「这是双击的第一下还是普通点击」，连点两下同一个移动格也不会再被吃掉。 */
      toggleAttack(idx);
      refreshBoardOnly();
 }
    else if (isWalkable(x, y) && !(x === player.x && y === player.y)) {
      const last = playerPath.length ? playerPath[playerPath.length - 1] : { x: player.x, y: player.y };
      if (dist(last, {x, y}) > 1) {
        const maxSteps = player.move - countMoveSteps(playerPath);
        if (maxSteps > 0) {
          const path = findPath(last.x, last.y, x, y, maxSteps);
          if (path) { for (const p of path) { if (countMoveSteps(playerPath) < player.move) playerPath.push(p); } refreshBoardOnly(); }
 }
 } else {
        if (countMoveSteps(playerPath) < player.move) { playerPath.push({ x, y }); refreshBoardOnly(); }
 }
 }
 }
  dragDownCell = null; hasDragged = false;
  try { boardEl.releasePointerCapture(e.pointerId); } catch (_) {}
  /* ★ ISSUE-20261031-110：路径 / 节点一变就推进教程步骤（见 tutPlanChanged 的说明）。
   * 放在这里而不是每个 toggleAttack 里：pointerup 是「本次点击落定」的唯一收口。 */
  tutPlanChanged();
});

boardEl.addEventListener('pointercancel', () => {
  clearTimeout(pressTimer);
  dragging = false; dragDownCell = null; hasDragged = false;
  /* ISSUE-18 约束 3：手指被系统手势打断（来电/下拉通知）必须清掉目标，
     否则跟随会留下一个过期目标点，角色自己跑。 */
  freeMovePress = null;
  if (isFreeMovePhase()) freeMoveClearTarget();
});

/* ★ ISSUE-20261029-47：这里**不再**无条件清跟随目标。
 * 旧口径「指针离开棋盘（移到设置/日志/抽屉/页面外）→ 立即停」把两件事混为一谈：
 *   · 移到操作 UI 上   → 该停；
 *   · 只是移出棋盘边界 → 不该停（要求「只要点击地图窗口内就会跟随」）。
 * 「该不该停」现在统一由 pointermove 里的 freeMoveOverUi() 判定（那里才拿得到坐标），
 * 这里只清按压态做兜底 —— 松手立即停仍由 pointerup 负责，未改动。 */
boardEl.addEventListener('pointerleave', () => {
  if (!isFreeMovePhase()) return;
  freeMovePress = null;
});

/* =========================================================
 * ★ 确认行动前的预结算（只处理「必须提前改写路径」的技能）
 *
 * 技能触发系统重做后，绝大多数技能都在玩家走到技能节点时结算（triggerSkillNode）。
 * 唯一的例外是风笛的「高效冲击」：冲锋会延长路径，必须在生成敌人意图之前算出来。
 * ========================================================= */
/* 风笛：结算直线移动技力；满技力时把第一个移动步上的技能节点改写成冲锋并延长路径。 */
function prepareWheelchairCharge() {
  if (selectedChar !== 'wheelchair') return null;
  /* 1) 结算本回合直线移动获得的技力（等待/转向会断开一段） */
  const gain = pathSpGain(playerPath);
  if (gain > 0) {
    const sass = sassExtraSp();
    const before = wheelchairSp;
    wheelchairSp = Math.min(WHEELCHAIR_SP_MAX, wheelchairSp + gain + sass);
    log(`风笛直线移动 ${gain} 步：技力 +${gain + sass}（${before} → ${wheelchairSp}/${WHEELCHAIR_SP_MAX}）${sass ? '　🥤 香草沙士 +1' : ''}`);
    if (before < WHEELCHAIR_SP_MAX && wheelchairSp >= WHEELCHAIR_SP_MAX) {
      log('风笛技力已满：右键路径里的移动节点设置技能节点，即可发动「高效冲击」。');
 }
 }
  /* 2) 技力满 5 → 第一个「移动步上的技能节点」变成冲锋触发点（沿该步方向直线冲到底） */
  const chargeIdx = findChargeSkillIndex(playerPath, wheelchairSp);
  if (chargeIdx === null) {
    if (wheelchairSp >= WHEELCHAIR_SP_MAX) {
      log('风笛技力已满：右键一个移动路径节点设置技能节点，即可发动「高效冲击」。');
 }
    return null;
 }
  const fromPos = playerPath[chargeIdx - 1];
  const toPos = playerPath[chargeIdx];
  const trigger = { endIdx: chargeIdx, dir: { dx: Math.sign(toPos.x - fromPos.x), dy: Math.sign(toPos.y - fromPos.y) } };
  /* ★ 额度 N = 本回合剩余移动步数（ISSUE-20261028-01）。
   * 不能用 chargeIdx 直接减：路径里同时含「移动步」与「等待步」，等待不消耗移动力，
   * 用下标减会把额度算少。必须只数移动步。 */
  const usedMove = countMoveSteps(playerPath.slice(0, chargeIdx + 1));
  const budget = Math.max(0, (player.move || 1) - usedMove);
  if (budget <= 0) {
    log('「高效冲击」无法发动：本回合剩余移动步数为 0，请下回合把技能节点放在前几步（技力保留）。');
    return null;
 }
  const { chargePath, stopReason } = computeStraightChargePath(playerPath, trigger, budget);
  if (chargePath.length === 0) {
    log('「高效冲击」无法发动：技能节点正前方就是墙（技力保留）。');
    return null;
 }
  playerPath = [...playerPath.slice(0, chargeIdx + 1), ...chargePath];
  attackIndices = attackIndices.filter(idx => idx < chargeIdx);
  /* 只保留到达冲锋点之前的技能节点（含冲锋触发节点本身），其余随路径改写丢弃 */
  skillIndices = skillIndices.filter(idx => idx <= chargeIdx);
  pendingChargeInfo = { startIdx: chargeIdx + 1, triggerIdx: chargeIdx, dir: trigger.dir, budget };
  playerChargeStopReason = stopReason;
  playerChargeCausedDamage = false;
  playerChargeBudget = budget;
  playerChargeHits = 0;
  playerChargeDir = trigger.dir;
  const stopText = stopReason === 'budget' ? `走满 ${budget} 步额度` : stopReason === 'wall' ? '撞墙提前停止' : '达到地图边界';
  log(`风笛「高效冲击」已就绪：第 ${chargeIdx} 步发动后沿直线冲锋 ${chargePath.length} 步（剩余移动步数 ${budget}，${stopText}），最多 ${budget} 次攻击（每次近战伤害 ×2）。冲锋期间免疫伤害，禁用攻击节点。`);
  floatText(playerPath[chargeIdx].x, playerPath[chargeIdx].y, '高效冲击', '#ffd700');
  ringFx(playerPath[chargeIdx].x, playerPath[chargeIdx].y, '#ffd700');
  return chargeIdx;
}

function confirmAction() {
  /* 联机模式：不本地结算，先把这一回合的计划交给房间服务，等两边齐了再一起算 */
  if (mode === 'pvp') { pvpSubmitPlan(); return; }
  /* ISSUE-20261028-10-B：眩晕中只允许「原地不动」的确认 —
   * 必须放行空路径，否则玩家会被彻底卡住（点了没反应，回合永远推不过去）。 */
  if (player && player.stunTurns > 0
      && (playerPath.length > 1 || attackIndices.length > 0 || skillIndices.length > 0)) {
    log('🌀 眩晕中：本回合只能原地不动，规划已被清除。');
    playerPath = [{ x: player.x, y: player.y }];
    attackIndices = []; skillIndices = [];
    refreshBoardOnly();
    return;
 }
  phase = PHASE.RESOLVING;
  resetTurnState();
  clearEnemyArrows();
  levelActions += 1;   // 仅用于结算日志展示，不参与经验计算

  /* ★ 动作规划（必须在风笛改写路径之前算）：闪避 / 攻击 / 技能 共用动作预算 */
  const plan = plannedActionInfo(playerPath, attackIndices, skillIndices);
  dodgeTriggerIndex = plan.dodgeIndex;
  /* 玩家操作录制（默认关）：记录本回合玩家原始计划（路径 / 攻击 / 技能 / 闪避） */
  if (window.ARK_REC) {
    window.ARK_REC.turn({
      level: level, char: selectedChar, path: playerPath, attacks: attackIndices, skills: skillIndices,
      dodgeIndex: plan.dodgeIndex, waitSteps: countWaitSteps(playerPath), actions: plan.actions,
      player: player, enemies: enemies, kills: runKills,
 });
 }

  if (attackIndices.includes(0)) pendingAttack = true;
  /* ★ ISSUE-20261029-34：原地技能（技能节点在起点）——本回合第一个 tick 发动，不移动。
   * 结算侧在 resolveStep 开头消费这个标记。 */
  if (skillIndices.includes(0)) pendingStartSkill = true;

  /* 唯一需要提前改写路径的技能（冲锋）。冲锋会把「冲锋节点」之后的所有路径节点丢弃（设计如此） */
  const chargeApplied = prepareWheelchairCharge();
  /* 若闪避节点原本排在冲锋之后，它已被冲锋吞掉：把 dodge 标记归位，避免指向改写后路径的错误格子 */
  if (chargeApplied !== null && dodgeTriggerIndex > chargeApplied) {
    log('⚠️ 闪避节点位于「高效冲击」之后，已被冲锋吞掉，本次闪避不生效。');
    dodgeTriggerIndex = -1;
 }

  /* =========================================================
   * ★ 动作结算说明（plan 已在函数开头算好）
   * ========================================================= */
  if (plan.dodge) {
    log(`⚡ 闪避节点：第一个等待视为闪避动作（AC +${playerDodgeACBonus}，持续到回合结束），占一次动作。`);
 }
  if (plan.skillCount > 0) {
    log(`✦ 技能节点 ×${plan.skillCount}：到达对应路径步时发动技能（每个占一次动作）。`);
 }
  if (plan.actions > maxActionsThisTurn()) {
    log(`⚠️ 本回合规划了 ${plan.actions} 个动作（闪避/攻击/技能），超出上限 ${maxActionsThisTurn()}：按路径顺序先到先得，后面的不会生效。`);
 }

  render();
  /* ★ ISSUE-20261031-128：合作局不在这里本地开跑 —— 计划要先交给房间服务，
   * 等全员到齐再一起结算（否则两端的敌人走位会分叉）。
   * 本地自测（无房号）由 coopSubmitAndWait 内部退化成原生结算。 */
  if (mode === 'coop') { coopSubmitAndWait(); return; }
  setTimeout(() => resolveStep(1, 0), 300);
}

/* =========================================================
 * 通用 BFS（用于敌人寻路）
 * ========================================================= */
// 玩家规划路径去掉连续重复格，并保留每个位置对应的 tick（结算步序号）。
// 保留 tick 是关键：带等待步时「去重后的序号」和「tick」不是一回事，
// 混用会让敌人先冲过头、再折返回来（旧版实战里出现过 12,4 → 11,4 → 12,4）。
function getPlayerEffectivePositions() {
  const positions = [];
  for (let i = 0; i < playerPath.length; i++) {
    const p = playerPath[i];
    const last = positions[positions.length - 1];
    if (!last || last.x !== p.x || last.y !== p.y) {
      positions.push({ x: p.x, y: p.y, tick: i });
 }
 }
  if (positions.length === 0 && player) {
    positions.push({ x: player.x, y: player.y, tick: 0 });
 }
  return positions;
}

// 攻击欲望越高，越倾向于提前堵在玩家路径的更靠后处。
// 用确定性取整（不用 Math.random）：否则玩家每画一格、每次重绘都会重掷目标，
// 敌人意图箭头会不停抖动，「意图可预判」这个核心体验就没了。
// 当前回合下的攻击欲望：基础 wis + 每 2 回合 +1 感知的时间加成，再乘全局系数
function enemyAggression(wis) {
  const base = (wis === undefined || wis === null) ? 10 : wis;
  const aggrWis = base + Math.floor(battleRound / 2) * AGGRESSION_WIS_PER_TWO_ROUNDS;
  return Math.max(0, Math.min(1, aggrWis / 20)) * ENEMY_AGGRESSION_SCALE;
}

function sampleAggressionTargetIndex(n, p) {
  if (n <= 1) return 0;
  const raw = (n - 1) * Math.max(0, Math.min(1, p));
  return Math.max(0, Math.min(n - 1, Math.round(raw)));
}

// 选预判目标：按攻击欲望取索引，但只能取「本回合来得及走到」的位置
// （tick 超过自身移动力的点没有意义，BFS 够不到只会退化成最近的格子）。
function pickEnemyTarget(positions, aggression, move) {
  let idx = sampleAggressionTargetIndex(positions.length, aggression);
  while (idx > 0 && positions[idx].tick > move) idx--;
  return positions[idx];
}

/* =========================================================
 * ★ ISSUE-20261029-32：敌人索敌（候选 = 玩家 + 存活的小队成员）
 *
 * 人类 05:48 原话：
 *   「敌人现在似乎不会攻击召唤单位，优化：敌人选择距离最近的路径格进行索敌，
 *     意思是两个距离一样的单位，一个要远离敌人，一个要接近敌人，
 *     敌人会选择要接近自己的单位，因为路径格更近。」
 *
 * 于是距离度量不是「单位当前格到我的距离」，而是
 *   「**该单位的路径格**里离我最近的那一格」到我的距离：
 *   · 玩家 → playerPositions（玩家画出来的那条路径上的每一格）；
 *   · 成员 → 它本回合要走到的**下一格**（成员每回合朝最近的敌人走，见 squadAct）。
 * 于是「正在朝我走」的那个单位路径格更近 → 被优先锁定；「正在远离」的那个路径格更远 → 被放弃。
 *
 * ★ 为什么不用「当前格距离」：当前距离相同时两者无法区分，必须靠路径方向才能判别「谁在靠近」。
 * ★ 玩家侧仍然走 pickEnemyTarget 的 WIS 预判（高感知敌人去堵玩家路径末端），这条不变；
 *   成员不会预判（它每回合只朝最近的敌人走），所以直接追它的当前格。
 * ★ ~~平手时优先玩家（人类口径：谁近打谁，平手打玩家）~~
 *   ⚠️ ISSUE-20261030-57：这条**只管移动索敌、不管攻击选靶**，两处口径现在不同：
 *     · 移动（本函数）：仍然「谁近追谁、平手追玩家」—— 57 号 §8 明确不改寻路；
 *     · 攻击（enemyMeleeTarget / resolveAlienShots）：改成**优先打小队成员**。
 *   别把这句旧口径照抄进攻击结算，也别为了「攻击优先成员」反过来改这里的移动目标
 *   （改了会让敌人绕开玩家、追着成员跑，手感全变）。
 * ========================================================= */
/* ★ ISSUE-20261031-132：`skeletonBoneTarget()` 已搬到 `src/data/enemies.js`（与骸骨/骨头的
 * 其余逻辑放在一起，避免两处分叉）。调用点仍是本文件 `_generateEnemyPathsCore` 里那一句，名字没变。
 * 口径摘要：☠ 完全不管骨头；💀 无骨头目标时返回 null → 走普通敌人 AI 追打玩家。 */

function pickEnemyTargetFor(e, playerPositions, aggression, move, extraTracks) {
  const cands = [];
  if (playerPositions.length > 0) {
    let d = Infinity;
    for (const p of playerPositions) {
      const dd = Math.abs(p.x - e.x) + Math.abs(p.y - e.y);
      if (dd < d) d = dd;
 }
    cands.push({ kind: 'player', dist: d });
 }
  if (typeof squadAliveUnits === 'function') {
    for (const s of squadAliveUnits()) {
      const next = squadPredictedNextCell(s) || { x: s.x, y: s.y };
      const dd = Math.abs(next.x - e.x) + Math.abs(next.y - e.y);
      cands.push({ kind: 'squad', unit: s, dist: dd });
 }
 }
  /* ★ ISSUE-20261031-128：合作队友进索敌候选池（口径与小队成员完全一致 ——
   * 用「这回合要走到的那格」算距离，而不是当前格，否则「正在朝我走」的队友会被漏判）。
   * 单人局 `coopAllies` 为空，这一段零开销。 */
  if (typeof coopAliveAllies === 'function') {
    for (const a of coopAliveAllies()) {
      const next = coopPredictedNextCell(a) || { x: a.x, y: a.y };
      const dd = Math.abs(next.x - e.x) + Math.abs(next.y - e.y);
      cands.push({ kind: 'ally', unit: a, dist: dd });
 }
 }
  /* ★ 合作模式的「路径轨」：每个队友一条，用**整条计划路径**里离本敌人最近的那格算距离
   * （与玩家侧同一套度量），命中后按 WIS 预判取路径上更靠后的一格。 */
  if (Array.isArray(extraTracks)) {
    for (const t of extraTracks) {
      const ps = (t && t.positions) || [];
      if (!ps.length) continue;
      let dd = Infinity;
      for (const p of ps) {
        const d = Math.abs(p.x - e.x) + Math.abs(p.y - e.y);
        if (d < dd) dd = d;
 }
      cands.push({ kind: t.kind || 'ally', unit: t.unit, dist: dd, track: t });
 }
 }
  if (!cands.length) return null;
  let best = cands[0];
  for (let i = 1; i < cands.length; i++) {
    const c = cands[i];
    if (c.dist < best.dist) { best = c; continue; }
    if (c.dist === best.dist && c.kind === 'player' && best.kind !== 'player') best = c;
 }
  if (best.kind === 'player') {
    const t = pickEnemyTarget(playerPositions, aggression, move);
    return { x: t.x, y: t.y, tick: t.tick, kind: 'player' };
 }
  /* 有路径轨的（合作队友）按自己的路径做 WIS 预判，没有轨的（小队成员）追当前格。 */
  if (best.track) {
    const t = pickEnemyTarget(best.track.positions, aggression, move);
    return { x: t.x, y: t.y, tick: t.tick, kind: best.kind, unit: best.unit };
 }
  return { x: best.unit.x, y: best.unit.y, tick: 0, kind: best.kind, unit: best.unit };
}

function buildPathFromPrev(prev, endX, endY) {
  const path = [];
  let curX = endX, curY = endY;
  while (true) {
    path.push({ x: curX, y: curY });
    const p = prev.get(key(curX, curY));
    if (p === null || p === undefined) break;
    curX = p.x; curY = p.y;
 }
  path.reverse();
  return path;
}

// 通用 BFS：目标不可达时返回最近可达点
function bfsPathTo(startX, startY, targetX, targetY, maxSteps, isOccupiedAtFn, isGhost, startT) {
  if (startT === undefined) startT = 0;
  if (startX === targetX && startY === targetY) {
    return [{ x: startX, y: startY }];
 }
  const prev = new Map();
  prev.set(key(startX, startY), null);
  const q = [{ x: startX, y: startY, t: 0, d: Math.abs(startX - targetX) + Math.abs(startY - targetY) }];
  let best = { x: startX, y: startY, t: 0, d: q[0].d };
  const dirs = DIR4_BFS;
  // ★ 修复「敌人永远不靠近」：原来 BFS 只展开 maxSteps 步，且 best 只按「曼哈顿距离更近」更新。
  //   遇到必须绕路的地形（例如玩家上方/侧面是墙），绕路第一步必然离目标更远 →
  //   best 永远停在起点 → 返回只有起点的路径 → 敌人原地站桩、永远不去玩家位置。
  //   现在改成：全图 BFS 找真实最短路径，只把「本回合能走的步数」截断，
  //   余下的下回合接着走；确实不可达（目标被墙完全封死）才退回最近可达点。
  const LIMIT = 400;
  while (q.length > 0) {
    const cur = q.shift();
    if (cur.d < best.d) best = cur;
    if (cur.x === targetX && cur.y === targetY) {
      const full = buildPathFromPrev(prev, cur.x, cur.y);
      return full.length > maxSteps + 1 ? full.slice(0, maxSteps + 1) : full;
 }
    if (cur.t >= LIMIT) continue;
    for (const [dx, dy] of dirs) {
      const nx = cur.x + dx, ny = cur.y + dy;
      if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) continue;
      if (isGhost) {
        // 幽灵：内部区域移动，无视墙
        if (nx === 0 || nx === COLS - 1 || ny === 0 || ny === ROWS - 1) continue;
 } else {
        if (map[ny][nx] === 1) continue;
 }
      const nk = key(nx, ny);
      if (prev.has(nk)) continue;
      if (isOccupiedAtFn && isOccupiedAtFn(startT + cur.t + 1, nx, ny)) continue;
      prev.set(nk, cur);
      q.push({ x: nx, y: ny, t: cur.t + 1, d: Math.abs(nx - targetX) + Math.abs(ny - targetY) });
 }
 }
  return buildPathFromPrev(prev, best.x, best.y);
}

/* ★ ISSUE-20261031-119：飞碟🛸 随机游走路径。
 * 移动力 = enemyMoveOf(e)（体质12→但 dex8→移动4）；每步在可走且未被 occ[t] 占用的邻格里随机挑一个。
 * 不消耗 rng()（保持回放/同种子确定性）：用「坐标 + 步数 + 回合」做确定性但看似无序的索引。 */
function planUfoRandomPath(e, occ, maxT) {
  let cx = e.x, cy = e.y;
  const path = [{ x: cx, y: cy }];
  const steps = enemyMoveOf(e);
  for (let t = 1; t <= steps; t++) {
    const cands = [];
    for (const [dx, dy] of DIR4_BFS) {
      const nx = cx + dx, ny = cy + dy;
      if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) continue;
      if (map[ny][nx] === 1) continue;                 // 墙
      if (occ[t] && occ[t].has(key(nx, ny))) continue; // 被同伴/玩家占位
      cands.push({ x: nx, y: ny });
    }
    if (cands.length === 0) break;                    // 走不动就停在原地
    const pick = cands[(cx * 31 + cy * 17 + t * 13 + battleRound * 7) % cands.length];
    cx = pick.x; cy = pick.y;
    path.push({ x: cx, y: cy });
  }
  return path;
}

/* 某格是否被存活单位（玩家 / 小队 / 敌人）占据 */
function isCellOccupiedByUnit(x, y) {
  if (player && player.alive && player.x === x && player.y === y) return true;
  /* ★ ISSUE-20261031-128：合作闯关的队友也是占位单位 —— 飞碟投放 / 出生点搜索
   * 都会问这一格空不空，漏了队友就会在队友身上生成外星人。 */
  if (typeof coopCellTakenByAlly === 'function' && coopCellTakenByAlly(x, y)) return true;
  if (typeof squadUnits !== 'undefined' && squadUnits) {
    for (const s of squadUnits) if (s && s.alive && s.x === x && s.y === y) return true;
  }
  if (typeof enemies !== 'undefined' && enemies) {
    for (const o of enemies) if (o && o.alive && o.x === x && o.y === y) return true;
  }
  return false;
}

/* ★ ISSUE-20261031-119：飞碟在「离开的那一格」投放 1 只外星人👽。
 * 与飞碟共享 groupId（ufo.id）→ 经验结算算同一敌人；离开格被占则找相邻空格，都没空就跳过。 */
function spawnUfoMinion(ufo, cell) {
  let tx = cell.x, ty = cell.y;
  if (ty < 0 || ty >= ROWS || tx < 0 || tx >= COLS || map[ty][tx] === 1 || isCellOccupiedByUnit(tx, ty)) {
    const alt = [];
    for (const [dx, dy] of DIR4_BFS) {
      const nx = cell.x + dx, ny = cell.y + dy;
      if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) continue;
      if (map[ny][nx] === 1) continue;
      if (isCellOccupiedByUnit(nx, ny)) continue;
      alt.push({ x: nx, y: ny });
    }
    if (!alt.length) { log(`🛸 飞碟${ufo.id + 1}想投放外星人，但周围无空位，跳过。`); return; }
    tx = alt[0].x; ty = alt[0].y;
  }
  const idx = nextEnemyId++;
  const grow = computeEnemyGrowth('alien_grunt', battleLevel, idx, RUN_SEED);
  const a = grow.abilities;
  const prof = getEnemyProf('alien_grunt');
  const ac = computeAC(a);
  const mv = Math.max(1, Math.floor(a.dex / 2));
  const bd = ENEMY_STATS['alien_grunt'].dice || {};
  const md = bd.melee ? { n: bd.melee[0], s: bd.melee[1] } : null;
  const rd = bd.ranged ? { n: bd.ranged[0], s: bd.ranged[1] } : null;
  const hp = grow.maxHp;
  const m = {
    id: idx, groupId: ufo.id, x: tx, y: ty, hp, maxHp: hp, type: 'alien_grunt',
    move: mv, abilities: { ...a }, ac, prof,
    enemyLevel: grow.level, enemyGrowths: battleLevel,
    meleeDmg: diceAvg(md), rangedDmg: diceAvg(rd),
    meleeDice: md, rangedDice: rd, explodeDmg: 0,
    isElite: false, affixes: [], shieldLeft: 0, alive: true,
    attackedThisRound: false, facing: faceToward({ x: tx, y: ty }, player),
    amiyaRevealBonus: 0, amiyaRevealForNext: false, amiyaRevealActive: 0,
    stunTurns: 0, rockCd: 0,
  };
  enemies.push(m);
  log(`🛸 飞碟${ufo.id + 1}在 (${tx},${ty}) 投放了 1 只外星人👽（同组，经验结算算 1 个敌人）。`);
}

/* =========================================================================
 * ★ ISSUE-20261031-120：猴王召唤 / 猴子撒香蕉
 *
 * 两者都挂在本回合的「回合切换点」（endRound），与飞碟投放同一套写法：
 *   遍历中**不改** enemies 数组 → 先攒到 pending，循环外一次性投 → 再统一重规划 + 重绘。
 *   否则会踩到 #119 那三个坑：`enemies.length` 当 id（死敌不移除会串号）、
 *   `enemyPathOrder` 落位顺序被打乱（历史上「敌人永久罚站」的根因）、只 push 不重绘（图形延迟一格）。
 * ========================================================================= */

/* 全盘可落子的空格（避开墙 / 外圈 void / 所有存活单位 / 粗圆岩 / 已有道具）。
 * 猴王召唤与猴子撒香蕉共用这一份判定，避免两处口径漂移。 */
function freeSpawnCells() {
  const out = [];
  for (let y = 1; y < ROWS - 1; y++) {
    for (let x = 1; x < COLS - 1; x++) {
      if (map[y][x] === 1) continue;
      if (isCellOccupiedByUnit(x, y)) continue;
      if (roughRocks.has(key(x, y))) continue;
      if (rewardItems.some(r => r.x === x && r.y === y)) continue;
      out.push({ x, y });
    }
  }
  return out;
}

/* 猴王开技能：切形态（本回合立刻生效）+ 召唤 3 只🐒（受活体上限约束）。
 * 返回实际召唤成功的只数，供调用方决定要不要重规划。 */
function kingOpenSkill(king, form) {
  king.kingForm = form;
  const label = { '🙊': '禁技能', '🙉': '弱点无效', '🙈': '藏意图' }[form] || form;
  floatText(king.x, king.y, form + ' ' + label, '#ffd700', true);
  ringFx(king.x, king.y, '#ffd700');
  log(`🐵 猴王${king.id + 1} 开启技能 → 形态 ${form}（${label}）`);

  /* 活体上限：到顶就只切形态、不召唤（形态压制照常生效，不会白放技能）。
   * ⚠️ 与「每关最多 1 只飞碟」是两件事，那条是飞碟专属；这是通用上限。 */
  const alive = enemies.filter(e => e.alive).length;
  const room = Math.max(0, ALIVE_ENEMY_CAP - alive);
  if (room <= 0) {
    log(`🐵 场上活体已达上限 ${ALIVE_ENEMY_CAP}，本次不召唤（形态照常生效）。`);
    return 0;
  }
  const want = Math.min(MONKEY_KING_SUMMON, room);
  const pool = freeSpawnCells();
  if (!pool.length) {
    log(`🐵 棋盘上没有空位，本次不召唤。`);
    return 0;
  }
  let done = 0;
  for (let k = 0; k < want && pool.length; k++) {
    const pick = pool.splice(Math.floor(rng() * pool.length), 1)[0];
    if (spawnMonkeyMinion(king, pick)) done++;
  }
  log(`🐵 猴王召唤了 ${done} 只🐒（活体 ${alive + done}/${ALIVE_ENEMY_CAP}）。`);
  return done;
}

/* 召唤 1 只🐒。与 spawnUfoMinion 同构：唯一 id 走 nextEnemyId、groupId 跟随召唤者
 * （经验结算算同一个敌人，与 #119 的口径一致）。 */
function spawnMonkeyMinion(king, cell) {
  const idx = nextEnemyId++;
  const grow = computeEnemyGrowth('monkey', battleLevel, idx, RUN_SEED);
  const a = grow.abilities;
  const prof = getEnemyProf('monkey');
  const ac = computeAC(a);
  const mv = Math.max(1, Math.floor(a.dex / 2));
  const bd = ENEMY_STATS['monkey'].dice || {};
  const md = bd.melee ? { n: bd.melee[0], s: bd.melee[1] } : null;
  const rd = bd.ranged ? { n: bd.ranged[0], s: bd.ranged[1] } : null;
  const hp = grow.maxHp;
  enemies.push({
    id: idx, groupId: king.id, x: cell.x, y: cell.y, hp, maxHp: hp, type: 'monkey',
    move: mv, abilities: { ...a }, ac, prof,
    enemyLevel: grow.level, enemyGrowths: battleLevel,
    meleeDmg: diceAvg(md), rangedDmg: diceAvg(rd),
    meleeDice: md, rangedDice: rd, explodeDmg: 0,
    isElite: false, affixes: [], shieldLeft: 0, alive: true,
    attackedThisRound: false, facing: faceToward(cell, player),
    amiyaRevealBonus: 0, amiyaRevealForNext: false, amiyaRevealActive: 0,
    stunTurns: 0, rockCd: 0,
    kingForm: '', skillCd: 0, walkedThisTurn: [],
  });
  return true;
}

/* 猴子撒香蕉：在**本回合走过的路径格**里随机选 1 格放 1 根 🍌。
 * 人类口径（§2.6）：每回合最多 1 根（不是每走一步一根，否则移动力 4 的猴子一关铺满棋盘）。
 * 落点必须避开已有道具 / 单位 / 墙 —— 路径格里可能已经有别人站上去了。
 * 返回是否真的放了一根。 */
function placeBananaOnPath(monkey, walked) {
  const cands = walked.filter(c => c && !isCellOccupiedByUnit(c.x, c.y)
    && map[c.y] && map[c.y][c.x] !== 1
    && !roughRocks.has(key(c.x, c.y))
    && !rewardItems.some(r => r.x === c.x && r.y === c.y));
  if (!cands.length) return false;
  const pick = cands[Math.floor(rng() * cands.length)];
  /* ⚠️ `type` 字段是 #120 新加的：rewardItems 以前只有 {x,y}，分不清 ❤️ 与 🍌。
   *   旧数据（事件关地图生成器给的爱心）没有 type → 一律按 'heart' 读（见 tryPickup）。 */
  rewardItems.push({ x: pick.x, y: pick.y, type: 'banana' });
  return true;
}

function generateEnemyPaths() {
  if (phase !== PHASE.PLANNING) return;
  _generateEnemyPathsCore();
}

/* ★ ISSUE-20261031-128：真正的计算体。为什么要拆出来：
 * 合作模式下「所有人的计划都到齐」时相位已经不在 PLANNING（`confirmAction` 开头就切到
 * RESOLVING 了），但敌人意图必须按**全员路径**重算一遍 —— 否则每个客户端只按自己那条路径
 * 算敌人走位，两端的敌人位置会当场分叉（lockstep 立刻破功）。
 * 拆分让「等待队友」那条链路能绕过相位守卫，而单机侧的调用方式一个字都没变。 */
function _generateEnemyPathsCore() {
  enemyPaths = [];
  for (let i = 0; i < enemies.length; i++) enemyPaths.push([]);

  const playerPositions = getPlayerEffectivePositions();
  /* ★ ISSUE-20261031-128：队友的「路径轨」——敌人要按**全员**的路径轨选靶，
   * 单人局这里是空数组，索敌逻辑与改动前逐项一致。 */
  const allyTracks = (typeof coopAllyTracks === 'function') ? coopAllyTracks() : [];
  /* ★ ISSUE-20261028-14：dormant（静止敌人）不参与寻路 —— 教程的木桩/未激活巡逻敌
   * 全程原地，路径恒为自身格；否则它会跟着玩家走，木桩当场变成追人怪。 */
  const dormantList = enemies.filter(e => e.alive && e.dormant);
  for (const e of dormantList) enemyPaths[enemies.indexOf(e)] = [{ x: e.x, y: e.y }];
  const aliveList = enemies.filter(e => e.alive && !e.dormant);
  if (!aliveList.length || playerPositions.length === 0) {
    for (const e of enemies) if (e.alive) enemyPaths[enemies.indexOf(e)] = [{ x: e.x, y: e.y }];
    lastPathSignature = calcPathSignature();
    return;
 }

  // 占位表 occ[t] = 第 t 个 tick 结束时被占用的格子。
  // 关键修复：还没轮到的敌人先按「原地不动」把所有 tick 都预留住。
  // 旧版只预留 t=0，第一个 tick 却去查 t=1，于是计划层允许踩同伴、结算层 occNow 又拦下来，
  // 路径被 slice 截断 → 窄走廊里幽灵被前方骷髅永久堵死（实测 25 回合零进展）。
  const maxT = Math.max(...aliveList.map(e => enemyMoveOf(e))) + 1;
  const occ = [];
  for (let t = 0; t <= maxT; t++) occ.push(new Set());
  for (const e of aliveList) {
    for (let t = 0; t <= maxT; t++) occ[t].add(key(e.x, e.y));
 }
  /* ISSUE-20261029-28：小队成员也算占位（敌人不会穿过自己人/友军，否则两个图标叠在一格）。
   * ★ ISSUE-20261029-32：成员**同时**进了敌人的索敌候选池（人类 05:48 拍板：成员能被敌人打死）。
   *   于是占位规则变成「除本敌人的目标成员那一格外，其余成员格仍是障碍」——
   *   敌人要能走到目标成员面前打它，但不顺路撞到的其他成员不误伤。 */
  for (const s of squadUnits) {
    if (!s.alive) continue;
    for (let t = 0; t <= maxT; t++) occ[t].add(key(s.x, s.y));
 }
  /* ★ ISSUE-20261031-128：合作队友同样是占位（敌人不会穿过队友），
   * 且和成员一样可以被选为索敌目标 —— 所以「目标那一格」的例外在下面按 kind 一起处理。 */
  if (typeof coopAliveAllies === 'function') {
    for (const a of coopAliveAllies()) {
      for (let t = 0; t <= maxT; t++) occ[t].add(key(a.x, a.y));
 }
 }
  const isOccupiedAt = (t, x, y) => !!occ[t] && occ[t].has(key(x, y));

  // 离玩家近的敌人先算，占路优先级更高。
  // 旧版按数组顺序算，0 号敌人永远优先，容易出现「后排先占位、前排动不了」。
  const order = aliveList.slice().sort((a, b) =>
    (Math.abs(a.x - player.x) + Math.abs(a.y - player.y)) -
    (Math.abs(b.x - player.x) + Math.abs(b.y - player.y)));
  // 记下来给结算层用，保证两边顺序完全一致
  enemyPathOrder = order.map(e => enemies.indexOf(e));

  for (const e of order) {
    const idx = enemies.indexOf(e);
    if (e.stunTurns > 0) { enemyPaths[idx] = [{ x: e.x, y: e.y }]; continue; }

    /* ★ ISSUE-20261031-119：飞碟🛸 = 完全随机游走（不索敌、不贴脸）。
     * preMoveCell 记下来，回合结束投放👽时用作「离开的那一格」。 */
    if (e.type === 'ufo') {
      const upath = planUfoRandomPath(e, occ, maxT);
      e.preMoveCell = { x: e.x, y: e.y };
      const uLast = upath.length - 1;
      for (let t = 0; t < upath.length; t++) {
        const c = upath[Math.min(t, uLast)];
        if (occ[t]) occ[t].add(key(c.x, c.y));
      }
      for (let t = upath.length; t <= maxT; t++) occ[t].add(key(upath[uLast].x, upath[uLast].y));
      enemyPaths[idx] = upath;
      continue;
    }

    // 轮到它了：解除自己的静态预留，后面按真实路径重新占位
    for (let t = 0; t <= maxT; t++) occ[t].delete(key(e.x, e.y));

    const ghost = e.type === 'ghost';
    const wis = e.abilities.wis || 10;
    // 攻击欲望 = (基础 wis + 回合加成)/20，再乘全局系数（见 ENEMY_AGGRESSION_SCALE）。
    // 拖回合会让敌人越来越激进，20 回合后 10 感知的敌人就到顶。
    const aggression = enemyAggression(wis);
    // ★ 预判：目标取玩家路径上更靠后的位置（WIS 越高越靠后）
    // ★ ISSUE-20261029-32：候选池扩到「玩家 + 存活的小队成员」，
    //   距离度量 = 「该目标的路径格里离本敌人最近的那一格」。
    //   人类原话：「敌人选择距离最近的路径格进行索敌 —— 两个距离一样的单位，
    //   一个要远离敌人、一个要接近敌人，敌人会选择要接近自己的那个，因为路径格更近。」
    let target = pickEnemyTargetFor(e, playerPositions, aggression, enemyMoveOf(e), allyTracks);
    /* ★ ISSUE-20261031-118 R5：骷髅掉血过半后改去捡骨头（不贴身、有骨头时）。
     * 放在「贴身固定目标」补丁**之前**也安全：那个补丁只在 kind==='player' 时生效，
     * 骨头目标是 kind==='bone'，不会被覆盖。 */
    {
      const boneT = skeletonBoneTarget(e);
      if (boneT) target = boneT;
    }
    // ★ 补丁：角色周围 8 格（切比雪夫距离 ≤1）内的敌人，寻路目标固定为角色所在格，
    // 不会再预判到玩家路径末端、也不会随重绘改变。
    // ★ ISSUE-20261029-32：只在「玩家仍是选中目标」时套用；
    //   成员被选中时目标本来就是它的当前格，不需要这个补丁。
    if (target && target.kind === 'player' &&
        Math.abs(e.x - player.x) <= 1 && Math.abs(e.y - player.y) <= 1) {
      target = { x: player.x, y: player.y, tick: 0, kind: 'player' };
 }

    /* 目标单位那一格允许进入（敌人要能走到它面前打它）；其余占位照旧。
     * ★ ISSUE-20261031-128：`ally`（合作队友）与 `squad`（小队成员）在这件事上口径相同。 */
    const targetUnit = (target && (target.kind === 'squad' || target.kind === 'ally')) ? target.unit : null;
    const isOccupiedAtFor = function (t, x, y) {
      if (!occ[t] || !occ[t].has(key(x, y))) return false;
      if (targetUnit && x === targetUnit.x && y === targetUnit.y) return false;
      return true;
 };

    // BFS 得到的是简单路径（每格只访问一次），所以不会再出现「冲过去又退回来」。
    // 旧版这里还有一段「到达目标后追玩家实际位置」，那段会从目标点折返，
    // 实测 500 局面里 24 次出现 A→B→A 的来回抖动，已移除：
    // 敌人提前到达预判点后原地待命，玩家自己会走进来（这本身就是最好的拦截）。
    let path = bfsPathTo(e.x, e.y, target.x, target.y, enemyMoveOf(e), isOccupiedAtFor, ghost, 0);

    // ★ 反罚站补丁：同伴占位可能把窄口/凹槽里的敌人完全堵死（BFS 一步都扩展不出去、返回原地），
    // 且每回合重算结果相同 → 敌人永久罚站（实测外星人距离玩家 5 格、几何可达，连站 11 回合不动）。
    // 此时忽略同伴占位重算一次：宁可让它在结算层贴着同伴排队（taken 拦截重叠、同伴挪开即跟进），
    // 也不要原地站死。目标本来就是自己格（真没路可走）的不算堵塞。
    const targetIsSelf = target.x === e.x && target.y === e.y;
    if (path.length <= 1 && !targetIsSelf) {
      path = bfsPathTo(e.x, e.y, target.x, target.y, enemyMoveOf(e), null, ghost, 0);
 }

    // 路径上如果某一 tick 正好落在「玩家在该 tick 的位置」，就是贴脸/相杀，
    // 结算层会走相杀分支、不落位，敌人实际停在它的前一格。
    // 占位也要按这个来算，否则同伴会误判那格是空的，每回合刷「移动受阻」。
    let stopTick = path.length;
    for (let t = 1; t < path.length; t++) {
      const pp = t < playerPath.length ? playerPath[t] : playerPath[playerPath.length - 1];
      if (path[t].x === pp.x && path[t].y === pp.y) { stopTick = t; break; }
 }
    const lastIdx = path.length - 1;
    for (let t = 0; t < path.length; t++) {
      const c = path[Math.min(t, stopTick - 1)];
      if (occ[t]) occ[t].add(key(c.x, c.y));
 }
    // 路径走完后原地待命，剩下的 tick 继续占住落脚点
    const tail = path[Math.min(lastIdx, stopTick - 1)];
    for (let t = path.length; t <= maxT; t++) occ[t].add(key(tail.x, tail.y));

    enemyPaths[idx] = path;
 }

  lastPathSignature = calcPathSignature();
}

function clearItemCell(x, y) {
  const cell = getCellEl(x, y);
  if (cell) {
    /* ★ ISSUE-20261030-64：原来靠「内容里有没有 ❤ / 🩸 这两个字符」判断要不要清场，
     *   图标换成 <svg> 之后 textContent 里再也找不到字符 —— 改判 class，语义完全一致。 */
    const held = cell.classList.contains('item-cell') || cell.classList.contains('blood-cell')
      || cell.classList.contains('bone-cell')   /* ISSUE-20261031-118 */
      || cell.classList.contains('banana-cell'); /* ISSUE-20261031-120：🍌 与 ❤️ 共用 item-cell 的壳 */
    cell.classList.remove('item-cell', 'blood-cell', 'bone-cell', 'banana-cell');
    if (held) cell.innerHTML = '';
 }
}

/* 在指定格留下血迹（同一格只留一处）
 * ★ ISSUE-20261029-29：必须**当场重绘一次棋盘**。
 * 旧代码只 push 进数组，而结算里后续只调 refreshUnits()（它只刷单位层与数值，不刷格子），
 * 于是 🩸 要等下一次整盘 render() 才出现 —— 那时敌人已经走完这一步了：
 * 血留在 A 的旧位置，A 走开、B 路过，玩家看到的就是「血迹生成在了另一个敌人那里」。
 * 立刻重绘 → 血在被击中的那一格、在敌人还没动的那一刻出现。 */
function addBloodAt(x, y) {
  if (bloodDrops.some(b => b.x === x && b.y === y)) return false;
  bloodDrops.push({ x, y });
  log('华法琳的攻击留下了血迹 🩸！');
  try { refreshBoardOnly(); } catch (_) {}
  return true;
}

/* ★ ISSUE-20261031-132：玩家路过 🦴 就踩碎（人类拍板 9：能踩、**路过就算**、不需要停在那格，
 * 且不是「拾取」—— 骨头不进背包，踩掉就等于断绝那只 💀 的复活路）。
 * 为什么放在 tryPickup() 开头而不是逐分支写：
 *   `resolveStep` 的玩家位移段有 **三处**落位（正常落位 / 相杀后落位 / 冲锋撞死落位），
 *   三处都只调这一个函数 —— 挂这里等于一处覆盖全部，以后新增落位分支也不会漏。
 * ⚠️ 被 Boss 推开那格不走这里（那不是「走进来」），骨头会留到玩家下次落脚时清掉。 */
function playerStepOnBones() {
  if (typeof boneDrops === 'undefined' || !boneDrops || !boneDrops.length) return 0;
  let n = 0;
  for (let i = boneDrops.length - 1; i >= 0; i--) {
    if (boneDrops[i].x === player.x && boneDrops[i].y === player.y) { boneDrops.splice(i, 1); n++; }
  }
  if (n > 0) {
    floatText(player.x, player.y, '踩碎 🦴', '#e8d7b0');
    log('你踩碎了地上的 🦴：场上的 💀 骸骨失去复活目标，会转来追你。');
    try { refreshBoardOnly(); } catch (_) {}
  }
  return n;
}

function tryPickup() {
  playerStepOnBones();
  const rIdx = rewardItems.findIndex(r => r.x === player.x && r.y === player.y);
  if (rIdx >= 0) {
    /* ★ ISSUE-20261031-120：道具分两种 —— ❤️ 回 3 HP（原口径不变）、🍌 回 **1** HP（人类原话
     *   「角色经过香蕉所在格恢复1HP」）。两者共用「踩上去回血 + 消耗」这条流程，只有上限不同。
     * ⚠️ 旧数据（事件关地图生成器给的爱心）**没有 type 字段** → 按 ❤️ 处理，
     *   否则「事件关地图里一个血包都不回血」这种回退级 bug 会悄悄上线。 */
    const item = rewardItems[rIdx];
    const isBanana = !!item && item.type === 'banana';
    const healCap = isBanana ? 1 : 3;
    const label = isBanana ? '🍌 香蕉' : '❤️ 恢复道具';
    const heal = Math.min(player.maxHp - player.hp, healCap);
    if (heal > 0) {
      player.hp += heal;
      floatText(player.x, player.y, `+${heal} HP`, '#2ecc71');
      log(`拾取${label}，恢复 ${heal} HP！`);
 } else {
      log(`拾取${label}，但血量已满`);
 }
    rewardItems.splice(rIdx, 1);
    clearItemCell(player.x, player.y);
 }
  const bIdx = bloodDrops.findIndex(b => b.x === player.x && b.y === player.y);
  if (bIdx >= 0) {
    if (selectedChar === 'vampire') {
      /* 华法琳：血迹 = 1 技力 + 2 HP */
      const heal = Math.min(player.maxHp - player.hp, 2);
      if (heal > 0) { player.hp += heal; floatText(player.x, player.y, `+${heal} HP`, '#ff6b6b'); }
      const spBefore = vampireSp;
      const sass = sassExtraSp();
      vampireSp = Math.min(VAMPIRE_SP_MAX, vampireSp + 1 + sass);
      const spGain = vampireSp - spBefore;
      if (spGain > 0) floatText(player.x, player.y, `+${spGain} SP`, '#5cc9f5', false, -22);
      /* ★ ISSUE-20261028-14：教程血迹计数（华法琳课） */
      if (typeof tutorialOnBloodPicked === 'function') tutorialOnBloodPicked();
      log(`拾取血迹 🩸：技力 +${spGain}（${vampireSp}/${VAMPIRE_SP_MAX}）${sass ? '　🥤 香草沙士 +1' : ''}，${heal > 0 ? `恢复 ${heal} HP` : '血量已满无回血'}。`);
      if (spBefore < VAMPIRE_SP_MAX && vampireSp >= VAMPIRE_SP_MAX) {
        log('华法琳技力已满：右键路径节点（脚下那格也可以 = 原地施法）即可发动「不稳定血浆」。');
 }
 } else {
      const heal = Math.min(player.maxHp - player.hp, 1);
      if (heal > 0) {
        player.hp += heal;
        floatText(player.x, player.y, `+${heal} HP`, '#ff6b6b');
        log(`拾取血迹 🩸，恢复 ${heal} HP！`);
 }
 }
    bloodDrops.splice(bIdx, 1);
    clearItemCell(player.x, player.y);
 }
}

/* =========================================================
 * ★ 结算子步骤（resolveStep 拆出来的可独立阅读的单元）
 * 约定：会改玩家状态的函数返回 true = 玩家阵亡 / 对局结束，
 *       调用方必须立刻 return，避免在「已死」状态下继续结算。
 * ========================================================= */

/* 每个 tick 收尾：判负 / 判胜。返回 true 表示对局已结束。 */
async function settleTick() {
  if (player.hp <= 0) { endGame(); return true; }
  if (enemies.filter(e => e.alive).length === 0) { await finishLevel(); return true; }
  return false;
}

/* 敌人落位：按寻路顺序（离玩家近的优先）依次结算。
 * 先把自己从占位表里拿掉再查目标格 —— 这样「跟到同伴本 tick 腾出的格子」合法，
 * 「撞上还没走的同伴」仍然会被拦住。 */
/* =========================================================
 * ★ ISSUE-20261028-10-B：圆岩巨像的两个专属动作
 *
 * ① bossPushPlayer：Boss 走到玩家格 → 把玩家沿自己的前进方向推开 1 格并眩晕。
 * ② crushRoughRock：Boss 撞上（或把玩家推向）粗圆岩 → 石头碎、Boss 自伤 1。
 *
 * ★ 为什么推动要「替换」相杀而不是并存：
 *   相杀是「玩家主动撞进敌人的格」，而 Boss 是**主动走过来推人**。
 *   若沿用相杀，玩家会被锁在原地挨一次暴击 ×2 —— 那不是「被推开」，是「被处决」，
 *   与 issue 要的「逼玩家换站位」完全相反。
 * ★ 推不动也眩晕（issue §待确认 4 取「推不动也眩晕」）：接触即压制，
 *   否则玩家会发现「贴墙站就免疫」，Boss 的威胁可以零成本规避。
 * ========================================================= */

/* Boss 每 COLOSSUS_ROCK_EVERY 回合在玩家身边落一块粗圆岩。
 * 选格规则（issue §待确认 5 取「朝向最近的空格」）：
 *   在玩家四邻的空地里挑「离 Boss 最近」的那格 —— 石头会挡在玩家与 Boss 之间，
 *   玩家立刻能感受到「走位空间在变小」；并列时用全局 rng 打散，避免每次都落同一侧。
 * ★ 硬保护：落完之后不许把玩家四邻**全部**堵死。否则玩家会被永久困在原地，
 *   而「原地等待」并不能拆墙 —— 那是死局，不是难度。
 * 返回 true = 真的落了。 */
function placeRoughRock(boss) {
  if (!player || !player.alive) return false;
  const cands = DIR4
    .map(([dx, dy]) => ({ x: player.x + dx, y: player.y + dy }))
    .filter(p => p.x > 0 && p.y > 0 && p.x < COLS - 1 && p.y < ROWS - 1
      && map[p.y][p.x] !== 1
      && !roughRocks.has(key(p.x, p.y))
      && !enemies.some(e => e.alive && e.x === p.x && e.y === p.y)
      && !rewardItems.some(r => r.x === p.x && r.y === p.y));
  if (cands.length === 0) {
    log(`🗿 圆岩巨像${boss.id + 1} 想落石，但玩家四周没有空格，本次未落。`);
    return false;
 }
  /* 离 Boss 最近优先（并列随机） */
  let best = [], bestD = Infinity;
  for (const p of cands) {
    const d = cheb(p, boss);
    if (d < bestD) { bestD = d; best = [p]; }
    else if (d === bestD) best.push(p);
 }
  const pick = best[randInt(best.length)];
  /* 死局保护：预测落完之后玩家还能不能动 */
  const wouldTrap = DIR4.every(([dx, dy]) => {
    const x = player.x + dx, y = player.y + dy;
    if (x <= 0 || y <= 0 || x >= COLS - 1 || y >= ROWS - 1) return true;
    if (x === pick.x && y === pick.y) return true;
    return map[y][x] === 1;
 });
  if (wouldTrap) {
    log(`🗿 圆岩巨像${boss.id + 1} 想落石，但那会把玩家彻底堵死，本次未落。`);
    return false;
 }
  map[pick.y][pick.x] = 1;
  roughRocks.add(key(pick.x, pick.y));
  floatText(pick.x, pick.y, '落石!', '#c8a165');
  ringFx(pick.x, pick.y, '#c8a165');
  log(`🗿 圆岩巨像${boss.id + 1} 在 (${pick.x},${pick.y}) 落下一块粗圆岩（挡路，可被它自己撞碎）。`);
  return true;
}

/* 粗圆岩被圆岩巨像撞碎：石头消失、Boss 掉 1 HP。
 * ★ 打敌人只走 enemyTakeDamage（项目硬契约），这里不直接改 hp。 */
function crushRoughRock(boss, x, y) {
  roughRocks.delete(key(x, y));
  if (map[y] && map[y][x] === 1) map[y][x] = 0;
  const dealt = enemyTakeDamage(boss, COLOSSUS_ROCK_SELF_DAMAGE);
  floatText(x, y, '岩碎', '#ffd166');
  ringFx(x, y, '#ffd166');
  hitFlashCell(x, y);
  log(`⛰️ 粗圆岩被撞碎，圆岩巨像${boss.id + 1} 自伤 ${dealt} 点（剩 ${Math.max(0, boss.hp)}）。`);
  if (boss.hp <= 0) {
    killEnemy(boss, { floatMsg: '自毁', logText: `圆岩巨像${boss.id + 1} 被自己的石头撞碎` });
 }
}

/* ★ ISSUE-20261029-32：Boss 推开小队成员（Boss 走到成员格时）。
 *   与 bossPushPlayer 同构，但成员没有「眩晕」状态（眩晕是玩家专属）→ 只推开。
 *   推不动时成员留在原地（伤害在近战结算里给，不在这里）。 */
function bossPushSquad(boss, em, member) {
  const dx = Math.sign(em.to.x - em.from.x);
  const dy = Math.sign(em.to.y - em.from.y);
  const tx = member.x + dx, ty = member.y + dy;
  const blocked = !inBounds(tx, ty)
    || map[ty][tx] === 1
    || roughRocks.has(key(tx, ty))
    || (typeof squadUnitAt === 'function' && squadUnitAt(tx, ty))
    || (player && player.alive && player.x === tx && player.y === ty)
    || enemies.some(e => e.alive && e.x === tx && e.y === ty);
  if (!blocked) {
    member.x = tx; member.y = ty;
    if (dx || dy) member.facing = { dx: -dx, dy: -dy };
    floatText(tx, ty, '推开!', '#ff9f43');
    ringFx(tx, ty, '#ff9f43');
    log(`🗿 圆岩巨像${boss.id + 1} 把${member.icon} ${member.name}推开 1 格。`);
 } else {
    floatText(member.x, member.y, '推不动', '#bbb');
    log(`🗿 圆岩巨像${boss.id + 1} 想推开${member.name}，但后面被挡住了。`);
 }
}

/* 返回 true = 玩家真的被推走了；false = 推不动（但玩家照样眩晕） */
function bossPushPlayer(boss, em, taken, eIdx) {
  const dx = Math.sign(em.to.x - em.from.x);
  const dy = Math.sign(em.to.y - em.from.y);
  const tx = player.x + dx, ty = player.y + dy;

  /* 玩家身后正好是粗圆岩 → 先撞碎（Boss 自伤 1），碎完之后那格才可能站人 */
  if (roughRocks.has(key(tx, ty))) {
    crushRoughRock(boss, tx, ty);
    if (!boss.alive) return false;
 }

  const blocked = !inBounds(tx, ty)
    || map[ty][tx] === 1
    || roughRocks.has(key(tx, ty))
    || taken.has(key(tx, ty))
    || (enemies.some(e => e.alive && e.id !== boss.id && e.x === tx && e.y === ty))
    /* 不能把玩家推出地图可视区（外圈是 void，地图外一律不可站） */
    || (tx <= 0 || ty <= 0 || tx >= COLS - 1 || ty >= ROWS - 1);

  const px = player.x, py = player.y;
  if (!blocked) {
    player.x = tx; player.y = ty;
    if (dx || dy) player.facing = { dx: -dx, dy: -dy };   // 面朝 Boss（晕着也得知道是谁推的）
    taken.delete(key(boss.x, boss.y));
    boss.x = px; boss.y = py;
    taken.set(key(boss.x, boss.y), boss);
    floatText(px, py, '推开!', '#ff9f43');
    floatText(tx, ty, '眩晕', '#ffd166');
    ringFx(px, py, '#ff9f43');
    log(`🗿 圆岩巨像${boss.id + 1} 把玩家推开 1 格，你眩晕了（下一回合无法行动）。`);
 } else {
    floatText(player.x, player.y, '推不动', '#bbb');
    log(`🗿 圆岩巨像${boss.id + 1} 想推开玩家，但后面被挡住了（推不动，仍然眩晕）。`);
    /* 推不动 → Boss 不前进，停在原格；它的路径在这里截断，避免「下一 tick 直接穿人」 */
    if (enemyPaths[em.enemyIdx]) enemyPaths[em.enemyIdx] = enemyPaths[em.enemyIdx].slice(0, eIdx + 1);
 }

  player.stunTurns = COLOSSUS_PUSH_STUN;
  player.stunNoticeShown = false;   // 新一次眩晕 → 允许再提示一次
  refreshUnits();
  return !blocked;
}

/* 眩晕拦截的统一提示（只喊一次，别让每次点格子都刷一行日志） */
function stunBlockOnce() {
  if (!player || !(player.stunTurns > 0)) return;
  if (player.stunNoticeShown) return;
  player.stunNoticeShown = true;
  log('🌀 眩晕中：本回合无法移动 / 攻击 / 技能。点「开始」只能原地承受这一回合。');
  floatText(player.x, player.y, '眩晕', '#ffd166');
}

/* ========================= 相杀判定（唯一出口） =========================
 * ★ ISSUE-20261031-124（人类 21:13 原话：「相杀bug 玩家和敌人相邻的时候，互相朝对方格移动，
 *   不应该触发相杀，因为不是进入同一格」）。
 *
 * 「相杀」= 双方**同时进入同一格**之后才一起出手互吃双倍近战伤害 —— 前提是那一格被两人同占。
 *
 * ⚠️ 修复前这里还有第二条判据 `isSwap`：
 *      const isSwap = playerFrom.x === em.to.x && playerFrom.y === em.to.y &&
 *                     targetPos.x === em.from.x && targetPos.y === em.from.y;
 *    它描述的是「两人各走到对方的格子」，也就是**擦肩而过**：
 *      修复前（错）  玩家 A / 敌人 B → 玩家去 B、敌人去 A → 判成相杀，双方都不落位、各吃 ×2
 *      修复后（对）  同上动作 → 正常落位：玩家在 B、敌人在 A，一格一人，谁都没被同占
 *    「互换位置」的结果里没有任何一格被两人同占，因此不构成相杀。整条 `isSwap` 已删除。
 *    （删除后这两个人就落回下面「走到敌人正在离开的格子」那条既有分支：`willMoveAway`
 *      放行 → 玩家正常落位，敌人随后由 applyEnemyMoves 回到玩家原位，不会叠格。）
 *
 * 联机侧 `src/net/pvp-core.js` 的「互换位置 → clash」是逐字对应的同一判据，已同步删除。
 * 谁要再想加「互换也算相杀」，先把上面这段读完，并且改 pvp-core 与三套测试一起改。
 */
function isShootoutStep(targetPos, em) {
  return targetPos.x === em.to.x && targetPos.y === em.to.y;
}

function applyEnemyMoves(enemyMoves, eIdx, killedEnemyIds) {
  const taken = new Map();
  for (const e of enemies) if (e.alive) taken.set(key(e.x, e.y), e);

  const orderIndex = new Map(enemyPathOrder.map((idx, i) => [idx, i]));
  const moveQueue = enemyMoves.slice().sort((a, b) => {
    const ia = orderIndex.has(a.enemyIdx) ? orderIndex.get(a.enemyIdx) : 999;
    const ib = orderIndex.has(b.enemyIdx) ? orderIndex.get(b.enemyIdx) : 999;
    return ia - ib;
 });

  for (const em of moveQueue) {
    if (killedEnemyIds.has(em.enemyIdx)) { taken.delete(key(em.from.x, em.from.y)); continue; }
    if (!em.unit.alive) continue;
    if (em.unit.stunTurns > 0) continue;
    const u = em.unit;

    /* ★ ISSUE-20261028-10-B：圆岩巨像走到玩家格 = 推开 + 眩晕，不是相杀。
     * 必须放在「相杀」分支之前 —— 否则玩家会在原地被暴击 ×2，而不会被推开。 */
    if (u.type === BOSS_TYPE && em.to.x === player.x && em.to.y === player.y) {
      bossPushPlayer(u, em, taken, eIdx);
      continue;
 }

    /* ★ ISSUE-20261029-32：Boss 走到小队成员格 → 推开它 1 格。
     *   成员没有「眩晕」状态（眩晕是玩家专属），所以只推开、不压制；
     *   推不动时成员留在原地（也不会死在这里，伤害在近战结算里给）。 */
    if (u.type === BOSS_TYPE) {
      const sqB = (typeof squadUnitAt === 'function') ? squadUnitAt(em.to.x, em.to.y) : null;
      if (sqB) {
        bossPushSquad(u, em, sqB);
        if (enemyPaths[em.enemyIdx]) enemyPaths[em.enemyIdx] = enemyPaths[em.enemyIdx].slice(0, eIdx + 1);
        continue;
 }
 }

    // 走到玩家身上 → 相杀（交给相杀逻辑处理，这里不落位，仍占自己的格）
    if (em.to.x === player.x && em.to.y === player.y) {
      u.facing = faceToward(u, player);
      if (enemyPaths[em.enemyIdx]) {
        enemyPaths[em.enemyIdx] = enemyPaths[em.enemyIdx].slice(0, eIdx + 1);
 }
      continue;
 }
    /* ★ ISSUE-20261029-32：走到小队成员身上 → 停下打它（成员不再是无敌的）。
     *   与「撞到玩家」同构：不落位（停在原地，成员那一格不被占据），
     *   具体伤害由 resolveEnemyMeleeAttacks 统一结算（近战贴身那一段）。
     *   ⚠️ 原注释「顺序放在玩家分支之后：平手时打玩家（人类 05:48 口径）」已作废 ——
     *      ISSUE-20261030-57 把**攻击选靶**改成优先打成员；但「撞到人」本身不涉及选靶
     *      （撞谁都停下），所以这里的分支顺序仍然保留：同格时先按相杀处理玩家。 */
    const sqAt = (typeof squadUnitAt === 'function') ? squadUnitAt(em.to.x, em.to.y) : null;
    if (sqAt) {
      u.facing = faceToward(u, sqAt);
      if (enemyPaths[em.enemyIdx]) {
        enemyPaths[em.enemyIdx] = enemyPaths[em.enemyIdx].slice(0, eIdx + 1);
 }
      continue;
 }

    /* ★ ISSUE-20261031-128：走到合作队友身上 → 与「撞到小队成员」同构：停下打它，不落位。
     *   寻路层（`isOccupiedAtFor`）对 `ally` 特意放开了目标格，敌人本来打算走进去，
     *   所以这里**必须**有这道拦截，否则敌人会和队友叠在同一格 ——
     *   叠格之后两边都判不出相邻（曼哈顿距离 0），队友反而变成打不到的靶子。
     *   实测：3 人自测局第 2 回合复现（`enemy#1` 与 `ally#1` 同占 (2,4)）。 */
    const allyAt = (typeof coopAllyAt === 'function') ? coopAllyAt(em.to.x, em.to.y) : null;
    if (allyAt) {
      u.facing = faceToward(u, allyAt);
      if (enemyPaths[em.enemyIdx]) {
        enemyPaths[em.enemyIdx] = enemyPaths[em.enemyIdx].slice(0, eIdx + 1);
 }
      continue;
 }
    if (em.to.x === u.x && em.to.y === u.y) continue;

    /* ★ ISSUE-20261028-10-B：目标格是粗圆岩 → 撞碎（自己掉 1 HP），碎掉之后才落位。
     * 正常寻路不会主动走向墙，但「玩家被推向石头 → 石头碎 → 玩家站到碎掉的位置」
     * 与「Boss 贴着石头被挤」都会走到这里。 */
    if (roughRocks.has(key(em.to.x, em.to.y))) {
      crushRoughRock(u, em.to.x, em.to.y);
      if (!u.alive) {
        if (enemyPaths[em.enemyIdx]) enemyPaths[em.enemyIdx] = enemyPaths[em.enemyIdx].slice(0, eIdx + 1);
        continue;
 }
 }

    const destKey = key(em.to.x, em.to.y);
    taken.delete(key(u.x, u.y));
    /* ★ ISSUE-20261030-57 §4.3：敌人不得与友方同格 —— 落位前的最终兜底。
     * 理论上上面 3 个分支（Boss 推开玩家 / 推开成员 / 撞玩家相杀 / 撞成员停下）已经把
     * 所有「落点是友方」的情况拦完了；真走到这里说明后来新增了分支却忘了处理。
     * 宁可让它站着不动，也不要让敌人和玩家 / 成员叠格 —— 叠格会破坏 56 号的斜分显示
     * （那一格到底是「一个敌人」还是「敌人 + 玩家」就再也看不出来了）。 */
    if ((player && player.alive && em.to.x === player.x && em.to.y === player.y)
        || (typeof squadUnitAt === 'function' && squadUnitAt(em.to.x, em.to.y))
        || (typeof coopAllyAt === 'function' && coopAllyAt(em.to.x, em.to.y))) {
      taken.set(key(u.x, u.y), u);
      if (enemyPaths[em.enemyIdx]) {
        enemyPaths[em.enemyIdx] = enemyPaths[em.enemyIdx].slice(0, eIdx + 1);
 }
      continue;
 }
    if (taken.has(destKey)) {
      taken.set(key(u.x, u.y), u);   // 走不了，把格子放回去
      if (enemyPaths[em.enemyIdx]) {
        enemyPaths[em.enemyIdx] = enemyPaths[em.enemyIdx].slice(0, eIdx + 1);
 }
      log(`敌人${u.id + 1}移动受阻，停止前进`);
      continue;
 }
    u.x = em.to.x;
    u.y = em.to.y;
    taken.set(destKey, u);

    /* ★ ISSUE-20261031-120：记录🐒 本回合**真的走过**哪些格（撒香蕉只在这些格里挑）。
     * 必须在落位成功之后记 —— 受阻 / 相杀 / 推开 / 撞碎的分支都在上面 continue 了，
     * 那些格子它其实没走到；提前记会撒出「它根本没经过的地方」。 */
    if (u.type === 'monkey') (u.walkedThisTurn || (u.walkedThisTurn = [])).push({ x: u.x, y: u.y });

    /* ★ ISSUE-20261031-132：💀 骸骨落到 🦴 上 → 立刻复活成 ☠（满血、原属性、当回合不能再动）。
     * 挂在这里而不是寻路里：寻路只是「打算去哪」，落位才是「真的踩上去了」；
     * 受阻 / 相杀 / 推开 / 被撞碎的分支都在上面 continue 了，不会误触发。
     * 旧 #118 的「☠ 踩骨头 +2 HP」已整段下线。 */
    if (typeof skeletonCorpseReachBone === 'function') skeletonCorpseReachBone(u);

    const dx = Math.sign(em.to.x - em.from.x);
    const dy = Math.sign(em.to.y - em.from.y);
    if (dx || dy) u.facing = { dx, dy };
 }
}

/* 攻击节点结算：近战范围攻击 / 远程射击。返回 true = 玩家阵亡。 */
async function resolvePlayerAttack() {
  const maxAttacks = maxAttacksThisTurn();

  if (selectedChar === 'wheelchair' && playerChargingThisTurn) {
    log('冲锋状态禁止攻击节点，本次攻击取消。');
    floatText(player.x, player.y, '禁止攻击', '#bbb');
    return false;
 }
  if (selectedChar === 'fencer' && fencerCounterActive) {
    log('反击状态禁止攻击节点，本次攻击取消。');
    floatText(player.x, player.y, '禁止攻击', '#bbb');
    return false;
 }

  /* ---- 近战：周围 1 格全部目标 ----
   * ★ ISSUE-20261028-19：这里原本写的是 `selectedChar === 'wheelchair' || selectedChar === 'fencer'`。
   *   预备干员的攻击类型由加点决定，用角色名判断会把它直接送进下面的远程分支（近战角色打 3 格）。
   *   改成按「当前攻击类型」判定：静态四人结果完全不变，预备干员按 int 与 str 的大小走。 */
  if (!playerIsRanged()) {
    if (!(playerAttacksDone < maxAttacks && canPerformAttackAction())) return false;
    playerAttacksDone++;
    playerActionsUsed++;   // 攻击占用一次动作
    const atkPip = noteActionPip('attack');   // ISSUE-20261030-77：点亮攻击格，伤害结算完回填数字
    let atkPipDealt = 0;
    const targets = enemies.filter(e => e.alive && cheb(e, player) === 1);
    if (targets.length === 0) {
      log('近战范围攻击挥空，未命中任何敌人。');
      floatText(player.x, player.y, '挥空', '#bbb');
      finishActionPip(atkPip, 0);
      refreshUnits();
      await sleep(200);
      return false;
 }
    const strMod = abilityMod(player.abilities.str);
    /* ISSUE-20261029-28：预备干员「每次造成弱点攻击 +1 技力」。
     * 一次出手打多个目标也只给 1 点（否则扇形一扫就满技力，召唤会变成每回合都能放）。 */
    let rookieSpGained = false;
    for (const target of targets) {
      if (target.hp <= 0) continue;
      const atk = attackRoll(strMod, player.meleeProf || 0, target.ac);
      /* ISSUE-20261028-15 A1：正对目标 → 必中（覆盖自然1，B1）。仍是掷过骰的。 */
      applyFacingGuaranteedHit(atk, target);
      if (!atk.hit) {
        missFx(target.x, target.y);
        log(`近战范围攻击未命中敌人${target.id+1} (${fmtRoll(atk, target.ac)})`);
        refreshUnits();
        await sleep(120);
        continue;
 }
      /* 伤害 = 2d4 + 力量修正 + 锈蚀刀片（每次都掷一次），冲锋/暴击再乘在总伤害上 */
      let dmg = rollPlayerMeleeDamage();
      if (selectedChar === 'wheelchair' && playerChargingThisTurn) dmg *= 2;
      const critTag = meleeCritTag(target, atk, 'cone');
      const isCrit = !!critTag;
      /* A3：弱点必中在暴击来源之后追加，自然20 的优先级不被覆盖 → 「自然20暴击 · 必定命中」 */
      const hitTag = atk.facingHit ? ' · 必定命中' : '';
      if (isCrit) dmg *= 2;
      /* ★ ISSUE-20261031-118 R4：`atk.facingHit` 就是「弱点攻击」的统一标记 ——
       * dnd.js#applyFacingGuaranteedHit() 已经把近战（面向三格扇形）与远程（同行同列）两把尺子
       * 合成了一个布尔，这里直接透传，不再另写一套判定。 */
      const dealt = enemyTakeDamage(target, dmg, { weak: !!atk.facingHit });
      atkPipDealt += dealt;   // ISSUE-20261030-77：多目标累加，攻击格显示本次总伤害
      if (selectedChar === 'wheelchair' && playerChargingThisTurn) playerChargeCausedDamage = true;
      if (selectedChar === 'amiya') amiyaMarkReveal(target);
      /* ★ ISSUE-20261031-100：「荆棘」词条已删除，`enemyThornsReflect` 调用点同步移除。 */
      if (dealt === 0) { refreshUnits(); await sleep(120); continue; }
      /* 朝向 = 玩家朝向扇形（与「弱点暴击」同一个判定）。只有真打出伤害才算「造成攻击」。
       * ★ ISSUE-20261031-120：🙉 形态下没有「弱点攻击」这回事，技力也不给
       *   （否则「弱点」被格挡、技力却照给，玩家会以为机制坏了）。 */
      if (!rookieSpGained && selectedChar === 'rookie' && isInFacingCone(player, target)
          && !(typeof kingDisablesWeak === 'function' && kingDisablesWeak())) {
        rookieSpGained = true;
        gainRookieSp(ROOKIE_SP_PER_ATTACK);
 }
      slashFx(target.x, target.y, isCrit ? '#ffd700' : '#ffb86b');
      hitFlashCell(target.x, target.y);
      if (isCrit) {
        ringFx(target.x, target.y, '#ff4500');
        floatText(target.x, target.y, critTag + hitTag + ' -' + dmg, '#ffd700', true);
        log(`近战范围${critTag}${hitTag}敌人${target.id+1}，造成${dmg}伤害 (${fmtRoll(atk, target.ac)})`);
 } else {
        ringFx(target.x, target.y, '#ffb86b');
        floatText(target.x, target.y, hitTag ? '必定命中 -' + dmg : '-' + dmg, hitTag ? '#ffd700' : '#ff6b6b');
        log(`近战范围命中${hitTag}敌人${target.id+1}，造成${dmg}伤害 (${fmtRoll(atk, target.ac)})`);
 }
      if (target.hp <= 0) killEnemy(target, { showRing: false });
      refreshUnits();
      await sleep(200);
 }
    finishActionPip(atkPip, atkPipDealt);
    return false;
 }

  /* ---- 远程：射程 + 视线，一次攻击可覆盖多个目标 ---- */
  if (playerChargingThisTurn) {
    log('冲锋中无法远程攻击。');
    return false;
 }
  if (!(playerAttacksDone < maxAttacks && canPerformAttackAction())) return false;
  playerAttacksDone++;
  playerActionsUsed++;   // 远程攻击占用一次动作（打空同样消耗，与近战一致）
  const atkPip = noteActionPip('attack');   // ISSUE-20261030-77：点亮攻击格，伤害结算完回填数字
  let atkPipDealt = 0;

  const fromPos = { x: player.x, y: player.y, range: player.range };
  let targets = enemies.filter(e => e.alive && canRangedAttack(fromPos, e));
  if (targets.length === 0) {
    log('远程攻击节点无视线内目标，挥空（已消耗攻击次数）。');
    floatText(player.x, player.y, '挥空', '#bbb');
    finishActionPip(atkPip, 0);
    refreshUnits();
    await sleep(160);
    return false;
 }
  /* ★ ISSUE-20261030-61（人类 2026-10-30 03:09「朝向是绝对优先」）：
   *   正前方一条直线上的敌人排最前，其余按距离。
   *   为什么把 shooter 提到这里：它原本定义在循环之前（晚于本排序），
   *   导致「排序不看朝向、判定看朝向」两套口径打架 —— 正前方有敌人却去打更近的背后那只。
   *   上移后排序与必中判定共用同一个 shooter，且同一 tick 内 player / playerPath 不变，结果等价。
   *   ★ 注意：这是远程分支专用的「渲染朝向」（playerFacingForRanged），近战仍用 player.facing。 */
  const shooterFacing = (typeof playerFacingForRanged === 'function') ? playerFacingForRanged() : player.facing;
  const shooter = { x: player.x, y: player.y, facing: shooterFacing };
  targets.sort((a, b) => {
    const fa = isFacingCross(shooter, a) ? 0 : 1;
    const fb = isFacingCross(shooter, b) ? 0 : 1;
    return (fa - fb) || (cheb(a, fromPos) - cheb(b, fromPos));
 });
  targets = targets.slice(0, 1 + player.extraTargets);
  const intMod = abilityMod(player.abilities.int);
  /* 不稳定血浆：本关内远程攻击必定命中 + 必定暴击 */
  const vampPlasma = selectedChar === 'vampire' && vampireSkillActive;
  const actionCrit = vampPlasma || rng() < player.critChance;
  if (vampPlasma) log('「不稳定血浆」：本次攻击必定命中、必定暴击、必定留血迹！');
  else if (actionCrit) log('本次攻击行动触发暴击，所有目标共享！');

  const hits = [];
  const bulletPromises = [];
  for (const target of targets) {
    if (target.hp <= 0) continue;
    const atk = attackRoll(intMod, player.rangedProf || 0, target.ac);
    /* ★ ISSUE-20261029-33 + 20261030-61 + 20261030-88：远程角色的「弱点攻击」。
     *   33 号口径：正前方那一 line → 必定命中（覆盖自然 1）。
     *   61 号口径：「弱点攻击就是暴击伤害」→ 追加 ×2。
     *   **88 号口径（现行）**：判定尺子换成 isFacingCross —— 同行 / 同列**四个方向**、
     *     无限格、中间有墙则不算。人类 2026-10-30 拍板「共线即暴击（维持现状）」。
     *   ★ 三处必须同一把尺子：必中（本行）· 暴击（facingCrit）· 选目标排序（targets.sort）·
     *     技力 +5（isFacingAttack）。人类原话「必中就是弱点暴击，两者是一样的概念」，
     *     少换一处就会出现「打不中但一打中就翻倍」这类自相矛盾。
     *   ★ 近战**不动**：3901 行仍是 2 参数（isFacingTarget 单方向），meleeCritTag 用 isInFacingCone。 */
    applyFacingGuaranteedHit(atk, target, shooter, isFacingCross);
    if (vampPlasma && !atk.hit) { atk.hit = true; atk.forcedHit = true; }
    /* ★ ISSUE-20261030-61（人类「弱点攻击就是暴击伤害」）：朝向 → 必中 + 伤害 ×2。
     *   优先级与近战 meleeCritTag 同序：自然20 > 朝向 > 行动暴击（不稳定血浆 / 8% 随机）。
     *   ★ 远程「弱点攻击」已扩展为十字（isFacingCross：同行/同列、无墙遮挡、无限格），
     *     仍只在远程分支内联，不碰近战 meleeCritTag（近战弱点必中保持单方向）。
     *   ★ ISSUE-20261031-120（🙉 猴王形态）：弱点暴击整条失效 —— 必中已在
     *     applyFacingGuaranteedHit 里掐掉（那里直接 return 就不会置 atk.facingHit），
     *     这里再把「十字朝向 = 暴击」这一支一起关掉；自然20 / 行动暴击照旧。 */
    const weakOk = !(typeof kingDisablesWeak === 'function' && kingDisablesWeak());
    const facingCrit = weakOk && atk.hit && isFacingCross(shooter, target);
    const critTag = !atk.hit ? ''
      : atk.nat20 ? '自然20暴击'
      : facingCrit ? '弱点暴击'
      : actionCrit ? '暴击' : '';
    const isCrit = !!critTag;
    hits.push({ target, hit: atk.hit, isCrit, atk, critTag });
    /* ISSUE-20261031-114：普通远程 —— 只有阿米娅换成单音符 🎵，华法琳仍走黄圆点 */
    bulletPromises.push(animateBullet(fromPos, 'enemy-' + target.id, target, isCrit, false, 'player',
                                      selectedChar === 'amiya' ? 'musical_note' : ''));
 }
  if (hits.length > 0) {
    await Promise.all(bulletPromises);
    await sleep(80);
    for (const { target, hit, isCrit, atk, critTag } of hits) {
      /* 只要出手（即使 MISS）就能看到目标意图 */
      if (selectedChar === 'amiya') amiyaMarkReveal(target);
      /* 华法琳：血迹只由远程攻击产生 —— 不稳定血浆生效时必定留，平时命中后 50% */
      if (selectedChar === 'vampire' && hit && (vampPlasma || rng() < 0.5)) {
        addBloodAt(target.x, target.y);
 }
      if (hit) {
        const dmg = rollPlayerRangedDamage() * (isCrit ? 2 : 1);
        const forcedTag = (atk.forcedHit || atk.facingHit) ? ' · 必定命中' : '';
        /* ★ ISSUE-20261031-118 R4：远程的弱点攻击 = 同行/同列（isFacingCross），同样由 facingHit 标记 */
        const dealt = enemyTakeDamage(target, dmg, { weak: !!atk.facingHit });
        atkPipDealt += dealt;   // ISSUE-20261030-77：多目标累加，攻击格显示本次总伤害
        if (target.hp <= 0) {
          killEnemy(target, { showRing: true, showFloat: true, logText: `敌人${target.id+1}被击败（远程击杀）` });
 }
        if (dealt === 0) {
          /* 护盾词缀已吸收，伤害表现交给 enemyTakeDamage 的提示 */
 } else if (isCrit) {
          hitFx(target.x, target.y, dealt, true, critTag);
          log(`玩家远程${critTag}敌人${target.id+1}，造成${dealt}伤害 (${fmtRoll(atk, target.ac)})${forcedTag}`);
 } else {
          hitFx(target.x, target.y, dealt, false);
          log(`玩家远程命中敌人${target.id+1}，造成${dealt}伤害 (${fmtRoll(atk, target.ac)})${forcedTag}`);
 }
 } else {
        missFx(target.x, target.y);
        log(`玩家远程未命中 (${fmtRoll(atk, target.ac)})`);
 }
 }
 }
  /* ISSUE-20261030-77：远程攻击的总伤害回填到攻击格（全 MISS / 被护盾吃光 → 0，不显示数字）。
   * 放在技力结算之前，是为了让玩家在子弹落点消隐前就看到格子里的数字。 */
  finishActionPip(atkPip, atkPipDealt);
  /* 阿米娅：每次攻击（攻击节点出手，无论命中与否）+1 技力 */
  /* 阿米娅：每次攻击（攻击节点出手，无论命中与否）+1 技力。
   * ★ ISSUE-20261030-58 被动：本次出手的目标里有位于「十字四向（同行或同列、无墙遮挡）」上的
   *   （isFacingCross），就是「打出弱点攻击」→ 额外 +5。 */
  if (selectedChar === 'amiya') {
    /* ★ ISSUE-20261031-120：🙉 形态下没有「弱点攻击」，额外 +5 也一并关掉
     * （与近战侧预备干员的口径一致：机制被格挡，就不该再触发它的附属收益）。 */
    const isFacingAttack = !(typeof kingDisablesWeak === 'function' && kingDisablesWeak())
      && hits.some(h => h.target && isFacingCross(shooter, h.target));
    amiyaGainAttackSp(isFacingAttack);
 }
  /* ISSUE-20261029-28：预备干员的远程形态没有「朝向」概念（射程 3 走视线），
   * 按「本次出手至少命中一个目标」等价处理 —— 否则远程形态永远攒不到技力，召唤形同不存在。 */
  if (selectedChar === 'rookie' && hits.some(h => h.hit)) gainRookieSp(ROOKIE_SP_PER_ATTACK);
  /* 不稳定血浆的代价：每次远程攻击后自身 -1 HP（护盾可抵消） */
  if (selectedChar === 'vampire' && vampireSkillActive) {
    const selfRes = damagePlayer(1, '不稳定血浆');
    showPlayerDamage(selfRes, '-1 HP');
    log(`不稳定血浆：攻击后失去 1 HP${selfRes.shielded ? '（护盾抵消）' : `（剩 ${player.hp}）`}。`);
    updateStats();
    if (player.hp <= 0) { endGame('不稳定血浆耗尽了生命。游戏结束。'); return true; }
 }
  /* ISSUE-20261029-24：这里原本还有一对 playerAttacksDone++ / playerActionsUsed++，
   * 与远程分支入口（上方「远程攻击占用一次动作」）重复计 → 探测先锋对远程角色失效。
   * 近战分支在本函数更早处已 return，本行以下只有远程路径可达，故不再补计。 */
  refreshUnits();
  await sleep(220);
  return false;
}

/* 冲锋结束时的撞墙伤害（只在没撞到敌人时结算）。返回 true = 玩家阵亡。 */
function resolveChargeWallDamage(chargeWillEnd, playerBlocked) {
  if (!chargeWillEnd) return false;
  let willHitWall = false;
  if (!playerBlocked && playerChargeStopReason === 'wall' && player.hp > 0) {
    willHitWall = DIR4.some(([dx, dy]) => {
      const nx = player.x + dx, ny = player.y + dy;
      return !inBounds(nx, ny) || map[ny][nx] === 1;
 });
 }
  if (!willHitWall) return false;

  if (playerChargeCausedDamage) {
    floatText(player.x, player.y, '减免撞墙', '#4ecdc4');
    log('冲锋过程中已造成过伤害，本次撞墙免伤。');
    return false;
 }
  const oldHp = player.hp;
  const wallDmg = oldHp - Math.floor(oldHp / 2);
  const wallRes = damagePlayer(wallDmg, '冲锋撞墙');
  showPlayerDamage(wallRes, '撞墙 -' + wallDmg);
  ringFx(player.x, player.y, '#ff6b6b');
  hitFlashCell(player.x, player.y);
  log(`冲锋撞墙，失去一半 HP${wallRes.shielded ? '（护盾抵消）' : '（-' + wallDmg + '，剩 ' + player.hp + '）'}`);
  if (player.hp <= 0) { player.alive = false; refreshUnits(); endGame(); return true; }
  return false;
}

/* 冲锋走完路径后收尾：退出冲锋状态。 */
function finishChargeState(chargeWillEnd) {
  if (!chargeWillEnd) return;
  log('冲锋结束，失去冲锋状态。');
  playerChargingThisTurn = false;
  playerChargeStopReason = null;
  playerChargeCausedDamage = false;
}

/* ★ ISSUE-20261030-57：近战选靶（抽出来，让「谁被打」不再写死 player）。
 * 返回 { kind:'squad'|'player', ref } —— **小队成员优先**，只有身边一个成员都没有才轮到玩家。
 *
 * 人类 2026-10-30 01:01 原话：「敌人的攻击优先打小队成员」。
 * ⚠️ 这条**推翻**了 ISSUE-20261029-32 的「谁近打谁，平手打玩家」—— 现在即使玩家也贴身，
 *    只要身边有存活成员就打成员（成员替玩家挡刀，这正是「带小队」的价值）。
 * ⚠️ 注意与寻路的区分：pickEnemyTargetFor 管的是「往哪走」，仍然是玩家优先（57 号 §8 不改寻路）；
 *    这里管的是「打谁」，两者口径不同是有意为之，别再合回一处。
 * §6-2（同格时打谁）：成员与玩家同格时，两者到敌人的 dist 都是 1 → 走成员优先，
 *    即同格反而是好事（成员在替玩家挡）。 */
function enemyMeleeTarget(e) {
  if (typeof squadAliveUnits === 'function') {
    /* 多个成员都贴身时按「当前 HP 最少」优先？—— 不，保持与旧实现一致：取第一个（数组顺序 = 召唤顺序），
     * 不去引入新的集火规则（57 号 §8 明确不做目标锁定）。 */
    const sq = squadAliveUnits().find(s => dist(e, s) === 1);
    if (sq) return { kind: 'squad', ref: sq };
 }
  /* ★ ISSUE-20261031-128：合作队友同理 —— 贴身的队友先吃这一拳，玩家兜底。
   * 顺序刻意排在成员之后、玩家之前：单人局没有队友，这一行等于不存在（既有对局零影响）；
   * 多人局里「谁站在我旁边谁挨打」也符合直觉。 */
  if (typeof coopAliveAllies === 'function') {
    const al = coopAliveAllies().find(a => dist(e, a) === 1);
    if (al) return { kind: 'ally', ref: al };
 }
  if (player && player.alive && dist(e, player) === 1) return { kind: 'player', ref: player };
  return null;
}

/* 相邻敌人的近战反击（每回合每个敌人一次）。
 * ★ ISSUE-20261029-32：贴身目标可以是玩家，也可以是小队成员（成员不再是无敌的）。
 * ★ ISSUE-20261030-57：~~口径（人类 05:48 拍板）：谁近打谁，平手打玩家~~
 *   已作废，改成 **小队成员优先**（见 enemyMeleeTarget）。判定过了之后整段结算也要跟着
 *   换目标 —— 所以下面按 tgt.kind 分叉，而不是只改一个 if。 */
async function resolveEnemyMeleeAttacks() {
  if (!(player.hp > 0)) return;
  for (let i = 0; i < enemies.length; i++) {
    if (player.hp <= 0) break;
    const e = enemies[i];
    if (!e.alive || e.type === 'alien' || e.type === 'ufo') continue;
    /* ★ ISSUE-20261028-14：dormant = 这一关完全不动也不打（教程木桩 / 未激活巡逻敌）。
     * 独立标记，不借 stunTurns —— 后者会往日志里打「眩晕中（无意图）」，新手会当成 bug。 */
    if (e.dormant) continue;
    if (e.stunTurns > 0) continue;
    if (e.attackedThisRound) continue;
    /* ★ ISSUE-20261031-132：💀 骸骨只要场上还有 🦴 就一心找骨，**路过也不打人**（人类拍板 14 最终口径）。
     *   「不打人」放在**攻击结算侧**实现（判据 = 有没有骨头目标），寻路只负责把它领到骨头那边；
     *   场上没骨头时 `skeletonBoneTarget()` 返回 null → 它退回普通敌人 AI，贴脸照打。 */
    if (e.type === SKELETON_CORPSE_TYPE && typeof skeletonBoneTarget === 'function'
        && skeletonBoneTarget(e)) continue;
    /* ★ ISSUE-20261030-57：贴身目标 = 存活的小队成员（优先）→ 否则玩家 */
    const tgt = enemyMeleeTarget(e);
    if (!tgt) continue;
    e.attackedThisRound = true;
    gainFencerSp(1);
    /* 自爆虫（ISSUE-20261028-04）：贴到相邻格立即自爆。
     * 固定 explodeDmg 伤害，不吃命中检定、不吃暴击、不吃朝向 —— 逼玩家拉开距离而不是站着换血。
     * 眩晕中不炸（上面的 stunTurns 分支已挡住）。免疫状态（风笛冲锋 / 泥岩满技力）照样免疫。
     * ★ ISSUE-20261030-57 §3-4：自爆是**范围**伤害，不存在「选靶」—— 相邻的玩家与成员都吃，
     *   所以这一段刻意不走 enemyMeleeTarget（只用它判断「要不要炸」），行为与 57 号之前一致。 */
    if (e.type === 'bomber') {
      /* ★ ISSUE-20261031-100-②：自爆按正常攻击算 —— 伤害口径等同一次近战攻击（带骰子，
       * 走 rollEnemyDamage 同口径；不再用固定 explodeDmg）。范围伤害 + 必中 + 免疫仍保留。 */
      const boom = rollEnemyDamage(e, 'melee');
      /* ★ ISSUE-20261029-32：爆炸同样波及**相邻的小队成员**（自爆不看目标是谁）。 */
      if (typeof squadAliveUnits === 'function') {
        for (const s of squadAliveUnits()) {
          if (dist(e, s) !== 1) continue;
          slashFx(s.x, s.y, '#ff9f43', 'squad-' + s.uid);
          hitFlashCell(s.x, s.y);
          squadTakeDamage(s, boom, `自爆虫${i + 1}自爆`);
 }
 }
      /* ★ ISSUE-20261031-128：合作队友一样会被炸（范围伤害不选靶）。 */
      if (typeof coopAliveAllies === 'function') {
        for (const a of coopAliveAllies()) {
          if (dist(e, a) !== 1) continue;
          slashFx(a.x, a.y, '#ff9f43', 'coop-' + a.slot);
          hitFlashCell(a.x, a.y);
          coopAllyTakeDamage(a, boom, `自爆虫${i + 1}自爆`);
 }
 }
      if (tryPlayerImmuneHit(playerImmuneState(), `自爆虫${i+1}自爆`, `自爆虫${i+1}自爆`, '')) {
        e.hp = 0;
        killEnemy(e, { floatMsg: '自爆!', logText: `自爆虫${i+1}自爆，但玩家免疫了本次伤害` });
        refreshUnits();
        await sleep(240);
        continue;
 }
      slashFx(player.x, player.y, '#ff9f43', 'player');
      hitFlashCell(player.x, player.y);
      const boomRes = damagePlayer(boom, '自爆虫');
      showPlayerDamage(boomRes, '-' + boom, { color: '#ff9f43' });
      log(`自爆虫${i+1}贴身自爆！${boomRes.shielded ? '（护盾抵消）' : '造成' + boom + '伤害'}`);
      e.hp = 0;
      /* ★ ISSUE-20261031-100-④：自爆虫不留 —— 自爆后即时移出战场（alive=false，棋盘不再渲染/占格）。
       * 不增删 enemies[] 元素，仅置死亡，避免破坏 enemyPathOrder 落位顺序（同「分裂」词缀教训）。 */
      killEnemy(e, { floatMsg: '自爆!', logText: `自爆虫${i+1}自爆后消散` });
      if (player.hp > 0) triggerFencerCounter();
      refreshUnits();
      await sleep(240);
      continue;
 }
    /* ★ ISSUE-20261030-57：目标是小队成员 → 整段结算都指向成员（不再写死 player）。
     *   成员走玩家同一套掷骰（rollEnemyDamage(e,'melee')）与 AC 检定，
     *   但**没有**护盾 / 免疫 / 反击那套（那是玩家专属机制，见下面 player 分支）：
     *     · 不调 tryPlayerImmuneHit —— 免疫是玩家的状态，成员没有；
     *     · 不调 triggerFencerCounter —— 57 号 §6-1 建议「成员被打不触发泥岩反击」
     *       （反击是玩家自己的技能，成员替玩家挡刀已经赚了；触发会让成员变成反击触媒，强度大变）。
     *       ⚠️ 这条待人类定案，当前按 issue 的建议实现。 */
    /* ★ ISSUE-20261031-128：贴身的合作队友 → 整段结算指向该队友。
     * 与成员分支同口径（同一套掷骰 + AC 检定 + 朝向弱点暴击），但不触发玩家的
     * 护盾 / 免疫 / 泥岩反击 —— 那些是**本地玩家**的机制，队友身上没有。 */
    if (tgt.kind === 'ally') {
      const al = tgt.ref;
      /* ★ ISSUE-20261031-128 剩余项③（2026-11-01）：泥岩「岩崩锤」的反击状态。
       * 处于反击状态时**免疫本次伤害并回敬一次**（与玩家侧 `IMMUNE_COUNTER` 同效果）。
       * 敌人已经挥出来了 → 先播未命中表现，再走反击，视觉上「打空了然后被打」。
       * ⚠️ 这条必须在 `coopAllyTakeDamage` 之前：一旦扣了血再免疫就迟了。 */
      if (al.counterReady && typeof coopAllyTryCounter === 'function') {
        const res = await coopAllyTryCounter(al, e);
        if (res.immune) {
          refreshUnits();
          await sleep(240);
          continue;
        }
      }
      const alMod = abilityMod(e.abilities.str);
      const alAtk = rollEnemyAttack(alMod, e.prof, al.ac);
      const alKey = 'coop-' + al.slot;
      slashFx(al.x, al.y, '#ff6b6b', alKey);
      hitFlashCell(al.x, al.y);
      if (alAtk.hit) {
        let alEd = rollEnemyDamage(e, 'melee');
        let alCrit = '';
        if (alAtk.nat20) { alEd *= 2; alCrit = '自然20暴击'; }
        else if (isFacingTarget(e, al)) { alEd *= 2; alCrit = '弱点暴击'; }
        coopAllyTakeDamage(al, alEd, `敌人${i + 1}近战`);
        log(`敌人${i + 1}近战命中${al.icon} ${al.name}${alCrit ? '（' + alCrit + '）' : ''}，造成 ${alEd} 伤害 (${fmtRoll(alAtk, al.ac)})`);
 } else {
        missFx(al.x, al.y);
        log(`敌人${i + 1}近战未命中 ${al.icon} ${al.name} (${fmtRoll(alAtk, al.ac)})`);
 }
      refreshUnits();
      await sleep(240);
      continue;
 }
    if (tgt.kind === 'squad') {
      const sqAdj = tgt.ref;
      const sqStrMod = abilityMod(e.abilities.str);
      const sqAtk = rollEnemyAttack(sqStrMod, e.prof, sqAdj.ac);
      slashFx(sqAdj.x, sqAdj.y, '#ff6b6b', 'squad-' + sqAdj.uid);
      hitFlashCell(sqAdj.x, sqAdj.y);
      if (sqAtk.hit) {
        let sqEd = rollEnemyDamage(e, 'melee');
        let sqCrit = '';
        if (sqAtk.nat20) { sqEd *= 2; sqCrit = '自然20暴击'; }
        else if (isFacingTarget(e, sqAdj)) { sqEd *= 2; sqCrit = '弱点暴击'; }
        squadTakeDamage(sqAdj, sqEd, `敌人${i + 1}近战`);
        log(`敌人${i + 1}近战命中${sqAdj.icon} ${sqAdj.name}${sqCrit ? '（' + sqCrit + '）' : ''}，造成 ${sqEd} 伤害 (${fmtRoll(sqAtk, sqAdj.ac)})`);
 } else {
        missFx(sqAdj.x, sqAdj.y);
        log(`敌人${i + 1}近战未命中 ${sqAdj.icon} ${sqAdj.name} (${fmtRoll(sqAtk, sqAdj.ac)})`);
 }
      refreshUnits();
      await sleep(240);
      continue;
 }
    /* 走到这里 = tgt.kind === 'player'（身边没有存活成员，或成员都在远处）：照旧打玩家。
     * 护盾 / 免疫 / 泥岩反击那一套全部保留 —— 它们只在玩家分支走。 */
    const eStrMod = abilityMod(e.abilities.str);
    const pAC = playerEffectiveAC();
    const atk = rollEnemyAttack(eStrMod, e.prof, pAC);
    slashFx(player.x, player.y, '#ff6b6b', 'player');
    hitFlashCell(player.x, player.y);
    if (atk.hit) {
      let ed = rollEnemyDamage(e, 'melee');
      let critTag = '';
      if (atk.nat20) { ed *= 2; critTag = '自然20暴击'; }
      else if (isFacingTarget(e, player)) { ed *= 2; critTag = '弱点暴击'; }
      if (tryPlayerImmuneHit(playerImmuneState(), `敌人${i+1}近战攻击`, `敌人${i+1}近战命中`, critTag)) {
        refreshUnits();
        await sleep(240);
        continue;
 }
      const meleeRes = damagePlayer(ed, '敌人近战');
      showPlayerDamage(meleeRes, (critTag ? critTag + ' -' : '-') + ed, {
        color: critTag ? '#ffd700' : '#ff6b6b', crit: !!critTag,
 });
      log(`敌人${i+1}近战命中${critTag ? '（' + critTag + '）' : ''}${meleeRes.shielded ? '（护盾抵消）' : '，造成' + ed + '伤害'} (${fmtRoll(atk, pAC)})`);
      if (player.hp > 0) triggerFencerCounter();
 } else {
      missFx(player.x, player.y);
      log(`敌人${i+1}近战未命中 (${fmtRoll(atk, pAC)})`);
 }
    refreshUnits();
    await sleep(240);
 }
}

/* 兜底清扫：任何渠道把敌人打到 0 HP 却没标记死亡的，在这里补结算。 */
function sweepDeadEnemies() {
  for (const e of enemies) {
    if (e.alive && e.hp <= 0) killEnemy(e);
 }
}

/* =========================================================
 * ★ 技能节点触发：玩家实际走到该路径步时发动角色技能
 * 统一入口 —— 先校验「节点存在 / 技能就绪 / 动作预算」，再按角色发动。
 * 被敌人挡住（没走到）不会触发；返回 true 表示技能已发动（动作已消耗）。
 * ========================================================= */
async function triggerSkillNode(pathIdx) {
  if (!player || !player.alive || player.hp <= 0) return false;
  if (!skillIndices.includes(pathIdx)) return false;
  /* ★ ISSUE-20261031-120（🙊）：**执行时的第二道闸**。
   * 入口 toggleSkill 已经拦过一次，但玩家可能在猴王换形态之前就排好了节点 ——
   * 到这一步它可能已经是 🙊，此时「禁技能」必须真的生效，否则就是个空头承诺。
   * 动作与技力都不消耗（与「技能未就绪」同口径）。 */
  if (typeof kingMuteSkills === 'function' && kingMuteSkills()) {
    log(`✦ 技能节点（第 ${pathIdx} 步）：🙊 猴王捂嘴，技能未能发动（动作与技力均未消耗）。`);
    floatText(player.x, player.y, '技能被禁', '#bbb');
    return false;
  }
  const here = playerPath[pathIdx];
  const prev = playerPath[pathIdx - 1];
  const isWaitStep = !!prev && here.x === prev.x && here.y === prev.y;
  /* ★ ISSUE-20261029-34：起点没有冲锋方向，风笛的「高效冲击」不能原地发动。
   * （toggleSkill 已经在设置时拦过一次，这里是兜底 —— 防止别处塞进来的技能节点。） */
  if (pathIdx === 0 && selectedChar === 'wheelchair') {
    log('✦ 技能节点（原地）：风笛的「高效冲击」需要沿移动方向冲锋，起点不能发动。');
    floatText(player.x, player.y, '需移动节点', '#bbb');
    return false;
 }
  /* 风笛的冲锋只能沿移动方向前进，放在等待步上无效 */
  if (selectedChar === 'wheelchair' && isWaitStep) {
    log(`✦ 技能节点（第 ${pathIdx} 步）：风笛的「高效冲击」需要放在移动节点上，等待步不发动。`);
    floatText(player.x, player.y, '需移动节点', '#bbb');
    return false;
 }
  const info = skillReadyInfo(playerPath, false);
  if (!info.ready) {
    log(`✦ 技能节点（第 ${pathIdx} 步）：「${info.name}」尚未就绪（${info.spNow}/${info.spMax}），本次未发动。`);
    floatText(player.x, player.y, '技能未就绪', '#bbb');
    return false;
 }
  if (playerActionsUsed >= maxActionsThisTurn()) {
    /* ISSUE-20261029-40 起闪避在「到达闪避格」那一步就扣动作了，
     * 所以要同时认「到达步」与「等待步」两个下标，否则同一步会报成「动作已用完」。 */
    const spentOnDodge = playerDodging && dodgeTriggerIndex > 0 &&
      (pathIdx === dodgeTriggerIndex || pathIdx === dodgeTriggerIndex - 1);
    log(spentOnDodge
      ? `✦ 技能节点（第 ${pathIdx} 步）：这一步已经用于闪避，动作已用完，「${info.name}」未能发动。`
      : `✦ 技能节点（第 ${pathIdx} 步）：本回合动作已用完（${playerActionsUsed}/${maxActionsThisTurn()}），「${info.name}」未能发动。`);
    floatText(player.x, player.y, '动作已用完', '#bbb');
    return false;
 }

  playerActionsUsed += 1;
  const skillPip = noteActionPip('skill');   // ISSUE-20261030-77：点亮技能格（紫）
  /* ★ ISSUE-20261028-14：教程技能计数。挂在这里（四个 case 之前）= 一处顶四处，
   * 以后再加第五个角色的技能也不会漏记。 */
  if (typeof tutorialOnSkillCast === 'function') tutorialOnSkillCast(selectedChar);
  switch (selectedChar) {
    case 'wheelchair':
      wheelchairSp = 0;   // 技力在真正发动时清零（未走到就不浪费）
      log('风笛发动「高效冲击」！技力清零，下一步沿直线开始冲锋。');
      floatText(player.x, player.y, '高效冲击！', '#ffd700');
      ringFx(player.x, player.y, '#ffd700');
      break;
    case 'vampire':
      vampireSkillActive = true;
      vampireSp = 0;
      log('华法琳发动技能「不稳定血浆」：本关内远程攻击必定命中、必定暴击、必定留血迹，但每次攻击后自身失去 1 HP（技力清零）。');
      floatText(player.x, player.y, '不稳定血浆', '#ff6b6b');
      ringFx(player.x, player.y, '#ff6b6b');
      break;
    case 'fencer':
      fencerCounterActive = true;
      log('泥岩发动技能「岩崩锤」：进入反击状态（本回合受击免疫并反击）。');
      floatText(player.x, player.y, '反击就绪！', '#ffd700');
      ringFx(player.x, player.y, '#ffd700');
      break;
    case 'amiya': {
      const count = amiyaBonusTargets;
      amiyaBonusTargets = 0;
      log(`阿米娅发动「精神爆发」！倾泻 ${count} 点技力，进行连续远程攻击！`);
      floatText(player.x, player.y, '精神爆发！', '#ffd700');
      ringFx(player.x, player.y, '#ffd700');
      await executeAmiyaBurst(count);
      break;
 }
    /* ISSUE-20261029-28：预备干员「增援召唤」。
     * ★ ISSUE-20261030-54：落点改成预备干员本格后，「周围 8 格没空位」这个失败原因不存在了；
     *   唯一的失败原因变成**满编**（四种类型各一个 = 4 个成员）。照样退还技力与动作，
     *   否则一次空放就把 5 点技力吞了。 */
    case 'rookie': {
      const res = summonSquadMember();
      if (!res.ok) {
        playerActionsUsed -= 1;       // 上面的统一扣费要还回去
        revokeActionPip(skillPip);    // ISSUE-20261030-77：格子也要一起退，否则 UI 显示已花掉
        rookieSp = ROOKIE_SP_MAX;     // 技力未消耗
        const why = res.reason === 'full' ? '小队已满编（4 名成员，四种类型各一）' : '增援召唤失败';
        log(`😶 ${why}，增援召唤失败：技力与动作均未消耗。`);
        floatText(player.x, player.y, res.reason === 'full' ? '已满编' : '召唤失败', '#bbb', false, 0, 'player');
        return false;
 }
      rookieSp = 0;
      floatText(player.x, player.y, '增援召唤！', '#7dd3fc');
      break;
 }
 }
  /* ISSUE-20261028-06 回响回路：技能**真正发动之后**才装填（不是规划时），
   * 这样「本回合先攻击、后放技能」不会让第一下白吃加成，顺序与玩家预期一致；
   * 放在 switch 之后还顺便避开阿米娅精神爆发 —— 它内部连打多次，否则会被自己那几发消耗掉。 */
  relicArmEcho();
  return true;
}

async function resolveStep(pIdxIn, eIdx) {
  let pIdx = pIdxIn;
  if (phase !== PHASE.RESOLVING) return;
  if (!player.alive || player.hp <= 0) { endGame(); return; }
  if (enemies.filter(e => e.alive).length === 0) { clearEnemyArrows(); onLevelClear(); return; }
  /* ISSUE-20261030-77：本 tick 起始坐标。玩家走没走，靠 tick 前后坐标对比判定（见下方 noteActionPip）。 */
  const pipFrom = { x: player.x, y: player.y };

  const enemyMoves = [];
  enemies.forEach((e, i) => {
    if (!e.alive) return;
    if (e.stunTurns > 0) return;
    const p = enemyPaths[i];
    if (p && eIdx + 1 < p.length) {
      enemyMoves.push({ unit: e, from: { x: e.x, y: e.y }, to: p[eIdx + 1], enemyIdx: i });
 }
 });

  const killedEnemyIds = new Set();
  let playerBlocked = false;
  let didAttackThisTick = false;

  /* ★ ISSUE-20261029-34：原地技能（技能节点在起点 idx 0）——本回合第一个 tick 就发动，不移动。
   * 必须早于任何路径步消费；与 pendingAttack 互斥（同一格只能有一种）。
   * 放在 pendingAttack 分支之前：两者不可能同时为真，顺序不影响结果。 */
  if (pendingStartSkill) {
    pendingStartSkill = false;
    await triggerSkillNode(0);
    if (await settleTick()) return;
 }

  if (pendingAttack) {
    pendingAttack = false;
    didAttackThisTick = true;
    /* ISSUE-20261029-41：原地攻击（路径第 0 格）没有落地动作，也就没人给它写朝向。
     * 出手前先转向「下一步要去的方向」——「朝上站、下一步往左走」时这一拳打左边那个敌人，
     * 与人类 16:18「3 是」的口径一致（先决定往哪走，再打那边）。
     * pIdx === 1 只可能是起点攻击；路径中途的攻击节点由上面的落位代码写好朝向。 */
    if (pIdx <= 1) {
      const f0 = facingAt(playerPath, 0, null);
      if (f0.dx || f0.dy) player.facing = f0;
 }
 } else if (pIdx < playerPath.length) {
    if (pendingChargeInfo && pIdx >= pendingChargeInfo.startIdx && !playerChargingThisTurn && player.alive) {
      playerChargingThisTurn = true;
      playerChargeCausedDamage = false;
      /* 冲锋额度在规划期就算好了（= 剩余移动步数），这里接手朝向与额度 */
      playerChargeDir = pendingChargeInfo.dir || playerChargeDir;
      playerChargeBudget = pendingChargeInfo.budget || 0;
      playerChargeHits = 0;
      pendingChargeInfo = null;
      log(`「高效冲击」：冲锋开始！本次额度 ${playerChargeBudget} 次攻击（= 剩余移动步数）。`);
      floatText(player.x, player.y, '高效冲击！', '#ffd700');
      ringFx(player.x, player.y, '#ffd700');
 }

    const pathIdx = pIdx;
    const targetPos = playerPath[pathIdx];
    const playerFrom = { x: player.x, y: player.y };
    /* ISSUE-20261029-40：本 tick 是否是玩家**主动走进**某格的落位（正常落位 / 冲锋撞死落位）。
     * 闪避的「到达即生效」只认这两条 —— 相杀与被 Boss 推开不算（人类 16:18 拍板）。 */
    let arrivedByMove = false;

    /* ★ 闪避的触发已挪到「落地之后」（见本轮落位代码尾部）——
     * ISSUE-20261029-40：原来在这里要求「本步是等待步」，导致玩家走进闪避格的同一 tick
     * 敌人攻击吃不到闪避加成。现在按「站上闪避格」判定，同一 tick 的敌人攻击就吃到加成
     * （ISSUE-20261030-60 起加成为 ⌊敏捷 / 2⌋，不再是固定 +3）。 */

    const shootouts = [];
    for (const em of enemyMoves) {
      /* ★ ISSUE-20261031-124：判据只剩「双方落点相同」。
       * 原先并列的 `isSwap`（各走对方格 = 擦肩而过）已删除，详见 isShootoutStep() 上方注释。 */
      if (isShootoutStep(targetPos, em)) shootouts.push(em);
 }

    if (shootouts.length > 0) {
      const c1 = cellCenter(targetPos.x, targetPos.y);
      const c2 = cellCenter(playerFrom.x, playerFrom.y);
      floatTextAt((c1.x + c2.x) / 2, (c1.y + c2.y) / 2,
        '相杀！' + (shootouts.length > 1 ? '×' + shootouts.length : ''),
        '#ff4500', false, -6, 'crosskill');
      ringFx(targetPos.x, targetPos.y, '#ff4500');
      slashFx(targetPos.x, targetPos.y, '#ff4500');
      hitFlashCell(playerFrom.x, playerFrom.y);

      for (const em of shootouts) {
        const ex = em.unit.x, ey = em.unit.y;
        let pd = rollPlayerMeleeDamage() * 2;
        if (playerChargingThisTurn) pd *= 2;
        const pdDealt = enemyTakeDamage(em.unit, pd);
        if (playerChargingThisTurn) {
          playerChargeCausedDamage = true;
          playerChargeBudget = Math.max(0, playerChargeBudget - 1);   // 每次命中消耗 1 次冲锋额度
          playerChargeHits += 1;
 }
        if (selectedChar === 'amiya') amiyaMarkReveal(em.unit);
        if (pdDealt > 0) {
          floatText(ex, ey, '暴击 -' + pdDealt, '#ffd700', true);
          log(`相杀！玩家对敌人${em.unit.id+1}造成暴击${pdDealt}伤害`);
 } else {
          log(`相杀！敌人${em.unit.id+1} 的护盾吸收了本次伤害。`);
 }
        if (em.unit.hp <= 0) killEnemy(em.unit, { killedIds: killedEnemyIds });
        em.unit.attackedThisRound = true;
 }
      gainFencerSp(shootouts.length);
      const counterImmune = selectedChar === 'fencer' && fencerCounterActive;
      let counterImmuneShown = false;
      let chargeImmuneShown = false;
      for (const em of shootouts) {
        let ed = rollEnemyDamage(em.unit, 'melee') * 2;
        if (playerChargingThisTurn) {
          if (!chargeImmuneShown) {
            floatText(playerFrom.x, playerFrom.y, '冲锋免疫', '#ffd700');
            chargeImmuneShown = true;
 }
          log(`相杀！敌人${em.unit.id+1}对玩家造成暴击${ed}伤害，但风笛处于冲锋状态，免疫本次伤害。`);
          continue;
 }
        if (counterImmune) {
          if (!counterImmuneShown) {
            floatText(playerFrom.x, playerFrom.y, '反击免疫', '#ffd700');
            counterImmuneShown = true;
 }
          log(`相杀！敌人${em.unit.id+1}对玩家造成暴击${ed}伤害，但泥岩处于反击状态，免疫本次伤害。`);
          continue;
 }
        const dmgRes = damagePlayer(ed, '相杀');
        showPlayerDamage(dmgRes, '暴击 -' + ed, { color: '#ffd700', crit: true, x: playerFrom.x, y: playerFrom.y });
        log(`相杀！敌人${em.unit.id+1}对玩家造成暴击${dmgRes.shielded ? '（护盾抵消）' : ' ' + ed + '伤害'}`);
 }
      if (shootouts.length > 0 && player.hp > 0) triggerFencerCounter();
      if (player.hp <= 0) { endGame('你在相杀中阵亡。游戏结束。'); return; }
      const anySurvivor = shootouts.some(em => em.unit.alive);
      if (!anySurvivor) {
        const dx = Math.sign(targetPos.x - playerFrom.x);
        const dy = Math.sign(targetPos.y - playerFrom.y);
        player.x = targetPos.x; player.y = targetPos.y;
        /* ISSUE-20261029-41：落地朝向 = 下一步方向（终点则沿用进入方向）。 */
        const f = facingAt(playerPath, pathIdx, { dx, dy });
        if (f.dx || f.dy) player.facing = f;
        if (attackIndices.includes(pathIdx)) {
          if (playerChargingThisTurn) didAttackThisTick = true;
          else pendingAttack = true;
 }
        tryPickup();
 } else {
        if (playerChargingThisTurn) log('冲锋相杀，但仍有敌人存活，冲锋停止。');
        playerBlocked = true;
 }
 } else {
      let blockingEnemy = null;
      for (const e of enemies) {
        if (!e.alive || killedEnemyIds.has(e.id)) continue;
        if (e.x !== targetPos.x || e.y !== targetPos.y) continue;
        const move = enemyMoves.find(em => em.enemyIdx === e.id);
        let willMoveAway = false;
        if (move && (move.to.x !== e.x || move.to.y !== e.y)) {
          const destBlocked = enemies.some(o =>
            o.alive && o.id !== e.id && o.x === move.to.x && o.y === move.to.y
          );
          willMoveAway = !destBlocked;
 }
        if (willMoveAway) continue;
        blockingEnemy = e;
        break;
 }
      if (blockingEnemy) {
        if (playerChargingThisTurn) {
          let dmg = rollPlayerMeleeDamage() * 2;
          const dmgDealt = enemyTakeDamage(blockingEnemy, dmg);
          playerChargeCausedDamage = true;
          playerChargeBudget = Math.max(0, playerChargeBudget - 1);   // 撞击消耗 1 次额度
          playerChargeHits += 1;
          slashFx(blockingEnemy.x, blockingEnemy.y, '#ffd700');
          ringFx(blockingEnemy.x, blockingEnemy.y, '#ff4500');
          hitFlashCell(blockingEnemy.x, blockingEnemy.y);
          floatText(blockingEnemy.x, blockingEnemy.y, '冲锋撞击 -' + dmgDealt, '#ffd700', true);
          log(`冲锋撞击敌人${blockingEnemy.id+1}，造成${dmgDealt}点伤害！（剩余 ${playerChargeBudget} 次）`);
          if (blockingEnemy.hp <= 0) {
            killEnemy(blockingEnemy, {
              showRing: false,
              killedIds: killedEnemyIds,
              logText: `敌人${blockingEnemy.id+1}被撞飞`,
 });
            const dx = Math.sign(targetPos.x - playerFrom.x);
            const dy = Math.sign(targetPos.y - playerFrom.y);
            player.x = targetPos.x; player.y = targetPos.y;
            /* ISSUE-20261029-41：落地朝向 = 下一步方向；ISSUE-20261029-40：这条落位算「走进来了」。 */
            const f = facingAt(playerPath, pathIdx, { dx, dy });
            if (f.dx || f.dy) player.facing = f;
            arrivedByMove = true;
            if (attackIndices.includes(pathIdx)) didAttackThisTick = true;
            tryPickup();
 } else {
            log(`冲锋撞击后敌人${blockingEnemy.id+1}未被击倒，冲锋停止。`);
            playerBlocked = true;
 }
 } else {
          log(`玩家被敌人${blockingEnemy.id + 1}挡住，停止移动`);
          if (attackIndices.includes(pathIdx)) {
            log(`⚔️ 路径被挡，攻击节点改为在当前位置触发。`);
            floatText(player.x, player.y, '原地攻击', '#ffd700');
            if (playerChargingThisTurn) didAttackThisTick = true;
            else pendingAttack = true;
 } else {
            floatText(targetPos.x, targetPos.y, '被挡', '#bbb');
 }
          playerBlocked = true;
 }
 } else {
        const dx = Math.sign(targetPos.x - playerFrom.x);
        const dy = Math.sign(targetPos.y - playerFrom.y);
        player.x = targetPos.x; player.y = targetPos.y;
        /* ISSUE-20261029-41：落地朝向 = 下一步方向（终点沿用进入方向）。
         * ISSUE-20261029-40：这是唯一「玩家主动走进去」的落位 —— 闪避只认它。 */
        const f = facingAt(playerPath, pathIdx, { dx, dy });
        if (f.dx || f.dy) player.facing = f;
        arrivedByMove = true;
        if (attackIndices.includes(pathIdx)) {
          if (playerChargingThisTurn) didAttackThisTick = true;
          else pendingAttack = true;
 }
        tryPickup();
 }
 }
    /* ★ ISSUE-20261029-40：闪避 = 走到闪避格**即生效**（不再等下一个「等待」tick）。
     *
     * 判定用「玩家实际站上了闪避格」而不是「这一步是等待步」：
     *   · 走进闪避格的那一 tick（arrivedByMove）→ 生效，本 tick 后面的
     *     resolveEnemyMeleeAttacks() 立刻用含 +3 的 AC；
     *   · 仍在闪避格上等待的后续 tick 兜底一次（路径第 0 格之后立刻等待时，
     *     「到达步」= 0 不会被 tick 走到，靠这条保住旧行为）；
     *   · 相杀 / 被 Boss 推开 / 被挡这三种情况都不会满足 —— 玩家其实没走进去。
     * 动作仍占 1 个（人类 16:18 拍板），动作不够时照旧不成立，且不再重复刷日志。 */
    if (!dodgeResolved && dodgeTriggerIndex > 0 && !playerBlocked) {
      const dodgeCell = playerPath[dodgeTriggerIndex];
      const onDodgeCell = !!dodgeCell && player.x === dodgeCell.x && player.y === dodgeCell.y;
      if (onDodgeCell && (arrivedByMove || pathIdx === dodgeTriggerIndex)) {
        dodgeResolved = true;
        if (playerActionsUsed >= maxActionsThisTurn()) {
          // 本回合动作已用完（ISSUE-20261029-25 起上限 2：打完一拳还能闪一次）
          log('本回合的动作已用于攻击，闪避不成立。');
          floatText(player.x, player.y, '无法闪避', '#bbb');
 } else {
          playerDodging = true;
          /* ISSUE-20261028-06 危险直觉 + ISSUE-20261030-60：
           * 闪避基础加成 = ⌊敏捷 / 2⌋（不再是固定 3），持有「危险直觉」再额外 +3。 */
          playerDodgeACBonus = relicDodgeAcBonus(dodgeAcBonusBase());
          playerActionsUsed += 1;   // 闪避占用 1 个动作
          noteActionPip('dodge');   // ISSUE-20261030-77：动作 UI 点亮一格青色
          log(`闪避！到达闪避格，本回合 AC +${playerDodgeACBonus}（${player.ac} → ${playerEffectiveAC()}）。`);
          floatText(player.x, player.y, `闪避 +${playerDodgeACBonus}AC`, '#7dd3fc', true);
          ringFx(player.x, player.y, '#7dd3fc');
          renderHeroCard();   // 面板 AC 立刻变成含闪避加成的生效值（验收项）
 }
 }
 }
    /* ISSUE-20261030-77：本 tick 玩家真的走动了 → 动作 UI 的移动格 +1。
     * 判「tick 前后坐标变了」而不是「这一步是移动步」，好处是自动覆盖三处落位分支
     * （正常落位 / 相杀后落位 / 冲锋撞死落位），不必在每个分支各写一遍。
     * 被挡住、原地等待、原地攻击都不改坐标 → 不会误记。 */
    if (player.x !== pipFrom.x || player.y !== pipFrom.y) noteActionPip('move');
    if (playerBlocked) pIdx = playerPath.length;
    else pIdx++;

    /* ★ 技能节点：玩家实际到达该步才触发（被挡住不触发），移动结算之后、敌人行动之前 */
    if (!playerBlocked && skillIndices.includes(pathIdx)) {
      await triggerSkillNode(pathIdx);
      if (await settleTick()) return;
 }
 }

  /* ★ 冲锋剩余额度（ISSUE-20261028-01）：被挡住 or 走完冲锋段后，把没用掉的攻击次数
   * 按朝向补给前方 3 格内的敌人。必须放在敌人移动之前结算——否则目标会先跑掉。
   * 撞墙掉血在更后面（resolveChargeWallDamage），所以「先打、再判撞墙」的时序是对的。 */
  if (playerChargingThisTurn && pIdx >= playerPath.length) {
    resolveChargeRemainingHits();
    if (await settleTick()) return;
 }

  // 结算顺序 = 寻路顺序（离玩家近的优先），与规划层保持一致
  applyEnemyMoves(enemyMoves, eIdx, killedEnemyIds);

  refreshUnits();
  await sleep(UNIT_MOVE_MS);
  clearEnemyArrows();

  if (await settleTick()) return;

  // ★ 外星人特殊攻击：只在「它已经停下的格子」开火。
  // 每个 tick 都判一次，但还在移动途中的外星人会被 resolveAlienShots 跳过，
  // 所以它必须走完本回合的落点才会开枪；此时冲锋 / 反击状态仍然有效，免疫能正常生效。
  await resolveAlienShots(eIdx);
  if (await settleTick()) return;

  if (didAttackThisTick && player.alive) {
    if (await resolvePlayerAttack()) return;
 }

  const chargeWillEnd = playerChargingThisTurn && (playerBlocked || pIdx >= playerPath.length);
  if (resolveChargeWallDamage(chargeWillEnd, playerBlocked)) return;

  await resolveEnemyMeleeAttacks();

  finishChargeState(chargeWillEnd);

  if (player.hp <= 0) player.alive = false;
  sweepDeadEnemies();
  if (await settleTick()) return;

  const playerFinished = pIdx >= playerPath.length && !pendingAttack;
  const enemiesFinished = enemies.every((e, i) => {
    if (!e.alive) return true;
    if (e.stunTurns > 0) return true;
    const p = enemyPaths[i];
    return !p || eIdx + 1 >= p.length;
 });
  if (playerFinished && enemiesFinished) {
    await endRound();
 } else {
    renderUnits();
    await resolveStep(pIdx, eIdx + 1);
 }
}

// 外星人远程攻击：只在自己「停下的格子」开火。
// 本回合路径没走完（下一 tick 还要移动）时一律不开火 —— 移动途中路过与你同行/同列也不算。
// 停下之后站着不动，你什么时候走进它的行/列就什么时候开枪（每回合每人一次）。
async function resolveAlienShots(eIdx) {
  if (!player || !player.alive || player.hp <= 0) return;
  for (let i = 0; i < enemies.length; i++) {
    if (player.hp <= 0) break;
    const e = enemies[i];
    if (!e.alive || e.type !== 'alien') continue;
    if (e.stunTurns > 0) continue;
    if (e.attackedThisRound) continue;
    // ★ 还在移动途中 → 不开火（必须已经停在落点上）
    const ep = enemyPaths[i];
    if (ep && eIdx + 1 < ep.length) continue;
    /* ★ ISSUE-20261029-32 + ISSUE-20261030-57：目标可以是玩家，也可以是小队成员（同行 / 同列 + 有视线）。
     *   ~~口径（人类 05:48）：谁近打谁，平手打玩家~~
     *   ⚠️ 已作废：改成**小队成员优先**（与近战 enemyMeleeTarget 同口径）。
     *   ★ hasLineOfSight 必须按**成员自己的坐标**重算，不能沿用玩家的射线结果。 */
    const shotTargets = [];
    if (e.x === player.x || e.y === player.y) {
      if (hasLineOfSight(e, player)) shotTargets.push({ kind: 'player', obj: player });
 }
    if (typeof squadAliveUnits === 'function') {
      for (const s of squadAliveUnits()) {
        if (e.x !== s.x && e.y !== s.y) continue;
        if (!hasLineOfSight(e, s)) continue;
        shotTargets.push({ kind: 'squad', obj: s });
 }
 }
    if (!shotTargets.length) continue;
    shotTargets.sort((a, b) => {
      /* ★ ISSUE-20261030-57：成员优先（原来这里是 `kind === 'player' ? 0 : 1`，玩家优先）。
       *   成员之间 / 玩家之间才按距离取近；跨类型时**不看距离**直接选成员
       *   —— 与 57 号 §3-1「即使玩家也贴身也打成员」同口径。
       *   若人类更想要「距离优先、平手才打成员」，把下面这行换成距离比较即可（一行的事）。 */
      const ka = a.kind === 'squad' ? 0 : 1;
      const kb = b.kind === 'squad' ? 0 : 1;
      if (ka !== kb) return ka - kb;
      const da = Math.abs(a.obj.x - e.x) + Math.abs(a.obj.y - e.y);
      const db = Math.abs(b.obj.x - e.x) + Math.abs(b.obj.y - e.y);
      return da - db;
 });
    const shotTgt = shotTargets[0];
    const isPlayerTgt = shotTgt.kind === 'player';
    e.attackedThisRound = true;
    gainFencerSp(1);
    const intMod = abilityMod(e.abilities.int);
    const pAC = isPlayerTgt ? playerEffectiveAC() : shotTgt.obj.ac;
    const atk = rollEnemyAttack(intMod, e.prof, pAC);
    await animateBullet({ x: e.x, y: e.y },
      isPlayerTgt ? 'player' : 'squad-' + shotTgt.obj.uid,
      shotTgt.obj, atk.nat20, true, 'enemy-' + e.id);
    if (atk.hit) {
      let ed = rollEnemyDamage(e, 'ranged');
      if (atk.nat20) ed *= 2;
      /* ★ ISSUE-20261029-32：打成员 —— 成员没有护盾 / 免疫那套 */
      if (!isPlayerTgt) {
        squadTakeDamage(shotTgt.obj, ed, `外星怪物${i + 1}射击`);
        log(`外星怪物${i + 1}远程命中${shotTgt.obj.icon} ${shotTgt.obj.name}，造成 ${ed} 伤害 (${fmtRoll(atk, pAC)})`);
        refreshUnits();
        await sleep(240);
        continue;
 }
      // 免疫不等于跳过反击，否则满技力会永久锁死、眩晕永远不触发（见 tryPlayerImmuneHit）
      if (tryPlayerImmuneHit(playerImmuneState(), `外星怪物${i+1}远程命中`, `外星怪物${i+1}远程命中`, atk.nat20 ? '自然20暴击' : '')) {
        refreshUnits();
        await sleep(240);
        continue;
 }
      const shotRes = damagePlayer(ed, '外星怪物射击');
      showPlayerDamage(shotRes, (atk.nat20 ? '自然20暴击 -' : '-') + ed, {
        color: atk.nat20 ? '#ffd700' : '#a55eea', crit: atk.nat20,
 });
      log(`外星怪物${i+1}远程命中${shotRes.shielded ? '（护盾抵消）' : '，造成' + ed + '伤害'} (${fmtRoll(atk, pAC)})`);
      if (player.hp > 0) triggerFencerCounter();
 } else {
      /* ★ ISSUE-20261029-32：未命中也要落在**实际目标**那一格（可能是成员） */
      missFx(shotTgt.obj.x, shotTgt.obj.y);
      log(`外星怪物${i+1}远程未命中${isPlayerTgt ? '' : shotTgt.obj.name} (${fmtRoll(atk, pAC)})`);
 }
    refreshUnits();
    await sleep(240);
 }
}

async function endRound() {
  if (player.hp <= 0) { endGame(); return; }
  clearEnemyArrows();
  /* ★ ISSUE-20261031-128：合作队友的回合（玩家结算完 → 敌人结算完 → 队友 → 小队成员）。
   * 顺序口径：人类玩家优先于召唤物 —— 队友走开之后成员再挪，不会互相挤在同一个窄口。
   * 同样必须在 `phase = PHASE.PLANNING` 之前（resolveCoopTurn 只认 RESOLVING）。
   * 队友清场时也直接进通关，理由同上：别让流程跑回「重新生成敌人意图」。 */
  await resolveCoopTurn();
  if (enemies.every(e => !e.alive)) { onLevelClear(); return; }
  /* ISSUE-20261029-28：小队成员的回合行动（玩家结算完 → 敌人结算完 → 小队）。
   * ⚠️ 必须在下面 `phase = PHASE.PLANNING` 之前 —— resolveSquadTurn 只认 RESOLVING 相位。
   * 成员清场时直接进通关，别让流程继续跑到「重新生成敌人意图」那一步。 */
  await resolveSquadTurn();
  if (enemies.every(e => !e.alive)) { onLevelClear(); return; }
  enemies.forEach(e => e.attackedThisRound = false);
  playerPath = [{ x: player.x, y: player.y }];
  attackIndices = []; skillIndices = []; enemyPaths = [];
  resetTurnState({ clearCounter: true });   // 闪避 / 冲锋 / 反击等临时状态到回合结束为止
  phase = PHASE.PLANNING;
  /* 玩家操作录制（默认关）：回合正常结束，补记结算后状态（血量 / 敌人 / 击杀） */
  if (window.ARK_REC) window.ARK_REC.endTurn({ player: player, enemies: enemies, kills: runKills });
  battleRound++;
  log('--- 回合结束 ---');

  const pendingUfoSpawns = [];
  /* ★ ISSUE-20261031-120：猴王要开的技能（形态在本循环里就切，召唤延后到循环外）。 */
  const pendingKingActs = [];
  let kingSummoned = 0;
  enemies.forEach(e => {
    e.amiyaRevealActive = 0;
    if (e.amiyaRevealForNext) {
      e.amiyaRevealActive = e.amiyaRevealBonus || 0;
      e.amiyaRevealForNext = false;
      e.amiyaRevealBonus = 0;
 }
    if (e.stunTurns > 0) {
      e.stunTurns--;
      if (e.stunTurns <= 0) {
        log(`敌人${e.id+1}解除眩晕。`);
 }
 }
    /* ISSUE-20261028-10-B：Boss 落石计时。放在 endRound（回合切换点）而不是它自己行动时，
     * 是因为石头必须出现在「玩家下一次规划之前」，否则玩家看不到新墙就撞上去。 */
    if (e.alive && e.type === BOSS_TYPE) {
      e.rockCd = (typeof e.rockCd === 'number' ? e.rockCd : COLOSSUS_ROCK_EVERY) - 1;
      if (e.rockCd <= 0) {
        placeRoughRock(e);
        e.rockCd = COLOSSUS_ROCK_EVERY;
      }
    }
    /* ★ ISSUE-20261031-119：飞碟🛸 每 2 回合在「离开的那一格」投放 1 只👽。
     * 实际投放统一放在 forEach 之后（避免遍历中改数组 + 重规划重入）。 */
    if (e.alive && e.type === 'ufo') {
      e.spawnCd = (typeof e.spawnCd === 'number' ? e.spawnCd : UFO_SPAWN_EVERY) - 1;
      if (e.spawnCd <= 0) {
        const lc = e.preMoveCell || { x: e.x, y: e.y };
        const moved = !(lc.x === e.x && lc.y === e.y);
        if (moved) pendingUfoSpawns.push({ ufo: e, cell: lc });
        e.spawnCd = UFO_SPAWN_EVERY;
      }
    }
    /* ★ ISSUE-20261031-120：猴王🐵 每 2 回合开一次技能 —— 切形态 + 召唤 3 只🐒。
     * 计时口径照抄 rockCd（回合切换点递减、到 0 开一次并重置），首回合不开：
     * 让玩家先看清它是谁、往哪走，再开始被压制。
     * 形态切换在本循环里立刻生效（玩家下一回合就受限）；召唤延后到循环外。 */
    if (e.alive && e.type === 'monkey_king') {
      e.skillCd = (typeof e.skillCd === 'number' ? e.skillCd : MONKEY_KING_SKILL_EVERY) - 1;
      if (e.skillCd <= 0) {
        pendingKingActs.push({ king: e, form: nextKingForm(e.kingForm) });
        e.skillCd = MONKEY_KING_SKILL_EVERY;
      }
    }
    /* ★ ISSUE-20261031-120：🐒 撒香蕉🍌 —— 每回合最多 1 根，落在本回合**真的走过**的路径格里。
     * `walkedThisTurn` 由 applyEnemyMoves 落位成功时记；没动 / 被眩晕时它本来就是空的。
     * 消费完立刻清空，否则「这回合没动的猴子会拿上回合的路线撒香蕉」。 */
    if (e.alive && e.type === 'monkey') {
      const walked = Array.isArray(e.walkedThisTurn) ? e.walkedThisTurn : [];
      if (walked.length && placeBananaOnPath(e, walked)) {
        log(`🐒 猴子${e.id + 1}在走过的路径上掉了 1 根🍌。`);
      }
      e.walkedThisTurn = [];
    }
  });
  /* ★ ISSUE-20261031-119：统一投放，然后一次性重规划 + 重绘（新单位当回合可见、下回合能行动）。 */
  if (pendingUfoSpawns.length) {
    for (const sp of pendingUfoSpawns) spawnUfoMinion(sp.ufo, sp.cell);
    generateEnemyPaths();
    refreshUnits();
    log(`🛸 本回合飞碟共投放了 ${pendingUfoSpawns.length} 只外星人👽。`);
  }
  /* ★ ISSUE-20261031-120：猴王开技能 —— 形态已切好，这里只负责召唤 + 一次性重规划重绘。
   * 与飞碟同一套收口：新召唤的🐒 当回合可见、下回合就能行动（否则它们整局站着不动）。 */
  if (pendingKingActs.length) {
    for (const act of pendingKingActs) kingSummoned += kingOpenSkill(act.king, act.form);
    if (kingSummoned > 0) {
      generateEnemyPaths();
      refreshUnits();
    }
  }

  /* ISSUE-20261028-10-B：玩家眩晕在**回合切换点**递减（与敌人同口径）。
   * 被推时置 2 → 这里减到 1（下一回合不能动）→ 再减到 0（恢复）。 */
  if (player && player.stunTurns > 0) {
    player.stunTurns--;
    if (player.stunTurns <= 0) {
      player.stunTurns = 0;
      player.stunNoticeShown = false;
      log('眩晕解除，下一回合可以正常行动。');
 } else {
      log(`仍然眩晕：下一回合无法移动 / 攻击 / 技能（只剩原地承受）。`);
 }
 }

  /* ★ ISSUE-20261028-14：教程分步推进（判据只看状态：玩家站在哪 / 木桩被打了几下 / 技力多少）。
   * 教程全程**不调用 onLevelClear**，所以既不结算经验、也不往排行榜写成绩（D1/D2 一次满足，
   * 不用另立 GAMEOVER 阶段）。
   * 返回值三种（tutorialAfterTurn 的约定）：
   *   'lesson' —— 通用课走完，切到了所选角色的专属课 → 立刻重开一张教程图
   *   'done'   —— 整条教程结束 → 起正常第 1 关
   *   其他     —— 只是往前走了几步，重绘提示条即可 */
  if (typeof tutorialIsOn === 'function' && tutorialIsOn()) {
    const tutRes = tutorialAfterTurn();
    if (tutRes === 'lesson') { initLevel(); return; }
    if (tutRes === 'done') {
      /* ★ ISSUE-20261031-94：教程走完 → **回选角厅**，不再直接开第 1 关。
       * 这时 🚪 会正常出现（tutorialPendingLesson 返回 null），玩家自己决定什么时候开局。 */
      log('✅ 教程结束！回到角色选择。');
      returnToLobbyAfterTutorial();
      return;
 }
    if (typeof renderTutorialBar === 'function') renderTutorialBar();
 }

  /* ★ ISSUE-20261031-128：合作局结算完要报 ready 并等队友，不能直接回到 PLANNING
   * （否则一个人结算快就会先画下回合，两边进度错位）。 */
  if (mode === 'coop' && typeof coopOnTurnEnd === 'function' && coopOnTurnEnd()) return;

  generateEnemyPaths();
  logEnemyMainDirections();
  render();
}

/* ★ ISSUE-20261028-14 + 20261030-91：教程 HUD（唯一出口，写 DOM 的事不放到 rules 层去）。
 *
 * 三块，各管一件事（人类 2026-10-30 23:4x 的口径）：
 *   #tutBar    顶部 chip：只有「教程 3/6 · 基础操作」，**不再承载说明文字**，不挡点击。
 *   #tutText   叠在地图 y=6..9（4×9）上的说明区：顶部一排方向键（← 上一步 / → 下一步）+ 说明文字，半透明不遮全图。
 *   #tutCursor 平滑移动的光标指引：指向本步该去/该点的那一格（rules 层给坐标）。
 *
 * 定位一律用 getCellEl() 的**实时矩形**：棋盘是 grid + 2px gap 且 --cell 随窗口变，
 * 手算像素必错（ISSUE-91 §三 已经写死了这条）。#tutText / #tutCursor 挂在 #fxLayer 上
 * （#fxLayer 是 #board 的兄弟节点，paintBoard() 的 innerHTML 重建冲不掉它）。
 * 只在教程态创建，正式局零新增 DOM。
 */
function tutorialZoneRect() {
  try {
    const z = (typeof tutorialTextZone === 'function') ? tutorialTextZone() : { x0: 1, y0: 6, x1: 9, y1: 9 };
    const a = getCellEl(z.x0, z.y0), b = getCellEl(z.x1, z.y1);
    if (!a || !b) return null;
    const lr = fxLayer.getBoundingClientRect();
    const ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect();
    if (!(ra.width > 0) || !(rb.width > 0)) return null;
    return {
      left: ra.left - lr.left,
      top: ra.top - lr.top,
      width: (rb.left + rb.width) - ra.left,
      height: (rb.top + rb.height) - ra.top,
 };
 } catch (_) { return null; }
}

/* ★ ISSUE-20261031-94：教程整条链路走完 → 回选角厅（人类原话「完成所有教程之后回到大厅」）。
 * 为什么不自己拼赋值：initCharSelect() 是「回到大厅」的唯一出口，它同时做了
 *   ① tutorialAbort() + renderTutorialBar()（把 #tutText / #tutCursor 的 .on 摘掉）；
 *   ② candidateAbilities / candidatePoints 归零 —— 教程里用的是**被强制指定的角色**，
 *      留着这份加点会被带去正式局（issue §三-C 明确点过的坑）；
 *   ③ 重掷种子、清日志、重建自由移动层。
 *   手拼一遍只会漏其中某一条（联机退出走的也是这个出口，见 chrome.js#onlineQuit）。
 * ⚠️ 两处出口（回合结算 / 提示条「继续」）必须共用本函数 —— 漏一处就会「点继续直接开局、
 *   走回合反而回大厅」的分裂。 */
/* ★ ISSUE-20261031-110：入门三关的两个小工具。
 *
 * tutBlockHint()：玩家点了光标以外的格子时的提示。**必须限流** ——
 *   每点一下写一行日志会把日志区刷爆，玩家反而看不到真正的教程说明。
 *
 * tutPlanChanged()：规划态变化后推进教程步骤的唯一出口。
 *   为什么要有它：入门三关的步骤判据（铺路径 / 设节点 / 长按等待）全部在**规划阶段**
 *   就成立，而 tutorialAfterTurn 只在回合结束时跑 —— 只靠那条链路，第一关会永远停在第一步。
 *   'lesson' 用 setTimeout 切关：此刻还在 pointerup 里，initLevel 会重建整个棋盘 DOM，
 *   同步调用会让 releasePointerCapture 落在已经被移除的节点上。 */
let tutBlockShownAt = 0;
function tutBlockHint() {
  const now = Date.now();
  if (now - tutBlockShownAt < 1600) return;
  tutBlockShownAt = now;
  log('📖 教程里请点光标指着的那一格 —— 其它格子这一步用不到。');
}
function tutPlanChanged() {
  if (typeof tutorialIsOn !== 'function' || !tutorialIsOn()) return;
  if (typeof tutorialTick !== 'function') return;
  const r = tutorialTick();
  if (r === 'lesson') { setTimeout(() => { initLevel(); }, 0); return; }
  if (r === 'done') {
    log('✅ 教程结束！回到角色选择。');
    setTimeout(() => { returnToLobbyAfterTutorial(); }, 0);
    return;
  }
  if (typeof renderTutorialBar === 'function') renderTutorialBar();
}

function returnToLobbyAfterTutorial() {
  if (typeof initCharSelect === 'function') { initCharSelect(); return; }
  /* 兜底（裁剪版没有选角厅时保持旧行为，至少不会把玩家卡在教程相位） */
  level = 1;
  initLevel();
}

function renderTutorialBar() {
  const chip = document.getElementById('tutBar');
  const on = (typeof tutorialIsOn === 'function') && tutorialIsOn();
  if (!on) {
    if (chip) { chip.hidden = true; chip.textContent = ''; }
    const p0 = document.getElementById('tutText');
    const c0 = document.getElementById('tutCursor');
    if (p0) p0.classList.remove('on');
    if (c0) c0.classList.remove('on');
    /* 教程关闭时顺手清掉开始行动按钮的高亮（如果上一步留了的话） */
    const sb0 = document.querySelector('.start-btn.tut-point-start');
    if (sb0) sb0.classList.remove('tut-point-start');
    return;
 }

  let panel = document.getElementById('tutText');
  let cursor = document.getElementById('tutCursor');
  if (!panel || !cursor) {
    if (typeof fxLayer === 'undefined' || !fxLayer) return;
    if (!panel) { panel = document.createElement('div'); panel.id = 'tutText'; fxLayer.appendChild(panel); }
    if (!cursor) { cursor = document.createElement('div'); cursor.id = 'tutCursor'; fxLayer.appendChild(cursor); }
 }

  const p = tutorialProgress();
  const st = tutorialCurrentStep();
  const title = (typeof tutorialLessonTitle === 'function') ? tutorialLessonTitle() : '教程';

  /* ① 顶部 chip —— 只报进度，不放说明文字（说明在地图里） */
  if (chip) {
    chip.hidden = false;
    chip.textContent = '教程 ' + p.step + '/' + p.total + ' · ' + title;
 }

  /* ② 4×9 说明区 */
  /* ★ ISSUE-教程导航：说明文字上方加一排方向键按钮 —— ← 上一步 / → 下一步。
   *   · 下一步只在「本步已完成」或「本步是收尾总结步」时可点；
   *     未完成时禁用，从根上杜绝「跳过未完成的教程」。
   *   · 上一步在首步禁用；回退只是复习，不丢进度（计数器只增不减）。 */
  const isCont = !!(st && st.cond && st.cond.cont);
  const canPrev = tutorialStepIdx > 0;
  const canNext = isCont || (st && tutorialCondMet(st.cond));
  panel.innerHTML =
      '<div class="tut-nav">'
    +   '<button class="tut-prev" id="tutPrev"' + (canPrev ? '' : ' disabled') + ' title="上一步">&lt;</button>'
    +   '<button class="tut-next" id="tutNext"' + (canNext ? '' : ' disabled') + ' title="下一步">&gt;</button>'
    + '</div>'
    + '<div class="tut-step">第 ' + p.step + ' / ' + p.total + ' 步</div>'
    + '<div class="tut-body">' + tutorialTipText() + '</div>';
  const prevBtn = document.getElementById('tutPrev');
  if (prevBtn) prevBtn.onclick = function (e) {
    e.preventDefault();
    e.stopPropagation();
    tutorialBack();
    renderTutorialBar();
 };
  const btn = document.getElementById('tutNext');
  if (btn) btn.onclick = function (e) {
    e.preventDefault();
    e.stopPropagation();
    /* 收尾总结步用 force 推进（= 原「继续」语义）；普通步只在本步完成后才走。 */
    const s = tutorialCurrentStep();
    const force = !!(s && s.cond && s.cond.cont);
    const r = tutorialAdvance(force);
    if (r === 'lesson') { initLevel(); return; }
    if (r === 'done') { log('✅ 教程结束！回到角色选择。'); returnToLobbyAfterTutorial(); return; }
    renderTutorialBar();
 };
  const rect = tutorialZoneRect();
  if (rect) {
    panel.style.left = Math.round(rect.left) + 'px';
    panel.style.top = Math.round(rect.top) + 'px';
    panel.style.width = Math.round(rect.width) + 'px';
    panel.style.height = Math.round(rect.height) + 'px';
 }
  panel.classList.add('on');

  /* ③ 光标指引：指到「本步目标格」。首帧不做过渡（否则会从屏幕外"飞"进来，
   *    看着像动画卡了），之后每步切换才用 0.55s 平滑移动。 */
  const t = (typeof tutorialGuideTarget === 'function') ? tutorialGuideTarget() : null;
  /* 先清掉上一步可能留在开始行动按钮上的高亮（本步不是「按按钮」时复原） */
  const sbPrev = document.querySelector('.start-btn.tut-point-start');
  if (sbPrev) sbPrev.classList.remove('tut-point-start');
  if (t && t.button === 'start') {
    /* 本步教「按开始行动」：高亮开始行动按钮，棋盘光标收起 */
    const sb = document.querySelector('.start-btn');
    if (sb) sb.classList.add('tut-point-start');
    cursor.classList.remove('on');
 } else if (t && typeof t.x === 'number') {
    const c = cellCenter(t.x, t.y);
    const size = (cursor.getBoundingClientRect().width || 26);
    const first = !cursor.classList.contains('on');
    if (first) cursor.style.transition = 'none';
    cursor.style.transform = 'translate(' + Math.round(c.x - size / 2) + 'px,'
      + Math.round(c.y - size / 2) + 'px)';
    if (first) { void cursor.offsetWidth; cursor.style.transition = ''; }
    cursor.classList.add('on');
 } else {
    cursor.classList.remove('on');
 }

  /* chip 贴棋盘顶沿：那里是第 0 行（整行墙），压住它不会遮任何内容 */
  try {
    const br = boardEl.getBoundingClientRect();
    if (br && br.height > 0) {
      document.documentElement.style.setProperty('--tut-chip-top', Math.max(4, Math.round(br.top) + 4) + 'px');
 }
 } catch (_) {}
}

function onLevelClear() {
  if (phase === PHASE.LEVELCLEAR || phase === PHASE.GAMEOVER) return;   // 防止同回合被多个入口重复触发
  /* ★ ISSUE-20261031-110：教程关「清场」≠ 通关。
   * 第二关（弱点攻击）的教学目标就是把三只 1 HP 敌人一次打光，所以玩家一定会走到这里
   * （finishLevel / resolveStep / endRound / 调试秒杀 四个入口最终都汇入本函数）。
   * 放它进正式结算的后果：加经验、level+1、弹升级与藏品面板、往排行榜写成绩 ——
   * 而教程必须**零结算**（tutorial_test 的 D1–D8 就是钉这条）。
   * 这里改成「清场只是一次步骤满足」：交给教程推进，推进完该重开教程图就重开。 */
  if (typeof tutorialIsOn === 'function' && tutorialIsOn()) {
    const tutRes = (typeof tutorialAfterTurn === 'function') ? tutorialAfterTurn() : false;
    if (tutRes === 'lesson') { initLevel(); return; }
    if (tutRes === 'done') { returnToLobbyAfterTutorial(); return; }
    if (typeof renderTutorialBar === 'function') renderTutorialBar();
    return;
  }
  /* ★ ISSUE-20261031-128：合作局清场也要报 ready（这条不走 endRound）。
   * 不报的话服务端停在旧回合，下一关交计划会被 409 拒掉。 */
  if (typeof coopSendReady === 'function') coopSendReady();
  clearEnemyArrows();
  playerStats.currentHp = player.hp;
  if (selectedChar === 'vampire' && bloodDrops.length > 0) {
    const n = bloodDrops.length;
    let totalHeal = 0, totalSp = 0;
    for (let i = 0; i < n; i++) {
      const heal = Math.min(playerStats.maxHp - playerStats.currentHp, 2);
      if (heal > 0) { playerStats.currentHp += heal; totalHeal += heal; }
      if (vampireSp < VAMPIRE_SP_MAX) { vampireSp++; totalSp++; }
      const sass = sassExtraSp();
      if (sass && vampireSp < VAMPIRE_SP_MAX) { vampireSp++; totalSp++; }
 }
    log(`华法琳吸收了场上 ${n} 处血迹 🩸：恢复 ${totalHeal} HP、技力 +${totalSp}（${vampireSp}/${VAMPIRE_SP_MAX}）。`);
    bloodDrops = [];
    player.hp = playerStats.currentHp;
 }

  if (selectedChar === 'amiya' && amiyaBonusTargets > 0) {
    log(`阿米娅的技力 ${amiyaBonusTargets}/${amiyaSpMax()} 将继承到下一关。`);
 }
  if (selectedChar === 'fencer' && fencerSp > 0) {
    log(`泥岩的技力 ${fencerSp}/${FENCER_SP_MAX} 将继承到下一关。`);
 }
  if (selectedChar === 'vampire' && vampireSp > 0) {
    log(`华法琳的技力 ${vampireSp}/${VAMPIRE_SP_MAX} 将继承到下一关。`);
 }
  const clearedLevel = level;
  /* 玩家操作录制（ISSUE-83 强制开）：本关通关只记 outcome=cleared，整局没结束不 dump */
  if (window.ARK_REC) window.ARK_REC.levelCleared({ level: clearedLevel, player: player, enemies: enemies, kills: runKills });
  level += 1;
  /* ===== 经验结算（ISSUE-20261028-10） =====
   * 失血 = levelStartHp − endHp，endHp 取的是「华法琳吸完场上血迹之后」的 player.hp
   * （此时 playerStats.currentHp 已在函数开头同步过，两者一致）。
   * 数值必须在这里冻结，不能延后：
   *   ① openLevelUp() 由 setTimeout(600) 在两关之间触发，升级回满血会污染 endHp 口径；
   *   ② allocateAbilityPoint() 在 LEVELCLEAR 阶段会因体质变化加 HP，延后算等于加体质能刷经验。 */
  const endHp = player.hp;
  const xpInfo = computeLevelXp(levelStartHp, endHp);
  xp += xpInfo.gain;
  /* ★ ISSUE-20261031-100：击败带词条的敌人 → 关后经验加成。
   * 数值定案（ISSUE-100 §待确认-1）：**加成本关所有已击败敌人的「词条个数」之和**（每词条 +1）。
   *   不按「每只 +1」的理由：精英必带 2 词条，按只算会让精英与普通词条敌人等价，
   *   而精英已经通过 1.5×HP + 掉落 ❤️ 给过回报；按词条数算正好「越硬经验越多」，一句话能解释。
   * 为什么直接读 enemies 而不是累加计数器：进 onLevelClear 时本关敌人已全灭（调用点保证），
   *   数数组就行 —— 少一个「重开时可能忘了清」的跨关状态。
   * ⚠️ 必须早于 queueLevelUps()：否则这一份加成的升级不会在本关结算出来。 */
  const affixXp = (typeof enemies !== 'undefined' && enemies)
    ? enemies.reduce((s, e) => s + ((e && e.affixes) ? e.affixes.length : 0), 0)
    : 0;
  if (affixXp > 0) xp += affixXp;
  queueLevelUps();
  const willLevelUp = pendingLevelUps > 0;
  /* ★ ISSUE-20261030-80：金币产出（通关收口）。
   * 位置在 level += 1 之后、log 之前 —— 只取「通关固有奖励」，不掺任何击杀结算。
   * 教程不走本函数，所以不需要额外判教程态（currencyOnLevelClear 里还有一道双保险）。 */
  const coinGain = (typeof currencyOnLevelClear === 'function') ? currencyOnLevelClear() : 0;
  log(`第 ${clearedLevel} 关通过！行动 ${levelActions} 次 · 本关失血 ${xpInfo.hpLoss}（开局 ${levelStartHp} → 结束 ${endHp}，失血基准 ${xpInfo.ref}）→ 经验 +${xpInfo.gain + affixXp}${affixXp > 0 ? `（含词条敌人 +${affixXp}）` : ''}（${xp}/${xpThresholdForLevel(heroLevel)}）${coinGain > 0 ? ` · ${CURRENCY_NAME} +${coinGain}（共 ${currency} 枚）` : ''}。`);
  if (willLevelUp) {
    log(`⭐ 经验已满：连升 ${pendingLevelUps} 级，每次升级都要从奖励池选 1 个 buff，并获得 ${ABILITY_POINTS_PER_LEVELUP} 点属性点。`);
 }
  /* ★ ISSUE-20261028-06：收藏品与事件的记账，**必须早于下面任何定时器**——
   * afterClearGate() 是照着这两个标记决定弹什么的，晚一步就会看到上一关的状态。 */
  /* ★ ISSUE-20261031-126：战斗关通关计数 —— 判「该不该进事件关」的唯一依据。
   * ⚠️ 数的是**战斗关**：事件关自己不经过本函数（不走 onLevelClear），所以天然不会混进来。
   * 用 `level` 取模会错：事件关让 level 越跑越快，`level % 3` 完全错位。 */
  battleLevelsCleared += 1;
  /* ★ 收藏品不再按关数发放（并进事件池当一条加权事件，见 relics.js 的 RELIC_DRAFT_CHANCE）。
   * 下面两行原本是「每 RELIC_EVERY_N_LEVELS 关欠一次三选一」的记账，现已停用 ——
   * 变量保留不删是因为 drawer.js / reset.js / 若干测试仍引用它们，删了要同时改四处、
   * 收益为零而风险不为零。新代码**不要**再往里写。 */
  /* relicLevelsCleared += 1; */
  /* if (relicLevelsCleared % RELIC_EVERY_N_LEVELS === 0) relicOfferPendingCount += 1; */
  /* ★ 事件不再是「每关必弹的抽屉」，改成「每 3 个战斗关进一次的房间」——
   * 这里不再置 levelEventDue，改写由 afterClearGate() 判 battleLevelsCleared。 */

  /* 速效绷带：每关通关回复 3 HP/层（ISSUE-20261028-06）。
   * 放在这里而不是 initLevel：下一关开场会把 >maxHp 夹回去、<=0 兜成满血，
   * 那两处会吃掉本该属于「通关奖励」的回复量。 */
  if (relicCount('bandage') > 0 && player && player.alive) {
    const healed = relicHealPlayer(3 * relicCount('bandage'));
    if (healed > 0) log(`🩹 速效绷带：通关回复 ${healed} HP（${player.hp}/${player.maxHp}）。`);
 }

  phase = PHASE.LEVELCLEAR;
  render();

  /* 升级：HP 上限 + 体质加值、回满血，再从奖励池 3 选 1（升级次数由 pendingLevelUps 决定） */
  /* 定时器加上阶段校验：玩家可能已经点了「下一关」，避免过期定时器把同一关初始化两次 */
  if (willLevelUp) {
    setTimeout(() => { if (phase === PHASE.LEVELCLEAR) openLevelUp(); }, 600);
 } else {
    setTimeout(() => { if (phase === PHASE.LEVELCLEAR) enterAllocGate(); }, 700);
 }
}

/* 通关闸门：若仍有点数未分配，停在 levelclear 并强制先加点；否则进入下一关 */
function enterAllocGate() {
  if (playerStats.abilityPoints > 0) {
    log('📌 还有属性点未分配，角色面板（♟️）已打开，点六维图上的属性名加点，加完才能进入下一关。');
    render();
    drawerOpen('char');           // 属性抽屉已移除（ISSUE-20261029-37）：改用 ♟️ 角色面板做六维加点
 } else {
    afterClearGate();
 }
}
/* 「下一关」按钮：仅当所有属性点分配完毕才可用。
 * ISSUE-20261028-06 起**不再直接 initLevel()**：收藏品 / 事件还欠着时必须先处理完，
 * 否则玩家点「下一关」会直接跳过关卡事件、并把该拿的收藏品丢掉（掉落静默丢失最难查）。 */
function proceedNextLevel() {
  if (phase !== PHASE.LEVELCLEAR || playerStats.abilityPoints > 0) return;
  afterClearGate();
}

/* ★ ISSUE-20261030-47：奖励是否还欠着。
 * drawer.js 的 ✕ / 遮罩 / Esc 关闭前都会问这一句，为 true 就拒绝关闭。
 * 两条都为真才算欠着：levelUpOpen（浮层已铺开还没选）/ pendingLevelUps（还有几次没结算）。 */
function levelUpRewardPending() {
  return levelUpOpen || pendingLevelUps > 0;
}

/* =========================================================================
 * 收藏品 3 选 1 与关卡事件（ISSUE-20261028-06）
 *
 * ★ 通关后的完整流水线，顺序不能乱（历史上这里卡死过：5 局 3 局 stuck in levelclear）：
 *     通关 → 升级奖励(3选1) → 属性点(♟️) → 收藏品(每 3 关) → 事件(每关) → 下一关
 *   每一环都是**抽屉**而不是全屏遮罩，且只有处理完才会往后走；
 *   最后一环之后统一走 afterClearGate() 递归，所以任何一环「弹不出来」都能被下一环兜住，
 *   最坏情况也只是少一个面板，绝不会把玩家丢在 LEVELCLEAR 里干等 —— 「下一关」按钮同时兜底。
 *
 * ★ 状态变量（relicOfferOpen / relicOfferChoices / levelEventOpen / levelEventData /
 *   relicOfferPendingCount / levelEventDue / relicLevelsCleared）**全部声明在
 *   src/rules/relics.js**。模板里不要再 let 一遍，否则打包后重复声明直接语法错误。
 * ========================================================================= */

/* 通关闸门的续章：加点 → 收藏品 → 事件 → 下一关。任何一环不满足就继续往后走。 */
function afterClearGate() {
  if (phase !== PHASE.LEVELCLEAR) return;
  /* ★ ISSUE-20261031-110：教程关是独立模式 —— 不领奖励、不弹事件、不「进下一关」。
   * 正常路径上根本到不了这里（onLevelClear 在教程里直接早退，phase 永远不会变成 LEVELCLEAR），
   * 这条是给「将来有人把 LEVELCLEAR 用在别处」留的闸门，别删。 */
  if (typeof tutorialIsOn === 'function' && tutorialIsOn()) return;
  if (playerStats.abilityPoints > 0) { enterAllocGate(); return; }   // 属性点优先（闸门不能被绕过）
  /* ★ ISSUE-20261031-126：收藏品三选一抽屉与「每关弹一次的事件抽屉」**两条分支都已删除**。
   *   两个内容都搬进了事件关卡：进关踩 ❓ 弹一次事件，其中 50% 就是「三选一收藏品」。
   *   （`openRelicOffer` / `openLevelEvent` 两个函数保留 —— 后者仍是事件关的弹窗实现，
   *     前者已无调用点，留着是为了「以后想把收藏品抽屉加回来」时不用重写。） */
  /* 该进事件关？判据唯一出口：已通关的战斗关数是否是 EVENT_LEVEL_EVERY_N_BATTLES 的整数倍。 */
  if (eventLevelDueNow()) { initEventLevel(); return; }
  initLevel();
}

/* ★ ISSUE-20261031-126：这一次通关之后要不要进事件关。
 * ⚠️ 必须有 `> 0`：`battleLevelsCleared` 为 0 时 `0 % 3 === 0` 也成立，
 *   若这里被别处提前调用（例如未来把 afterClearGate 用在开局路径上），会一进场就掉进事件关。
 * ⚠️ 教程 / 联机都不参与：教程在 onLevelClear 就早退（到不了这里），联机走 pvp 独立结算。 */
function eventLevelDueNow() {
  if (typeof tutorialIsOn === 'function' && tutorialIsOn()) return false;
  if (mode === 'pvp') return false;
  return battleLevelsCleared > 0
      && battleLevelsCleared % EVENT_LEVEL_EVERY_N_BATTLES === 0;
}

/* =========================================================================
 * 事件关卡 · 主流程（ISSUE-20261031-126）
 *
 * 一整轮的形状：
 *   进关  initEventLevel()  → 房间地图 + 玩家站出生点 + 出口上锁
 *   探索  freeMoveTick()    → 自由走动（char-select.js 那套；❓ 靠近 0.5 格立即触发）
 *   事件  eventObjectTouch() → openLevelEvent() 弹抽屉 → 选完 → eventObjectFinish()
 *   解锁  eventObjectFinish() → 所有 ❓ 用完 → eventExitOpen = true
 *   离开  exitEventLevel()  → initLevel() 进下一个战斗关
 *
 * ⚠️ 三条不能动的不变量：
 *   ① `level` +1、`battleLevel` **不动**（人类拍板 5/6）。数值只读 battleLevel。
 *   ② 不走 onLevelClear —— 不给经验 / 不给金币 / 不改 levelStartHp（人类拍板：事件关独立于战斗结算）。
 *   ③ 出口解锁后**只认 `exitEventLevel()` 一条出口**，它直接调 initLevel()；
 *      绝不能回 afterClearGate()（battleLevelsCleared 没变 → 会无限重复进同一间房）。
 * ========================================================================= */

/* 自由移动层里事件关角色的 id。带双下划线前缀是为了不和真实角色 id 撞名
 * （candEls 是「id → 元素」的全局 Map，撞名会让大厅角色和房间角色互相顶掉）。 */
const EVENT_ACTOR_ID = '__event_player';

function initEventLevel() {
  /* 注册表被清空（改数据时手滑）→ 退回「直接进下一战斗关」。
   * 绝不能在这里 return 而不推进关卡：玩家会停在 LEVELCLEAR 里，点「下一关」再进一次本函数，
   * 表现为「按钮点了没反应」。 */
  const def = pickEventLevel();
  if (!def) { log('⚠️ 事件关注册表为空，跳过事件关直接进入下一关。'); initLevel(); return; }

  stopFreeMove();
  freeMoveClearEls();
  clearTimeout(pressTimer);
  isMoving = false;
  dragging = false;
  dragDownCell = null;
  pendingAttack = false;
  pendingChargeInfo = null;

  /* ★ 事件关也占一个关卡号（人类拍板 5）。battleLevel 不动 —— 它是「第几个战斗关」。 */
  level += 1;

  eventLevelData = def;
  ROWS = def.rows || BOARD_ROWS;
  COLS = def.cols || BOARD_COLS;
  map = buildEventRoomMap(def);
  eventExit = { x: def.exit.x, y: def.exit.y };
  eventObjects = instantiateEventObjects(def);
  eventExitOpen = false;
  levelEventDue = false;
  levelEventOpen = false;
  levelEventData = null;

  /* 战斗层全部清空：事件关没有敌人 / 血迹 / 骨头 / 路径 / 奖励格。
   * ★ 这些必须在进关时清，不能指望下一关的 initLevel 清 —— 事件关里 render() 会读它们，
   *   残留的 playerPath 会被当成「上一关的规划」画在地板上。 */
  enemies = [];
  playerPath = [];
  attackIndices = [];
  skillIndices = [];
  rewardItems = [];
  bloodDrops = [];
  boneDrops = [];
  roughRocks.clear();
  playerShield = 0;
  playerDodging = false;
  playerDodgeACBonus = 0;

  /* 玩家单位重建：血量沿用 playerStats.currentHp（事件关**不结算**血量，
   * 所以进关前后 currentHp 完全一致）。 */
  player = createPlayerUnit({ x: def.spawn.x, y: def.spawn.y });
  /* 自由移动用的连续坐标对象（不是 player，理由见 char-select.js 那段长注释） */
  eventActor = {
    id: EVENT_ACTOR_ID,
    x: def.spawn.x, y: def.spawn.y,
    fx: def.spawn.x, fy: def.spawn.y,
    icon: (CHARACTERS[selectedChar] || {}).icon || '❓',
  };

  phase = PHASE.EVENT;
  try { if (typeof closeCharInfoSheet === 'function') closeCharInfoSheet(); } catch (_) {}
  try { if (typeof drawerClose === 'function') drawerClose(); } catch (_) {}

  log(`🚪 第 ${level} 关 · 事件：你走进了一间${def.name}。走到 ❓ 看看这里有什么，出口在对面（要先把 ❓ 用完才开）。`);

  /* 与选角厅同一套节奏：先让格子布局稳定（updateCellSize），再渲染，最后量几何启动自由移动。
   * 顺序反了会在手机上量到旧格距 → 角色按错的比例摆放（偏半格到一格）。 */
  updateCellSize();
  render();
  setTimeout(() => {
    if (phase !== PHASE.EVENT) return;
    initFreeMoveEvent();
  }, 50);
}

/* 踩到 ❓：弹事件抽屉。
 * ★ 这里**不**把 obj.used 置 true —— 要等玩家真正选完（eventObjectFinish）。
 *   提前置 true 的后果：抽屉万一被关掉（虽然 84 号口径是强制不可关），
 *   房间里的 ❓ 已经变成「已用过」，出口却永远不解锁 → 死局。 */
function eventObjectTouch(obj) {
  if (phase !== PHASE.EVENT || !obj || obj.used) return;
  eventPendingObject = obj;
  levelEventDue = true;
  levelEventOpen = false;
  openLevelEvent();
}

/* 事件选完：标记 ❓ 已用 → 检查出口是否该解锁 → 恢复自由移动。
 * ★ 恢复自由移动这一步不能省：eventObjectTouch 里 stopFreeMove() 停表了，
 *   不重新 initFreeMoveEvent 的话，玩家选完事件会发现「角色不能动了」。 */
function eventObjectFinish() {
  if (eventPendingObject) eventPendingObject.used = true;
  eventPendingObject = null;
  levelEventDue = false;
  const wasOpen = eventExitOpen;
  eventExitOpen = eventAllObjectsUsed();
  if (!wasOpen && eventExitOpen) {
    log('🚪 出口的锁开了 —— 走到对面那扇门就能离开这间屋子。');
    ringFx(eventExit.x, eventExit.y, '#8fe28a');
  }
  render();
  if (phase === PHASE.EVENT) initFreeMoveEvent();
}

/* 离开事件关 → 下一个战斗关。
 * ⚠️ 直接 initLevel()，**不要**回 afterClearGate()：那里会重新判「该不该进事件关」，
 *   而 battleLevelsCleared 在事件关里没有变化 → 无限循环进同一间房。 */
function exitEventLevel() {
  if (phase !== PHASE.EVENT) return;
  stopFreeMove();
  freeMoveClearEls();
  /* ★ 事件关的运行时状态必须在这里清干净，不能指望「下次进关会重置」：
   *   · eventObjects / eventExitOpen 留着不改，任何读到它们的地方（渲染 / 测试 / 以后的成就判定）
   *     都会看到一份「上一间屋子」的快照；
   *   · eventActor 留着会让 freeMoveActors() 在事件相位之外也返回它（虽然调用点都判了相位，
   *     但这种「靠外部判断兜住」的隐含前提越少越好）。 */
  eventLevelData = null;
  eventObjects = [];
  eventActor = null;
  eventExitOpen = false;
  eventPendingObject = null;
  levelEventDue = false;
  levelEventOpen = false;
  levelEventData = null;
  log('🚪 你走出这间屋子，继续向前。');
  initLevel();
}

/* 收藏品三选一。锁与抽屉实际状态对齐（同 ISSUE-20261030-47 的教训：
 * 「开过就永远 true」的布尔会把后续每一次都早退掉）。 */
function openRelicOffer() {
  if (phase !== PHASE.LEVELCLEAR) return;
  if (relicOfferOpen) {
    if (typeof drawerIsOpen === 'function' && drawerIsOpen('relic')) return;
    relicOfferOpen = false;
 }
  const host = document.getElementById('drawerRelicBody');
  if (!host) return;
  relicOfferChoices = pickRelicChoices(3);
  /* 池子被抽空（理论上 15 件 × 15 次选择才会发生）：别再弹空面板，直接记账放行 */
  if (!relicOfferChoices.length) { relicOfferPendingCount = 0; afterClearGate(); return; }
  relicOfferOpen = true;
  const t = document.getElementById('drawerRelicTitle');
  if (t) t.textContent = `🎁 收藏品 · 已通关 ${relicLevelsCleared} 关`;
  host.innerHTML = `
    <div class="lv-sub">
      每通关 ${RELIC_EVERY_N_LEVELS} 关可从收藏品池取一件（同一件可重复获得，效果叠加）<br>
      稀有度：普通常见 · <b>★ 稀有</b>约 18%
    </div>
    <div class="lv-cards">
      ${relicOfferChoices.map(r => `
        <button class="lv-card" data-relic="${r.id}">
          <span class="ico">${iconify(r.icon)}</span>
          <span class="nm">${r.name}${r.rarity === 'rare' ? ' ★' : ''}</span>
          <span class="ds">${r.desc}</span>
          <span class="own">已拥有 <b>${relicCount(r.id)}</b> 层</span>
        </button>`).join('')}
    </div>`;
  drawerOpen('relic');
  host.querySelectorAll('[data-relic]').forEach(btn => {
    btn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (!relicOfferOpen) return;
      relicOfferOpen = false;
      applyRelic(btn.dataset.relic);
      if (relicOfferPendingCount > 0) relicOfferPendingCount -= 1;
      if (relicOfferPending()) { openRelicOffer(); return; }   // 连拿多次：原地换内容
      /* 关抽屉顺手清内容：不清的话 `#drawerRelicBody [data-relic]` 这些旧卡片会一直留在 DOM 里，
       * 谁要是按选择器去点（自动化脚本最容易这么干）就会点到早就失效的按钮，
       * 然后被上面的 `if (!relicOfferOpen) return` 静默吃掉 —— 看起来像卡死。 */
      host.innerHTML = '';
      drawerClose();
      afterClearGate();
 };
 });
}

/* 关卡事件：每关通关必弹。选项自带「什么都不做」的安全项，所以不存在卡死。
 * 效果执行包 try/catch —— 选项里要动 HP 上限 / 敌人数，抛错也不能把流程断在这一层。 */
function openLevelEvent() {
  /* ★ ISSUE-20261031-126：相位判据从「只认 LEVELCLEAR」扩成「LEVELCLEAR / EVENT 都行」。
   *   事件关里踩到 ❓ 弹的就是这个抽屉 —— 一套 UI 两处复用，避免再写一份「房间版事件面板」。 */
  if (phase !== PHASE.LEVELCLEAR && phase !== PHASE.EVENT) return;
  if (levelEventOpen) {
    if (typeof drawerIsOpen === 'function' && drawerIsOpen('event')) return;
    levelEventOpen = false;
 }
  const host = document.getElementById('drawerEventBody');
  if (!host) return;
  const ev = pickLevelEvent();
  if (!ev) {
    levelEventDue = false;
    if (phase === PHASE.EVENT) eventObjectFinish(); else afterClearGate();
    return;
  }
  levelEventOpen = true;
  levelEventData = ev;
  const t = document.getElementById('drawerEventTitle');

  /* ---------------- 收藏品三选一（RELIC_DRAFT_EVENT） ----------------
   * 内容是**运行时生成**的（每次 pickRelicChoices(3) 三张都不同），所以不能走下面那套
   * 静态 `ev.options` 渲染。人类拍板 3/4：收藏品并进事件池、以 50% 权重出现。 */
  if (ev.isRelicDraft) {
    const choices = pickRelicChoices(3);
    if (!choices.length) {
      /* 池子空（只有改数据时手滑才会发生）→ 静默回落。
       * 绝不能弹一个点不动的空面板：事件抽屉是**强制不可关**的，空面板 = 死局。 */
      log('⚠️ 收藏品池为空，这一次什么也没抽到。');
      levelEventOpen = false;
      levelEventData = null;
      if (phase === PHASE.EVENT) { eventObjectFinish(); return; }
      levelEventDue = false;
      afterClearGate();
      return;
    }
    if (t) t.innerHTML = iconify(`${ev.icon} ${ev.name}`);
    host.innerHTML = `
      <div class="lv-sub">${ev.desc}<br><b>从下面三件里挑一件带走。</b></div>
      <div class="lv-cards">
        ${choices.map(r => `
          <button class="lv-card" data-relic="${r.id}">
            <span class="ico">${iconify(r.icon)}</span>
            <span class="nm">${r.name}${r.rarity === 'rare' ? ' ★' : ''}</span>
            <span class="ds">${r.desc}</span>
            <span class="own">已拥有 <b>${relicCount(r.id)}</b> 层</span>
          </button>`).join('')}
      </div>`;
    drawerOpen('event');
    host.querySelectorAll('[data-relic]').forEach(btn => {
      btn.onclick = (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (!levelEventOpen) return;
        levelEventOpen = false;
        applyRelic(btn.dataset.relic);
        levelEventData = null;
        /* ★ 必须在 drawerClose() 之前清 levelEventDue —— drawer.js#drawerClose()
         *   会问 levelEventPending()（= levelEventDue），true 就**拒绝关闭**（84 号口径：
         *   事件抽屉强制不可关）。普通事件分支本来就有这一行，收藏品分支漏了 →
         *   事件关里抽到「遗物残骸」时，选完遗物 `used/exitOpen` 都对了，抽屉却死活不关，
         *   表现为「房间灯亮了但面板糊在脸上」。战斗关里之所以没暴露：
         *   eventObjectFinish/afterClearGate 之后 levelEventDue 反正会被改，而抽屉早已关过。 */
        levelEventDue = false;
        host.innerHTML = '';        /* 清场：别留失效按钮在 DOM 里（自动化最容易点到） */
        drawerClose();
        /* ★ 事件关：选完就恢复自由移动并检查出口；
         *   战斗关（LEVELCLEAR）：回到统一闸门。两条分支不能混。 */
        if (phase === PHASE.EVENT) { eventObjectFinish(); return; }
        levelEventDue = false;
        afterClearGate();
      };
    });
    return;
  }

  /* ---------------- 普通事件（11 条静态池） ---------------- */
  /* ★ ISSUE-20261030-64：事件标题里带 icon，必须是 innerHTML（textContent 会把 <svg> 当字打出来） */
  if (t) t.innerHTML = iconify(`${ev.icon} ${ev.name}`);
  host.innerHTML = `
    <div class="lv-sub">${ev.desc}</div>
    <div class="lv-cards">
      ${ev.options.map((o, i) => `
        <button class="lv-card" data-opt="${i}">
          <span class="ds">${o.label}</span>
        </button>`).join('')}
    </div>`;
  drawerOpen('event');
  host.querySelectorAll('[data-opt]').forEach(btn => {
    btn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (!levelEventOpen) return;
      levelEventOpen = false;
      const opt = ev.options[Number(btn.dataset.opt)];
      try {
        if (opt && typeof opt.run === 'function') opt.run();
 } catch (err) {
        /* 选项效果出错绝不能吞掉流程：记一笔然后照常往下走 */
        console.error('[level event]', err);
        log('⚠️ 事件结算出错，已跳过（原因见控制台）。');
 }
      levelEventDue = false;
      levelEventData = null;
      host.innerHTML = '';          // 同收藏品抽屉：关掉就清场，别留失效按钮在 DOM 里
      drawerClose();
      /* ★ 事件关：选完恢复自由移动（eventObjectTouch 里停过表）；
       *   战斗关：事件可能给了属性点 / 收藏品（血色契约），所以回统一闸门而不是直接 initLevel。 */
      if (phase === PHASE.EVENT) { eventObjectFinish(); return; }
      afterClearGate();
 };
 });
}

/* =========================================================
 * 升级：等级 +1 → HP 上限 + 体质加值 → 回满血 → 奖励池 3 选 1
 * ========================================================= */
function openLevelUp() {
  if (phase !== PHASE.LEVELCLEAR) return;
  if (levelUpOpen) {
    /* ★ ISSUE-20261030-47：锁要跟抽屉的实际状态对齐，不能用「开过就永远 true」的布尔。
     * 抽屉已经不在前台（被别的抽屉顶掉 / 被关掉 / 根本没弹出来）时，把锁复位重弹一次；
     * 否则第二次升级会在这里早退，pendingLevelUps 永远扣不掉 —— 表现就是
     * 「显示请选择一项奖励，但没有奖励，也点不到下一关」。 */
    if (typeof drawerIsOpen === 'function' && drawerIsOpen('levelup')) return;
    levelUpOpen = false;
 }
  if (pendingLevelUps > 0) {
    pendingLevelUps -= 1;
    heroLevel += 1;
    const conMod = Math.max(0, abilityMod(playerStats.abilities.con));
    lastLevelUpConMod = conMod;
    levelHpBonus += conMod;
    recomputePlayerDerivedStats();
    playerStats.currentHp = playerStats.maxHp;        // 升级回满血
    /* 属性点与等级同时到账（ISSUE-20261028-03）：2 点自由分配，可叠同一项 */
    playerStats.abilityPoints += ABILITY_POINTS_PER_LEVELUP;
    if (player) { player.maxHp = playerStats.maxHp; player.hp = playerStats.maxHp; }
    log(`⭐ 升级！Lv.${heroLevel}：HP 上限 +${conMod}（体质加值，累计 +${levelHpBonus}），生命已回满（${playerStats.maxHp}/${playerStats.maxHp}），获得 ${ABILITY_POINTS_PER_LEVELUP} 点属性点。`);
    /* ISSUE-20261029-28：预备干员的升级福利 —— **额外**获得一个收藏品。
     * 走「随机直接到账」而不是「再弹一次三选一」：人类原话是「额外获得一个收藏品」，
     * 多一次三选一会让预备干员的收藏品数量翻倍（3 选 1 变 2 个三选一），那是另一种规则。
     * 连升多级时每次 openLevelUp 都会进这里，所以连升 2 级 = 额外 2 个，符合「每次升级」。 */
    if (selectedChar === 'rookie') {
      const extra = pickRelicChoices(1)[0];
      if (extra) {
        log(`🎁 预备干员专属：本次升级额外获得一个收藏品 —— ${extra.icon} ${extra.name}。`);
        applyRelic(extra.id);
 }
 }
    updateStats();
 }
  showLevelUpOverlay(lastLevelUpConMod);
}

/* ★ ISSUE-20261028-06：pickRelicChoices / applyRelic 已整体搬进 src/rules/relics.js。
 * 这里原来还留着一份旧副本，构建的「无重复定义」校验会直接报红（实测 pickRelicChoices ×2、applyRelic ×2）。
 * 别再往模板里抄回来 —— 规则层的东西归 src/rules/**，模板只管 UI 与流程。 */

function showLevelUpOverlay(conMod) {
  if (levelUpOpen) return;
  const host = document.getElementById('drawerLevelUpBody');
  if (!host) return;
  levelUpOpen = true;
  const choices = pickRelicChoices(3);
  const lvTitle = document.getElementById('drawerLevelUpTitle');
  if (lvTitle) lvTitle.textContent = '⭐ 升级 Lv.' + heroLevel;
  /* 浮层 = 侧边栏（ISSUE-20261028-09 G）：不再创建全屏 .lv-mask，内容直接铺在抽屉里 */
  host.innerHTML = `
    <div class="lv-sub">
      HP 上限 +${conMod}（体质加值）· 生命已回满<br>
      从奖励池中选择 1 个 buff（同一 buff 可重复获得，效果叠加）
    </div>
    <div class="lv-cards">
      ${choices.map(b => `
        <button class="lv-card" data-buff="${b.id}">
          <span class="ico">${iconify(b.icon)}</span>
          <span class="nm">${b.name}</span>
          <span class="ds">${b.desc}</span>
          <span class="own">已拥有 <b>${relics[b.id] || 0}</b> 层</span>
        </button>`).join('')}
    </div>`;
  drawerOpen('levelup');
  host.querySelectorAll('[data-buff]').forEach(btn => {
    btn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (!levelUpOpen) return;
      levelUpOpen = false;
      applyRelic(btn.dataset.buff);
      /* 一次通关可能连升多级（ISSUE-20261028-10）：还有待结算的升级就接着换下一张，
       * 全部选完才进加点闸门。
       * ★ ISSUE-20261030-47：奖励抽屉现在关不掉了（drawerClose 会拒绝），所以连升时
       * 不再「清空 + 收起 + 350ms 后重开」，直接原地换内容，省掉中间那一下空面板。 */
      if (pendingLevelUps > 0) {
        openLevelUp();
 } else {
        host.innerHTML = '';
        drawerClose();
        enterAllocGate();
 }
 };
 });
}

/* src: src/ui/chrome.js 第 1 段/beforeLogPanel */
/* P0.1-4 拆分 · 设置与日志面板外壳
 *
 * ISSUE-20261028-09 G 起，旧版「左上角可拖动悬浮窗」整体废除：
 *  - 删除 LOG_POS_KEY / clampLogPanelPos() / bindLogDrag() 与绝对定位拖动；
 *  - localStorage['ark_log_pos'] 读到也直接忽略（布局已完全不同，不迁移）；
 *  - 设置内容改为 #drawerSettings 抽屉，开关仍是左上角同一个 ⚙（位置不变）。 */
const logResetBtn  = document.getElementById('logResetBtn');
const logRotateBtn = document.getElementById('logRotateBtn');
const setOpenBtnEl = document.getElementById('setOpenBtn');

/* 兼容旧调用点：语义改成「开/关设置抽屉」 */
function setSettingsOpen(open) {
  if (open) drawerOpen('settings');
  else if (drawerIsOpen('settings')) drawerClose();
}

if (setOpenBtnEl) setOpenBtnEl.addEventListener('click', function (e) {
  e.stopPropagation();
  drawerToggle('settings');
});

// 旧的悬浮窗坐标不再有任何意义：清掉，避免以后有人以为它还在生效
try { localStorage.removeItem('ark_log_pos'); } catch (_) {}

/* =========================================================================
 * 隐藏调试开关（ISSUE-20261028-11）
 * 在设置抽屉标题栏的版本号 #setVer 上「连点 5 次，相邻间隔 ≤500ms」切换调试模式。
 * 设计要点：
 *  - 触发时不弹 toast / 不写日志 / 不闪浮字，玩家侧零感知；状态只在
 *    window.__ARK_DEBUG__ 暴露（控制台可读，不算提示）。
 *  - 用 pointerdown 而非 click：标题栏在抽屉里，stopPropagation + preventDefault
 *    既能触发计数又不至于选中文字。
 *  - touch-action:manipulation 已在 CSS 侧加上，避免移动端双击缩放吞掉快速连点。
 *  - 已开启状态下再连满 5 次 → 关闭（A3）；任一次超 500ms → 计数立即清零（A2）。
 *  - 三种重置点（回选角 / 开新局 / 重置 / 联机）在各自入口调用 setDebugMode(false)。
 *  - ISSUE-20261030-55：加了管理员门槛 —— 只有「账号口令 === ARK_ADMIN_CODE」的账号认这套
 *    连点，其余账号连点零反应；真正的闸门在 setDebugMode() 里（state.js），这里只是省事。
 * ========================================================================= */
(function bindHiddenDebugSwitch() {
  const el = document.getElementById('setVer');
  if (!el) return;
  const NEED = 5, GAP_MS = 500;
  let count = 0, lastAt = 0;
  const evt = ('onpointerdown' in window) ? 'pointerdown' : 'click';
  el.addEventListener(evt, function (e) {
    e.stopPropagation();
    e.preventDefault();
    // ISSUE-20261030-55：这套连点只认管理员账号（口令 === ARK_ADMIN_CODE）。
    // 其他账号：不累加计数、不切换调试态、不给任何提示 —— 与「玩家侧零感知」口径一致。
    if (!isAdmin()) { count = 0; lastAt = 0; return; }
    const now = Date.now();
    count = (now - lastAt <= GAP_MS) ? count + 1 : 1;
    lastAt = now;
    if (count >= NEED) {
      count = 0; lastAt = 0;
      setDebugMode(!debugMode);
    }
  }, { passive: false });
})();

/* 「重开」：随时回到选角大厅（ISSUE-20261029-22：人类明确「重开不用提示是否确定」，
 * 点了直接走 drawerClose() + initCharSelect()，与设置抽屉里其余按钮同一节奏。
 * 取舍已知：战斗中手滑点它会立刻丢当前局、不可撤销 —— 这是「少一次点击 > 防误触」的
 * 明确要求。将来若要防误触，正确做法是改成长按，不要把 confirm 加回来。
 * ★ ISSUE-20261029-46 D：联机模式下同一个按钮文案变成「退出」，点了断开联机再回选角厅。 */
logResetBtn.addEventListener('click', function (e) {
  e.stopPropagation();
  drawerClose();
  if (onlineIsActive()) { onlineQuit(); return; }
  initCharSelect();
});
/* ★ ISSUE-20261028-14 D3：设置面板「📖 教程」= 教程重看入口。
 *
 * 为什么不是「点一下直接原地重播」：角色课的每一步判据都绑在**那个角色**的技力上
 * （泥岩要挨打攒、华法琳要捡血迹），原地换角色会把整局的属性 / 收藏品 / 等级全搅乱。
 * 所以这里的动作是「记下要看哪一节 → 回选角大厅 → 由 selectCharacter 认这节课」，
 * 走的是和第一次进游戏完全同一条路，不多一条分支。 */
(function bindTutorialReplay() {
  const btn = document.getElementById('tutReplayBtn');
  const list = document.getElementById('tutReplayList');
  if (!btn || !list) return;
  function buildList() {
    /* ★ ISSUE-110：入门三关取代了老的「基础操作」通用课，重看列表也拆成三节。 */
    const items = [
      ['action', '📖 第一关 · 行动'],
      ['battle', '⚔ 第二关 · 弱点攻击'],
      ['mutual', '💥 第三关 · 相杀'],
    ];
    if (typeof CHARACTERS !== 'undefined' && typeof tutorialLessonForChar === 'function') {
      for (const id of Object.keys(CHARACTERS)) {
        const lid = tutorialLessonForChar(id);
        if (!lid) continue;
        items.push([lid, '▶ ' + CHARACTERS[id].icon + ' ' + CHARACTERS[id].name + ' · 专属课']);
      }
    }
    let html = '<div class="tut-replay-hint">选一节 → 回选角大厅，进去后自动开始（角色课固定用该角色）</div>';
    for (const it of items) {
      html += '<button data-tut="' + it[0] + '">' + it[1] + '</button>';
    }
    list.innerHTML = html;
    list.querySelectorAll('button[data-tut]').forEach(function (b) {
      b.addEventListener('click', function (e) {
        e.stopPropagation();
        const lid = b.getAttribute('data-tut');
        try { window.__ARK_TUT_REPLAY = lid; } catch (_) {}
        list.hidden = true;
        drawerClose();
        initCharSelect();
      });
    });
  }
  btn.addEventListener('click', function (e) {
    e.stopPropagation();
    if (list.hidden) { buildList(); list.hidden = false; }
    else list.hidden = true;
  });
})();

/* 「👤 账号与排行」角标（ISSUE-20261029-21 S2 / ISSUE-20261029-45 重构）
 * 外壳（账号 + 榜单 + 面板）已内联进本文件，不再有 iframe 边界，所以原来那套
 * 「上报棋盘矩形 → postMessage 开面板 → 等外壳回发状态」全部删除：
 *   · 面板位置：ArkShell.panel.place() 直接读 #board 的 rect
 *   · 开合状态：ArkShell.panel.setOpen() 直接改这里的 .on / aria-expanded
 *   · 按钮不再「非嵌入就隐藏」—— 单文件里它永远有功能。 */
(function bindLobbyOpenBtn() {
  const btn = document.getElementById('lobbyOpenBtn');
  if (!btn) return;
  btn.addEventListener('click', function (e) {
    e.stopPropagation();
    if (typeof window.arkOpenLobby === 'function') window.arkOpenLobby();
  });
})();

/* src: src/ui/layout.js 第 2 段/beforeLayoutToggle */
/* P0.1-4 拆分 · 20261028c 基线（templates/game.html）3382-3428 行 · 横竖版切换：LAYOUT_KEY / currentLayout / setLayout / 旋转按钮 / initLayoutMode */
// 「旋转」：切换横版（地图左/UI右）↔ 竖版（地图上/UI下）
const LAYOUT_KEY = 'ark_layout';
function currentLayout() {
  return document.body.classList.contains('layout-v') ? 'v' : 'h';
}
function setLayout(mode, save) {
  const v = mode === 'v';
  document.body.classList.toggle('layout-v', v);
  document.body.classList.toggle('layout-h', !v);
  if (save) { try { localStorage.setItem(LAYOUT_KEY, v ? 'v' : 'h'); } catch (_) {} }
  try {
    if (v) {
      // 竖版：侧栏铺满宽度（六维图在抽屉里，尺寸固定，不再随侧栏变化）
      sidebarEl.style.width = '';
    } else if (window.innerWidth > 760) {
      // 横版：恢复上次拖动宽度
      let saved = NaN;
      try { saved = parseInt(localStorage.getItem(SIDE_W_KEY), 10); } catch (_) {}
      if (!isNaN(saved) && saved > 0) applySidebarWidth(saved, false);
      else fitSidebarToWidth();
    } else {
      sidebarEl.style.width = '';
    }
  } catch (_) {}
  // 布局类切换后必须重算正方形边长（否则会残留上一个方向的尺寸）
  setTimeout(() => {
    updateCellSize();
    if (player || phase === PHASE.CHAR_SELECT) render();
  }, 30);
}
logRotateBtn.addEventListener('click', (e) => {
  e.stopPropagation();
  setLayout(currentLayout() === 'v' ? 'h' : 'v', true);
});
/* 按「设备形态」选默认横竖版。
 *
 * ★ ISSUE-20261101-154（人类 2026-11-01 22:2x「手机端现在没有自动旋转，让手机端点开
 *   就是竖屏布局」）：**手机端默认竖版，不再按「高 ≥ 宽」才给竖版。**
 *
 * 旧逻辑是「innerWidth<=760 且 innerHeight>=innerWidth → 竖版」，两个坑：
 *   ① 浏览器地址栏/软键盘一伸缩，innerHeight 与 innerWidth 的比较会抖，同一台手机
 *      一会儿竖版一会儿横版 —— 就是人类说的「没有自动旋转」；
 *   ② 记忆里存着 'h'（当时横持自动选的）就先读记忆，竖持点开也是横版。
 * 现在：手机**一律先进竖版**（竖持 11 列 × 22 行，格子由宽度主导、铺满屏幕宽度），
 * 只有「横持且高度矮到竖版会把格子压到看不清」（<560px，横持手机 390~430 这一段）
 * 才回落到横版 22 列 —— 不然横持时 22 行只能塞进 15px 的格子，反而没法玩。
 * 平板（>760）与桌面仍按原规则走横版。
 */
function isPhoneViewport() {
  return window.innerWidth <= 760;
}
function pickLayout() {
  if (!isPhoneViewport()) return 'h';
  const sideways = window.innerWidth > window.innerHeight;
  return (sideways && window.innerHeight < 560) ? 'h' : 'v';
}
(function initLayoutMode() {
  /* ★ 手机端**不读** localStorage 的横竖记忆：老用户浏览器里可能存着 'h'
     （当时横持手机自动选的），照着读就永远是横版，人类要的「点开就是竖屏」当场失效。
     判据除了「宽 ≤ 760」，还兜住**横持手机**（宽 > 高 且 高 < 560）—— 那时 innerWidth
     会超过 760（如 844），但按桌面去读记忆同样会把竖版记忆带进横持布局。
     桌面/平板仍尊重记忆（那是用户主动点「旋转」选的）。 */
  const sidewaysPhone = window.innerWidth > window.innerHeight && window.innerHeight < 560;
  if (isPhoneViewport() || sidewaysPhone) { setLayout(pickLayout(), false); return; }
  let m = null;
  try { m = localStorage.getItem(LAYOUT_KEY); } catch (_) {}
  if (m === 'v' || m === 'h') setLayout(m, false);
  else setLayout(pickLayout(), false);
})();

/* ★ ISSUE-20261101-138：视口一变就重算格栅。
 *
 * 出过的 P1（人类 2026-11-01 05:5x 真机）：手机进游戏后地图只剩两行、UI 压在地图上。
 * 根因之一是**全项目没有任何 window.resize → updateCellSize() 的挂钩** ——
 * 只有切横竖版的 setLayout() 里补了一次。于是：
 *   · Telegram 小程序从半屏展开到全屏（只改 innerHeight，不改布局类）
 *   · 头部地址栏收起 / 软键盘弹出收起
 *   · 分屏、旋转后浏览器延迟改视口
 * 这些场景格栅都还按**旧高度**排，一眼就是「格子没铺满、UI 跑到地图上」。
 * 这里统一兜住：window.resize + orientationchange + visualViewport.resize，
 * 80ms 防抖，只重算几何（CSS 变量），不重绘棋盘 —— 重算本身很便宜，也不会闪。 */
(function initViewportWatch() {
  let timer = 0;
  function kick() {
    clearTimeout(timer);
    timer = setTimeout(function () {
      try { if (typeof updateCellSize === 'function') updateCellSize(); } catch (_) {}
      /* 虚拟按钮的高度也要重测：横竖版切换后按钮排布会变（原来的 140ms 太慢，
         格栅会在按钮缩高之前先按旧高度算一遍） */
      try { if (typeof syncVpadInset === 'function') syncVpadInset(); } catch (_) {}
    }, 80);
  }
  window.addEventListener('resize', kick);
  window.addEventListener('orientationchange', kick);
  if (window.visualViewport && window.visualViewport.addEventListener) {
    window.visualViewport.addEventListener('resize', kick);
    window.visualViewport.addEventListener('scroll', kick);
  }
})();

/* ★ ISSUE-20261031-98 · PRTS 自定义光标开关（设置面板「光标·开 / 光标·关」）
 * 实现思路：不逐条改那 31 条 cursor: 规则，只给 <html> 挂一个 class ——
 * templates/game.html 里 `html.no-prts-cursor { --cur-arrow: default; --cur-no: not-allowed; }`
 * 把两个变量重定义成系统值，31 条走 var() 的规则同时失效；字面值例外（col-resize / text）自动存活。
 * 默认「开」= 保持现状，不静默改变老玩家观感；只有用户主动点过才写 localStorage。
 * 范围：只关「玩家鼠标」—— 教程指引 #tutCursor 读的是 --cur-src，本开关刻意不动它。
 * 整段包 IIFE：产物是单脚本共享作用域，避免新顶层标识符撞名（verify 有「无重复定义」检查）。 */
(function initPrtsCursorToggle() {
  const KEY = 'ark_prts_cursor';
  const btn = document.getElementById('curToggleBtn');
  function isOn() {
    return !document.documentElement.classList.contains('no-prts-cursor');
  }
  function apply(on, save) {
    document.documentElement.classList.toggle('no-prts-cursor', !on);
    if (btn) {
      btn.textContent = on ? '光标·开' : '光标·关';
      btn.title = on ? '当前：PRTS 自定义光标（点击恢复系统光标）' : '当前：系统光标（点击恢复 PRTS 光标）';
      btn.setAttribute('aria-pressed', on ? 'true' : 'false');
    }
    if (save) { try { localStorage.setItem(KEY, on ? '1' : '0'); } catch (_) {} }
  }
  let saved = null;
  try { saved = localStorage.getItem(KEY); } catch (_) {}
  apply(saved !== '0', false);   // 无记忆 / 读不到 → 默认开
  if (btn) {
    btn.addEventListener('click', function (e) {
      e.stopPropagation();
      apply(!isOn(), true);
    });
  }
})();

/* =========================================================
 * ★ 联机对战（PvP）
 *
 * 单人流程完全不受影响：mode 默认为 'solo'，只有从这里进来才切到 'pvp'。
 *
 * 同步模型：
 *   双方各自规划 → 都把计划交给房间服务 → 服务端凑齐后广播两份计划 + 一颗种子
 *   → 两端各自跑 pvpResolveTurn（纯函数）→ 得到同一串事件 → 各自播动画
 *   → 都播完报 ready → 服务端推进回合。
 *
 * 因为结算是纯函数且种子一致，两端画面必然一致，不需要任何「谁是权威」的仲裁。
 * 代价是服务端无法校验计划合法性（规则只存在于客户端），只适合熟人局。
 *
 * PvP v1 支持：移动 / 普通攻击 / 闪避（等待节点）。
 * 技能节点（冲锋 / 反击 / 爆发 / 血浆）未接入，规划时会被忽略并提示。
 * ========================================================= */
let pvpUnits = null;          // [slot0, slot1] 结算权威状态
let pvpSlot = 0;              // 我是哪个座位
let pvpTurn = 0;
let pvpChars = ['', ''];
let pvpNames = ['', ''];
/* ISSUE-20261029-26：双方六维加点（服务端 start 事件里的 `abilities`，形如 [[6,8,8,12,10,10],[...]]）。
 * 任一为 null 表示那一端没传（老客户端/老服务端）→ 回退静态 CHARACTERS 值。 */
let pvpAbilities = [null, null];
let pvpWaiting = false;       // 已交计划，等对手
let pvpOver = false;
let pvpPick = 'vampire';      // 面板里选的角色
const PVP_SPAWNS = [{ x: 2, y: 4 }, { x: 6, y: 4 }];   // 9x9 竞技场，左右对称

/* ---------------- 传输层（与 net/net.js 同协议，内联以维持单文件） ------------- */
const PVP_NET = (function () {
  let base = '', room = null, token = null, slot = 0, seq = 0, alive = false, ctrl = null;
  /* ★ ISSUE-20261031-128：房间属性（服务端 create 回带的 mode/cap）。
   * 老服务端不返回这两个字段 → 兜底 pvp / 2，行为与改动前一致。 */
  let roomMode = 'pvp', roomCap = 2;
  const hs = {};
  function on(k, fn) { (hs[k] = hs[k] || []).push(fn); }
  function fire(k, d) {
    (hs[k] || []).forEach(function (f) { try { f(d); } catch (e) { console.error('[PVP]', e); } });
 }
  function req(path, body) {
    const opt = { method: body ? 'POST' : 'GET', cache: 'no-store' };
    if (body) { opt.headers = { 'Content-Type': 'application/json' }; opt.body = JSON.stringify(body); }
    return fetch(base + path, opt).then(function (r) {
      return r.json().catch(function () { return {}; }).then(function (j) {
        if (!r.ok) { const e = new Error(j.error || ('HTTP ' + r.status)); e.status = r.status; throw e; }
        return j;
 });
 });
 }
  function absorb(list) {
    for (let i = 0; i < list.length; i++) {
      const ev = list[i];
      if (ev.seq > seq) seq = ev.seq;
      if (ev.type === 'turn') pvpTurn = ev.turn + 1;
      if (ev.type === 'next') pvpTurn = ev.turn;
      fire(ev.type, ev); fire('*', ev);
 }
 }
  function loop() {
    if (!alive) return;
    ctrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    const opt = { cache: 'no-store' };
    if (ctrl) opt.signal = ctrl.signal;
    fetch(base + '/api/poll?room=' + encodeURIComponent(room) +
          '&token=' + encodeURIComponent(token) + '&since=' + seq + '&wait=25', opt)
      .then(function (r) { return r.json(); })
      .then(function (j) {
        if (j.events && j.events.length) absorb(j.events);
        if (typeof j.turn === 'number' && j.turn > pvpTurn) pvpTurn = j.turn;
        loop();
 })
      .catch(function (e) {
        if (!alive) return;
        if (e && (e.status === 403 || e.status === 404)) { alive = false; fire('closed', { reason: e.message }); return; }
        setTimeout(loop, 1000);
 });
 }
  function start() { if (alive) return; alive = true; loop(); }
  return {
    on: on,
    setBase: function (b) {
      base = String(b || '').replace(/\/+$/, '');
      if (location.protocol === 'https:' && /^http:\/\//i.test(base)) {
        throw new Error('页面是 https，服务地址却是 http://，浏览器会拦截。请改用 https 隧道地址。');
 }
 },
    room: function () { return room; },
    slot: function () { return slot; },
    /* ★ ISSUE-20261031-128：房间模式 / 容量（合作大厅的人数显示与开始按钮靠这两个值） */
    mode: function () { return roomMode; },
    cap: function () { return roomCap; },
    /* ★ 合作模式：房主点「开始」→ 服务端摇种子并广播 start。 */
    start: function () { return req('/api/start', { room: room, token: token }); },
    create: function (name, charId, abilities, mode) {
      /* ★ ISSUE-20261031-128：`mode` 缺省不传 → 服务端按 'pvp' 处理（老路径一个字节不变）。 */
      const body = { name: name, charId: charId, abilities: abilities || null };
      if (mode) body.mode = mode;
      return req('/api/create', body).then(function (j) {
        room = j.room; token = j.token; slot = j.slot; seq = 0;
        roomMode = j.mode || 'pvp';
        roomCap = j.cap || 2;
        start(); return j;
 });
 },
    join: function (r, name, charId, abilities) {
      return req('/api/join', { room: r, name: name, charId: charId, abilities: abilities || null }).then(function (j) {
        /* DEBUG-20261030-02：归一化必须与服务端 `_join` 的 `.strip().upper()` 完全一致，
         * 否则「存进闭包的 room」和「服务端 ROOMS{} 的键」可能不是同一个字符串，
         * 后续 /api/poll 会对着一个不存在的房间长轮询 → 表现为「莫名掉线」。 */
        room = String(r).trim().toUpperCase(); token = j.token; slot = j.slot; seq = 0;
        /* ★ ISSUE-20261031-128：加入者拿到的 mode 来自服务端；老服务端没有这个字段，
         * 用 cap 兜底推断（cap=4 只可能是合作房）。 */
        roomMode = j.mode || ((j.cap === 4) ? 'coop' : 'pvp');
        roomCap = j.cap || 2;
        start(); return j;
 });
 },
    plan: function (t, plan) { return req('/api/plan', { room: room, token: token, turn: t, plan: plan }); },
    ready: function (t) { return req('/api/ready', { room: room, token: token, turn: t }); },
    /* ★ ISSUE-20261029-46 D：联机模式下的「退出」按钮要走 /api/quit 通知服务端，
     * 否则房间里还挂着一个座位，对手会一直显示「2/2 已开始」却等不到人。
     * ★ 顺序很关键：先把 alive 置 false 并 abort 掉在飞的 poll —— 否则 quit 返回后
     *   轮询还会用**已经清空的** room/token 再打一次请求，服务端回 404 触发 closed 事件，
     *   玩家已经回到选角厅却弹一条「与房间服务的连接断开」。 */
    quit: function () {
      const r = room, t = token;
      alive = false;
      if (ctrl) { try { ctrl.abort(); } catch (e) {} }
      ctrl = null;
      room = null; token = null;
      if (!r) return Promise.resolve({});
      return req('/api/quit', { room: r, token: t }).catch(function () { return {}; });
 }
 };
})();

function pvpNameOf(slot) {
  if (slot === pvpSlot) return '你';
  return pvpNames[1 - pvpSlot] || '对手';
}

/* ---------------- 战场初始化 ---------------- */
function pvpStartMatch() {
  /* ★ ISSUE-20261029-46：正式开打前必须收掉联机大厅面板并清掉联机地图标记 ——
   * 面板是「覆盖棋盘」的，不关的话 9×9 竞技场会被它整块盖住；
   * onlineRoomCode 不清的话，下一张图若是 11 行还会在底行画出上局的房间码。 */
  onlineStage = '';
  onlineRoomCode = '';
  if (typeof drawerIsOpen === 'function' && drawerIsOpen('online')) drawerClose();
  mode = 'pvp';
  pvpOver = false;
  pvpTurn = 0;
  pvpWaiting = false;
  setDebugMode(false);
  isMoving = false; dragging = false; dragDownCell = null; hasDragged = false;
  level = 1; levelHpBonus = 0; heroLevel = 1; playerShield = 0;
  relics = freshRelics();
  bloodDrops = []; rewardItems = [];
  /* ISSUE-20261031-118：联机里没有骷髅（竞技场只有双方英雄），骨头一并清掉，
   * 免得单人局的骨头残留影响渲染/寻路。 */
  boneDrops = [];
  /* ★ ISSUE-20261031-117 方案 B：进联机必须清零单人局攒下的技力。
   * 这些是 run 级全局量（跨关不清），不清就会把单人进度带进竞技场 ——
   * 即使联机暂时不显示技力槽，结算/事件里读到非 0 值仍可能造成两端不一致。 */
  fencerSp = 0; wheelchairSp = 0; vampireSp = 0; rookieSp = 0; amiyaBonusTargets = 0;
  enemies = []; enemyPaths = []; enemyArrows = [];
  ROWS = 9; COLS = 9;
  /* ISSUE-20261028-13 方案 A：联机竞技场用独立快照，不再复用选角地图
   * （大厅已删内部障碍；这样做联机地形逐格不变，不会顺手改到平衡） */
  map = buildPvpArena();
  stopFreeMove();
  selectedChar = pvpChars[pvpSlot] || 'fencer';

  playerStats = createPlayerStats(selectedChar);
  /* ISSUE-20261029-26（2026-10-29 收尾）：联机现在**真同步**六维加点了。
   * 链路：建房/加入时把 `playerStats.abilities` 压成 [str,dex,con,int,wis,cha] 传上去
   *   → 房间服务 `_norm_abilities` 归一 → 满员时 start 事件回带双方 `abilities`
   *   → 这里按自己那份重建 playerStats，`pvpMakeUnit` 也吃同一份构单位。
   * 兼容：老服务端不回带 abilities（或某端没传）→ 走原来的兜底
   *   （预备干员强制全 8，面板与结算一致，不会出现「假加点」）。 */
  const mineAb = pvpAbilities[pvpSlot];
  const rookieInPvp = charIsDynamic(selectedChar);
  if (Array.isArray(mineAb) && mineAb.length === 6) {
    playerStats.abilities = { str: mineAb[0], dex: mineAb[1], con: mineAb[2],
                              int: mineAb[3], wis: mineAb[4], cha: mineAb[5] };
    playerStats.abilityPoints = 0;
 } else if (rookieInPvp) {
    playerStats.abilities = { ...CHARACTERS[selectedChar].abilities };
    playerStats.abilityPoints = 0;
 }
  recomputePlayerDerivedStats();
  playerStats.currentHp = playerStats.maxHp;
  player = createPlayerUnit(PVP_SPAWNS[pvpSlot]);

  pvpUnits = [
    pvpMakeUnit(CHARACTERS, pvpChars[0] || 'fencer', 0, PVP_SPAWNS[0].x, PVP_SPAWNS[0].y, pvpAbilities[0]),
    pvpMakeUnit(CHARACTERS, pvpChars[1] || 'fencer', 1, PVP_SPAWNS[1].x, PVP_SPAWNS[1].y, pvpAbilities[1])
  ];
  const foeUnit = pvpUnits[1 - pvpSlot];
  peer = {
    charId: pvpChars[1 - pvpSlot] || 'fencer',
    x: foeUnit.x, y: foeUnit.y, hp: foeUnit.hp, maxHp: foeUnit.maxHp,
    alive: true, facing: foeUnit.facing, stunTurns: 0
 };
  pvpSyncDisplay();
  playerPath = [{ x: player.x, y: player.y }];
  attackIndices = []; skillIndices = [];
  resetTurnState({ clearCounter: true });
  phase = PHASE.PLANNING;
  battleRound = 1;
  clearLog();
  log('⚔️ 联机对战开始');
  log('你：' + (CHARACTERS[selectedChar] ? CHARACTERS[selectedChar].name : selectedChar) +
      '　对手：' + pvpNames[1 - pvpSlot] + '（' + (CHARACTERS[peer.charId] ? CHARACTERS[peer.charId].name : peer.charId) + '）');
  log('回合 ' + (pvpTurn + 1) + '：规划你的路径与攻击节点，然后点「开始」。');
  /* ★ ISSUE-20261031-117 方案 B：明确告知，避免玩家按单人局的直觉攒技力 */
  log('⚠️ 联机模式暂不提供技力与技能：本局只有移动、攻击、闪避、相杀四件事。');
  if (rookieInPvp) log('⚠️ 联机模式里「预备干员」不参与自由分配：双方都按全 8 静态六维作战（加点仅单人局生效）。');
  if (typeof updateCellSize === 'function') updateCellSize();
  render();
}

function pvpSyncDisplay() {
  if (!pvpUnits || !player || !peer) return;
  const mine = pvpUnits[pvpSlot], foe = pvpUnits[1 - pvpSlot];
  player.x = mine.x; player.y = mine.y;
  player.hp = mine.hp; player.maxHp = mine.maxHp; player.alive = mine.alive;
  if (mine.facing) player.facing = mine.facing;
  playerStats.currentHp = mine.hp;
  peer.x = foe.x; peer.y = foe.y;
  peer.hp = foe.hp; peer.maxHp = foe.maxHp; peer.alive = foe.alive;
  if (foe.facing) peer.facing = foe.facing;
}

/* ---------------- 回合：提交计划 ---------------- */
function pvpSubmitPlan() {
  if (pvpOver || pvpWaiting || phase !== PHASE.PLANNING) return;
  if (skillIndices.length) log('⚠️ 联机模式暂不支持技能节点，本回合的技能标记已被忽略。');
  const plan = {
    charId: selectedChar,
    path: playerPath.map(function (p) { return { x: p.x, y: p.y }; }),
    attackIndices: attackIndices.slice()
 };
  pvpWaiting = true;
  phase = PHASE.RESOLVING;
  log('📤 计划已提交，等待对手…');
  render();
  PVP_NET.plan(pvpTurn, plan).then(function (r) {
    if (!r.waiting) log('双方计划齐备，开始结算…');
 }).catch(function (e) {
    pvpWaiting = false;
    phase = PHASE.PLANNING;
    log('⚠️ 提交失败：' + e.message);
    render();
 });
}

/* ---------------- 回合：播放结算 ---------------- */
async function pvpPlayTurn(turn, plans, seed) {
  log('—— 第 ' + (turn + 1) + ' 回合结算（seed ' + seed + '）——');
  let res;
  try {
    res = pvpResolveTurn(CHARACTERS, pvpUnits, plans, seed);
 } catch (e) {
    log('⚠️ 结算异常：' + e.message);
    return;
 }
  /* 播放动画失败不能拖死整局：ready 必须照发，否则对手会一直卡在等待 */
  try {
    await pvpPlayEvents(res.events);
 } catch (e) {
    log('⚠️ 结算动画异常（已跳过剩余特效）：' + e.message);
    console.error('[PVP] playEvents', e);
 }
  pvpUnits = res.units;
  pvpSyncDisplay();
  refreshUnits();
  if (res.winner >= 0) { pvpFinish(res.winner); return; }
  PVP_NET.ready(turn).catch(function () {});
}

async function pvpPlayEvents(events) {
  for (let i = 0; i < events.length; i++) {
    const ev = events[i];
    const mine = (ev.slot === pvpSlot);
    if (ev.t === 'move') {
      const d = mine ? player : peer;
      d.x = ev.to.x; d.y = ev.to.y;
      refreshUnits();
      await sleep(UNIT_MOVE_MS);
 } else if (ev.t === 'dodge') {
      const d = mine ? player : peer;
      floatText(d.x, d.y, '闪避 +3AC', '#7dd3fc', true);
      ringFx(d.x, d.y, '#7dd3fc');
      log(pvpNameOf(ev.slot) + ' 驻足闪避，AC → ' + ev.ac);
      await sleep(200);
 } else if (ev.t === 'hit') {
      const t = mine ? peer : player;
      slashFx(t.x, t.y, '#ff4500');
      hitFlashCell(t.x, t.y);
      floatText(t.x, t.y, (ev.crit ? '暴击 -' : '-') + ev.dmg, ev.crit ? '#ffd700' : '#ff5c5c', true);
      t.hp = ev.hp;
      refreshUnits();
      log(pvpNameOf(ev.slot) + ' 命中 ' + pvpNameOf(1 - ev.slot) + '，' + (ev.crit ? '暴击 ' : '') +
          ev.dmg + ' 点（d20=' + ev.d20 + (ev.crit ? ' 自然20' : '') + ' vs AC' + ev.ac + '）');
      await sleep(280);
 } else if (ev.t === 'miss') {
      const t = mine ? peer : player;
      missFx(t.x, t.y);
      log(pvpNameOf(ev.slot) + ' 落空（d20=' + ev.d20 + ' vs AC' + ev.ac + '）');
      await sleep(220);
 } else if (ev.t === 'whiff') {
      const d = mine ? player : peer;
      floatText(d.x, d.y, '射程外', '#888');
      log(pvpNameOf(ev.slot) + ' 的攻击够不着对手，空挥');
      await sleep(200);
 } else if (ev.t === 'clash') {
      floatText(ev.cell.x, ev.cell.y, '相杀！', '#ff4500', true);
      ringFx(ev.cell.x, ev.cell.y, '#ff4500');
      slashFx(ev.cell.x, ev.cell.y, '#ff4500');
      player.hp = ev.hp[pvpSlot];
      peer.hp = ev.hp[1 - pvpSlot];
      refreshUnits();
      log('相杀！双方各受暴击 ' + ev.dmg[0] + ' / ' + ev.dmg[1] + ' 点');
      await sleep(400);
 } else if (ev.t === 'blocked') {
      const d = mine ? player : peer;
      floatText(d.x, d.y, '被挡', '#bbb');
      log(pvpNameOf(ev.slot) + ' 被挡住，停止移动');
      await sleep(160);
 } else if (ev.t === 'invalid') {
      log('⚠️ ' + pvpNameOf(ev.slot) + ' 的计划含非法步，移动被中止');
 } else if (ev.t === 'death') {
      const d = (ev.slot === pvpSlot) ? player : peer;
      d.alive = false;
      refreshUnits();
      log('💀 ' + pvpNameOf(ev.slot) + ' 倒下了');
      await sleep(320);
 }
 }
}

function pvpFinish(winner) {
  pvpOver = true;
  pvpWaiting = false;
  const draw = winner < 0;
  const win = (winner === pvpSlot);
  phase = PHASE.PVP_OVER;   // 不能是 GAMEOVER，否则会被主页钩子当成单人死亡上报成绩
  log(draw ? '🤝 同归于尽，平局。' : (win ? '🏆 你赢了！' : '💀 你输了。'));
  render();
  pvpShowResult(draw ? null : win);
}

function pvpShowResult(result) {
  const draw = (result === null);
  const title = draw ? '🤝 平局' : (result ? '🏆 胜利' : '💀 落败');
  const color = draw ? '#9aa0c0' : (result ? '#ffd166' : '#e74c3c');
  const mask = document.createElement('div');
  mask.className = 'pvp-result';
  mask.innerHTML =
    '<div class="pvp-result-card">' +
      '<div class="pvp-result-title" style="color:' + color + '">' + title + '</div>' +
      '<div class="pvp-result-sub">对手：' + (pvpNames[1 - pvpSlot] || '对手') + '</div>' +
      '<button id="pvpBack">返回角色选择</button>' +
    '</div>';
  document.body.appendChild(mask);
  mask.querySelector('#pvpBack').onclick = function () {
    mask.remove();
    mode = 'solo';
    pvpUnits = null; peer = null;
    initCharSelect();
 };
}

/* ---------------- 事件接线 ---------------- */
PVP_NET.on('start', function (ev) {
  /* ★ ISSUE-20261031-128：合作局走另一条开局链路（N 个角色同场打 PvE），
   * 与 PVP 的二元竞技场完全不是一回事，所以这里分叉而不是复用 pvpStartMatch。 */
  if (ev && ev.mode === 'coop') { coopStartRun(ev); return; }
  pvpNames = ev.slots || ['房主', '挑战者'];
  pvpChars = ev.chars || ['', ''];
  // ISSUE-20261029-26：服务端回带的双方六维（[房主, 挑战者]，任一可能为 null）
  pvpAbilities = Array.isArray(ev.abilities) ? ev.abilities : [null, null];
  pvpSlot = PVP_NET.slot();
  pvpClosePanel();
  pvpStartMatch();
});
PVP_NET.on('turn', function (ev) {
  if (mode !== 'pvp' || pvpOver) return;
  const plans = [ev.plans && ev.plans['0'], ev.plans && ev.plans['1']];
  if (!plans[0] || !plans[1]) { log('⚠️ 对手计划缺失，本回合跳过'); return; }
  pvpPlayTurn(ev.turn, plans, ev.seed).catch(function (e) {
    log('⚠️ 回合结算失败：' + e.message);
    console.error('[PVP] playTurn', e);
    PVP_NET.ready(ev.turn).catch(function () {});   // 兜底推进，避免双方互相等待
 });
});
PVP_NET.on('next', function (ev) {
  if (mode !== 'pvp' || pvpOver) return;
  pvpTurn = ev.turn;
  pvpWaiting = false;
  playerPath = [{ x: player.x, y: player.y }];
  attackIndices = []; skillIndices = [];
  resetTurnState({ clearCounter: true });
  phase = PHASE.PLANNING;
  log('—— 第 ' + (ev.turn + 1) + ' 回合：请规划 ——');
  render();
});
PVP_NET.on('peer_left', function (ev) {
  if (mode !== 'pvp') return;
  log('⚠️ 对手离开了房间');
  pvpOver = true;
  phase = PHASE.PVP_OVER;
  render();
  pvpShowResult(true);
});
PVP_NET.on('closed', function (ev) {
  if (mode !== 'pvp') return;
  log('⚠️ 与房间服务的连接断开：' + ev.reason);
  pvpOver = true;
  phase = PHASE.PVP_OVER;
  render();
});

/* =========================================================================
 * ★ ISSUE-20261031-128 §十六：合作闯关 · 客户端编排
 *
 * 为什么单独一段而不是改 `pvpXxx`：两者虽然共用 `PVP_NET`（同一套房间协议），
 * 但**对局模型完全不同**：PVP 是「两个人的镜像竞技场、一方死就结束」，
 * 合作是「一张 PvE 关卡、N 个角色各自控制、死了不影响别人」。
 * 把两套塞进同一个函数会让 PVP 那 900 多项断言跟着遭殃。
 *
 * 一条回合的完整链路：
 *   我点「开始行动」→ confirmAction 跑完本地预演（闪避/冲锋/记动作）
 *   → POST /api/plan 交我的计划 → 停在 RESOLVING 等
 *   → 收到 turn（全员计划 + 种子）→ 记下所有人的计划
 *   → 按**全员路径**重算敌人意图（关键！只按自己那条会分叉）
 *   → 本地结算（敌人 → 队友 → 通关判定）
 *   → 结算完 POST /api/ready → 收到 next → 回到 PLANNING 画下回合
 * ========================================================================= */

/* 本机是不是「真联机」的合作局。没有房号 = 本地自测（`?coop=N`），全程走本地代理。 */
function coopIsOnline() {
  try { return mode === 'coop' && !!(PVP_NET && PVP_NET.room && PVP_NET.room()); } catch (e) { return false; }
}

/* 收到 start（房主点了开始）→ 整局从零起一局 PvE，但场上多 N−1 个队友。
 *
 * ★ 种子必须是服务端那一颗：地图 / 敌人 / 词缀全由 RUN_SEED 派生，
 *   两端各摇一颗的话，两个人看到的根本不是同一关。 */
function coopStartRun(ev) {
  const players = (ev && Array.isArray(ev.players)) ? ev.players : [];
  if (players.length < 2) { log('⚠️ 合作闯关至少要 2 人。'); return; }
  const mySlot = (typeof PVP_NET !== 'undefined' && PVP_NET.slot) ? PVP_NET.slot() : 0;
  const mine = players.find(function (p) { return p.slot === mySlot; }) || players[0];
  const others = players.filter(function (p) { return p.slot !== mySlot; });

  coopAlliesReset();
  coopSetMySlot(mySlot);
  coopSetAllyInfos(others.map(function (p) {
    return { slot: p.slot, name: p.name, charId: p.charId, abilities: p.abilities };
  }));

  mode = 'coop';
  onlineStage = 'run';
  onlineRoomCode = '';
  if (typeof drawerIsOpen === 'function' && drawerIsOpen('online')) drawerClose();
  setDebugMode(false);
  stopFreeMove();
  freeMoveClearEls();
  isMoving = false; dragging = false; dragDownCell = null; hasDragged = false;

  selectedChar = (mine && mine.charId) || pvpPick || 'fencer';
  /* ★ 种子：服务端一次摇定，两端写死同一颗 */
  seedRng(Number((ev && ev.runSeed) || 1) || 1);

  level = 1;
  battleLevel = 0;
  heroLevel = 1;
  playerShield = 0;
  relics = freshRelics();
  bloodDrops = []; rewardItems = []; boneDrops = [];
  squadUnits = [];
  fencerSp = 0; wheelchairSp = 0; vampireSp = 0; rookieSp = 0; amiyaBonusTargets = 0;
  enemies = []; enemyPaths = []; enemyArrows = [];

  resetRunProgress();
  playerStats = createPlayerStats(selectedChar);
  /* 自己的六维用自己那份（服务端透传的 abilities，[str,dex,con,int,wis,cha]） */
  if (mine && Array.isArray(mine.abilities) && mine.abilities.length === 6) {
    const ab = mine.abilities;
    playerStats.abilities = { str: ab[0], dex: ab[1], con: ab[2], int: ab[3], wis: ab[4], cha: ab[5] };
    recomputePlayerDerivedStats();
  }
  playerStats.currentHp = playerStats.maxHp;

  /* ★ 人数口径在这里落定：`coopEnemyCount()` 之后每一关都读它 */
  enterCoopRun(players.length);
  log('🤝 合作闯关开始：' + players.length + ' 人局（敌人每关 ' +
      coopEnemyCount(3) + ' 只起步，每多 1 人 +2 只）。');
  initLevel();
}

/* 点「开始行动」后：把本地计划交给房间服务，然后等 turn。
 * ⚠️ 本地自测（无房号）不进来 —— 那条路走原生的 setTimeout(resolveStep)。 */
function coopSubmitAndWait() {
  if (!coopIsOnline()) { setTimeout(() => resolveStep(1, 0), 300); return; }
  const plan = {
    path: playerPath.map(function (p) { return { x: p.x, y: p.y }; }),
    attacks: attackIndices.slice(),
    skills: skillIndices.slice(),
  };
  PVP_NET.plan(coopTurnNo, plan).then(function (j) {
    if (j && j.waiting) log('⏳ 已交计划，等队友（超时会自动原地待命）…');
  }).catch(function (e) {
    log('⚠️ 交计划失败：' + (e && e.message ? e.message : e) + '，本回合按本地结算。');
    setTimeout(() => resolveStep(1, 0), 120);
  });
}

/* 收到 turn：记下全员计划 → 重算敌人意图 → 结算。 */
async function coopResolveWithPlans(turn, plans) {
  coopSetTurnPlans(turn, plans);
  /* ★ 关键：敌人意图必须按**全员路径**重算。
   * 只按本地玩家那条路径算的话，A 端敌人去追 A 的玩家、B 端去追 B 的玩家，
   * 两端敌人的位置当场分叉 —— 之后每一拳都打在不同的人身上。 */
  try { _generateEnemyPathsCore(); } catch (e) { console.warn('[coop] 重算敌人意图失败', e); }
  phase = PHASE.RESOLVING;
  render();
  await resolveStep(1, 0);
}

/* 告诉房间服务「我这回合看完了」。
 *
 * ★ 为什么单拎出来：**两个地方**都要报 ready —— 一个是正常回合结束（`coopOnTurnEnd`），
 *   另一个是清场通关（`onLevelClear`）。后者不走 `endRound`，漏了就会让服务端停在
 *   旧回合，下一关交计划时被 409「回合不同步」拒掉（队友那边也一直等 next）。 */
function coopSendReady() {
  if (!coopIsOnline()) return false;
  PVP_NET.ready(coopTurnNo).catch(function (e) { console.warn('[coop] ready 失败', e); });
  return true;
}

/* 回合结算完（endRound 末尾）→ 报 ready 并等待下一回合。
 * 返回 true 表示「已经接管」，endRound 不要再往下走成 PLANNING。 */
function coopOnTurnEnd() {
  if (!coopIsOnline()) return false;
  phase = PHASE.RESOLVING;
  render();
  log('⏳ 本回合结算完毕，等队友看完…');
  coopSendReady();
  return true;
}

PVP_NET.on('peer_joined', function (ev) {
  if (PVP_NET.mode && PVP_NET.mode() !== 'coop') return;
  onlineRenderCoopRoom(ev && ev.players, ev && ev.cap);
  const ps = (ev && ev.players) || [];
  log('🤝 有玩家进大厅（' + ps.length + '/' + ((ev && ev.cap) || 4) + '）：' +
      ps.map(function (p) { return p.name; }).join('、'));
});

PVP_NET.on('peer_left', function (ev) {
  if (PVP_NET.mode && PVP_NET.mode() !== 'coop') return;
  if (mode === 'coop') {
    const u = coopAllyBySlot(ev && ev.slot);
    if (u) { u.alive = false; log('⚠️ 队友 ' + u.name + ' 离开了，他的角色退出战场。'); refreshUnits(); }
  }
  onlineRenderCoopRoom(ev && ev.players, ev && ev.cap);
});

PVP_NET.on('turn', function (ev) {
  /* PVP 的 turn 由上面那个 handler 消费；这里只管合作局。 */
  if (mode !== 'coop') return;
  const plans = (ev && ev.plans) || {};
  coopResolveWithPlans(ev.turn, plans).catch(function (e) {
    log('⚠️ 合作回合结算失败：' + (e && e.message ? e.message : e));
    console.error('[coop] resolve', e);
  });
});

PVP_NET.on('next', function (ev) {
  if (mode !== 'coop') return;
  coopTurnNo = Math.max(coopTurnNo, Number(ev && ev.turn) || 0);
  playerPath = [{ x: player.x, y: player.y }];
  attackIndices = []; skillIndices = [];
  resetTurnState({ clearCounter: true });
  phase = PHASE.PLANNING;
  log('--- 回合 ' + (coopTurnNo + 1) + ' ---');
  generateEnemyPaths();
  render();
});

PVP_NET.on('closed', function (ev) {
  if (mode !== 'coop') return;
  log('⚠️ 与合作房间的连接断开：' + (ev && ev.reason));
  mode = 'solo';
  leaveCoopRun();
});

/* 本地自测开局：`?coop=3` → 3 人合作局（没有服务端，队友全走本地代理）。
 *
 * ★ 为什么留这个入口：真联机要两台机器 + 一个房间服务，覆盖不到「队友上场 / 敌人打队友 /
 *   多人回合驱动」这些纯本地逻辑。有了它，jsdom 门禁和人工验收都能一条 URL 复现同一局
 *  （种子固定，`?coop=4&seed=123` 也一样）。玩家侧不可见 —— 不带参数就是普通单人局。 */
function coopStartLocal(n, seed) {
  const ids = ['fencer', 'vampire', 'wheelchair', 'amiya'].filter(function (id) {
    return typeof CHARACTERS !== 'undefined' && CHARACTERS[id];
  });
  const names = ['你', '队友A', '队友B', '队友C'];
  const players = [];
  for (let i = 0; i < Math.min(4, Math.max(2, n)); i++) {
    players.push({
      slot: i,
      name: names[i] || ('队友' + i),
      charId: (i === 0 ? (selectedChar || 'fencer') : ids[i % ids.length]),
      abilities: null,
    });
  }
  log('🤝 本地合作自测：' + players.length + ' 人（无服务端，队友由本地代理驱动）。');
  coopStartRun({ mode: 'coop', players: players, runSeed: seed || 20261101 });
}

(function bootCoopLocal() {
  try {
    const q = new URLSearchParams(location.search || '');
    const n = parseInt(q.get('coop') || '', 10);
    if (!(n >= 2)) return;
    const seed = parseInt(q.get('seed') || '', 10) || 20261101;
    /* 等外壳与首帧就绪：initLevel 要量棋盘尺寸，太早跑会算出 --cell = 0 */
    setTimeout(function () { coopStartLocal(n, seed); }, 500);
  } catch (e) { /* 老浏览器没有 URLSearchParams → 这条路直接不启用 */ }
})();

/* ---------------- UI ---------------- */

/* ★★ ISSUE-20261029-27（2026-10-29，人类拍板「先关闭联机系统，PVP 搁置」）
 * 联机唯一开关。改回 true 即完整恢复（按钮 / 面板 / 建房 / 加入 / 房间流程的代码一行没删）。
 * 为什么用开关而不是删代码：联机不是「坏的」，是「先不开」；删了以后要重写，
 * 而且 pvp-core.js 的协议、pvpMakeUnit 的镜像逻辑都是花时间调出来的。
 * ★ ISSUE-20261030-63：旧的那一整套（设置面板的「⚔️ 联机」按钮 + 运行时注入的 #pvpMask
 *   房间卡片）已经删除 —— 联机改从选角厅地图上的 🌐 入口进（src/ui/chrome.js#enterOnlineLobby，
 *   面板是 #drawerOnline，DOM 与旧面板完全不共用）。这里只留开关，关掉时该入口会提示未开放。 */
const PVP_ENABLED = true;

/* ★ ISSUE-20261030-63：旧房间卡（#pvpMask）已整套删除，这里本体就没什么可关的了。
 * 函数仍然保留：`enterOnlineLobby()` 会调它，留着比改调用点便宜，也不会误伤。 */
function pvpClosePanel() { /* 无遗留面板需要关闭 */ }

/* src: src/ui/chrome.js 第 2 段/beforeDlcChrome */
/* =========================================================================
 * ★ 联机大厅 / 房间（ISSUE-20261029-46）
 *
 * 入口：选角厅地图上的 🌐 那格（代码 (9,5)，人类 (9,5)）—— 走过去或点一下都能进
 *   （走进去的判定在 src/ui/char-select.js 的 freeMoveTouchesOnline()，
 *    点一下的判定在 templates/game.html 的 boardEl pointerdown 选角分支）。
 * 面板：#drawerOnline，复用 drawer.js 的「覆盖棋盘」机制（--board-* 四个 CSS 变量），
 *   上面 = 玩家昵称（**直接取账号昵称**）／中间 = 房间号输入／左下建房 · 右下加入。
 * 域名固定 https://arkroguelike.top → 面板里只让填房间号，不再填地址。
 *
 * ⚠️ 坐标换算（本 issue 最容易搞反的一条）：人类 y 从**下往上**，代码 y 从上往下，
 *    棋盘 11×11 → **代码 y = 10 − 人类 y**。
 *      · 门 🚪  人类 (5,10) → 代码 (5,0)
 *      · 入口 🌐 人类 (9,5)  → 代码 (9,5)（5 换算后还是 5）
 *      · 房间码 人类「最底一行 (0,3)~(0,7)」→ 代码 y = ROWS-1 = 10，x = 3..7
 * ========================================================================= */
const ONLINE_BASE = 'https://arkroguelike.top';

/* ★ ISSUE-20261031-128：联机面板的**模式**（'pvp' 对战 / 'coop' 合作闯关）。
 * 默认 'pvp' —— 与改动前完全一致；只有玩家主动点「合作闯关」才会变。 */
let onlineMode = 'pvp';
/* 合作大厅的座位快照（服务端 peer_joined / join 回来的人名单）。 */
let onlineRoomPlayers = [];
let onlineRoomCap = 2;

/* 把联机面板注册进 drawer.js 那套机制 —— **不改 drawer.js 本身**：
 * DRAWER_IDS 是 const 数组、drawerEls 是 const 对象，push / 加键都不违反。
 * 前提是本段晚于 src/ui/drawer.js 求值：chrome.js 在构建清单里排在它后面，成立。 */
if (typeof DRAWER_IDS !== 'undefined' && DRAWER_IDS.indexOf('online') < 0) DRAWER_IDS.push('online');
if (typeof drawerEls !== 'undefined') {
  const onlineDrawerEl = document.querySelector('[data-drawer="online"]');
  if (onlineDrawerEl) drawerEls.online = onlineDrawerEl;
}

/* 玩家昵称：与账号**同一套**（src/shell/02-account.js 的 app.myName），
 * 不再让联机里另填一个 —— 两边不一致时排行榜和对手看到的名字会对不上。
 * 外壳还没起来（或裁剪版）时逐级降级到本机存储，最后兜底「玩家」。 */
function onlineNickname() {
  try {
    const acct = (window.ArkShell && window.ArkShell.account) ? window.ArkShell.account : null;
    if (acct && acct.app && acct.app.myName) return acct.app.myName;
  } catch (e) { /* 外壳不可用 → 走下面的本机存储 */ }
  try {
    const n = localStorage.getItem('ark_player_name');
    if (n) return n;
    const a = localStorage.getItem('ark_account') || '';
    const m = a.match(/^([\u4e00-\u9fa5A-Za-z]{1,12})\d{4,8}$/);
    if (m) return m[1];
  } catch (e) {}
  return '玩家';
}

/* 联机大厅 / 房间：固定 11×11 地图（不走 mapgen —— 每次进来必须一模一样）。
 * 与选角厅同款「左右两列是墙」的框感，中间全可走。 */
function onlineFixedMap() {
  const m = Array.from({ length: BOARD_ROWS }, () => Array(BOARD_COLS).fill(0));
  for (let i = 0; i < BOARD_ROWS; i++) { m[i][0] = 1; m[i][BOARD_COLS - 1] = 1; }
  return m;
}

/* 当前算不算「联机模式」：人在联机地图上，或已经占着房间（建房 / 加入后、对局中）。 */
function onlineIsActive() {
  return !!onlineStage || (typeof PVP_NET !== 'undefined' && !!PVP_NET.room());
}

/* 设置面板里那个按钮的文案：联机中是「退出」，否则「重开」（ISSUE-20261029-46 D） */
function setOnlineResetLabel() {
  if (!logResetBtn) return;
  const on = onlineIsActive();
  logResetBtn.textContent = on ? '⏻ 退出' : '⟲ 重开';
  logResetBtn.title = on ? '退出联机（断开房间连接并回到选角界面）' : '重开游戏（回到选角界面）';
}

function onlineStatus(t) {
  const el = document.getElementById('onlineStatus');
  if (el) el.textContent = t;
}

/* 自己这份六维 → 服务端认的 [str,dex,con,int,wis,cha]（顺序不能变）。
 * 选角厅里 playerStats 还不存在，所以退回候选副本 / 角色常量 ——
 * 否则建房时传 null，对手看到的是「没加点」的六维。 */
function onlineMyAbilities() {
  let a = (playerStats && playerStats.abilities) || null;
  if (!a && selectedCandidate) {
    a = candidateAbilitiesOf(selectedCandidate.id)
      || (CHARACTERS[selectedCandidate.id] && CHARACTERS[selectedCandidate.id].abilities)
      || null;
  }
  if (!a) return null;
  return [a.str, a.dex, a.con, a.int, a.wis, a.cha];
}

function onlineRenderPanel() {
  const el = document.getElementById('onlineNick');
  if (el) el.textContent = onlineNickname();
  onlineStatus('');
  const inp = document.getElementById('onlineRoomIn');
  if (inp) inp.value = '';
}

/* =========================================================================
 * ★ ISSUE-20261031-128：合作大厅（座位表 + 房主开始）
 *
 * 与 PVP 的房间流程**共用同一个面板**，差别只有两点：
 *   ① PVP 进房后把面板收起（房间码画在棋盘底行、满了自动开打）；
 *   ② 合作进房后**面板留着**，里面就是大厅：座位 0..3、人数、"开始闯关"按钮。
 * 理由：合作模式要等房主手动点开始，把面板收起来玩家就没有「开始」可点了。
 * ========================================================================= */

function onlineSetMode(m) {
  onlineMode = (m === 'coop') ? 'coop' : 'pvp';
  const pvp = document.getElementById('onlineModePvp');
  const coop = document.getElementById('onlineModeCoop');
  if (pvp) pvp.classList.toggle('on', onlineMode === 'pvp');
  if (coop) coop.classList.toggle('on', onlineMode === 'coop');
  const createBtn = document.getElementById('onlineCreate');
  if (createBtn) createBtn.textContent = (onlineMode === 'coop') ? '建合作房' : '建房';
  onlineStatus('');
}

/* 渲染座位表。`players` 省略时用上一次的快照（退出重进 / 重绘）。 */
function onlineRenderCoopRoom(players, cap) {
  if (Array.isArray(players)) onlineRoomPlayers = players.slice();
  if (cap) onlineRoomCap = Number(cap) || onlineRoomCap;
  const box = document.getElementById('onlineRoom');
  const startBtn = document.getElementById('onlineStart');
  const list = document.getElementById('orSlots');
  const codeEl = document.getElementById('orCode');
  const countEl = document.getElementById('orCount');
  const hintEl = document.getElementById('orHint');
  if (!box || !list) return;
  /* 只有「合作模式 + 已在房间里」才显示这一块 */
  const show = (onlineMode === 'coop' && onlineStage === 'room');
  box.hidden = !show;
  if (!show) {
    if (startBtn) startBtn.hidden = true;
    return;
  }
  const mySlot = (typeof PVP_NET !== 'undefined' && PVP_NET.slot) ? PVP_NET.slot() : 0;
  const bySlot = {};
  for (const p of onlineRoomPlayers) bySlot[p.slot] = p;
  const capN = Math.max(2, Math.min(4, onlineRoomCap || 4));
  let html = '';
  for (let s = 0; s < capN; s++) {
    const p = bySlot[s];
    const cls = 'or-slot' + (p ? (s === mySlot ? ' me' : '') : ' empty');
    const seat = '座位 ' + (s + 1) + (s === 0 ? ' · 房主' : '');
    html += '<li class="' + cls + '">'
      + '<span class="seat">' + seat + '</span>'
      + '<span class="who">' + (p ? (p.name || '玩家') + (s === mySlot ? '（你）' : '') : '等待加入…') + '</span>'
      + '</li>';
  }
  list.innerHTML = html;
  if (codeEl) codeEl.textContent = onlineRoomCode || '—';
  if (countEl) countEl.textContent = onlineRoomPlayers.length + '/' + capN;
  const isHost = (mySlot === 0);
  const canStart = isHost && onlineRoomPlayers.length >= 2;
  if (startBtn) {
    startBtn.hidden = !isHost;
    startBtn.disabled = !canStart;
    startBtn.textContent = canStart ? '开始闯关（' + onlineRoomPlayers.length + ' 人）' : '至少 2 人才能开始';
  }
  if (hintEl) {
    hintEl.textContent = isHost
      ? '把房间号发给队友，人齐了点「开始闯关」。敌人会随人数变多（每多 1 人 +2 只）。'
      : '等房主点「开始闯关」。房间号：' + (onlineRoomCode || '—');
  }
}

/* 进入联机大厅：切到固定地图 + 展开覆盖棋盘的联机面板 */
function enterOnlineLobby() {
  if (typeof PVP_NET === 'undefined') return;
  if (typeof PVP_ENABLED !== 'undefined' && !PVP_ENABLED) { log('联机暂未开放。'); return; }
  try { PVP_NET.setBase(ONLINE_BASE); } catch (err) { log('⚠️ ' + err.message); }
  setDebugMode(false);          /* 与 pvpStartMatch 同一条：进联机必须关掉调试 */
  stopFreeMove();
  freeMoveClearEls();
  /* 出战角色 = 玩家在选角厅选中的那个（面板里不再让玩家重选一遍） */
  if (selectedCandidate && CHARACTERS[selectedCandidate.id]) pvpPick = selectedCandidate.id;
  onlineStage = 'lobby';
  onlineRoomCode = '';
  ROWS = BOARD_ROWS;
  COLS = BOARD_COLS;
  selMap = onlineFixedMap();
  phase = PHASE.CHAR_SELECT;
  /* 联机地图里场上只有「你自己」：沿用同一个自由移动层，站在正中 */
  charCandidates = [{ id: pvpPick, x: 5, y: 5, fx: 5, fy: 5, alive: true }];
  selectedCandidate = charCandidates[0];
  charSheetOpen = false;
  freeMoveExiting = false;
  pvpOver = false;
  pvpWaiting = false;
  pvpClosePanel();
  log('🌐 联机大厅：点「建房」把房间号发给对手，或输入对手的房间号点「加入」。');
  log('（这张地图里的 🚪 是返回角色选择；设置面板里的「退出」会断开联机。）');
  /* 面板是「覆盖棋盘」的，矩形必须自己同步一次 —— drawer.js 只对 settings / char 自动做 */
  setTimeout(function () { updateCellSize(); render(); initFreeMoveLobby(); }, 50);
  syncBoardOverlayRect();
  onlineRenderPanel();
  /* 进大厅时先把上一次的座位快照清掉，免得残留上一间的队友名单 */
  onlineRoomPlayers = [];
  onlineRoomCap = (onlineMode === 'coop') ? 4 : 2;
  onlineRenderCoopRoom();
  drawerOpen('online');
  setOnlineResetLabel();
}

/* 建房 / 加入成功后进入「房间地图」：房间码渲染在**底行居中**（5 位 → 代码 y = ROWS-1, x = 3..7）
 * ★ DEBUG-20261030-02：这里原来写的是 `.slice(0, 5)`，而服务端发的是 6 位
 *   → 房主屏幕上少了最后一位，对手照抄就 404「房间不存在或已回收」，联机 100% 打不开。
 *   位数由服务端决定，显示层**绝不允许截断或补位**：服务端给几位就显示几位。 */
function enterOnlineRoom(code, mode, players, cap) {
  onlineStage = 'room';
  onlineRoomCode = String(code || '').trim().toUpperCase();
  if (mode) onlineSetMode(mode);
  if (Array.isArray(players)) onlineRoomPlayers = players.slice();
  if (cap) onlineRoomCap = Number(cap) || onlineRoomCap;
  ROWS = BOARD_ROWS;
  COLS = BOARD_COLS;
  selMap = onlineFixedMap();
  if (onlineMode === 'coop') {
    /* ★ 合作：面板**不收**，它就是大厅（座位表 + 开始按钮）。
     * 收起面板玩家就没有「开始」可点了 —— PVP 之所以能收，是因为它人满自动开打。 */
    log('🏠 合作房间 ' + onlineRoomCode + '：把房间号发给队友，人齐后房主点「开始闯关」。');
    onlineRenderCoopRoom();
  } else {
    /* 面板必须收起：房间码画在棋盘底行，面板盖着就看不见 */
    drawerClose();
    log('🏠 房间号 ' + onlineRoomCode + '：把这 ' + onlineRoomCode.length + ' 位发给对手，他加入后自动开始对战。');
  }
  setTimeout(function () {
    updateCellSize(); render();
    /* 面板矩形同步必须在 render 之后 —— 棋盘尺寸变了，--board-* 也得跟着更新 */
    if (onlineMode === 'coop') drawerOpen('online');
  }, 50);
  setOnlineResetLabel();
}

/* 退出联机：断连（若还占着房间）+ 回选角厅。
 * 联机地图里的 🚪 和设置面板里的「退出」都走这里 —— 只回选角厅不断连会留下
 * 「房间还挂着人、玩家却看不到房间号」的状态，对手那边会一直卡在等。 */
function onlineQuit() {
  /* ★ 实时 PVP：退出联机前必须先停掉实时循环（rAF 插值 + 33ms 输入轮询 + 键盘捕获监听），
   * 否则回到选角厅后 overlay 还在跑、按键还被拦截。pvpRtStop 内部自带 pvpRealtime=false。 */
  if (typeof pvpRtStop === 'function') pvpRtStop();
  try { PVP_NET.quit(); } catch (e) {}
  mode = 'solo';
  pvpUnits = null;
  peer = null;
  pvpOver = false;
  pvpWaiting = false;
  onlineStage = '';
  onlineRoomCode = '';
  /* ★ ISSUE-20261031-128：退出联机要把合作局的队友与人数口径一起复位，
   * 否则回到选角厅再开单人局时 `coopPartySize` 还停在 4 —— 敌人数量会凭空多 6 只。 */
  onlineRoomPlayers = [];
  if (typeof leaveCoopRun === 'function') leaveCoopRun();
  if (typeof coopAlliesReset === 'function') coopAlliesReset();
  if (typeof onlineRenderCoopRoom === 'function') onlineRenderCoopRoom();
  pvpClosePanel();
  setOnlineResetLabel();
  initCharSelect();
  log('已退出联机模式。');
}

(function bindOnlinePanel() {
  const createBtn = document.getElementById('onlineCreate');
  const joinBtn = document.getElementById('onlineJoin');
  const roomInput = document.getElementById('onlineRoomIn');
  if (!createBtn || !joinBtn) return;

  function baseReady() {
    if (typeof PVP_ENABLED !== 'undefined' && !PVP_ENABLED) { onlineStatus('联机暂未开放。'); return false; }
    try { PVP_NET.setBase(ONLINE_BASE); return true; }
    catch (err) { onlineStatus('⚠️ ' + err.message); return false; }
  }

  createBtn.addEventListener('click', function (e) {
    e.stopPropagation();
    if (!baseReady()) return;
    onlineStatus('建房中…');
    /* ★ 实时 PVP：对战房一律走 rtpvp（服务器权威实时模拟），合作房才传 coop。
     * 内部 onlineMode 仍保持 'pvp' 用于渲染/文案；真正决定服务端对局模型的是第四个参数。 */
    PVP_NET.create(onlineNickname(), pvpPick, onlineMyAbilities(), onlineMode === 'coop' ? 'coop' : 'rtpvp').then(function (j) {
      enterOnlineRoom(String((j && j.room) || '').toUpperCase(), (j && j.mode) || onlineMode,
                      null, (j && j.cap) || 0);
    }).catch(function (err) {
      onlineStatus('⚠️ 建房失败：' + (err && err.message ? err.message : err));
    });
  });

  joinBtn.addEventListener('click', function (e) {
    e.stopPropagation();
    const r = String((roomInput && roomInput.value) || '').trim().toUpperCase();
    if (!r) { onlineStatus('⚠️ 先填房间号'); return; }
    if (!baseReady()) return;
    onlineStatus('加入中…');
    PVP_NET.join(r, onlineNickname(), pvpPick, onlineMyAbilities()).then(function (j) {
      enterOnlineRoom(r, (j && j.mode) || onlineMode, (j && j.players) || null, (j && j.cap) || 0);
    }).catch(function (err) {
      onlineStatus('⚠️ 加入失败：' + (err && err.message ? err.message : err));
    });
  });

  /* 模式切换（对战 / 合作）。切换只改按钮文案与本地状态，不碰已建立的房间。 */
  const modeBtns = [document.getElementById('onlineModePvp'), document.getElementById('onlineModeCoop')];
  for (const b of modeBtns) {
    if (!b) continue;
    b.addEventListener('click', function (e) {
      e.stopPropagation();
      onlineSetMode(b.getAttribute('data-mode'));
    });
  }

  /* 合作房「开始闯关」：仅房主可见（渲染层已 hidden，这里再兜一层权限判断） */
  const startBtn = document.getElementById('onlineStart');
  if (startBtn) {
    startBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      if (!baseReady()) return;
      if (typeof PVP_NET.slot === 'function' && PVP_NET.slot() !== 0) {
        onlineStatus('只有房主能开始。'); return;
      }
      startBtn.disabled = true;
      onlineStatus('开始中…');
      PVP_NET.start().then(function () {
        onlineStatus('已发出开始请求，等待服务端广播…');
      }).catch(function (err) {
        startBtn.disabled = false;
        onlineStatus('⚠️ 开始失败：' + (err && err.message ? err.message : err));
      });
    });
  }

  if (roomInput) {
    roomInput.addEventListener('keydown', function (e) {
      e.stopPropagation();
      if (e.key === 'Enter' || e.keyCode === 13) { e.preventDefault(); joinBtn.click(); }
    });
  }
})();

initCharSelect();

/* ISSUE-20261029-45：外壳（账号 / 榜单 / 面板）在游戏初始化**之后**启动。
   顺序敏感：它要读 updateCellSize() 算出的 --cell / --corner-x，
   以及确认 #lobbyOpenBtn 已挂好监听，否则面板角标会落在错误的格子上。 */
/* src: src/shell/00-guard.js */
/* ============================================================================
 * 外壳 · 全局异常兜底（ISSUE-20261030-51）
 * ----------------------------------------------------------------------------
 * 合并成单文件后，外壳与游戏跑在**同一个 window** 里（合并前是 index.html 外壳
 * + iframe 两层文档，游戏炸了最坏只卡住画面，外壳还能点「重开」）。现在一处
 * 未捕获异常就可能让账号面板、排行榜一起失灵，且 Console 之外**没有任何提示**，
 * 玩家看到的就是「点了没反应」。
 *
 * 本文件只做三件事，且**不掩盖真实报错**（不 preventDefault、不吞异常，
 * Console 里的原始堆栈照旧）：
 *   1. 一句人话提示（复用 NS.ui.toast），并按 message **去重** —— 同一处异常
 *      每帧都抛时不能把 toast 刷成跑马灯；
 *   2. 把 message + build + 时间写进 localStorage 环形缓冲（最近 20 条），
 *      玩家截图反馈时能直接对上 `更新日志/CHANGELOG-<build>.md`；
 *   3. 让异常继续冒泡 —— 本监听器只观察，不拦截。
 *
 * ★ 排位：本文件在 manifest 里是第一个模块（且带 @slot:shell，落在 shell 槽最前），
 *   监听装得越早，能接住的错误越多。
 * ★ 门禁 dom_load 有一条「除外壳段外不许 Math.random」的硬断言 —— 这里没有随机数，
 *   时间戳只用 Date.now()。
 * ========================================================================== */
(function () {
  'use strict';
  var NS = window.ArkShell = window.ArkShell || {};
  var KEY = 'ark_error_log';
  var MAX = 20;
  var seen = Object.create(null);   // 同一 message 只提示一次

  function buildNo() {
    try {
      var v = window.__ARK_VERSION__;
      return (v && v.build) ? String(v.build) : '';
    } catch (e) { return ''; }
  }

  /* 环形缓冲：只留最近 20 条。localStorage 不可用（隐私模式/配额满）时静默放弃 ——
     记日志这件事本身绝不能再崩一次。 */
  function record(msg) {
    try {
      var list = [];
      try { list = JSON.parse(localStorage.getItem(KEY)) || []; } catch (e) { list = []; }
      if (!list || typeof list.push !== 'function') list = [];
      list.push({ t: Date.now(), build: buildNo(), msg: String(msg).slice(0, 300) });
      while (list.length > MAX) list.shift();
      localStorage.setItem(KEY, JSON.stringify(list));
    } catch (e) {}
  }

  function dump() {
    try { return JSON.parse(localStorage.getItem(KEY)) || []; } catch (e) { return []; }
  }

  function toast(text) {
    try {
      var ui = (window.ArkShell && window.ArkShell.ui) || null;
      if (ui && typeof ui.toast === 'function') ui.toast(text, 6000);
    } catch (e) {}
  }

  /* 一次异常 = 一条记录 + 最多一次提示 */
  function note(msg) {
    var key = String(msg).slice(0, 300);
    record(key);
    if (seen[key]) return;
    seen[key] = true;
    toast('出了点问题，游戏可能卡住。\n排行榜和「重开一局」应该还能用（错误已记录）');
  }

  window.addEventListener('error', function (e) {
    if (!e || !e.message) return;   // 图片/脚本等资源加载失败不算崩溃，别误报
    try {
      note(e.message + (e.filename ? ' @ ' + String(e.filename).split('/').pop() + ':' + e.lineno : ''));
    } catch (err) {}
  });

  window.addEventListener('unhandledrejection', function (e) {
    try {
      var r = (e && e.reason) || null;
      note('未处理的 Promise 拒绝：' + ((r && r.message) ? r.message : String(r)));
    } catch (err) {}
  });

  /* dump() 给排查用：Console 里 ArkShell.guard.dump() 能直接列出最近 20 条。 */
  NS.guard = { record: record, note: note, dump: dump, KEY: KEY };
})();

/* src: src/shell/01-sdk.js */
/* #SHELL_START */
/* ============================================================================
 * 外壳 · 平台层（ISSUE-20261029-45）
 * ----------------------------------------------------------------------------
 * 把原 index.html 的「Telegram 能力判定」搬进单文件，并改了一处关键实现：
 *
 *   Telegram SDK 由本文件**运行时按需注入**，不再是 index.html 里那行
 *   外链 script 标签（src=…telegram-web-app.js）。因为外壳内联后，那行外链会让
 *   NB-04（离线自包含）直接失败 —— 游戏本体必须能双击离线跑。
 *
 *   语义是「有则增强、无则降级」，不是偷偷绕闸门：
 *     · 加载成功 → Mini App 能力（initData 验签身份、sendData 上报）
 *     · 失败/超时  → 网页游客通道（localStorage 设备 id），功能不残缺
 *   build/verify.mjs 的 NB-04 注释里已显式写下这条例外。
 *
 * 所有模块各自独立 IIFE，只通过 window.ArkShell 命名空间通信 ——
 * 避免与游戏侧已有的 ~26 个模块抢全局名（曾实测 paintBoard / hideHint 撞名）。
 * ========================================================================== */
(function () {
  'use strict';
  var NS = window.ArkShell = window.ArkShell || {};

  /* ---- UI 占位：04-panel 会覆盖成真实实现，保证 02/03 先写也不报错 ---- */
  NS.ui = NS.ui || {};
  if (!NS.ui.toast) NS.ui.toast = function () {};
  if (!NS.ui.showHint) NS.ui.showHint = function () {};
  if (!NS.ui.hideHint) NS.ui.hideHint = function () {};

  var SDK_URL = 'https://telegram.org/js/telegram-web-app.js';
  /* Telegram 的 WebView 里 SDK 一般 <300ms；普通浏览器/离线要等到失败才知道，
     这里按 UA 给两档超时，避免网页模式干等。 */
  var TIMEOUT_MS = /Telegram/i.test(navigator.userAgent || '') ? 3000 : 1200;

  NS.sdkReady = new Promise(function (resolve) {
    if (window.Telegram && window.Telegram.WebApp) return resolve(window.Telegram.WebApp);
    var settled = false;
    function done(v) { if (settled) return; settled = true; resolve(v || null); }
    try {
      var s = document.createElement('script');
      s.src = SDK_URL;
      s.async = true;
      s.onload = function () { done(window.Telegram && window.Telegram.WebApp); };
      s.onerror = function () { done(null); };
      document.head.appendChild(s);
      setTimeout(function () { done(window.Telegram && window.Telegram.WebApp); }, TIMEOUT_MS);
    } catch (e) { done(null); }
  }).then(function (W) {
    /* 纯浏览器里 telegram-web-app.js 也会注入 WebApp，但 platform === 'unknown'
       且 sendData 是空壳 —— 不排除这种情况会把「已提交」变成「实际没记录」。*/
    var HAS_SDK = !!W;
    var HAS_INIT = !!(W && W.initData);
    var IN_TG = HAS_SDK && W.platform !== 'unknown';
    NS.plat = {
      W: W || null,
      HAS_SDK: HAS_SDK,
      HAS_INIT: HAS_INIT,
      IN_TG: IN_TG,
      CAN_REPORT: IN_TG && !HAS_INIT,   // 键盘按钮入口：sendData 可用
      IS_WEB: !HAS_INIT,                // 无 initData（含纯浏览器）→ 走设备身份
    };
    return NS.plat;
  });

  /* ---- 小工具 ---- */
  NS.$ = function (id) { return document.getElementById(id); };

  /** 设备身份（网页直接打开时用，替代 initData）。 */
  NS.deviceId = function () {
    var k = 'ark_device_id';
    try {
      var v = localStorage.getItem(k);
      if (v && v.length >= 8) return v;
      var id = '';
      if (window.crypto && crypto.randomUUID) id = crypto.randomUUID().replace(/-/g, '');
      else {
        var s = 'abcdef0123456789';
        for (var i = 0; i < 32; i++) id += s.charAt(Math.floor(Math.random() * 16));
      }
      localStorage.setItem(k, id);
      return id;
    } catch (e) { return ''; }
  };
})();

/* src: src/shell/02-account.js */
/* ============================================================================
 * 外壳 · 账号层（ISSUE-20261029-45）
 * ----------------------------------------------------------------------------
 * 搬自 index.html，业务逻辑**逐字未改**（账号串解析、本机存储、身份判定、上报），
 * 只做了两处结构性调整：
 *   1. 全局单例 APP → NS.app（避免与游戏侧 ~26 个模块抢全局名）
 *   2. 直接调用的 toast/showHint → NS.ui.*（由 04-panel 覆盖成真实实现）
 *
 * 身份模型（与服务端 bot_rank.py 一致，勿单方面改）：
 *   · Telegram 入口 → initData 验签 → uid = tg user id（跨设备稳定）
 *   · 网页游客     → localStorage 设备 id → uid = dev_<uuid>（换设备即换 uid，已知限制）
 *
 * 「改名不新注册」：走 kind:'rename' → bot 侧 rename_user(uid, name) 按 uid 更新，
 * 保留 best_level/best_kills/runs，只有该 uid 从未出现过才新建。服务端语义已满足，
 * 前端要做的只是**别传错身份**（始终用同一个 uid，不因改名而重置设备 id）。
 * ========================================================================== */
(function () {
  'use strict';
  var NS = window.ArkShell;
  if (!NS) return;

  var ACCT_KEY = 'ark_account';        // 完整账号串（含数字口令），只存本机
  var NAME_KEY = 'ark_player_name';    // 显示名（兼容旧字段与上报）
  var ACCT_RE = /^([\u4e00-\u9fa5A-Za-z]{1,12})(\d{4,8})$/;
  var REPORT_URL_FALLBACK = '';
  var BOT_USER_FALLBACK = 'yu7_bot';

  var app = NS.app = {
    data: null,          // leaderboard 数据
    myId: 0,             // Telegram user id 或 dev_<uuid>
    myName: '',          // 显示名
    myAccount: '',       // 完整账号 = 显示名 + 数字口令
    isNewAccount: false,
    reportUrl: '',
    botUser: '',
  };
  NS.myScore = null;

  function $(id) { return document.getElementById(id); }
  function ui() { return NS.ui; }

  /* ===== 账号串解析 / 校验（失败必须给具体原因，绝不静默截断） ===== */
  function parseAccount(raw) {
    var s = String(raw == null ? '' : raw).trim();
    if (!s) return { ok: false, reason: '请输入「名字 + 4–8 位数字口令」，例如 阿米娅1234' };
    if (/\s/.test(s)) return { ok: false, reason: '不能包含空格：名字后面直接跟数字' };
    if (/^\d+$/.test(s)) return { ok: false, reason: '名字不能全是数字：开头请用汉字或英文字母' };
    var m = s.match(ACCT_RE);
    if (m) return { ok: true, name: m[1], code: m[2] };
    var tail = s.match(/(\d+)$/);
    var head = tail ? s.slice(0, s.length - tail[1].length) : s;
    if (!/[\u4e00-\u9fa5A-Za-z]/.test(head)) return { ok: false, reason: '名字只能用汉字或英文字母' };
    if (/\d/.test(head)) return { ok: false, reason: '数字只能放在最后当口令，不能夹在名字里' };
    if (head.length > 12) return { ok: false, reason: '名字最多 12 个字' };
    if (!tail) return { ok: false, reason: '结尾需要 4–8 位数字口令（例如 阿米娅1234）' };
    if (tail[1].length < 4) return { ok: false, reason: '数字口令至少 4 位' };
    if (tail[1].length > 8) return { ok: false, reason: '数字口令最多 8 位' };
    return { ok: false, reason: '格式是「名字 + 4–8 位数字」，中间不要加字符' };
  }

  function displayNameOf(acct) {
    var p = parseAccount(acct);
    return p.ok ? p.name : '';
  }

  /* 公开显示名：老数据可能把口令写在名字里（如 阿米娅1234），公开位置一律剥掉 4–8 位纯数字尾巴。
     只影响显示，不回写 leaderboard.json（那是 bot 的事）。 */
  function publicName(raw) {
    var s = String(raw == null ? '' : raw);
    var stripped = s.replace(/\d{4,8}$/, '');
    return stripped || s;
  }

  /* ===== 本机账号 ===== */
  function loadAccount() {
    try { app.myAccount = localStorage.getItem(ACCT_KEY) || ''; } catch (e) { app.myAccount = ''; }
    if (!app.myAccount) {
      var legacy = '';
      try { legacy = localStorage.getItem(NAME_KEY) || ''; } catch (e) {}
      if (legacy && parseAccount(legacy).ok) app.myAccount = legacy;
    }
    if (!app.myAccount) {
      // 首次进入：自动生成「玩家 + 4 位数字」
      var code = String(1000 + Math.floor(Math.random() * 9000));
      app.myAccount = '玩家' + code;
      app.isNewAccount = true;
      saveAccount(app.myAccount);
    }
    app.myName = displayNameOf(app.myAccount);
  }

  function saveAccount(acct) {
    app.myAccount = acct;
    app.myName = displayNameOf(acct) || app.myName;
    try {
      localStorage.setItem(ACCT_KEY, acct);
      if (app.myName) localStorage.setItem(NAME_KEY, app.myName);
    } catch (e) {}
  }

  /* ===== 我的身份 ===== */
  function resolveMyId() {
    var p = NS.plat || {};
    if (p.HAS_INIT && p.W && p.W.initDataUnsafe && p.W.initDataUnsafe.user) {
      app.myId = p.W.initDataUnsafe.user.id || 0;
    } else {
      var dev = NS.deviceId();
      app.myId = dev ? ('dev_' + dev) : 0;
    }
  }

  /* ===== 接口地址 ===== */
  function onOurDomain() {
    var h = (location.hostname || '').toLowerCase();
    return h === 'arkroguelike.top' || /\.arkroguelike\.top$/.test(h);
  }
  function apiBase() {
    if (onOurDomain()) return location.origin;
    var u = app.reportUrl || '';
    return u.replace(/\/api\/score\/?$/i, '');
  }

  /* ===== 配置与静态榜单兜底 ===== */
  /**
   * 没有 fetch 的环境（老 Safari、jsdom 门禁、离线裁剪版）直接走回调，
   * 不要抛异常 —— 外壳现在内联在产物里，一旦在这里冒泡就会把整个游戏打白。
   * 榜单显示为「还没有人上榜」，游戏照常可玩。
   */
  function hasFetch() { return typeof fetch === 'function'; }

  function loadConfig(cb) {
    if (!hasFetch()) { if (cb) cb(); return; }
    /* ISSUE-20261101-143 · 首帧不等网络。
     * 这个 fetch 只是取排行榜上报地址，与画棋盘毫无关系，但它原来直接卡着
     * `boot()` 里的 `NS.board.paint()` —— 服务器不理/网络半断时，棋盘**永远**不画，
     * 玩家看到的就是纯黑骨架。2.5s 强制放行，晚到的数据照样会写回 app.data。 */
    var fired = false;
    var guard = null;
    function finish() {
      if (fired) return;
      fired = true;
      if (guard) clearTimeout(guard);
      if (cb) cb();
    }
    guard = setTimeout(finish, 2500);
    fetch('leaderboard.json?t=' + Date.now(), { cache: 'no-store' })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (d) {
        app.data = d || app.data;
        if (app.data) {
          app.reportUrl = app.data.report_url || REPORT_URL_FALLBACK || '';
          app.botUser = app.data.bot_username || BOT_USER_FALLBACK || app.botUser || '';
          if (onOurDomain()) app.reportUrl = location.origin + '/api/score';
        }
        finish();
      })
      .catch(function () { finish(); });
  }

  /* ===== 上报 ===== */
  function deepLinkScore(level, kills) {
    try {
      var bot = app.botUser || BOT_USER_FALLBACK;
      if (!bot) {
        ui().toast('未配置 bot 用户名，无法回传成绩。\n用 /play 的键盘按钮重开一局即可记录。', 9000);
        return;
      }
      var dl = 'https://t.me/' + bot + '?start=score:' + level + '_' + kills;
      var W = (NS.plat || {}).W;
      if (W && W.openTelegramLink) W.openTelegramLink(dl);
      else window.location.href = dl;
      ui().toast('正在记录成绩…（已切到聊天）\n点机器人回复里的 /rank 看排行榜', 5000);
    } catch (e) {
      ui().toast('当前入口无法回传成绩。\n用 /play 的键盘按钮重开一局即可记录。', 9000);
    }
  }

  function reportScore(level, kills) {
    var p = NS.plat || {};
    var W = p.W;
    NS.myScore = { level: level, kills: kills };
    if (NS.board && NS.board.pushMyScore) NS.board.pushMyScore();

    if (p.CAN_REPORT && W && W.sendData) {
      try {
        W.sendData(JSON.stringify({ type: 'rogue_score', level: level, kills: kills, tg_id: 0, tg_name: app.myName || '', initData: '' }));
        ui().toast('成绩已提交：第 ' + level + ' 层 / 击杀 ' + kills + '\n点棋盘左上角 👤 可看排行榜', 5000);
        return;
      } catch (e) { /* 落到下面的 fetch 通道 */ }
    }

    if (app.reportUrl && (p.HAS_INIT || p.IS_WEB)) {
      /* ISSUE-20261030-50：body 带完整账号串（名字 + 数字口令），供服务端按
         「账号串 → uid」索引归并，实现跨设备找回同一条榜单记录。
         服务端（bot_rank.py）未改造前会忽略这个字段，行为与现在完全一致。 */
      var body = { kind: 'score', level: level, kills: kills, name: app.myName || '', account: app.myAccount || '' };
      if (p.HAS_INIT) { body.initData = W.initData; }
      else {
        var dev = NS.deviceId();
        if (!dev) { ui().toast('浏览器禁用了本地存储，无法识别身份。\n请在 Telegram 内打开。', 9000); return; }
        body.device = dev;
      }
      /* ISSUE-20261030-51：fetch 本身也可能**同步**抛（URL 非法 / 被 CSP 拦截），
         外壳现在与游戏同文档，异常冒出去就是整页白 —— 补最后一道 catch。 */
      try {
        fetch(app.reportUrl, {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
        }).then(function (r) { return r.json(); }).then(function (j) {
          if (j && j.ok) {
            ui().toast('成绩已记录：第 ' + level + ' 层 / 击杀 ' + kills + '\n点棋盘左上角 👤 可看排行榜', 5000);
            /* ★ ISSUE-20261030-50：服务端可能把这条成绩记到**另一个 uid** 上
               （换设备输入同一账号串 → 命中「账号串→uid」索引 → 找回原记录）。
               本地还拿着设备 id 的话，榜单里就找不到自己那行，所以要用服务端回的 id 覆盖。 */
            if (j.id && String(j.id) !== String(app.myId)) {
              app.myId = j.id;
              if (NS.board && NS.board.pushMyId) NS.board.pushMyId();
            }
            if (j.leaderboard && NS.board && NS.board.apply(j.leaderboard)) NS.board.paint();
            else if (NS.board) NS.board.refresh();
            if (NS.board) setTimeout(function () { NS.board.refresh(); }, 3000);
          } else if (p.HAS_INIT) { deepLinkScore(level, kills); }
          else { ui().toast('成绩记录失败（服务器拒绝了请求）。\n稍后再打一局试试。', 8000); }
        }).catch(function () {
          if (p.HAS_INIT) { deepLinkScore(level, kills); }
          else { ui().toast('连不上成绩服务器。\n确认 bot 正在运行后重试。', 8000); }
        });
      } catch (e) {
        ui().toast('成绩记录失败。\n稍后再打一局试试。', 8000);
      }
      return;
    }

    if (p.HAS_INIT && app.botUser) { deepLinkScore(level, kills); return; }
    if (p.IN_TG) {
      ui().toast('当前入口无法回传成绩。\n用 /play 的键盘按钮重开一局即可记录。', 9000);
    } else if (!app.reportUrl) {
      ui().toast('成绩服务器地址还没加载到（bot 可能没启动）。\n你的成绩：第 ' + level + ' 层 / 击杀 ' + kills, 8000);
    } else {
      ui().toast('浏览器预览模式，成绩不会记录。\n（你的成绩：第 ' + level + ' 层 / 击杀 ' + kills + '）', 7000);
    }
  }

  /**
   * 改名字 + 口令。
   * 「直接视为修改，不新注册」靠两点：
   *   1. 前端不动设备 id / initData（uid 不变）
   *   2. 上报 kind:'rename'（不是 kind:'score'），服务端 rename_user(uid) 只改 name 字段
   * 因此历史成绩（best_level / best_kills / runs）全部保留在同一条记录上。
   */
  function renameAccount(name, code) {
    var p = NS.plat || {};
    var W = p.W;
    if (p.CAN_REPORT && W && W.sendData) {
      try {
        W.sendData(JSON.stringify({ type: 'rename', name: name, account: name + code }));
        ui().toast('账号已保存，回聊天确认同步', 4000);
        return;
      } catch (e) { ui().toast('账号已在本机保存', 3000); return; }
    }
    if (app.reportUrl && (p.HAS_INIT || p.IS_WEB)) {
      var body = { kind: 'rename', name: name, account: name + code, code: code };
      if (p.HAS_INIT) { body.initData = W.initData; }
      else { body.device = NS.deviceId(); }
      /* ISSUE-20261030-51：同 reportScore —— fetch 同步抛时不能把异常冒到 window */
      try {
        fetch(app.reportUrl, {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
        }).then(function (r) { return r.json(); }).then(function (j) {
          if (j && j.ok) {
            /* ★ ISSUE-20261030-50：改名后服务端回的是「索引里的 uid」。
               换设备时它可能不是本机设备 id —— 不覆盖就会在榜单里标不出自己。 */
            if (j.id && String(j.id) !== String(app.myId)) {
              app.myId = j.id;
              if (NS.board && NS.board.pushMyId) NS.board.pushMyId();
            }
            ui().toast('账号已同步到排行榜', 4000);
            if (NS.board) NS.board.refresh();
          } else {
            ui().toast('账号已在本机保存（同步失败）', 4000);
          }
        }).catch(function () { ui().toast('账号已在本机保存（同步失败）', 4000); });
      } catch (e) { ui().toast('账号已在本机保存（同步失败）', 4000); }
    } else {
      ui().toast('账号已在本机保存', 3000);
    }
  }

  /* 我是否在榜单里（先按 id，再按显示名兜底） */
  function findMe() {
    if (!app.data || !app.data.entries) return null;
    var list = app.data.entries;
    if (app.myId) {
      for (var i = 0; i < list.length; i++) if (String(list[i].id) === String(app.myId)) return list[i];
    }
    if (app.myName) {
      for (var j = 0; j < list.length; j++) if (publicName(list[j].name) === app.myName) return list[j];
    }
    return null;
  }

  /* ===== 管理员判定（ISSUE-20261030-55） =====
   * 口径：账号串 = 显示名 + 数字口令，**口令 === ARK_ADMIN_CODE 的那个账号就是管理员**。
   * 复用 parseAccount 取 code（不要再写一套解析），此刻 app.myAccount 已由 loadAccount() 填好。
   * ★ 客户端判定：改 localStorage 或读源码都能自封管理员，所以它防误触不防作弊，
   *   别拿它保护服务端资源（详见 ISSUE-20261030-55 §备注）。 */
  function isAdmin() {
    var code = (typeof ARK_ADMIN_CODE === 'undefined') ? '' : String(ARK_ADMIN_CODE);
    if (!code) return false;
    var p = parseAccount(app.myAccount);
    return !!(p.ok && p.code === code);
  }

  NS.account = {
    app: app,
    parseAccount: parseAccount,
    displayNameOf: displayNameOf,
    publicName: publicName,
    hasFetch: hasFetch,
    loadAccount: loadAccount,
    saveAccount: saveAccount,
    resolveMyId: resolveMyId,
    onOurDomain: onOurDomain,
    apiBase: apiBase,
    loadConfig: loadConfig,
    reportScore: reportScore,
    renameAccount: renameAccount,
    deepLinkScore: deepLinkScore,
    findMe: findMe,
    isAdmin: isAdmin,
  };
})();

/* src: src/shell/03-board.js */
/* ============================================================================
 * 外壳 · 榜单层（ISSUE-20261029-45）
 * ----------------------------------------------------------------------------
 * 数据来源与原实现一致（优先 /api/leaderboard 实时接口，失败回退 leaderboard.json）。
 *
 * 渲染按人类 2026-10-29 的新规格重写：
 *   · 面板内**只显示排行榜**（原左 1/3 账号卡整块删除）
 *   · 自己那行：名字右侧 [我] 徽标 → [编辑] 按钮
 *   · 点 [编辑] → 在**该行下方**插入 editRow（输入框 + 保存 + 说明文字），不换屏不弹窗
 *   · 未上榜 → 榜单底部 setRow 提供同一套入口
 *   · 打开面板自动滚到自己那行（scrollTop 居中，不用 scrollIntoView，避免连带滚动整页）
 *
 * 密度：每项 ≈38px（原 ≈62px），竖屏 390x844 下至少 8 名完整可见（ISSUE-45 AC-7）。
 * ========================================================================== */
(function () {
  'use strict';
  var NS = window.ArkShell;
  if (!NS) return;

  var editAnchor = null;      // 当前展开编辑抽屉所依附的 <li>

  function $(id) { return document.getElementById(id); }
  function acct() { return NS.account; }
  function ui() { return NS.ui; }

  /* 按显示名合并同名账户（公开 leaderboard.json 只有显示名、无口令）。
     口径：最高层、最高击杀、游玩次数累加；代表 id 取最高层那条。 */
  function mergeByName(entries) {
    var map = {}, order = [];
    for (var i = 0; i < entries.length; i++) {
      var e = entries[i] || {};
      var key = acct().publicName(e.name) || '匿名';
      var m = map[key];
      if (!m) {
        m = map[key] = { id: e.id, ids: [e.id], name: key, level: (e.level || 0), kills: (e.kills || 0), runs: (e.runs || 0) };
        order.push(key);
      } else {
        if (e.id) m.ids.push(e.id);
        if ((e.level || 0) > m.level) { m.level = (e.level || 0); m.id = e.id; }
        if ((e.kills || 0) > m.kills) m.kills = (e.kills || 0);
        m.runs += (e.runs || 0);
      }
    }
    return order.map(function (k) { return map[k]; });
  }

  function sortedList() {
    var app = NS.app;
    var raw = (app.data && app.data.entries) ? app.data.entries.slice() : [];
    return mergeByName(raw).sort(function (a, b) {
      if ((b.level || 0) !== (a.level || 0)) return (b.level || 0) - (a.level || 0);
      return (b.kills || 0) - (a.kills || 0);
    });
  }

  function isMine(u) {
    var app = NS.app;
    if (app.myId && String(u.id) === String(app.myId)) return true;
    return !!(app.myName && u.name === app.myName);
  }

  /* ===== 删榜（ISSUE-20261028-16，人类 2026-10-30 拍板改为「右键就能删」）=====
   * 口径（人类 23:10 / 23:15 定的四条，本轮只改掉「口令」那一条）：
   *   · 按 id 只删那一条记录 —— 不写 banned、不在上报入口拦人，
   *     对方再打一局正常重新上榜（**这是硬边界，别自作主张加黑名单**）；
   *   · 不做 🗑 按钮、不改行内布局，靠手势：桌面右键 / 触屏长按 600ms；
   *   · 删前必须过一次浏览器原生二次确认。
   * ⚠️ 没有口令 = 任何打开这个页面的人右键都能删别人的记录。这是人类明确接受的取舍，
   *    所以服务端也不做鉴权（`bot_rank._handle_admin_delete`）。要收回这个口子，
   *    设环境变量 `RANK_DELETE_LOCK=1` + `RANK_ADMIN_TOKEN` 即可（见该函数注释）。
   *
   * 为什么要删「这一行背后的全部 id」：显示层 mergeByName 会把同名账户合并成一行，
   * 只删代表 id 的话这行会立刻被同名另一条顶回来，玩家会以为没删掉。
   */
  function deleteRow(u) {
    var ids = (u.ids && u.ids.length) ? u.ids.slice() : (u.id ? [u.id] : []);
    if (!ids.length) return;
    var label = '删除「' + (u.name || '匿名') + '」的榜单记录？\n（只删记录，对方再打一局可以重新上榜）';
    if (typeof window.confirm === 'function' && !window.confirm(label)) return;
    var b = acct().apiBase();
    if (!b) { if (ui() && ui().toast) ui().toast('离线状态，删不了', 2500); return; }
    var left = ids.length, changed = 0;
    ids.forEach(function (id) {
      fetch(b + '/api/score', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ kind: 'admin_delete', id: String(id) })
      }).then(function (r) { return r.ok ? r.json() : null; })
        .then(function (d) {
          if (d && d.deleted) changed++;
          if (d && d.leaderboard && apply(d.leaderboard)) { /* 先吃下最新榜，最后统一重绘 */ }
        })
        .catch(function () { /* 网络失败也要走收尾，否则计时器永远不归零 */ })
        .then(function () {
          if (--left > 0) return;
          paint();
          if (ui() && ui().toast) {
            ui().toast(changed ? ('已删除 ' + changed + ' 条记录')
              : '删除失败（离线，或服务端版本过旧）', 3000);
          }
        });
    });
  }

  /* 右键 / 长按两种手势都挂在 <li> 上；点在行内按钮（[编辑]）上时不算，避免误删 */
  function attachDeleteGesture(li, u) {
    li.addEventListener('contextmenu', function (e) {
      if (e.target && e.target.closest && e.target.closest('button')) return;
      e.preventDefault();
      e.stopPropagation();
      deleteRow(u);
    });
    var timer = null;
    var cancel = function () { if (timer) { clearTimeout(timer); timer = null; } };
    li.addEventListener('touchstart', function (e) {
      if (e.target && e.target.closest && e.target.closest('button')) return;
      cancel();
      timer = setTimeout(function () { timer = null; deleteRow(u); }, 600);
    }, { passive: true });
    li.addEventListener('touchend', cancel, { passive: true });
    li.addEventListener('touchmove', cancel, { passive: true });
    li.addEventListener('touchcancel', cancel, { passive: true });
  }

  /* ===== 渲染 =====
   * ISSUE-20261030-51：整帧先在文档片段里拼完，最后一次性换进 #miniBoard。
   * 原来是 ol.innerHTML = '' 再逐条 append —— 中途一抛错就留下一张**半截榜单**，
   * 同文档里没有 iframe 兜底，玩家看到的就是「榜坏了」。现在出错时上一帧原样保留。 */
  function render() {
    var ol = $('miniBoard');
    if (!ol) return;
    var frag;
    try {
      frag = buildRows();
    } catch (e) {
      /* 这里刻意什么都不做：DOM 还是上一次渲染成功的样子 */
      try { if (window.console && console.warn) console.warn('[board] 渲染失败，保留上一帧', e); } catch (e2) {}
      return;
    }
    ol.innerHTML = '';
    ol.appendChild(frag);
  }

  /* 拼一帧榜单（不碰 #miniBoard 本体，出错即整帧作废） */
  function buildRows() {
    var empty = $('boardEmpty'), meta = $('boardMeta');
    var frag = document.createDocumentFragment();
    closeEdit();

    var list = sortedList();
    if (!list.length) {
      if (empty) empty.hidden = false;
      if (meta) meta.textContent = '';
      return frag;
    }
    if (empty) empty.hidden = true;

    var data = NS.app.data;
    if (data && data.updated_at && meta) {
      var dt = new Date(data.updated_at * 1000);
      function p(n) { return n < 10 ? '0' + n : '' + n; }
      meta.textContent = '更新 ' + (dt.getMonth() + 1) + '-' + p(dt.getDate()) + ' ' + p(dt.getHours()) + ':' + p(dt.getMinutes());
    }

    var meFound = false;
    list.forEach(function (u, i) {
      var mine = isMine(u);
      if (mine) meFound = true;

      var li = document.createElement('li');
      if (mine) li.className = 'me';

      var rk = document.createElement('div');
      rk.className = 'rk';
      rk.textContent = (i + 1);

      var who = document.createElement('div');
      who.className = 'who';
      var nm = document.createElement('div');
      nm.className = 'nm';
      nm.textContent = u.name;
      /* 副信息（击杀 / 次数）在 ≤420px 由 CSS 隐藏，把宽度让给名字 */
      var sc = document.createElement('div');
      sc.className = 'sc';
      sc.textContent = (u.kills || 0) + '杀 · ' + (u.runs || 0) + '次';
      who.appendChild(nm);
      who.appendChild(sc);

      var lv = document.createElement('div');
      lv.className = 'lv';
      lv.textContent = '第 ' + (u.level || 0) + ' 层';

      li.appendChild(rk);
      li.appendChild(who);
      li.appendChild(lv);

      /* 自己那行：原来的 [我] 徽标 → [编辑]（ISSUE-45） */
      if (mine) {
        var btn = document.createElement('button');
        btn.className = 'meEdit';
        btn.type = 'button';
        btn.textContent = '编辑';
        btn.setAttribute('aria-label', '编辑账号');
        btn.addEventListener('click', function (e) {
          e.stopPropagation();
          if (editAnchor === li) { closeEdit(); return; }
          openEdit(li);
        });
        li.appendChild(btn);
      }
      attachDeleteGesture(li, u);
      frag.appendChild(li);
    });

    /* 未上榜：底部给一行入口，点开同一套编辑抽屉。
       没有它，新玩家在「只显示排行榜」的面板里就找不到改名字的地方。 */
    if (!meFound) {
      var row = document.createElement('li');
      row.className = 'setRow';
      var b = document.createElement('button');
      b.id = 'btnSetName';
      b.type = 'button';
      b.textContent = '你还没上榜 · 设置名字';
      b.addEventListener('click', function (e) {
        e.stopPropagation();
        if (editAnchor === row) { closeEdit(); return; }
        openEdit(row);
      });
      row.appendChild(b);
      frag.appendChild(row);
    }
    return frag;
  }

  /* ===== 编辑抽屉（内联展开在自己那一行下方） ===== */
  /* ISSUE-20261030-51：同文档无 iframe 兜底，插入半截 editRow 比不插入更难收场，
     所以整段包 try/catch —— 失败就当没点过，榜单本身不受影响。 */
  function openEdit(anchorLi) {
    closeEdit();
    try {
      openEditInner(anchorLi);
    } catch (e) {
      editAnchor = null;
      try { if (window.console && console.warn) console.warn('[board] 编辑抽屉打开失败', e); } catch (e2) {}
    }
  }

  function openEditInner(anchorLi) {
    var st = acct();
    var li = document.createElement('li');
    li.className = 'editRow';
    li.innerHTML =
      '<div class="edline">'
      + '<input class="pname" id="pName" maxlength="20" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="例如 阿米娅1234" />'
      + '<button class="psave" id="pSave" type="button">保存</button>'
      + '</div>'
      + '<div class="perr" id="pErr" hidden></div>'
      + '<div class="ednote">名字只能用<b>汉字或英文</b>，后面的数字是<b>口令</b>：只在你编辑时显示，<b>永远不会出现在排行榜上</b>。记住整串（如「阿米娅1234」），换设备输入同一串就能找回同一账号</div>';

    anchorLi.parentNode.insertBefore(li, anchorLi.nextSibling);
    editAnchor = anchorLi;

    var inp = $('pName'), save = $('pSave'), err = $('pErr');
    if (inp) {
      inp.value = st.app.myAccount || '';
      /* 把整条编辑抽屉（输入框 + 保存 + 说明）完整滚进可见区。
       * 原 scrollIntoView({block:'nearest'}) 在「自己行已在视口偏下」时只认「顶部可见」就不动，
       * 导致抽屉底部（保存按钮 / 说明文字）被 #rankScroll 下边缘裁掉（ISSUE-49 实测 bug）。
       * 这里手动算：底部超界先下滚；若整条比视口还高（窄屏说明换行），再回退到顶部，
       * 保证输入框优先可见。 */
      function revealRow() {
        var sc = $('rankScroll');
        if (!sc) return;
        var cr = sc.getBoundingClientRect();
        var er = li.getBoundingClientRect();
        if (er.bottom > cr.bottom + 1) sc.scrollTop += (er.bottom - cr.bottom);
        er = li.getBoundingClientRect();
        if (er.top < cr.top - 1) sc.scrollTop -= (cr.top - er.top);
      }
      try {
        inp.focus({ preventScroll: true });
        if (inp.setSelectionRange) inp.setSelectionRange(inp.value.length, inp.value.length);
      } catch (e) {}
      inp.addEventListener('keydown', function (e) {
        if (e.key === 'Enter') { e.preventDefault(); submit(); }
        else if (e.key === 'Escape') { e.preventDefault(); closeEdit(); }
      });
      /* 布局稳定后滚一次；移动端键盘弹起会压缩可视区，250ms 后再滚一次兜底（不挂持久监听，避免关抽屉后误滚） */
      setTimeout(revealRow, 60);
      setTimeout(revealRow, 280);
    }
    function showErr(msg) {
      if (!err) return;
      err.textContent = msg || '';
      err.hidden = !msg;
    }
    function submit() {
      var p = st.parseAccount(inp ? inp.value : '');
      if (!p.ok) { showErr(p.reason); return; }
      showErr('');
      var next = p.name + p.code;
      var changed = next !== st.app.myAccount;
      st.saveAccount(next);
      st.app.isNewAccount = false;
      closeEdit();
      render();                       // 名字变了要重绘（自己那行的高亮跟着走）
      if (!changed) { ui().toast('账号未变', 2500); return; }
      st.renameAccount(p.name, p.code);
    }
    if (save) save.addEventListener('click', submit);
  }

  function closeEdit() {
    if (!editAnchor) return;
    var row = editAnchor.nextElementSibling;
    if (row && row.classList && row.classList.contains('editRow')) row.parentNode.removeChild(row);
    editAnchor = null;
  }

  /* ===== 滚动到「我」 ===== */
  function scrollToMe() {
    var ol = $('miniBoard'), sc = $('rankScroll');
    if (!ol || !sc) return;
    var me = ol.querySelector('li.me');
    if (!me) return;
    var top = me.offsetTop - (sc.clientHeight - me.offsetHeight) / 2;
    sc.scrollTop = Math.max(0, top);
  }

  /* ===== 数据接入 ===== */
  function apply(d) {
    if (!d || !d.entries) return false;
    var app = NS.app;
    app.data = {
      updated_at: d.updated_at || Math.floor(Date.now() / 1000),
      entries: d.entries,
      bot_username: d.bot_username || app.botUser || 'yu7_bot',
      report_url: d.report_url || app.reportUrl,
    };
    if (d.report_url && !acct().onOurDomain()) app.reportUrl = d.report_url;
    if (d.bot_username) app.botUser = d.bot_username;
    return true;
  }

  /* 推给完整排行榜 iframe（leaderboard.html 是独立页面，这条 iframe 边界保留） */
  function pushToFrame(msg) {
    var f = $('rankFrame');
    try { if (f && f.contentWindow) f.contentWindow.postMessage(msg, '*'); } catch (e) {}
  }
  function pushMyScore() {
    if (!NS.myScore) return;
    pushToFrame({ type: 'my_score', level: NS.myScore.level, kills: NS.myScore.kills });
    pushMyId();
  }
  function pushMyId() {
    if (NS.app.myId) pushToFrame({ type: 'my_id', id: NS.app.myId });
  }
  function pushSnapshot() {
    if (NS.app.data && NS.app.data.entries) pushToFrame({ type: 'board', data: NS.app.data });
  }
  function pushApiBase() {
    var b = acct().apiBase();
    if (b) pushToFrame({ type: 'api_base', base: b });
  }

  function paint() {
    render();
    pushSnapshot();
    pushApiBase();
    if (NS.panel && NS.panel.syncCorner) NS.panel.syncCorner();
  }

  function refresh() {
    if (!acct().hasFetch()) { render(); return; }
    var b = acct().apiBase();
    if (!b) { acct().loadConfig(paint); return; }
    fetch(b + '/api/leaderboard?t=' + Date.now(), { cache: 'no-store' })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (d) {
        if (apply(d)) paint();
        else acct().loadConfig(paint);
      })
      .catch(function () { acct().loadConfig(paint); });
  }

  NS.board = {
    render: render,
    apply: apply,
    paint: paint,
    refresh: refresh,
    mergeByName: mergeByName,
    sortedList: sortedList,
    isMine: isMine,
    scrollToMe: scrollToMe,
    closeEdit: closeEdit,
    pushMyScore: pushMyScore,
    pushMyId: pushMyId,
    pushSnapshot: pushSnapshot,
    pushApiBase: pushApiBase,
  };
})();

/* src: src/shell/04-panel.js */
/* ============================================================================
 * 外壳 · 面板层（ISSUE-20261029-45）
 * ----------------------------------------------------------------------------
 * 与原 index.html 相比，这里删掉了两块纯为跨 iframe 服务的补丁：
 *   · placeLobbyOverBoard()：原来要「iframe 偏移 + 游戏内棋盘矩形」两次换算，
 *     还得等游戏 postMessage 上报；现在同文档，直接读 #board 的 rect。
 *   · syncCornerToGame()：原来要量 #lobbyOpenBtn 的 rect 再换算到抽屉坐标系；
 *     现在 CSS 直接用棋盘的 --corner-x / --cell（同 :root），CSS 就精确。
 *
 * 新增：面板高度按「至少 8 名」兜底（ISSUE-45 AC-7）—— 棋盘是正方形，
 * 竖屏下棋盘高可能只有 390px，装不下 8 行，所以面板允许在棋盘基础上**向上撑高**，
 * 上限是「棋盘上沿到视口底部」，不会溢出屏幕。
 * ========================================================================== */
(function () {
  'use strict';
  var NS = window.ArkShell;
  if (!NS) return;

  var open = false;
  var ROWS_VISIBLE = 8;
  var ROW_BLOCK = 42;      // 行高 38 + 间距 4
  var CHROME_H = 96;       // header 36 + footer 44 + 内边距

  function $(id) { return document.getElementById(id); }
  function boardEl() { return document.getElementById('board'); }

  /* ===== 提示条 / toast（游戏侧没有同名实现，这里是唯一一套）===== */
  function showHint(text, ok) {
    var h = $('hint');
    if (!h) return;
    h.textContent = text || '';
    h.className = (ok ? 'ok' : '');
    clearTimeout(showHint._t);
    showHint._t = setTimeout(hideHint, 6000);
  }
  function hideHint() {
    var h = $('hint');
    if (h) h.className = 'hide';
  }
  function toast(text, ms) {
    var t = $('toast');
    if (!t) return;
    t.textContent = text || '';
    t.style.display = 'block';
    clearTimeout(toast._t);
    toast._t = setTimeout(function () { t.style.display = 'none'; }, ms || 3000);
  }

  /* 覆盖 01 的占位实现，让 02/03 拿到真实 UI */
  NS.ui.toast = toast;
  NS.ui.showHint = showHint;
  NS.ui.hideHint = hideHint;

  /* ===== 面板定位与显隐 ===== */
  function place() {
    var d = $('lobbyDrawer'), b = boardEl();
    if (!d || !b) return;
    var r = b.getBoundingClientRect();
    if (!(r.width > 0) || !(r.height > 0)) return;
    var vh = window.innerHeight || 0;
    var need = ROWS_VISIBLE * ROW_BLOCK + CHROME_H;
    var avail = vh - r.top - 6;
    var h = Math.max(r.height, Math.min(need, avail > 0 ? avail : r.height));
    d.style.left = Math.round(r.left) + 'px';
    d.style.top = Math.round(r.top) + 'px';
    d.style.width = Math.round(r.width) + 'px';
    d.style.height = Math.round(h) + 'px';
    d.style.bottom = 'auto';
  }

  /* 角标位置由 CSS 的 --corner-x/--cell 决定，这里只需在尺寸变化时确保面板跟随 */
  function syncCorner() { /* CSS 变量自动生效，保留钩子供 board.paint() 调用 */ }

  /* 首次开合时记录「👤」被图标化后的 innerHTML，关闭时原样还原（不依赖全局 iconify） */
  var lobbyBtnClosedHtml = null;
  function setOpen(next) {
    open = !!next;
    var d = $('lobbyDrawer'), m = $('lobbyMask'), btn = $('lobbyOpenBtn');
    if (open) place();
    if (d) {
      d.classList.toggle('on', open);
      d.setAttribute('aria-hidden', open ? 'false' : 'true');
      d.style.pointerEvents = '';
    }
    if (m) m.classList.toggle('on', open);
    /* 游戏侧角标同步高亮 + 原地变 ✕（原来是 postMessage 'ark_lobby_state'，现在直接改）。
       ★ ISSUE-20261030-7x：与设置面板 ⚙ 同款 —— 角标是「同一颗按钮」，打开态变 ✕、位置不变，
       再按一下即关闭；不再用面板内那枚独立关闭按钮（它用棋盘相对坐标定位、与面板错位）。 */
    if (btn) {
      if (lobbyBtnClosedHtml === null) lobbyBtnClosedHtml = btn.innerHTML;
      btn.classList.toggle('on', open);
      btn.title = open ? '收起账号与排行' : '账号与排行';
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
      btn.innerHTML = open ? '✕' : (lobbyBtnClosedHtml || '👤');
    }
    if (open) {
      if (d && d.focus) { try { d.focus({ preventScroll: true }); } catch (e) {} }
      NS.board.refresh();          // 每次打开都拉一次实时榜
      /* 等榜单落地后再滚到自己：refresh 是异步的，paint 里会再调一次 */
      setTimeout(function () { NS.board.scrollToMe(); }, 120);
    } else {
      NS.board.closeEdit();
    }
  }

  /* ISSUE-20261030-72：游戏内完整排行榜浮层（#rankPanel + iframe leaderboard.html）已整体删除，
     openRank / closeRank 一并移除。完整榜仍是独立页 leaderboard.html，由榜单抽屉的
     #miniBoard 预览承担「看一眼」的需求（与 ISSUE-20261030-53 口径一致）。 */

  NS.panel = {
    isOpen: function () { return open; },
    setOpen: setOpen,
    open: function () { setOpen(true); },
    close: function () { setOpen(false); },
    toggle: function () { setOpen(!open); },
    place: place,
    syncCorner: syncCorner,
    toast: toast,
    showHint: showHint,
    hideHint: hideHint,
  };
})();

/* src: src/shell/05-score.js */
/* ============================================================================
 * 外壳 · 成绩触发（ISSUE-20261029-45 / ISSUE-20261030-52）
 * ----------------------------------------------------------------------------
 * 52 之前这里是 `setTimeout(tick, 300)` 永久轮询顶层变量 phase / level / enemies
 * 判断是否该上报，三个毛病（详见 ISSUE-20261030-52）：
 *   ① initLevel() 的 catch 也会把 phase 置成 GAMEOVER → 初始化报错被当成「玩家死亡」
 *      上报一条「第1层 / 0杀」的**假成绩**，这是正在发生的数据污染（P0）；
 *   ② `typeof phase !== 'undefined'` 这种写法永不报错 → 游戏侧一改名就静默失效；
 *   ③ 300ms 采样在「最后一个敌人死亡」与「换关替换 enemies 数组」撞到同一间隔时少记杀。
 *
 * 现在改成**事件驱动**：
 *   · 只在 endGame()（玩家真的死了）派发 `ark:gameover`，外壳监听后上报一次；
 *   · 击杀数取游戏侧自己维护的 runKills（src/rules/state.js），外壳不再猜；
 *   · initLevel 的异常分支与联机的 PVP_OVER **都不经过 endGame()** → 天然不会灌假成绩。
 *
 * ★ endGame() / killEnemy() 住在 templates/game.html，从 ISSUE-20261029-53 起
 *   **派发与计数都写在那两个函数体内**（endGame 派发 ark:gameover、killEnemy 累加 runKills），
 *   这里只剩监听 —— 不再有壳层包装。
 *   为什么必须拆掉那层 hook（重要，别加回去）：计数搬到 killEnemy() 函数体之后，
 *   hook 再记一笔就变成「每杀一个记两次」；而「绕过 killEnemy 直接置 alive=false」
 *   那两条路（泥岩反击 / 阿米娅精神爆发）已一并改走 killEnemy()，不需要 hook 兜底。
 *   判据不变：**只有走 endGame() 的才是死亡结算** —— initLevel() 的 catch 是直接置
 *   phase = PHASE.GAMEOVER，永远不会派发本事件，所以初始化异常不会灌假成绩。
 * ========================================================================== */
(function () {
  'use strict';
  var NS = window.ArkShell;
  if (!NS) return;

  var sent = false;   // 同一局只上报一次（重开一局后由 ark:runstart 解除）

  /* 结算即上报（ISSUE-20261030-52 期望 §1/§2） */
  window.addEventListener('ark:gameover', function (e) {
    try {
      if (sent) return;
      sent = true;
      var d = (e && e.detail) || {};
      if (typeof window.arkReportScore === 'function') window.arkReportScore(d.level || 0, d.kills || 0);
    } catch (err) {}
  });

  /* 新的一局 → 允许再次上报。由 resetRunProgress()（src/rules/reset.js）派发。 */
  window.addEventListener('ark:runstart', function () { sent = false; });
})();

/* src: src/shell/06-boot.js */
/* ============================================================================
 * 外壳 · 启动层（ISSUE-20261029-45）
 * ----------------------------------------------------------------------------
 * 串起 sdk → account → board → panel，并把两个入口暴露给游戏侧：
 *   window.arkOpenLobby()      —— 棋盘左上角 👤 角标点击
 *   window.arkReportScore(l,k) —— 游戏结束（原 hook 轮询 phase 的替代）
 *
 * 顺序说明：本文件在所有游戏模块**之后**执行（槽位在 initCharSelect() 之后），
 * 所以能保证 #board 已完成首次布局、--cell/--corner-x 已有值。
 * 但 SDK 是异步的：游戏立刻可玩，外壳的身份判定在 SDK 就绪（或超时）后才落定。
 * ========================================================================== */
(function () {
  'use strict';
  var NS = window.ArkShell;
  if (!NS) return;

  function $(id) { return document.getElementById(id); }

  /* ISSUE-20261030-51：外壳现在与游戏同文档，事件回调里冒出去的异常会一路顶到 window
     （表现就是整页失灵）。每个入口各自包一层，一个按钮炸了不影响其它入口，
     并给一句人话提示，而不是静默失效。 */
  function safe(fn) {
    return function () {
      try { return fn.apply(this, arguments); }
      catch (e) {
        try { if (NS.ui && NS.ui.toast) NS.ui.toast('操作失败，可重开一局'); } catch (e2) {}
      }
    };
  }

  function bindEvents() {
    var mask = $('lobbyMask');
    if (mask) mask.addEventListener('click', safe(function () { NS.panel.close(); }));

    /* ISSUE-20261030-7x：账号面板的关闭改由棋盘左上角 👤 角标原地变 ✕ 承担（与设置面板 ⚙ 同款），
       面板内独立关闭按钮 #lobbyCornerClose 已删除，这里不再绑定。遮罩点击 / Esc 仍兜底关闭。 */

    /* ISSUE-20261030-72：游戏内完整排行榜入口已删除（#btnFullRank / #rankPanel / #rankClose /
       #rankFrame 全不存在），这里不再有对应绑定。完整榜仍在独立页 leaderboard.html。 */

    document.addEventListener('keydown', safe(function (e) {
      if (e.key !== 'Escape') return;
      if (NS.panel.isOpen()) { NS.panel.close(); e.preventDefault(); }
    }));

    /* 转屏 / 改窗口大小：棋盘格子重算（--cell 变），面板正开着就重新贴一次 */
    window.addEventListener('resize', safe(function () {
      if (NS.panel.isOpen()) NS.panel.place();
    }));
  }

  function boot() {
    bindEvents();

    NS.sdkReady.then(function (plat) {
      /* ISSUE-20261101-143 · 这里的异常原来会被 Promise 吞掉：棋盘不画、界面无任何提示，
       * 玩家只看到黑骨架。现在至少把原因显示到首屏遮罩上（模板里那个 #bootMask）。 */
      try {
      NS.account.resolveMyId();
      NS.account.loadAccount();

      if (plat.IN_TG) {
        if (plat.CAN_REPORT) { NS.panel.showHint('键盘入口 · 成绩会自动记录', true); setTimeout(NS.panel.hideHint, 4000); }
        else { NS.panel.showHint('主页/菜单入口 · 成绩也会记录', true); setTimeout(NS.panel.hideHint, 4500); }
      } else {
        NS.panel.showHint('网页模式 · 正在连接成绩服务器…', false);
      }

      NS.account.loadConfig(function () {
        NS.board.paint();
        NS.board.refresh();
        if (window.__arkBootOk) window.__arkBootOk();

        if (!plat.IN_TG) {
          if (NS.app.reportUrl) {
            NS.panel.showHint('网页模式 · 成绩会自动记录（同一份排行榜）', true);
            setTimeout(NS.panel.hideHint, 4500);
          } else {
            NS.panel.showHint('网页模式 · 成绩服务未连接（bot 没启动？本局成绩不会记录）', false);
          }
        }

        if (NS.app.isNewAccount) {
          setTimeout(function () {
            NS.panel.toast('你的账号是「' + NS.app.myAccount + '」\n点棋盘左上角 👤 → 编辑，可以改成自己的名字（数字口令 4–8 位）', 7000);
          }, 1200);
        }
      });

      try { if (plat.W) { plat.W.ready(); plat.W.expand(); } } catch (e) {}
      } catch (err) {
        if (window.__arkBootFail) {
          window.__arkBootFail('启动失败：' + ((err && err.message) ? err.message : String(err)).slice(0, 80));
        }
        throw err;
      }
    });
  }

  /* 游戏侧入口：外壳总是存在（已内联），但保留 typeof 检查让 game.html 被裁剪时也不炸 */
  window.arkOpenLobby = function () { NS.panel.toggle(); };
  window.arkReportScore = function (level, kills) { NS.account.reportScore(level || 0, kills || 0); };

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
/* #SHELL_END */
